@unittest.skipUnless(
    JNI_INTEGRATION_ENABLED and JPYPE_AVAILABLE and jni_toolchain_available(),
    "requires UMBRA_ENABLE_JNI_INTEGRATION_TESTS=1, JPype, a JDK, CMake, and PowerShell",
)
class JPypeJniIntegrationTest(ProviderBindingParityConformanceMixin, unittest.TestCase):
    def make_factory(self) -> JavaRtiFactory:
        return self.factory

    @classmethod
    def setUpClass(cls) -> None:
        import jpype

        if jpype.isJVMStarted():
            raise unittest.SkipTest(
                "the JNI fixture classpath must be present before the JVM starts"
            )
        # JPype cannot safely restart a JVM. Leave the build output for process
        # cleanup so its DLL and JAR stay available for the single test JVM.
        cls._temporary_directory = Path(tempfile.mkdtemp(prefix="umbra-rti-jni-"))
        cls.artifacts = build_jni_bridge(cls._temporary_directory, run_smoke_test=True)
        # The named preset only assembles the exact API/bridge/native
        # artifacts. The generic JPype provider still calls Java's standard
        # ServiceLoader and the C++ JNI façade remains the sole RTI semantics
        # owner.
        from umbra._java.rti1516_2025 import UmbraJniRtiFactory

        cls.factory = UmbraJniRtiFactory(
            api_jar=cls.artifacts.api_jar,
            artifact_directory=cls.artifacts.bridge_jar.parent,
        )
        # Optional runtime evidence can wrap the concrete JPype façade and
        # record every public service reached by the external suite.  It is
        # installed only for this test class and restored in tearDownClass so
        # normal provider behavior and focused tests remain unchanged.
        cls._runtime_service_calls: set[str] = set()
        cls._runtime_service_originals: dict[str, object] = {}
        for service_name in RTIambassador.__abstractmethods__:
            original = getattr(JavaRTIambassador, service_name, None)
            if original is None or not callable(original):
                continue

            def traced(
                ambassador: JavaRTIambassador,
                *arguments: object,
                __name: str = service_name,
                __original: object = original,
                **keywords: object,
            ) -> object:
                cls._runtime_service_calls.add(__name)
                return __original(ambassador, *arguments, **keywords)  # type: ignore[operator]

            cls._runtime_service_originals[service_name] = original
            setattr(JavaRTIambassador, service_name, traced)

    @classmethod
    def tearDownClass(cls) -> None:
        for service_name, original in getattr(
            cls, "_runtime_service_originals", {}
        ).items():
            setattr(JavaRTIambassador, service_name, original)
        super().tearDownClass()

    def test_jpype_ambassador_is_the_exact_2025_java_interface(self) -> None:
        """The adapter must consume the Java API interface, not a Python shadow."""
        import jpype

        ambassador = self.factory.getRtiAmbassador()
        raw_ambassador = ambassador.unwrap_java_object()
        standard_interface = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
        self.assertTrue(standard_interface.isAssignableFrom(raw_ambassador.getClass()))

    def test_cpp_jni_java_jpype_basic_data_element_value_matrix(self) -> None:
        """Round-trip every shared 2025 basic value through Java and C++ JNI."""
        import jpype

        # Initialize the standard provider once before requesting the raw
        # encoder.  This follows the normal factory -> ambassador lifecycle
        # used by the rest of this integration class and avoids asking JPype
        # to resolve a second proxy during JVM startup.
        self.factory.getRtiAmbassador()
        raw_encoder = self.factory.unwrap_java_encoder_factory()
        python_encoder = self.factory.getEncoderFactory()
        byte_wrapper_type = jpype.JClass("hla.rti1516_2025.encoding.ByteWrapper")
        byte_kinds = {"HLAbyte", "HLAoctet", "HLAASCIIchar"}
        short_kinds = {"HLAunicodeChar", "HLAoctetPairBE", "HLAoctetPairLE"}
        unsigned_kinds = {
            "HLAunsignedInteger16BE",
            "HLAunsignedInteger16LE",
            "HLAunsignedInteger32BE",
            "HLAunsignedInteger32LE",
            "HLAunsignedInteger64BE",
            "HLAunsignedInteger64LE",
        }
        for vector in iter_data_element_value_matrix("2025"):
            with self.subTest(case=vector.case_id):
                method = getattr(python_encoder, "create" + vector.kind)
                python_element = method(vector.value)
                encoded = bytes(python_element.toByteArray())

                # The Python façade's value overload is the exact Java
                # EncoderFactory overload. Re-decode through the raw Java
                # carrier to prove the C++ JNI decoder sees the same bytes.
                raw_method = getattr(raw_encoder, "create" + vector.kind)
                raw_decoded = raw_method()
                raw_decoded.decode(self.factory._runtime.byte_array(encoded))
                self.assertEqual(bytes(raw_decoded.toByteArray()), encoded)

                decoded = method()
                decoded.decode(self.factory._runtime.byte_array(encoded))
                actual = decoded.getValue()
                if vector.kind in byte_kinds:
                    self.assertEqual(int(actual) & 0xFF, int(vector.value) & 0xFF)
                elif vector.kind in short_kinds:
                    self.assertEqual(int(actual) & 0xFFFF, int(vector.value) & 0xFFFF)
                elif vector.kind in unsigned_kinds:
                    self.assertEqual(int(actual), int(vector.value))
                elif vector.kind.startswith("HLAfloat32"):
                    self.assertEqual(
                        struct.pack(">f", float(actual)),
                        struct.pack(">f", float(vector.value)),
                    )
                elif vector.kind.startswith("HLAfloat64"):
                    self.assertEqual(
                        struct.pack(">d", float(actual)),
                        struct.pack(">d", float(vector.value)),
                    )
                elif vector.kind == "HLAopaqueData":
                    self.assertEqual(bytes(actual), bytes(vector.value))
                else:
                    self.assertEqual(actual, vector.value)

                # Exercise both Python and raw Java ByteWrapper overloads at
                # a non-zero offset, preserving a trailing sentinel.
                signed = [item if item < 0x80 else item - 0x100 for item in encoded]
                # JPype maps Java ``byte`` as a signed value.  Keep the
                # trailing sentinel's wire byte (0xA5) while constructing it
                # with the representable Java value -0x5B.
                java_buffer = jpype.JArray(jpype.JByte)([0x55, *signed, -0x5B])
                raw_wrapper = byte_wrapper_type(java_buffer, 1, len(encoded) + 1)
                raw_cursor = raw_method()
                raw_cursor.decode(raw_wrapper)
                self.assertEqual(raw_wrapper.getPos(), len(encoded) + 1)
                self.assertEqual(raw_wrapper.remaining(), 1)
                self.assertEqual(int(java_buffer[raw_wrapper.getPos()]) & 0xFF, 0xA5)

                python_wrapper = byte_wrapper_type(java_buffer, 1, len(encoded) + 1)
                python_cursor = method()
                python_cursor.decode(python_wrapper)
                self.assertEqual(python_wrapper.getPos(), len(encoded) + 1)
                self.assertEqual(python_wrapper.remaining(), 1)
                self.assertEqual(int(java_buffer[python_wrapper.getPos()]) & 0xFF, 0xA5)

                # Exercise the reverse cursor direction for every standard
                # carrier as well.  Both objects are already decoded from
                # the same provider-owned bytes, so this proves that raw
                # Java and Python façade ``encode(ByteWrapper)`` calls copy
                # the native representation and advance only the requested
                # window.
                raw_encode_buffer = jpype.JArray(jpype.JByte)(
                    [0] + [0] * len(encoded) + [-0x5B]
                )
                raw_encode_wrapper = byte_wrapper_type(
                    raw_encode_buffer, 1, len(encoded) + 1
                )
                raw_decoded.encode(raw_encode_wrapper)
                self.assertEqual(raw_encode_wrapper.getPos(), len(encoded) + 1)
                self.assertEqual(raw_encode_wrapper.remaining(), 1)
                self.assertEqual(bytes(raw_encode_buffer)[1 : len(encoded) + 1], encoded)
                self.assertEqual(
                    int(raw_encode_buffer[raw_encode_wrapper.getPos()]) & 0xFF,
                    0xA5,
                )

                python_encode_buffer = jpype.JArray(jpype.JByte)(
                    [0] + [0] * len(encoded) + [-0x5B]
                )
                python_encode_wrapper = byte_wrapper_type(
                    python_encode_buffer, 1, len(encoded) + 1
                )
                self.assertIs(
                    python_element.encode(python_encode_wrapper), python_element
                )
                self.assertEqual(
                    python_encode_wrapper.getPos(), len(encoded) + 1
                )
                self.assertEqual(python_encode_wrapper.remaining(), 1)
                self.assertEqual(
                    bytes(python_encode_buffer)[1 : len(encoded) + 1], encoded
                )
                self.assertEqual(
                    int(python_encode_buffer[python_encode_wrapper.getPos()]) & 0xFF,
                    0xA5,
                )

                # The Python façade preflights undersized destinations so a
                # provider that cannot surface a native encoder exception
                # cannot strand the caller in JNI.
                short_python_buffer = jpype.JArray(jpype.JByte)(
                    [0] * max(len(encoded) - 1, 0)
                )
                short_python_wrapper = byte_wrapper_type(
                    short_python_buffer, 0, len(encoded) - 1
                )
                with self.assertRaises(EncoderException):
                    python_element.encode(short_python_wrapper)
                self.assertEqual(short_python_wrapper.getPos(), 0)
                self.assertEqual(
                    bytes(short_python_buffer), b"\0" * max(len(encoded) - 1, 0)
                )


    def test_cpp_jni_java_jpype_python_composite_creator_arguments(self) -> None:
        """Preserve 2025 composite creator overload arguments through JPype.

        The raw Java integration vectors exercise the standard ``DataElement``
        and ``DataElement[]`` overloads directly.  This companion vector starts
        at the provider-neutral Python factory, then checks that the selected
        Java/JNI carrier retains factory-created children, varargs, record
        additions, and variant discriminant/value pairs.  It deliberately
        asserts carrier shape and canonical bytes instead of introducing a
        second Python wire codec.
        """

        encoder = self.factory.getEncoderFactory()
        element_factory = _Integer32ElementFactory(encoder)
        first = encoder.createHLAinteger32BE(17)
        second = encoder.createHLAinteger32BE(-23)

        variable = encoder.createHLAvariableArray(element_factory, first, second)
        self.assertEqual(variable.size(), 2)
        self.assertEqual(variable.get(0).getValue(), 17)
        self.assertEqual(variable.get(1).getValue(), -23)

        empty_variable = encoder.createHLAvariableArray(element_factory)
        self.assertEqual(empty_variable.size(), 0)

        fixed_from_factory = encoder.createHLAfixedArray(element_factory, 3)
        self.assertEqual(fixed_from_factory.size(), 3)
        for index in range(fixed_from_factory.size()):
            with self.subTest(fixed_factory_index=index):
                self.assertEqual(fixed_from_factory.get(index).getValue(), 0)

        fixed_from_values = encoder.createHLAfixedArray(first, second)
        self.assertEqual(fixed_from_values.size(), 2)
        self.assertEqual(fixed_from_values.get(0).getValue(), 17)
        self.assertEqual(fixed_from_values.get(1).getValue(), -23)
        self.assertEqual(
            fixed_from_values.toByteArray(),
            b"\x00\x00\x00\x11\xff\xff\xff\xe9",
        )

        record = encoder.createHLAfixedRecord()
        record.appendElement(first)
        record.appendElement(second)
        self.assertEqual(record.size(), 2)
        self.assertEqual(record.get(0).getValue(), 17)
        self.assertEqual(record.get(1).getValue(), -23)

        discriminant = encoder.createHLAoctet(1)
        variant = encoder.createHLAvariantRecord(discriminant)
        variant.setVariant(discriminant, second)
        self.assertEqual(variant.getDiscriminant().getValue(), 1)
        self.assertEqual(variant.getValue().getValue(), -23)

    def test_cpp_jni_java_jpype_exact_federate_ambassador_surface(self) -> None:
        """Every exact Java callback name has an explicit JPype dispatcher."""
        import jpype
        import inspect

        from umbra._java.rti1516_2025._runtime import _FederateAmbassadorCallback

        ambassador = self.factory.getRtiAmbassador()
        callback_interface = jpype.JClass("hla.rti1516_2025.FederateAmbassador").class_
        java_callback_names = {
            str(method.getName()) for method in callback_interface.getMethods()
        }
        python_dispatch_names = {
            name
            for name in dir(_FederateAmbassadorCallback)
            if not name.startswith("_")
        }
        self.assertEqual(len(java_callback_names), 56)
        self.assertSetEqual(java_callback_names, python_dispatch_names)

        # Names alone do not protect Java overloads.  The dispatcher exposes
        # one Python method with optional trailing arguments for the standard
        # timed/untimed callback pairs; verify every reflected Java arity falls
        # within that method's required-to-maximum argument range.
        arity_gaps: list[str] = []
        for callback_name in sorted(java_callback_names):
            dispatcher = getattr(_FederateAmbassadorCallback, callback_name)
            parameters = list(inspect.signature(dispatcher).parameters.values())[1:]
            required = sum(
                parameter.default is inspect.Parameter.empty
                and parameter.kind
                in (
                    inspect.Parameter.POSITIONAL_ONLY,
                    inspect.Parameter.POSITIONAL_OR_KEYWORD,
                )
                for parameter in parameters
            )
            maximum = sum(
                parameter.kind
                in (
                    inspect.Parameter.POSITIONAL_ONLY,
                    inspect.Parameter.POSITIONAL_OR_KEYWORD,
                )
                for parameter in parameters
            )
            java_arities = {
                int(method.getParameterCount())
                for method in callback_interface.getMethods()
                if str(method.getName()) == callback_name
            }
            for java_arity in sorted(java_arities):
                if not required <= java_arity <= maximum:
                    arity_gaps.append(
                        f"{callback_name}/{java_arity} outside {required}..{maximum}"
                    )
        self.assertEqual(arity_gaps, [])

        # Construct the actual standard proxy as a second guard: a name-only
        # comparison must not silently bypass JPype's interface binding.
        try:
            callback_binding = ambassador._runtime.bind_federate_ambassador(
                _JniCallbacks()
            )
            self.assertIsNotNone(callback_binding.proxy)
        finally:
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_callback_overload_carriers(self) -> None:
        """Round-trip every reflected 2025 callback overload into Python.

        The exact-surface test above verifies names and arity ranges, while
        the live federation tests verify callbacks selected by the RTI.  This
        matrix fills the remaining carrier gap: every overload in the
        standard Java ``FederateAmbassador`` interface is invoked with a
        representative Java value originating from the C++-backed JNI
        factories, then the Python callback receives the provider-neutral
        handle/set/map/enum/array/time shape.  It intentionally asserts
        carrier identity and values only; callback scheduling and RTI
        semantics remain provider-defined.
        """
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        integer_name = f"python-jni-callback-overloads-integer-{uuid4().hex[:12]}"
        float_name = f"python-jni-callback-overloads-float-{uuid4().hex[:12]}"

        class RecordingCallback(FederateAmbassador):
            def __init__(self) -> None:
                self.calls: list[tuple[str, tuple[object, ...]]] = []

        integer_ambassador = self.factory.getRtiAmbassador()
        float_ambassador = self.factory.getRtiAmbassador()
        integer_callback = RecordingCallback()
        float_callback = RecordingCallback()
        ambassadors = (integer_ambassador, float_ambassador)
        callbacks = (integer_callback, float_callback)
        bindings: list[object] = []
        connected = [False, False]
        created = [False, False]
        joined = [False, False]

        try:
            for index, (ambassador, callback, federation_name, time_name) in enumerate(
                (
                    (
                        integer_ambassador,
                        integer_callback,
                        integer_name,
                        HLA_TYPES.INTEGER64_TIME,
                    ),
                    (
                        float_ambassador,
                        float_callback,
                        float_name,
                        HLA_TYPES.FLOAT64_TIME,
                    ),
                )
            ):
                # Install a recorder for every exact Java method name.  An
                # instance attribute is deliberately used here so Python does
                # not bind an extra ``self`` argument to the lambda.
                callback_interface = jpype.JClass(
                    "hla.rti1516_2025.FederateAmbassador"
                ).class_
                callback_names = {
                    str(method.getName())
                    for method in callback_interface.getMethods()
                }
                for name in callback_names:
                    setattr(
                        callback,
                        name,
                        lambda *arguments, _name=name, _callback=callback: _callback.calls.append(
                            (_name, arguments)
                        ),
                    )
                ambassador.connect(callback, CallbackModel.HLA_EVOKED)
                connected[index] = True
                ambassador.createFederationExecution(
                    federation_name, str(fom_module), time_name
                )
                created[index] = True
                ambassador.joinFederationExecution(
                    f"callback-overloads-{index}", federation_name
                )
                joined[index] = True

            runtime = self.factory._runtime
            raw_ambassadors = tuple(
                ambassador.unwrap_java_object() for ambassador in ambassadors
            )
            for ambassador, callback in zip(ambassadors, callbacks, strict=True):
                bindings.append(ambassador._runtime.bind_federate_ambassador(callback))

            callback_interface = jpype.JClass(
                "hla.rti1516_2025.FederateAmbassador"
            ).class_
            methods_by_name: dict[str, list[object]] = {}
            for method in callback_interface.getMethods():
                methods_by_name.setdefault(str(method.getName()), []).append(method)

            handle_kinds = {
                "FederateHandle": "FederateHandle",
                "ObjectClassHandle": "ObjectClassHandle",
                "ObjectInstanceHandle": "ObjectInstanceHandle",
                "AttributeHandle": "AttributeHandle",
                "InteractionClassHandle": "InteractionClassHandle",
                "ParameterHandle": "ParameterHandle",
                "TransportationTypeHandle": "TransportationTypeHandle",
                "DimensionHandle": "DimensionHandle",
                "RegionHandle": "RegionHandle",
                "MessageRetractionHandle": "MessageRetractionHandle",
            }
            set_kinds = {
                "AttributeHandleSet": "AttributeHandle",
                "DimensionHandleSet": "DimensionHandle",
                "FederateHandleSet": "FederateHandle",
                "InteractionClassHandleSet": "InteractionClassHandle",
                "RegionHandleSet": "RegionHandle",
            }
            map_kinds = {
                "AttributeHandleValueMap": "AttributeHandle",
                "ParameterHandleValueMap": "ParameterHandle",
            }

            def encoded_handle(seed: int) -> bytes:
                # Standard MIM handle carriers are an HLAvariableArray: the
                # four-byte element count followed by implementation bytes.
                return struct.pack(">IQ", 8, seed)

            def raw_handle(raw_ambassador: object, kind: str, seed: int) -> object:
                factory = getattr(raw_ambassador, f"get{kind}Factory")()
                return factory.decode(runtime.byte_array(encoded_handle(seed)), 0)

            def raw_value(
                raw_ambassador: object,
                java_type: object,
                time_kind: str,
                seed: int,
            ) -> object:
                type_name = str(java_type.getName())  # type: ignore[attr-defined]
                simple_name = type_name.rsplit(".", 1)[-1]

                if type_name == "java.lang.String":
                    return "callback-matrix"
                if type_name == "[B":
                    return runtime.byte_array(b"callback-matrix")
                if type_name == "hla.rti1516_2025.time.LogicalTime":
                    return raw_ambassador.getTimeFactory().makeTime(
                        7.5 if time_kind == HLA_TYPES.FLOAT64_TIME else 7
                    )
                if simple_name in handle_kinds:
                    return raw_handle(raw_ambassador, handle_kinds[simple_name], seed)
                if simple_name in set_kinds:
                    if simple_name == "InteractionClassHandleSet":
                        values = raw_ambassador.getInteractionClassHandleSetFactory().create()
                    elif simple_name == "AttributeHandleSet":
                        values = raw_ambassador.getAttributeHandleSetFactory().create()
                    elif simple_name == "DimensionHandleSet":
                        values = raw_ambassador.getDimensionHandleSetFactory().create()
                    elif simple_name == "FederateHandleSet":
                        values = raw_ambassador.getFederateHandleSetFactory().create()
                    else:
                        values = raw_ambassador.getRegionHandleSetFactory().create()
                    values.add(
                        raw_handle(
                            raw_ambassador,
                            set_kinds[simple_name],
                            seed + 1,
                        )
                    )
                    return values
                if simple_name in map_kinds:
                    factory_name = f"get{simple_name}Factory"
                    values = getattr(raw_ambassador, factory_name)().create(1)
                    values.put(
                        raw_handle(raw_ambassador, map_kinds[simple_name], seed + 1),
                        runtime.byte_array(b"callback-value"),
                    )
                    return values
                if type_name == "java.util.Set":
                    values = jpype.JClass("java.util.LinkedHashSet")()
                    values.add("callback-matrix")
                    return values
                if type_name.endswith("FederationExecutionInformationSet"):
                    values = jpype.JClass(
                        "org.umbra.jni.rti1516_2025.NativeFederationExecutionInformationSet"
                    )()
                    information_type = jpype.JClass(
                        "hla.rti1516_2025.FederationExecutionInformation"
                    )
                    values.add(
                        information_type("callback-federation", time_kind)
                    )
                    return values
                if type_name.endswith("FederationExecutionMemberInformationSet"):
                    values = jpype.JClass(
                        "org.umbra.jni.rti1516_2025.NativeFederationExecutionMemberInformationSet"
                    )()
                    information_type = jpype.JClass(
                        "hla.rti1516_2025.FederationExecutionMemberInformation"
                    )
                    values.add(information_type("callback-federate", "callback-type"))
                    return values
                if type_name.startswith("[L") and type_name.endswith(";"):
                    component_name = type_name[2:-1].replace("/", ".")
                    component_type = jpype.JClass(component_name)
                    if component_name.endswith("FederateHandleSaveStatusPair"):
                        pair = component_type(
                            raw_handle(raw_ambassador, "FederateHandle", seed + 1),
                            jpype.JClass("hla.rti1516_2025.SaveStatus").values()[0],
                        )
                    elif component_name.endswith("FederateRestoreStatus"):
                        pair = component_type(
                            raw_handle(raw_ambassador, "FederateHandle", seed + 1),
                            raw_handle(raw_ambassador, "FederateHandle", seed + 2),
                            jpype.JClass("hla.rti1516_2025.RestoreStatus").values()[0],
                        )
                    else:
                        raise AssertionError(
                            "callback matrix has no array carrier for " + type_name
                        )
                    return jpype.JArray(component_type)([pair])
                if type_name.startswith("hla.rti1516_2025."):
                    # All remaining non-handle callback carriers are standard
                    # enums.  Selecting a declared value avoids inventing a
                    # vendor-specific enum member.
                    java_class = jpype.JClass(type_name)
                    if bool(java_class.class_.isEnum()):
                        return java_class.values()[0]
                raise AssertionError(
                    "callback matrix has no JNI carrier for " + type_name
                )

            def assert_python_value(java_type: object, value: object, time_kind: str) -> None:
                type_name = str(java_type.getName())  # type: ignore[attr-defined]
                simple_name = type_name.rsplit(".", 1)[-1]
                if type_name == "java.lang.String":
                    self.assertIsInstance(value, str)
                    self.assertEqual(value, "callback-matrix")
                elif type_name == "[B":
                    self.assertIsInstance(value, bytes)
                    self.assertEqual(value, b"callback-matrix")
                elif type_name == "hla.rti1516_2025.time.LogicalTime":
                    expected_type = (
                        HLAfloat64Time
                        if time_kind == HLA_TYPES.FLOAT64_TIME
                        else HLAinteger64Time
                    )
                    self.assertIsInstance(value, expected_type)
                    self.assertEqual(value.getTime(), 7.5 if expected_type is HLAfloat64Time else 7)
                elif simple_name in handle_kinds:
                    self.assertEqual(type(value).__name__, simple_name)
                    self.assertEqual(value.encodedValue, encoded_handle(0x101))
                elif simple_name in set_kinds:
                    expected_type = {
                        "AttributeHandleSet": AttributeHandleSet,
                        "DimensionHandleSet": DimensionHandleSet,
                        "FederateHandleSet": FederateHandleSet,
                        "InteractionClassHandleSet": InteractionClassHandleSet,
                        "RegionHandleSet": RegionHandleSet,
                    }[simple_name]
                    self.assertIsInstance(value, expected_type)
                    self.assertEqual(len(value), 1)
                elif simple_name in map_kinds:
                    expected_type = (
                        AttributeHandleValueMap
                        if simple_name == "AttributeHandleValueMap"
                        else ParameterHandleValueMap
                    )
                    self.assertIsInstance(value, expected_type)
                    self.assertEqual(len(value), 1)
                    self.assertEqual(next(iter(value.values())), b"callback-value")
                elif type_name == "java.util.Set":
                    self.assertIsInstance(value, frozenset)
                    self.assertEqual(value, frozenset({"callback-matrix"}))
                elif type_name.endswith("FederationExecutionInformationSet"):
                    self.assertIsInstance(value, FederationExecutionInformationSet)
                    self.assertEqual(
                        value,
                        FederationExecutionInformationSet(
                            {
                                FederationExecutionInformation(
                                    "callback-federation", time_kind
                                )
                            }
                        ),
                    )
                elif type_name.endswith("FederationExecutionMemberInformationSet"):
                    self.assertIsInstance(
                        value, FederationExecutionMemberInformationSet
                    )
                    self.assertEqual(
                        value,
                        FederationExecutionMemberInformationSet(
                            {
                                FederationExecutionMemberInformation(
                                    "callback-federate", "callback-type"
                                )
                            }
                        ),
                    )
                elif type_name.startswith("[L"):
                    self.assertIsInstance(value, tuple)
                    self.assertEqual(len(value), 1)
                elif type_name.startswith("hla.rti1516_2025."):
                    java_class = jpype.JClass(type_name)
                    if bool(java_class.class_.isEnum()):
                        self.assertEqual(type(value).__name__, simple_name)
                        return
                    raise AssertionError(
                        "callback matrix has no Python assertion for " + type_name
                    )
                else:
                    raise AssertionError(
                        "callback matrix has no Python assertion for " + type_name
                    )

            expected_calls = 0
            for route_index, (raw_ambassador, binding, callback, time_kind) in enumerate(
                zip(
                    raw_ambassadors,
                    bindings,
                    callbacks,
                    (HLA_TYPES.INTEGER64_TIME, HLA_TYPES.FLOAT64_TIME),
                    strict=True,
                )
            ):
                del route_index
                for callback_name in sorted(methods_by_name):
                    overloads = sorted(
                        methods_by_name[callback_name],
                        key=lambda method: tuple(
                            str(parameter.getName())
                            for parameter in method.getParameterTypes()
                        ),
                    )
                    for overload_index, method in enumerate(overloads):
                        parameter_types = list(method.getParameterTypes())
                        arguments = tuple(
                                raw_value(
                                    raw_ambassador,
                                    parameter_type,
                                    time_kind,
                                    0x101,
                                )
                            for index, parameter_type in enumerate(parameter_types)
                        )
                        before = len(callback.calls)
                        getattr(binding.target, callback_name)(*arguments)
                        self.assertEqual(
                            len(callback.calls), before + 1, callback_name
                        )
                        returned_name, returned = callback.calls[-1]
                        self.assertEqual(returned_name, callback_name)
                        self.assertEqual(len(returned), len(parameter_types))
                        for parameter_type, value in zip(
                            parameter_types, returned, strict=True
                        ):
                            with self.subTest(
                                callback=callback_name,
                                overload=tuple(
                                    str(parameter.getName())
                                    for parameter in parameter_types
                                ),
                                time_kind=time_kind,
                            ):
                                assert_python_value(parameter_type, value, time_kind)
                        expected_calls += 1

            reflected_overload_count = sum(
                len(overloads) for overloads in methods_by_name.values()
            )
            self.assertEqual(len(methods_by_name), 56)
            self.assertEqual(
                reflected_overload_count, CALLBACK_OVERLOAD_COUNTS["2025"]
            )
            self.assertEqual(len(integer_callback.calls), reflected_overload_count)
            self.assertEqual(len(float_callback.calls), reflected_overload_count)
            self.assertEqual(expected_calls, reflected_overload_count * 2)
        finally:
            for index in (1, 0):
                ambassador = ambassadors[index]
                if joined[index]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
                if created[index]:
                    try:
                        ambassador.destroyFederationExecution(
                            (integer_name, float_name)[index]
                        )
                    except Exception:
                        pass
                if connected[index]:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

    def test_cpp_jni_java_jpype_callback_provenance_carriers(self) -> None:
        """Normalize JNI-created Java callback carriers to shared semantics.

        The provider-neutral callback vectors are deliberately consumed with
        the real C++-backed Java handle/map/time factories.  The callback
        target is invoked directly because a Java ``JProxy`` has no public
        way to select one overload from Python; the existing live federation
        tests exercise the reverse C++ -> Java callback invocation.  Together
        these checks prove both carrier construction and Python normalization
        without introducing a second callback contract.
        """
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        integer_name = f"python-jni-callback-provenance-integer-{uuid4().hex[:12]}"
        float_name = f"python-jni-callback-provenance-float-{uuid4().hex[:12]}"
        integer_ambassador = self.factory.getRtiAmbassador()
        float_ambassador = self.factory.getRtiAmbassador()
        integer_callbacks = _JniCallbacks()
        float_callbacks = _JniCallbacks()
        integer_secondary_callbacks = _JniCallbacks()
        float_secondary_callbacks = _JniCallbacks()
        ambassadors = (integer_ambassador, float_ambassador)
        connected = [False, False]
        created = [False, False]
        joined = [False, False]
        try:
            for index, (ambassador, callbacks, federation_name, time_name) in enumerate(
                (
                    (
                        integer_ambassador,
                        integer_callbacks,
                        integer_name,
                        HLA_TYPES.INTEGER64_TIME,
                    ),
                    (
                        float_ambassador,
                        float_callbacks,
                        float_name,
                        HLA_TYPES.FLOAT64_TIME,
                    ),
                )
            ):
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
                connected[index] = True
                ambassador.createFederationExecution(
                    federation_name, str(fom_module), time_name
                )
                created[index] = True
                ambassador.joinFederationExecution(
                    f"callback-provenance-{index}", federation_name
                )
                joined[index] = True

            order_type = jpype.JClass("hla.rti1516_2025.OrderType")
            runtime = self.factory._runtime

            def encoded_handle(seed: int) -> bytes:
                # The standard MIM handle carrier is an HLAvariableArray:
                # four-byte element count followed by eight implementation
                # bytes.  Supplying this shape makes C++ validate every raw
                # Java handle before JPype sees it.
                return struct.pack(">IQ", 8, seed)

            def raw_handle(raw_ambassador: object, kind: str, seed: int) -> object:
                factory = getattr(raw_ambassador, f"get{kind}Factory")()
                return factory.decode(runtime.byte_array(encoded_handle(seed)), 0)

            def raw_map(
                raw_ambassador: object, callback_name: str, vector: object
            ) -> object:
                factory_name = (
                    "getAttributeHandleValueMapFactory"
                    if callback_name == "reflectAttributeValues"
                    else "getParameterHandleValueMapFactory"
                )
                handle_kind = (
                    "AttributeHandle"
                    if callback_name == "reflectAttributeValues"
                    else "ParameterHandle"
                )
                values = getattr(raw_ambassador, factory_name)().create(1)
                values.put(
                    raw_handle(raw_ambassador, handle_kind, 41),
                    runtime.byte_array(vector.payload),  # type: ignore[attr-defined]
                )
                return values

            raw_ambassadors = tuple(
                ambassador.unwrap_java_object() for ambassador in ambassadors
            )
            bindings = (
                integer_ambassador._runtime.bind_federate_ambassador(
                    integer_callbacks
                ),
                float_ambassador._runtime.bind_federate_ambassador(float_callbacks),
            )
            secondary_bindings = (
                integer_ambassador._runtime.bind_federate_ambassador(
                    integer_secondary_callbacks
                ),
                float_ambassador._runtime.bind_federate_ambassador(
                    float_secondary_callbacks
                ),
            )

            vectors = iter_callback_provenance_matrix()
            actual: list[CallbackDeliveryObservation] = []
            stream_positions = {name: 0 for name in (
                "integer-a", "integer-b", "float-a", "float-b"
            )}

            def invoke_and_record(
                recipient: str,
                target: object,
                callback: _JniCallbacks,
                vector: object,
                arguments: tuple[object, ...],
            ) -> None:
                """Invoke one raw carrier set and normalize its Python result."""

                getattr(target, vector.callback)(*arguments)  # type: ignore[attr-defined]
                sequence = stream_positions[recipient]
                stream_positions[recipient] += 1
                if vector.callback == "discoverObjectInstance":  # type: ignore[attr-defined]
                    result = callback.discovered_objects[-1]
                    self.assertEqual(result[0].encodedValue, encoded_handle(31))
                    self.assertEqual(result[1].encodedValue, encoded_handle(32))
                    self.assertEqual(result[2], vector.instance_name)  # type: ignore[attr-defined]
                    self.assertEqual(result[3].encodedValue, encoded_handle(33))
                    actual.append(
                        CallbackDeliveryObservation(
                            recipient=recipient,
                            sequence=sequence,
                            vector_id=vector.case_id,  # type: ignore[attr-defined]
                            callback=vector.callback,  # type: ignore[attr-defined]
                            timed=False,
                            object_instance=vector.object_instance,  # type: ignore[attr-defined]
                            object_class=vector.object_class,  # type: ignore[attr-defined]
                            instance_name=result[2],
                            producing_federate=vector.producing_federate,  # type: ignore[attr-defined]
                        )
                    )
                    return

                if vector.callback == "reflectAttributeValues":  # type: ignore[attr-defined]
                    result = (
                        callback.timestamped_reflections[-1]
                        if vector.timed  # type: ignore[attr-defined]
                        else callback.reflected_attributes[-1]
                    )
                    handle_type = AttributeHandle
                else:
                    result = (
                        callback.timestamped_interactions[-1]
                        if vector.timed  # type: ignore[attr-defined]
                        else callback.received_interactions[-1]
                    )
                    handle_type = ParameterHandle
                payload_key = handle_type(encoded_handle(41))
                self.assertEqual(result[2], vector.tag)  # type: ignore[attr-defined]
                self.assertEqual(result[3].encodedValue, encoded_handle(35))
                self.assertEqual(result[4].encodedValue, encoded_handle(33))
                self.assertEqual(result[1][payload_key], vector.payload)  # type: ignore[attr-defined]
                if vector.timed:  # type: ignore[attr-defined]
                    self.assertEqual(result[6].getTime(), vector.time_value)  # type: ignore[attr-defined]
                    self.assertEqual(result[7].name, vector.sent_order)  # type: ignore[attr-defined]
                    self.assertEqual(result[8].name, vector.received_order)  # type: ignore[attr-defined]
                    self.assertTrue(result[9].isValid())
                    self.assertEqual(result[9].encodedValue, encoded_handle(36))
                    if vector.sent_region is None:  # type: ignore[attr-defined]
                        self.assertIsNone(result[5])
                    else:
                        self.assertEqual(
                            next(iter(result[5])).encodedValue,
                            encoded_handle(37),
                        )
                    actual.append(
                        CallbackDeliveryObservation(
                            recipient=recipient,
                            sequence=sequence,
                            vector_id=vector.case_id,  # type: ignore[attr-defined]
                            callback=vector.callback,  # type: ignore[attr-defined]
                            timed=True,
                            object_instance=(
                                vector.object_instance  # type: ignore[attr-defined]
                                if vector.callback == "reflectAttributeValues"  # type: ignore[attr-defined]
                                else None
                            ),
                            interaction_class=(
                                vector.interaction_class  # type: ignore[attr-defined]
                                if vector.callback == "receiveInteraction"  # type: ignore[attr-defined]
                                else None
                            ),
                            payload_handle=vector.payload_handle,  # type: ignore[attr-defined]
                            payload=result[1][payload_key],
                            tag=result[2],
                            transportation=vector.transportation,  # type: ignore[attr-defined]
                            producing_federate=vector.producing_federate,  # type: ignore[attr-defined]
                            sent_region=vector.sent_region,  # type: ignore[attr-defined]
                            time_implementation=result[6].implementationName(),
                            time_value=result[6].getTime(),
                            sent_order=result[7].name,
                            received_order=result[8].name,
                            retraction=vector.retraction,  # type: ignore[attr-defined]
                        )
                    )
                else:
                    actual.append(
                        CallbackDeliveryObservation(
                            recipient=recipient,
                            sequence=sequence,
                            vector_id=vector.case_id,  # type: ignore[attr-defined]
                            callback=vector.callback,  # type: ignore[attr-defined]
                            timed=False,
                            object_instance=(
                                vector.object_instance  # type: ignore[attr-defined]
                                if vector.callback == "reflectAttributeValues"  # type: ignore[attr-defined]
                                else None
                            ),
                            interaction_class=(
                                vector.interaction_class  # type: ignore[attr-defined]
                                if vector.callback == "receiveInteraction"  # type: ignore[attr-defined]
                                else None
                            ),
                            payload_handle=vector.payload_handle,  # type: ignore[attr-defined]
                            payload=result[1][payload_key],
                            tag=result[2],
                            transportation=vector.transportation,  # type: ignore[attr-defined]
                            producing_federate=vector.producing_federate,  # type: ignore[attr-defined]
                            received_order=vector.received_order,  # type: ignore[attr-defined]
                        )
                    )

            for vector in vectors:
                # Use the selected time family for each timed vector.  The
                # untimed cases are carrier-identical and use the integer
                # ambassador to keep the matrix deterministic.
                route_index = (
                    1
                    if vector.timed
                    and vector.time_implementation == HLA_TYPES.FLOAT64_TIME
                    else 0
                )
                raw_ambassador = raw_ambassadors[route_index]
                callback_pair = (
                    (integer_callbacks, integer_secondary_callbacks)
                    if route_index == 0
                    else (float_callbacks, float_secondary_callbacks)
                )
                target_pair = (
                    (bindings[route_index].target, secondary_bindings[route_index].target)
                )
                recipient_pair = (
                    ("integer-a", "integer-b")
                    if route_index == 0
                    else ("float-a", "float-b")
                )
                with self.subTest(case=vector.case_id):
                    if vector.callback == "discoverObjectInstance":
                        arguments = (
                            raw_handle(raw_ambassador, "ObjectInstanceHandle", 31),
                            raw_handle(raw_ambassador, "ObjectClassHandle", 32),
                            vector.instance_name,
                            raw_handle(raw_ambassador, "FederateHandle", 33),
                        )
                    else:
                        raw_regions = None
                        if vector.sent_region is not None:
                            raw_regions = getattr(
                                raw_ambassador, "getRegionHandleSetFactory"
                            )().create()
                            raw_regions.add(
                                raw_handle(raw_ambassador, "RegionHandle", 37)
                            )
                        raw_time = None
                        if vector.timed:
                            raw_time = raw_ambassador.getTimeFactory().makeTime(
                                vector.time_value
                            )
                        raw_retraction = None
                        if vector.retraction is not None:
                            raw_retraction = raw_ambassador.getMessageRetractionHandleFactory().decode(
                                runtime.byte_array(encoded_handle(36)), 0
                            )
                        common = (
                            raw_handle(
                                raw_ambassador,
                                "ObjectInstanceHandle"
                                if vector.callback == "reflectAttributeValues"
                                else "InteractionClassHandle",
                                34,
                            ),
                            raw_map(raw_ambassador, vector.callback, vector),
                            runtime.byte_array(vector.tag),
                            raw_handle(raw_ambassador, "TransportationTypeHandle", 35),
                            raw_handle(raw_ambassador, "FederateHandle", 33),
                            raw_regions,
                        )
                        arguments = common
                        if vector.timed:
                            arguments += (
                                raw_time,
                                getattr(order_type, vector.sent_order),
                                getattr(order_type, vector.received_order),
                                raw_retraction,
                            )
                    for recipient, target, callback in zip(
                        recipient_pair, target_pair, callback_pair, strict=True
                    ):
                        invoke_and_record(recipient, target, callback, vector, arguments)

            expected = tuple(
                CallbackDeliveryObservation.from_vector(
                    vector,
                    recipient=recipient,
                    sequence=sequence,
                )
                for route_name, route_vectors in (
                    (
                        "integer",
                        tuple(
                            vector
                            for vector in vectors
                            if not (
                                vector.timed
                                and vector.time_implementation
                                == HLA_TYPES.FLOAT64_TIME
                            )
                        ),
                    ),
                    (
                        "float",
                        tuple(
                            vector
                            for vector in vectors
                            if vector.timed
                            and vector.time_implementation == HLA_TYPES.FLOAT64_TIME
                        ),
                    ),
                )
                for recipient in (f"{route_name}-a", f"{route_name}-b")
                for sequence, vector in enumerate(route_vectors)
            )
            assert_callback_delivery_parity(expected, actual)
        finally:
            for index in (1, 0):
                ambassador = ambassadors[index]
                if joined[index]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
                if created[index]:
                    try:
                        ambassador.destroyFederationExecution(
                            (integer_name, float_name)[index]
                        )
                    except Exception:
                        pass
                if connected[index]:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

    def test_cpp_jni_java_jpype_regional_interaction_subscription_service_report_failures(
        self,
    ) -> None:
        """Preserve C++ failure records for regional interaction subscriptions."""
        repository_root = Path(__file__).parents[3]
        restaurant_fom = (
            repository_root
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        switch_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-regional-interaction-report-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"regional-interaction-service-reports-{uuid4().hex[:12]}"
        )
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False
        region: RegionHandle | None = None
        invalid_region: RegionHandle | None = None

        def decode_appended(before: str) -> dict[str, object]:
            appended = report_file.read_text(encoding="utf-8")[len(before) :]
            record, consumed = json.JSONDecoder().raw_decode(appended)
            self.assertEqual(consumed, len(appended))
            return record

        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED, configuration)
            connected = True
            ambassador.createFederationExecution(
                federation_name,
                [str(restaurant_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-regional-interaction-report",
                federation_name,
                federateName="jni-regional-interaction-report",
            )
            joined = True
            report_files = sorted(reports_directory.glob("*"))
            self.assertEqual(len(report_files), 1)
            report_file = report_files[0]

            interaction_class = ambassador.getInteractionClassHandle(
                HLA_FOM.MAIN_COURSE_SERVED
            )
            dimension = ambassador.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            region = ambassador.createRegion(DimensionHandleSet([dimension]))
            ambassador.setRangeBounds(region, dimension, RangeBounds(0, 10))
            ambassador.commitRegionModifications(RegionHandleSet([region]))
            invalid_region = ambassador.createRegion(DimensionHandleSet([dimension]))
            ambassador.setRangeBounds(invalid_region, dimension, RangeBounds(11, 20))
            ambassador.commitRegionModifications(RegionHandleSet([invalid_region]))
            ambassador.deleteRegion(invalid_region)

            gated_before = report_file.read_text(encoding="utf-8")
            ambassador.setServiceReportingSwitch(False)
            ambassador.setSendServiceReportsToFileSwitch(False)
            with self.assertRaises(InvalidRegion):
                ambassador.subscribeInteractionClassWithRegions(
                    interaction_class, RegionHandleSet([invalid_region])
                )
            self.assertEqual(report_file.read_text(encoding="utf-8"), gated_before)

            ambassador.setServiceReportingSwitch(True)
            ambassador.setSendServiceReportsToFileSwitch(True)
            before_failed_subscribe = report_file.read_text(encoding="utf-8")
            with self.assertRaises(InvalidRegion):
                ambassador.subscribeInteractionClassWithRegions(
                    interaction_class, RegionHandleSet([invalid_region])
                )
            failed_subscribe = decode_appended(before_failed_subscribe)
            self.assertEqual(
                failed_subscribe[HLA_MOM.SERVICE],
                "SubscribeInteractionClassWithRegions",
            )
            self.assertFalse(failed_subscribe[HLA_MOM.SUCCESS_INDICATOR])
            failed_subscribe_serial = failed_subscribe[HLA_MOM.SERIAL_NUMBER]
            self.assertGreaterEqual(failed_subscribe_serial, 0)
            self.assertTrue(
                failed_subscribe[HLA_MOM.EXCEPTION].startswith("InvalidRegion:")
            )
            self.assertEqual(
                [
                    argument[HLA_MOM.ARGUMENT_TYPE]
                    for argument in failed_subscribe[HLA_MOM.SUPPLIED_ARGUMENTS]
                ],
                [27, 43, 6],
            )
            self.assertFalse(
                failed_subscribe[HLA_MOM.SUPPLIED_ARGUMENTS][2][HLA_MOM.ARGUMENT_VALUE]
            )

            before_success_subscribe = report_file.read_text(encoding="utf-8")
            ambassador.subscribeInteractionClassWithRegions(
                interaction_class, RegionHandleSet([region])
            )
            success_subscribe = decode_appended(before_success_subscribe)
            self.assertEqual(
                success_subscribe[HLA_MOM.SERVICE],
                "SubscribeInteractionClassWithRegions",
            )
            self.assertTrue(success_subscribe[HLA_MOM.SUCCESS_INDICATOR])
            self.assertEqual(
                success_subscribe[HLA_MOM.SERIAL_NUMBER], failed_subscribe_serial + 1
            )
            self.assertIsNone(success_subscribe[HLA_MOM.EXCEPTION])

            before_failed_unsubscribe = report_file.read_text(encoding="utf-8")
            with self.assertRaises(InvalidRegion):
                ambassador.unsubscribeInteractionClassWithRegions(
                    interaction_class, RegionHandleSet([invalid_region])
                )
            failed_unsubscribe = decode_appended(before_failed_unsubscribe)
            self.assertEqual(
                failed_unsubscribe[HLA_MOM.SERVICE],
                "UnsubscribeInteractionClassWithRegions",
            )
            self.assertFalse(failed_unsubscribe[HLA_MOM.SUCCESS_INDICATOR])
            failed_unsubscribe_serial = failed_unsubscribe[HLA_MOM.SERIAL_NUMBER]
            self.assertEqual(
                failed_unsubscribe_serial, success_subscribe[HLA_MOM.SERIAL_NUMBER] + 1
            )
            self.assertTrue(
                failed_unsubscribe[HLA_MOM.EXCEPTION].startswith("InvalidRegion:")
            )
            self.assertEqual(
                [
                    argument[HLA_MOM.ARGUMENT_TYPE]
                    for argument in failed_unsubscribe[HLA_MOM.SUPPLIED_ARGUMENTS]
                ],
                [27, 43],
            )

            before_success_unsubscribe = report_file.read_text(encoding="utf-8")
            ambassador.unsubscribeInteractionClassWithRegions(
                interaction_class, RegionHandleSet([region])
            )
            success_unsubscribe = decode_appended(before_success_unsubscribe)
            self.assertEqual(
                success_unsubscribe[HLA_MOM.SERVICE],
                "UnsubscribeInteractionClassWithRegions",
            )
            self.assertTrue(success_unsubscribe[HLA_MOM.SUCCESS_INDICATOR])
            self.assertEqual(
                success_unsubscribe[HLA_MOM.SERIAL_NUMBER],
                failed_unsubscribe_serial + 1,
            )
            self.assertIsNone(success_unsubscribe[HLA_MOM.EXCEPTION])
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if region is not None:
                try:
                    ambassador.deleteRegion(region)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_regional_subscription_failure_reaches_mom_callback(
        self,
    ) -> None:
        """Deliver a C++ regional-subscription failure through Java MOM callbacks."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-subscription-mom-{uuid4().hex[:12]}"
        subject = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        subject_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        subject_connected = observer_connected = False
        subject_joined = observer_joined = created = False
        invalid_region: RegionHandle | None = None

        def drain(rounds: int = 30) -> None:
            for _ in range(rounds):
                subject.evokeCallback(0.0)
                observer.evokeCallback(0.0)

        try:
            subject.connect(subject_callbacks, CallbackModel.HLA_EVOKED)
            subject_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_EVOKED)
            observer_connected = True
            subject.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            subject.joinFederationExecution(
                "jni-regional-subscription-mom-subject", federation_name
            )
            subject_joined = True
            observer.joinFederationExecution(
                "jni-regional-subscription-mom-observer", federation_name
            )
            observer_joined = True

            report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
            report_parameters = {
                name: observer.getParameterHandle(report_class, name)
                for name in (
                    HLA_MOM.SERVICE,
                    HLA_MOM.SERVICE_TYPE,
                    HLA_MOM.SUCCESS_INDICATOR,
                    HLA_MOM.SUPPLIED_ARGUMENTS,
                    HLA_MOM.RETURNED_ARGUMENT,
                    HLA_MOM.EXCEPTION,
                    HLA_MOM.SERIAL_NUMBER,
                )
            }
            observer.setServiceReportingSwitch(False)
            observer.subscribeInteractionClass(report_class)
            subject.setServiceReportingSwitch(False)
            subject.setSendServiceReportsToFileSwitch(False)

            interaction_class = subject.getInteractionClassHandle(
                HLA_FOM.MAIN_COURSE_SERVED
            )
            dimension = subject.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            invalid_region = subject.createRegion(DimensionHandleSet([dimension]))
            subject.setRangeBounds(invalid_region, dimension, RangeBounds(0, 10))
            subject.commitRegionModifications(RegionHandleSet([invalid_region]))
            subject.deleteRegion(invalid_region)

            subject.setServiceReportingSwitch(True)
            subject.setSendServiceReportsToFileSwitch(False)
            with self.assertRaises(InvalidRegion):
                subject.subscribeInteractionClassWithRegions(
                    interaction_class, RegionHandleSet([invalid_region])
                )
            drain()
            self.assertEqual(len(observer_callbacks.received_interactions), 1)
            report = observer_callbacks.received_interactions[0]
            self.assertEqual(report[0], report_class)
            self.assertEqual(report[2], b"")

            values = dict(report[1])
            encoder = self.factory.getEncoderFactory()
            self.assertEqual(
                encoder.createHLAunicodeString()
                .decode(values[report_parameters[HLA_MOM.SERVICE]])
                .getValue(),
                "SubscribeInteractionClassWithRegions",
            )
            self.assertEqual(
                encoder.createHLAinteger16BE()
                .decode(values[report_parameters[HLA_MOM.SERVICE_TYPE]])
                .getValue(),
                5,
            )
            self.assertFalse(
                encoder.createHLAboolean()
                .decode(values[report_parameters[HLA_MOM.SUCCESS_INDICATOR]])
                .getValue()
            )

            class _MomArgumentFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(encoder.createHLAinteger32BE())
                    record.appendElement(encoder.createHLAunicodeString())
                    record.appendElement(encoder.createHLAunicodeString())
                    return record

            supplied_arguments = encoder.createHLAvariableArray(_MomArgumentFactory())
            supplied_arguments.decode(
                values[report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]]
            )
            self.assertEqual(supplied_arguments.size(), 3)
            self.assertEqual(supplied_arguments.get(0).get(0).getValue(), 27)
            self.assertEqual(
                supplied_arguments.get(0).get(1).getValue(),
                "Interaction class designator",
            )
            self.assertEqual(supplied_arguments.get(1).get(0).getValue(), 43)
            self.assertEqual(
                supplied_arguments.get(1).get(1).getValue(),
                "Set of region designators",
            )
            self.assertIn("RegionHandle(", supplied_arguments.get(1).get(2).getValue())
            self.assertEqual(supplied_arguments.get(2).get(0).getValue(), 6)
            self.assertEqual(
                supplied_arguments.get(2).get(1).getValue(),
                "Optional passive subscription indicator",
            )
            self.assertEqual(supplied_arguments.get(2).get(2).getValue(), "false")

            returned_argument = encoder.createHLAfixedRecord()
            returned_argument.appendElement(encoder.createHLAinteger32BE())
            returned_argument.appendElement(encoder.createHLAunicodeString())
            returned_argument.appendElement(encoder.createHLAunicodeString())
            returned_argument.decode(
                values[report_parameters[HLA_MOM.RETURNED_ARGUMENT]]
            )
            self.assertEqual(returned_argument.get(0).getValue(), 34)
            self.assertEqual(returned_argument.get(1).getValue(), "")
            self.assertEqual(returned_argument.get(2).getValue(), "null")
            self.assertTrue(
                encoder.createHLAunicodeString()
                .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                .getValue()
                .startswith("InvalidRegion:")
            )
            self.assertGreaterEqual(
                encoder.createHLAinteger32BE()
                .decode(values[report_parameters[HLA_MOM.SERIAL_NUMBER]])
                .getValue(),
                0,
            )
        finally:
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if subject_joined:
                try:
                    subject.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    subject.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if subject_connected:
                try:
                    subject.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            subject._implementation.close()

    def test_cpp_jni_java_jpype_regional_association_failure_reaches_mom_callback(
        self,
    ) -> None:
        """Deliver failed and successful regional association reports through standard MOM."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        switch_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-regional-association-mom-{uuid4().hex[:12]}"
        subject = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        subject_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        subject_connected = observer_connected = False
        subject_joined = observer_joined = created = False
        owner_region: RegionHandle | None = None
        disjoint_region: RegionHandle | None = None
        object_instance: ObjectInstanceHandle | None = None

        def decode_report(
            index: int,
            service: str,
            success: bool,
            expected_exception: str | None,
            expected_first_type: int,
            expected_pair_count: int,
        ) -> None:
            self.assertGreater(len(observer_callbacks.received_interactions), index)
            report = observer_callbacks.received_interactions[index]
            self.assertEqual(report[0], report_class)
            values = dict(report[1])
            encoder = self.factory.getEncoderFactory()
            self.assertEqual(
                encoder.createHLAunicodeString()
                .decode(values[report_parameters[HLA_MOM.SERVICE]])
                .getValue(),
                service,
            )
            self.assertEqual(
                encoder.createHLAinteger16BE()
                .decode(values[report_parameters[HLA_MOM.SERVICE_TYPE]])
                .getValue(),
                5,
            )
            self.assertEqual(
                encoder.createHLAboolean()
                .decode(values[report_parameters[HLA_MOM.SUCCESS_INDICATOR]])
                .getValue(),
                success,
            )

            class _MomArgumentFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(encoder.createHLAinteger32BE())
                    record.appendElement(encoder.createHLAunicodeString())
                    record.appendElement(encoder.createHLAunicodeString())
                    return record

            supplied = encoder.createHLAvariableArray(_MomArgumentFactory())
            supplied.decode(values[report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]])
            self.assertEqual(supplied.size(), expected_pair_count)
            self.assertEqual(supplied.get(0).get(0).getValue(), expected_first_type)
            self.assertIn("designator", supplied.get(0).get(1).getValue().lower())
            self.assertGreaterEqual(supplied.size(), 2)
            self.assertEqual(supplied.get(1).get(0).getValue(), 4)
            self.assertIn("attribute", supplied.get(1).get(1).getValue().lower())
            self.assertIn("region", supplied.get(1).get(1).getValue().lower())

            returned = encoder.createHLAfixedRecord()
            returned.appendElement(encoder.createHLAinteger32BE())
            returned.appendElement(encoder.createHLAunicodeString())
            returned.appendElement(encoder.createHLAunicodeString())
            returned.decode(values[report_parameters[HLA_MOM.RETURNED_ARGUMENT]])
            self.assertEqual(returned.get(0).getValue(), 34)
            self.assertEqual(returned.get(1).getValue(), "")
            self.assertEqual(returned.get(2).getValue(), "null")
            exception = (
                encoder.createHLAunicodeString()
                .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                .getValue()
            )
            if expected_exception is None:
                self.assertEqual(exception, "")
            else:
                self.assertTrue(exception.startswith(expected_exception))
            self.assertEqual(
                encoder.createHLAinteger32BE()
                .decode(values[report_parameters[HLA_MOM.SERIAL_NUMBER]])
                .getValue(),
                index,
            )

        try:
            subject.connect(subject_callbacks, CallbackModel.HLA_EVOKED)
            subject_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_IMMEDIATE)
            observer_connected = True
            subject.createFederationExecution(
                federation_name,
                [str(fom_module), str(switch_module)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            subject.joinFederationExecution(
                "jni-regional-association-mom-subject", federation_name
            )
            subject_joined = True
            observer.joinFederationExecution(
                "jni-regional-association-mom-observer", federation_name
            )
            observer_joined = True

            report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
            report_parameters = {
                name: observer.getParameterHandle(report_class, name)
                for name in (
                    HLA_MOM.SERVICE,
                    HLA_MOM.SERVICE_TYPE,
                    HLA_MOM.SUCCESS_INDICATOR,
                    HLA_MOM.SUPPLIED_ARGUMENTS,
                    HLA_MOM.RETURNED_ARGUMENT,
                    HLA_MOM.EXCEPTION,
                    HLA_MOM.SERIAL_NUMBER,
                )
            }
            observer.setServiceReportingSwitch(False)
            observer.subscribeInteractionClass(report_class)
            subject.setServiceReportingSwitch(False)
            subject.setSendServiceReportsToFileSwitch(False)

            soda = subject.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            flavor = subject.getAttributeHandle(soda, HLA_FIXTURES.FLAVOR)
            soda_flavor = subject.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            flavor_set = AttributeHandleSet([flavor])
            subject.publishObjectClassAttributes(soda, flavor_set)
            owner_region = subject.createRegion(DimensionHandleSet([soda_flavor]))
            subject.setRangeBounds(owner_region, soda_flavor, RangeBounds(0, 1))
            subject.commitRegionModifications(RegionHandleSet([owner_region]))

            def pair_list(region: RegionHandle) -> AttributeSetRegionSetPairList:
                pairs = subject.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(flavor_set, RegionHandleSet([region]))
                )
                return pairs

            owner_pairs = pair_list(owner_region)
            object_instance = subject.registerObjectInstanceWithRegions(
                soda, owner_pairs
            )
            while subject.evokeCallback(0.0):
                pass
            unknown_object = ObjectInstanceHandle(
                object_instance.encodedValue[:-1]
                + bytes((object_instance.encodedValue[-1] ^ 0xFF,))
            )
            disjoint_region = subject.createRegion(DimensionHandleSet([soda_flavor]))
            subject.setRangeBounds(disjoint_region, soda_flavor, RangeBounds(2, 3))
            subject.commitRegionModifications(RegionHandleSet([disjoint_region]))
            valid_pairs = pair_list(disjoint_region)
            unknown_region = RegionHandle(
                disjoint_region.encodedValue[:-1]
                + bytes((disjoint_region.encodedValue[-1] ^ 0xFF,))
            )
            invalid_pairs = subject.getAttributeSetRegionSetPairListFactory().create(1)
            invalid_pairs.add(
                AttributeSetRegionSetPair(flavor_set, RegionHandleSet([unknown_region]))
            )
            empty_pairs = subject.getAttributeSetRegionSetPairListFactory().create(0)

            subject.setServiceReportingSwitch(True)
            with self.assertRaises(ObjectInstanceNotKnown):
                subject.associateRegionsForUpdates(unknown_object, empty_pairs)
            decode_report(
                0, "AssociateRegionsForUpdates", False, "ObjectInstanceNotKnown:", 37, 2
            )
            with self.assertRaises(ObjectInstanceNotKnown):
                subject.unassociateRegionsForUpdates(unknown_object, empty_pairs)
            decode_report(
                1,
                "UnassociateRegionsForUpdates",
                False,
                "ObjectInstanceNotKnown:",
                37,
                2,
            )
            assert object_instance is not None
            with self.assertRaises(InvalidRegion):
                subject.associateRegionsForUpdates(object_instance, invalid_pairs)
            decode_report(
                2, "AssociateRegionsForUpdates", False, "InvalidRegion:", 37, 2
            )
            with self.assertRaises(InvalidRegion):
                subject.unassociateRegionsForUpdates(object_instance, invalid_pairs)
            decode_report(
                3, "UnassociateRegionsForUpdates", False, "InvalidRegion:", 37, 2
            )
            subject.associateRegionsForUpdates(object_instance, valid_pairs)
            decode_report(4, "AssociateRegionsForUpdates", True, None, 37, 2)
            subject.unassociateRegionsForUpdates(object_instance, valid_pairs)
            decode_report(5, "UnassociateRegionsForUpdates", True, None, 37, 2)
            self.assertEqual(len(observer_callbacks.received_interactions), 6)
        finally:
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if subject_joined:
                try:
                    subject.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    subject.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if subject_connected:
                try:
                    subject.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            subject._implementation.close()

