    def test_cpp_jni_java_jpype_transport_loss_delivers_timestamped_interaction_before_cutoff(
        self,
    ) -> None:
        """Deliver a TSO strictly before the lost publisher's cutoff boundary."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )
        federation_name = f"jni-before-cutoff-tso-transport-{uuid4().hex[:12]}"
        lost = self.factory.getRtiAmbassador()
        surviving = self.factory.getRtiAmbassador()

        class _OrderingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[str] = []

            def receiveInteraction(self, *args: object, **kwargs: object) -> None:
                self.events.append("interaction")
                super().receiveInteraction(*args, **kwargs)

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                self.events.append("grant")
                super().timeAdvanceGrant(time)

        lost_callbacks = _JniCallbacks()
        surviving_callbacks = _OrderingCallbacks()
        lost_connected = surviving_connected = created = False
        lost_joined = surviving_joined = False
        try:
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED)
            lost_connected = True
            surviving.connect(surviving_callbacks, CallbackModel.HLA_EVOKED)
            surviving_connected = True
            lost.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            lost_federate = lost.joinFederationExecution(
                "jni-before-cutoff-lost-publisher",
                federation_name,
                federateName="jni-before-cutoff-lost-publisher",
            )
            lost_joined = True
            surviving.joinFederationExecution(
                "jni-before-cutoff-surviving-subscriber", federation_name
            )
            surviving_joined = True

            interaction = lost.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            identifier = lost.getParameterHandle(interaction, HLA_FIXTURES.IDENTIFIER)
            lost.publishInteractionClass(interaction)
            lost.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            surviving.subscribeInteractionClass(interaction)
            surviving.enableTimeConstrained()
            self.assertFalse(surviving.evokeCallback(0.0))
            self.assertEqual(len(surviving_callbacks.time_constrained_enabled), 1)

            time_factory = lost.getTimeFactory()
            lost.enableTimeRegulation(time_factory.makeLogicalTimeInterval(5))
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(len(lost_callbacks.time_regulation_enabled), 1)

            values = ParameterHandleValueMap({identifier: b"\x5a\x11"})
            tag = b"LESS"
            retraction = lost.sendInteractionWithTime(
                interaction, values, time_factory.makeLogicalTime(5), tag
            )
            self.assertTrue(retraction.isValid())
            surviving.timeAdvanceRequest(surviving.getTimeFactory().makeLogicalTime(6))
            lost.timeAdvanceRequest(time_factory.makeLogicalTime(6))
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.time_advance_grants[-1].getTime(), 6)
            self.assertEqual(surviving_callbacks.timestamped_interactions, [])
            self.assertEqual(surviving_callbacks.time_advance_grants, [])

            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
            string_class = jpype.JClass("java.lang.String").class_
            fault_method = native_handler_class.getDeclaredMethod(
                "failEmbeddedTransportConnectionForTesting",
                rti_interface_class,
                string_class,
            )
            fault_method.setAccessible(True)
            fault = "strictly-before cutoff transport fault"
            self.assertTrue(
                bool(fault_method.invoke(None, lost.unwrap_java_object(), fault))
            )
            lost_joined = False

            self.assertFalse(surviving.evokeCallback(0.0))
            self.assertEqual(surviving_callbacks.events, ["interaction", "grant"])
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.connection_lost, [fault])
            self.assertEqual(len(surviving_callbacks.timestamped_interactions), 1)
            report = surviving_callbacks.timestamped_interactions[0]
            self.assertEqual(report[0], interaction)
            self.assertEqual(dict(report[1]), {identifier: b"\x5a\x11"})
            self.assertEqual(report[2], tag)
            self.assertEqual(report[4], lost_federate)
            self.assertEqual(report[6].getTime(), 5)
            self.assertEqual(report[7], OrderType.TIMESTAMP)
            self.assertEqual(report[8], OrderType.TIMESTAMP)
            self.assertTrue(report[9].isValid())
            self.assertEqual(report[9].encodedValue, retraction.encodedValue)
            self.assertEqual(surviving_callbacks.time_advance_grants[-1].getTime(), 6)
        finally:
            if lost_joined:
                try:
                    lost.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if surviving_joined:
                try:
                    surviving.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    surviving.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if lost_connected:
                try:
                    lost.disconnect()
                except Exception:
                    pass
            if surviving_connected:
                try:
                    surviving.disconnect()
                except Exception:
                    pass
            lost._implementation.close()
            surviving._implementation.close()

