            lost.publishInteractionClass(interaction)
            lost.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            surviving.subscribeInteractionClass(interaction)
            surviving.enableTimeConstrained()
            self.assertFalse(surviving.evokeCallback(0.0))
            self.assertEqual(len(surviving_callbacks.time_constrained_enabled), 1)

            time_factory = lost.getTimeFactory()
            lost.enableTimeRegulation(time_factory.makeLogicalTimeInterval(5))
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(len(lost_callbacks.time_regulation_enabled), 1)

            values = ParameterHandleValueMap({identifier: b"\xa6\xa7"})
            tag = b"FUTURE"
            retraction = lost.sendInteractionWithTime(
                interaction, values, time_factory.makeLogicalTime(6), tag
            )
            self.assertTrue(retraction.isValid())
            lost.timeAdvanceRequest(time_factory.makeLogicalTime(6))
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.time_advance_grants[-1].getTime(), 6)
            self.assertEqual(surviving_callbacks.timestamped_interactions, [])
            self.assertEqual(surviving_callbacks.time_advance_grants, [])

