    def test_cpp_jni_java_jpype_transport_loss_delete_objects_cleanup(self) -> None:
        """Apply the standard DELETE_OBJECTS directive during C++ transport loss."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"jni-loss-delete-{uuid4().hex[:12]}"
        lost = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        lost_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        lost_connected = survivor_connected = created = False
        lost_joined = survivor_joined = False
        object_instance: ObjectInstanceHandle | None = None
        object_name: str | None = None
        lost_federate: FederateHandle | None = None
        try:
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED)
            lost_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            lost.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            lost_federate = lost.joinFederationExecution(
                "jni-loss-delete-lost",
                federation_name,
                federateName="jni-loss-delete-lost",
            )
            lost_joined = True
            survivor.joinFederationExecution(
                "jni-loss-delete-survivor",
                federation_name,
                federateName="jni-loss-delete-survivor",
            )
            survivor_joined = True

            object_class = lost.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            lost_attribute = lost.getAttributeHandle(
                object_class, HLA_FIXTURES.EFFICIENCY
            )
            survivor_class = survivor.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            survivor_attribute = survivor.getAttributeHandle(
                survivor_class, HLA_FIXTURES.EFFICIENCY
            )
            lost.publishObjectClassAttributes(
                object_class, AttributeHandleSet([lost_attribute])
            )
            survivor.subscribeObjectClassAttributes(
                survivor_class, AttributeHandleSet([survivor_attribute])
            )
            object_instance = lost.registerObjectInstance(object_class)
            object_name = lost.getObjectInstanceName(object_instance)
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if survivor_callbacks.discovered_objects:
                    break
            self.assertEqual(
                survivor_callbacks.discovered_objects[-1][0], object_instance
            )
            self.assertEqual(survivor_callbacks.removed_objects, [])

            # This is the standard Java service, not a test-only transport
            # setting. C++ owns the resulting automatic-resign disposition.
            lost.setAutomaticResignDirective(ResignAction.DELETE_OBJECTS)
            self.assertEqual(
                lost.getAutomaticResignDirective(), ResignAction.DELETE_OBJECTS
            )

            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
            string_class = jpype.JClass("java.lang.String").class_
            fault_method = native_handler_class.getDeclaredMethod(
                "failEmbeddedTransportConnectionForTesting",
                rti_interface_class,
                string_class,
            )
            fault_method.setAccessible(True)
            fault = "automatic delete transport fault"
            self.assertTrue(
                bool(fault_method.invoke(None, lost.unwrap_java_object(), fault))
            )
            lost_joined = False

            # The C++ automatic-resign cleanup queues both standard callback
            # paths; no Java-side object deletion is synthesized by JPype.
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.connection_lost, [fault])
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if survivor_callbacks.removed_objects:
                    break
            self.assertEqual(
                survivor_callbacks.removed_objects,
                [(object_instance, b"", lost_federate)],
            )
            self.assertEqual(
                survivor.getFederateName(lost_federate), "jni-loss-delete-lost"
            )
            with self.assertRaises(ObjectInstanceNotKnown):
                survivor.getObjectInstanceHandle(object_name)
        finally:
            if lost_joined:
                try:
                    lost.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    survivor.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if lost_connected:
                try:
                    lost.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            lost._implementation.close()
            survivor._implementation.close()

