    def test_cpp_jni_java_jpype_transport_loss_no_action_assumption_policy(
        self,
    ) -> None:
        """Apply the bounded NO_ACTION policy when a transport loss removes an owner."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"jni-loss-no-action-{uuid4().hex[:12]}"
        lost = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        lost_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        lost_connected = survivor_connected = created = False
        lost_joined = survivor_joined = False
        object_instance: ObjectInstanceHandle | None = None
        object_name: str | None = None
        lost_federate: FederateHandle | None = None
        try:
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED)
            lost_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            lost.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            lost_federate = lost.joinFederationExecution(
                "automatic-no-action-lost",
                federation_name,
                federateName="automatic-no-action-lost",
            )
            lost_joined = True
            survivor.joinFederationExecution(
                "automatic-no-action-survivor",
                federation_name,
                federateName="automatic-no-action-survivor",
            )
            survivor_joined = True

            lost_class = lost.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            survivor_class = survivor.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            lost_efficiency = lost.getAttributeHandle(
                lost_class, HLA_FIXTURES.EFFICIENCY
            )
            survivor_efficiency = survivor.getAttributeHandle(
                survivor_class, HLA_FIXTURES.EFFICIENCY
            )
            lost_privilege = lost.getAttributeHandle(
                lost_class, HLA_MOM.PRIVILEGE_TO_DELETE_OBJECT
            )
            survivor_privilege = survivor.getAttributeHandle(
                survivor_class, HLA_MOM.PRIVILEGE_TO_DELETE_OBJECT
            )
            lost_attributes = AttributeHandleSet([lost_efficiency])
            survivor_attributes = AttributeHandleSet([survivor_efficiency])
            expected_assumption = AttributeHandleSet(
                [survivor_efficiency, survivor_privilege]
            )
            lost.publishObjectClassAttributes(lost_class, lost_attributes)
            survivor.subscribeObjectClassAttributes(survivor_class, survivor_attributes)
            survivor.publishObjectClassAttributes(survivor_class, survivor_attributes)

            object_instance = lost.registerObjectInstance(lost_class)
            object_name = lost.getObjectInstanceName(object_instance)
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if survivor_callbacks.discovered_objects:
                    break
            self.assertEqual(
                survivor_callbacks.discovered_objects,
                [
                    (
                        object_instance,
                        survivor_class,
                        object_name,
                        lost_federate,
                    )
                ],
            )

            lost.setAutomaticResignDirective(ResignAction.NO_ACTION)
            self.assertEqual(lost.getAutomaticResignDirective(), ResignAction.NO_ACTION)

            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
            string_class = jpype.JClass("java.lang.String").class_
            fault_method = native_handler_class.getDeclaredMethod(
                "failEmbeddedTransportConnectionForTesting",
                rti_interface_class,
                string_class,
            )
            fault_method.setAccessible(True)
            fault = "automatic NoAction transport fault"
            self.assertTrue(
                bool(fault_method.invoke(None, lost.unwrap_java_object(), fault))
            )
            lost_joined = False

            # Transport failure queues the standard Java callback; the C++
            # cleanup policy is applied only when the callback is evoked.
            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.connection_lost, [fault])
            self.assertEqual(survivor_callbacks.ownership_assumptions, [])
            self.assertEqual(survivor_callbacks.removed_objects, [])
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if survivor_callbacks.ownership_assumptions:
                    break
            self.assertEqual(len(survivor_callbacks.ownership_assumptions), 1)
            assumed_object, assumed_attributes, assumed_tag = (
                survivor_callbacks.ownership_assumptions[0]
            )
            self.assertEqual(assumed_object, object_instance)
            self.assertEqual(assumed_attributes, expected_assumption)
            self.assertEqual(assumed_tag, b"")
            self.assertEqual(survivor_callbacks.removed_objects, [])
            self.assertEqual(
                survivor.getObjectInstanceHandle(object_name), object_instance
            )
            self.assertFalse(
                survivor.isAttributeOwnedByFederate(
                    object_instance, survivor_efficiency
                )
            )
            self.assertFalse(
                survivor.isAttributeOwnedByFederate(object_instance, survivor_privilege)
            )
            self.assertEqual(
                survivor.getFederateName(lost_federate), "automatic-no-action-lost"
            )

            survivor.resignFederationExecution(ResignAction.NO_ACTION)
            survivor_joined = False
            survivor.destroyFederationExecution(federation_name)
            created = False
            # Match the C++ lifetime check: a transport-lost ambassador can
            # reconnect after the federation has been cleaned up.
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED)
            lost_connected = True
            lost.disconnect()
            lost_connected = False
        finally:
            if lost_joined:
                try:
                    lost.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    survivor.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if lost_connected:
                try:
                    lost.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            lost._implementation.close()
            survivor._implementation.close()

    def test_cpp_jni_java_jpype_transport_loss_delete_then_divest(self) -> None:
        """Exercise C++ delete-then-divest cleanup for two owned-object paths."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"jni-loss-delete-divest-{uuid4().hex[:12]}"
        lost = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        lost_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        lost_connected = survivor_connected = created = False
        lost_joined = survivor_joined = False
        retained_object: ObjectInstanceHandle | None = None
        deleted_object: ObjectInstanceHandle | None = None
        retained_name: str | None = None
        deleted_name: str | None = None
        lost_federate: FederateHandle | None = None
        try:
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED)
            lost_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            survivor.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            lost_federate = lost.joinFederationExecution(
                "jni-loss-delete-divest-lost",
                federation_name,
                federateName="jni-loss-delete-divest-lost",
            )
            lost_joined = True
            survivor.joinFederationExecution(
                "jni-loss-delete-divest-survivor",
                federation_name,
                federateName="jni-loss-delete-divest-survivor",
            )
            survivor_joined = True

            lost_class = lost.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            survivor_class = survivor.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            lost_efficiency = lost.getAttributeHandle(
                lost_class, HLA_FIXTURES.EFFICIENCY
            )
            survivor_efficiency = survivor.getAttributeHandle(
                survivor_class, HLA_FIXTURES.EFFICIENCY
            )
            efficiency = AttributeHandleSet([lost_efficiency])
            survivor.publishObjectClassAttributes(
                survivor_class, AttributeHandleSet([survivor_efficiency])
            )
            survivor.subscribeObjectClassAttributes(
                survivor_class, AttributeHandleSet([survivor_efficiency])
            )
            lost.publishObjectClassAttributes(lost_class, efficiency)
            lost.subscribeObjectClassAttributes(lost_class, efficiency)

            # The retained object starts on the survivor, transfers its one
            # attribute to the federate that will later lose its connection,
            # and must survive DELETE_OBJECTS_THEN_DIVEST.
            retained_object = survivor.registerObjectInstance(survivor_class)
            retained_name = survivor.getObjectInstanceName(retained_object)
            for _ in range(20):
                lost.evokeCallback(0.0)
                if lost_callbacks.discovered_objects:
                    break
            self.assertEqual(lost_callbacks.discovered_objects[-1][0], retained_object)
            survivor.unconditionalAttributeOwnershipDivestiture(
                retained_object,
                AttributeHandleSet([survivor_efficiency]),
                b"manual-divest",
            )
            for _ in range(20):
                lost.evokeCallback(0.0)
                if lost_callbacks.ownership_assumptions:
                    break
            self.assertEqual(len(lost_callbacks.ownership_assumptions), 1)
            lost.attributeOwnershipAcquisitionIfAvailable(
                retained_object, efficiency, b"acquire-retained"
            )
            for _ in range(20):
                lost.evokeCallback(0.0)
                if lost_callbacks.ownership_acquisitions:
                    break
            self.assertEqual(len(lost_callbacks.ownership_acquisitions), 1)

            # This second object is owned and registered by the lost member;
            # the same directive must delete it before divesting the retained
            # object's transferred attribute.
            deleted_object = lost.registerObjectInstance(lost_class)
            deleted_name = lost.getObjectInstanceName(deleted_object)
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if survivor_callbacks.discovered_objects:
                    break
            self.assertEqual(
                survivor_callbacks.discovered_objects[-1][0], deleted_object
            )

            lost.setAutomaticResignDirective(ResignAction.DELETE_OBJECTS_THEN_DIVEST)
            self.assertEqual(
                lost.getAutomaticResignDirective(),
                ResignAction.DELETE_OBJECTS_THEN_DIVEST,
            )
            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
            string_class = jpype.JClass("java.lang.String").class_
            fault_method = native_handler_class.getDeclaredMethod(
                "failEmbeddedTransportConnectionForTesting",
                rti_interface_class,
                string_class,
            )
            fault_method.setAccessible(True)
            fault = "automatic delete-then-divest transport fault"
            self.assertTrue(
                bool(fault_method.invoke(None, lost.unwrap_java_object(), fault))
            )
            lost_joined = False

            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.connection_lost, [fault])
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if (
                    survivor_callbacks.removed_objects
                    and survivor_callbacks.ownership_assumptions
                ):
                    break
            self.assertEqual(
                survivor_callbacks.removed_objects,
                [(deleted_object, b"", lost_federate)],
            )
            self.assertEqual(len(survivor_callbacks.ownership_assumptions), 1)
            assumed_object, assumed_attributes, assumed_tag = (
                survivor_callbacks.ownership_assumptions[0]
            )
            self.assertEqual(assumed_object, retained_object)
            self.assertEqual(
                assumed_attributes, AttributeHandleSet([survivor_efficiency])
            )
            self.assertEqual(assumed_tag, b"")
            self.assertEqual(
                survivor.getObjectInstanceHandle(retained_name), retained_object
            )
            with self.assertRaises(ObjectInstanceNotKnown):
                survivor.getObjectInstanceHandle(deleted_name)
        finally:
            if lost_joined:
                try:
                    lost.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(ResignAction.DELETE_OBJECTS)
                except Exception:
                    pass
            if created:
                try:
                    survivor.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if lost_connected:
                try:
                    lost.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            lost._implementation.close()
            survivor._implementation.close()

    def test_cpp_jni_java_jpype_transport_loss_cancel_delete_then_divest(
        self,
    ) -> None:
        """Apply the combined automatic-resign directive through JNI."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"jni-loss-cancel-delete-divest-{uuid4().hex[:12]}"
        lost = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        lost_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        lost_connected = survivor_connected = created = False
        lost_joined = survivor_joined = False
        retained_object: ObjectInstanceHandle | None = None
        deleted_object: ObjectInstanceHandle | None = None
        acquisition_target: ObjectInstanceHandle | None = None
        retained_name: str | None = None
        deleted_name: str | None = None
        lost_federate: FederateHandle | None = None
        try:
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED)
            lost_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            survivor.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            lost_federate = lost.joinFederationExecution(
                "jni-loss-cancel-delete-divest-lost",
                federation_name,
                federateName="jni-loss-cancel-delete-divest-lost",
            )
            lost_joined = True
            survivor.joinFederationExecution(
                "jni-loss-cancel-delete-divest-survivor",
                federation_name,
                federateName="jni-loss-cancel-delete-divest-survivor",
            )
            survivor_joined = True

            lost_class = lost.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            survivor_class = survivor.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            lost_efficiency = lost.getAttributeHandle(
                lost_class, HLA_FIXTURES.EFFICIENCY
            )
            survivor_efficiency = survivor.getAttributeHandle(
                survivor_class, HLA_FIXTURES.EFFICIENCY
            )
            lost_attributes = AttributeHandleSet([lost_efficiency])
            survivor_attributes = AttributeHandleSet([survivor_efficiency])
            lost.publishObjectClassAttributes(lost_class, lost_attributes)
            lost.subscribeObjectClassAttributes(lost_class, lost_attributes)
            survivor.publishObjectClassAttributes(survivor_class, survivor_attributes)
            survivor.subscribeObjectClassAttributes(survivor_class, survivor_attributes)

            # Transfer a retained, non-delete-privileged attribute to the
            # member that will later lose transport.
            retained_object = survivor.registerObjectInstance(survivor_class)
            retained_name = survivor.getObjectInstanceName(retained_object)
            for _ in range(20):
                lost.evokeCallback(0.0)
                if lost_callbacks.discovered_objects:
                    break
            self.assertEqual(lost_callbacks.discovered_objects[-1][0], retained_object)
            survivor.unconditionalAttributeOwnershipDivestiture(
                retained_object, survivor_attributes, b"jni-combined-divest"
            )
            for _ in range(20):
                lost.evokeCallback(0.0)
                if lost_callbacks.ownership_assumptions:
                    break
            self.assertEqual(len(lost_callbacks.ownership_assumptions), 1)
            lost.attributeOwnershipAcquisitionIfAvailable(
                retained_object, lost_attributes, b"jni-combined-acquire"
            )
            for _ in range(20):
                lost.evokeCallback(0.0)
                if lost_callbacks.ownership_acquisitions:
                    break
            self.assertEqual(len(lost_callbacks.ownership_acquisitions), 1)

            # A lost-owned object is removed during the delete phase.
            deleted_object = lost.registerObjectInstance(lost_class)
            deleted_name = lost.getObjectInstanceName(deleted_object)
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if survivor_callbacks.discovered_objects:
                    break
            self.assertEqual(
                survivor_callbacks.discovered_objects[-1][0], deleted_object
            )

            # Keep a regular acquisition queued at the survivor so the cancel
            # phase has an observable stale owner-release callback to remove.
            acquisition_target = survivor.registerObjectInstance(survivor_class)
            for _ in range(20):
                lost.evokeCallback(0.0)
                if len(lost_callbacks.discovered_objects) >= 2:
                    break
            self.assertEqual(
                lost_callbacks.discovered_objects[-1][0], acquisition_target
            )
            lost.attributeOwnershipAcquisition(
                acquisition_target, lost_attributes, b"jni-combined-pending"
            )
            self.assertEqual(survivor_callbacks.ownership_release_requests, [])

            lost.setAutomaticResignDirective(
                ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
            )
            self.assertEqual(
                lost.getAutomaticResignDirective(),
                ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST,
            )
            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
            string_class = jpype.JClass("java.lang.String").class_
            fault_method = native_handler_class.getDeclaredMethod(
                "failEmbeddedTransportConnectionForTesting",
                rti_interface_class,
                string_class,
            )
            fault_method.setAccessible(True)
            fault = "automatic cancel-delete-divest transport fault"
            self.assertTrue(
                bool(fault_method.invoke(None, lost.unwrap_java_object(), fault))
            )
            lost_joined = False

            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.connection_lost, [fault])
            for _ in range(20):
                survivor.evokeCallback(0.0)
                if (
                    survivor_callbacks.removed_objects
                    and survivor_callbacks.ownership_assumptions
                ):
                    break
            self.assertEqual(survivor_callbacks.ownership_release_requests, [])
            self.assertEqual(
                survivor_callbacks.removed_objects,
                [(deleted_object, b"", lost_federate)],
            )
            self.assertEqual(len(survivor_callbacks.ownership_assumptions), 1)
            assumed_object, assumed_attributes, assumed_tag = (
                survivor_callbacks.ownership_assumptions[0]
            )
            self.assertEqual(assumed_object, retained_object)
            self.assertEqual(assumed_attributes, survivor_attributes)
            self.assertEqual(assumed_tag, b"")
            self.assertEqual(
                survivor.getObjectInstanceHandle(retained_name), retained_object
            )
            with self.assertRaises(ObjectInstanceNotKnown):
                survivor.getObjectInstanceHandle(deleted_name)
            self.assertFalse(
                survivor.isAttributeOwnedByFederate(
                    retained_object, survivor_efficiency
                )
            )
        finally:
            if lost_joined:
                try:
                    lost.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    survivor.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if lost_connected:
                try:
                    lost.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            lost._implementation.close()
            survivor._implementation.close()

