    def test_cpp_jni_java_jpype_evoked_restore_drops_resigning_member_callbacks(
        self,
    ) -> None:
        """Drop queued restore callbacks when an evoked member resigns."""

        class RestoreEvents(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[str] = []

            def requestFederationRestoreSucceeded(self, label: str) -> None:
                self.events.append("restore-request-succeeded")
                super().requestFederationRestoreSucceeded(label)

            def federationRestoreBegun(self) -> None:
                self.events.append("restore-begun")
                super().federationRestoreBegun()

            def initiateFederateRestore(
                self,
                label: str,
                federateName: str,
                postRestoreFederateHandle: FederateHandle,
            ) -> None:
                self.events.append("restore-initiate")
                super().initiateFederateRestore(
                    label, federateName, postRestoreFederateHandle
                )

            def federationNotRestored(self, reason: RestoreFailureReason) -> None:
                self.events.append("restore-failed")
                super().federationNotRestored(reason)

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-restore-queue-drop-{uuid4().hex[:12]}"
        survivor = self.factory.getRtiAmbassador()
        resigning = self.factory.getRtiAmbassador()
        survivor_callbacks = RestoreEvents()
        resigning_callbacks = RestoreEvents()
        survivor_connected = resigning_connected = created = False
        survivor_joined = resigning_joined = False

        def drain(ambassador: RTIambassador, rounds: int = 30) -> None:
            for _ in range(rounds):
                ambassador.evokeCallback(0.0)

        try:
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            resigning.connect(resigning_callbacks, CallbackModel.HLA_EVOKED)
            resigning_connected = True
            survivor.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            survivor.joinFederationExecution(
                "jni-restore-queue-survivor", federation_name
            )
            survivor_joined = True
            resigning.joinFederationExecution(
                "jni-restore-queue-resigning", federation_name
            )
            resigning_joined = True

            save_label = "jni-restore-queue-baseline"
            survivor.requestFederationSave(save_label)
            drain(survivor)
            drain(resigning)
            survivor.federateSaveBegun()
            resigning.federateSaveBegun()
            survivor.federateSaveComplete()
            resigning.federateSaveComplete()
            drain(survivor)
            drain(resigning)
            self.assertEqual(survivor_callbacks.saved_count, 1)
            self.assertEqual(resigning_callbacks.saved_count, 1)

            survivor_callbacks.events.clear()
            resigning_callbacks.events.clear()
            survivor_callbacks.restore_acceptances.clear()
            survivor_callbacks.restore_initiations.clear()
            survivor_callbacks.restore_failures.clear()
            resigning_callbacks.restore_acceptances.clear()
            resigning_callbacks.restore_initiations.clear()
            resigning_callbacks.restore_failures.clear()

            survivor.requestFederationRestore(save_label)
            self.assertEqual(survivor_callbacks.events, [])
            self.assertEqual(resigning_callbacks.events, [])

            # The resigning member has restore acceptance/begin/initiation
            # callbacks queued but not evoked. Resignation must invalidate its
            # private queue while leaving the survivor's ordered callbacks.
            resigning.resignFederationExecution(ResignAction.NO_ACTION)
            resigning_joined = False
            drain(survivor)
            self.assertEqual(
                survivor_callbacks.events,
                [
                    "restore-request-succeeded",
                    "restore-begun",
                    "restore-initiate",
                    "restore-failed",
                ],
            )
            self.assertEqual(
                survivor_callbacks.restore_failures,
                [RestoreFailureReason.FEDERATE_RESIGNED_DURING_RESTORE],
            )

            drain(resigning)
            self.assertEqual(resigning_callbacks.events, [])
            self.assertEqual(resigning_callbacks.restore_acceptances, [])
            self.assertEqual(resigning_callbacks.restore_initiations, [])
            self.assertEqual(resigning_callbacks.restore_failures, [])

            survivor.resignFederationExecution(ResignAction.NO_ACTION)
            survivor_joined = False
            survivor.destroyFederationExecution(federation_name)
            created = False
        finally:
            if resigning_joined:
                try:
                    resigning.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    survivor.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if resigning_connected:
                try:
                    resigning.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            resigning._implementation.close()
            survivor._implementation.close()

    def test_cpp_jni_java_jpype_object_name_reservation_matrix(self) -> None:
        """Preserve asynchronous single/batch name reservation semantics through JNI."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-object-name-reservation-{uuid4()}"
        unjoined = self.factory.getRtiAmbassador()
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        unjoined_callbacks = _JniCallbacks()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        unjoined_connected = owner_connected = peer_connected = False
        owner_joined = peer_joined = created = False
        try:
            with self.assertRaises(NotConnected):
                unjoined.reserveObjectInstanceName("Umbra.NotConnected")
            unjoined.connect(unjoined_callbacks, CallbackModel.HLA_EVOKED)
            unjoined_connected = True
            with self.assertRaises(FederateNotExecutionMember):
                unjoined.reserveObjectInstanceName("Umbra.NotJoined")

            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution("jni-name-owner", federation_name)
            owner_joined = True
            peer.joinFederationExecution("jni-name-peer", federation_name)
            peer_joined = True

            report_class = peer.getInteractionClassHandle(HLA_MOM.REPORT_EXCEPTION)
            report_parameters = {
                name: peer.getParameterHandle(report_class, name)
                for name in (HLA_MOM.SERVICE, HLA_MOM.EXCEPTION)
            }
            peer.subscribeInteractionClass(report_class)
            owner.setExceptionReportingSwitch(True)
            encoder = self.factory.getEncoderFactory()

            def report_at(index: int, service_name: str, exception_name: str) -> None:
                for _ in range(20):
                    peer.evokeCallback(0.0)
                    if len(peer_callbacks.received_interactions) > index:
                        break
                self.assertEqual(len(peer_callbacks.received_interactions), index + 1)
                report = peer_callbacks.received_interactions[index]
                self.assertEqual(report[0], report_class)
                values = dict(report[1])
                service = (
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue()
                )
                exception = (
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue()
                )
                self.assertEqual(service, service_name)
                self.assertTrue(exception.startswith(exception_name), exception)

            with self.assertRaises(IllegalName):
                owner.reserveObjectInstanceName("")
            report_at(0, "Reserve Object Instance Name", "IllegalName")
            with self.assertRaises(IllegalName):
                owner.reserveObjectInstanceName(
                    HLA_FIXTURES.RESERVED_OBJECT_INSTANCE_NAME
                )
            report_at(1, "Reserve Object Instance Name", "IllegalName")
            with self.assertRaises(NameSetWasEmpty):
                owner.reserveMultipleObjectInstanceNames(ObjectInstanceNameSet())
            report_at(2, "Reserve Multiple Object Instance Names", "NameSetWasEmpty")
            with self.assertRaises(IllegalName):
                owner.reserveMultipleObjectInstanceNames(
                    ObjectInstanceNameSet(
                        ["Umbra.Valid", HLA_FIXTURES.INVALID_OBJECT_INSTANCE_NAME]
                    )
                )
            report_at(3, "Reserve Multiple Object Instance Names", "IllegalName")

            single_name = "Umbra.JniSingleReservation"
            owner.reserveObjectInstanceName(single_name)
            for _ in range(20):
                owner.evokeCallback(0.0)
                if owner_callbacks.reserved_object_instance_names:
                    break
            self.assertEqual(
                owner_callbacks.reserved_object_instance_names, [single_name]
            )

            # Contention is asynchronous: the peer call succeeds, then the
            # standard failure callback carries the rejected name.
            peer.reserveObjectInstanceName(single_name)
            for _ in range(20):
                peer.evokeCallback(0.0)
                if peer_callbacks.rejected_object_instance_names:
                    break
            self.assertEqual(
                peer_callbacks.rejected_object_instance_names, [single_name]
            )
            owner.releaseObjectInstanceName(single_name)
            with self.assertRaises(ObjectInstanceNameNotReserved):
                owner.releaseObjectInstanceName(single_name)
            report_at(
                4, "Release Object Instance Name", "ObjectInstanceNameNotReserved"
            )
            peer.reserveObjectInstanceName(single_name)
            for _ in range(20):
                peer.evokeCallback(0.0)
                if peer_callbacks.reserved_object_instance_names:
                    break
            self.assertEqual(
                peer_callbacks.reserved_object_instance_names, [single_name]
            )
            peer.releaseObjectInstanceName(single_name)

            multiple_a = "Umbra.JniMultipleA"
            multiple_b = "Umbra.JniMultipleB"
            multiple_c = "Umbra.JniMultipleC"
            owner_batch = ObjectInstanceNameSet([multiple_a, multiple_b])
            owner.reserveMultipleObjectInstanceNames(owner_batch)
            for _ in range(20):
                owner.evokeCallback(0.0)
                if owner_callbacks.reserved_object_instance_name_sets:
                    break
            self.assertEqual(
                owner_callbacks.reserved_object_instance_name_sets, [owner_batch]
            )

            peer_batch = ObjectInstanceNameSet([multiple_b, multiple_c])
            peer.reserveMultipleObjectInstanceNames(peer_batch)
            for _ in range(20):
                peer.evokeCallback(0.0)
                if (
                    peer_callbacks.reserved_object_instance_name_sets
                    and peer_callbacks.rejected_object_instance_name_sets
                ):
                    break
            self.assertEqual(
                peer_callbacks.reserved_object_instance_name_sets,
                [ObjectInstanceNameSet([multiple_c])],
            )
            self.assertEqual(
                peer_callbacks.rejected_object_instance_name_sets,
                [ObjectInstanceNameSet([multiple_b])],
            )
            with self.assertRaises(ObjectInstanceNameNotReserved):
                owner.releaseMultipleObjectInstanceNames(
                    ObjectInstanceNameSet([multiple_a, multiple_c])
                )
            report_at(
                5,
                "Release Multiple Object Instance Names",
                "ObjectInstanceNameNotReserved",
            )
            peer.releaseObjectInstanceName(multiple_c)
            owner.releaseMultipleObjectInstanceNames(owner_batch)
            owner.releaseMultipleObjectInstanceNames(ObjectInstanceNameSet())
        finally:
            if peer_joined:
                try:
                    peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, connected in (
                (peer, peer_connected),
                (owner, owner_connected),
                (unjoined, unjoined_connected),
            ):
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
            peer._implementation.close()
            owner._implementation.close()
            unjoined._implementation.close()

    def test_cpp_jni_java_jpype_two_member_save_restore_barriers(self) -> None:
        """Exercise federation-wide save/restore barriers through the external API."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-two-member-save-restore-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        owner_connected = peer_connected = False
        owner_joined = peer_joined = False
        created = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner_handle = owner.joinFederationExecution(
                "jni-two-member-owner",
                federation_name,
                federateName="jni-two-member-owner",
            )
            owner_joined = True
            peer_handle = peer.joinFederationExecution(
                "jni-two-member-peer",
                federation_name,
                federateName="jni-two-member-peer",
            )
            peer_joined = True

            owner.listFederationExecutionMembers(federation_name)
            drain()
            self.assertEqual(owner_callbacks.member_reports[-1][0], federation_name)
            self.assertEqual(
                owner_callbacks.member_reports[-1][1],
                FederationExecutionMemberInformationSet(
                    {
                        FederationExecutionMemberInformation(
                            "jni-two-member-owner", "jni-two-member-owner"
                        ),
                        FederationExecutionMemberInformation(
                            "jni-two-member-peer", "jni-two-member-peer"
                        ),
                    }
                ),
            )

            owner.queryFederationSaveStatus()
            drain()
            initial_status = owner_callbacks.save_status_reports[-1]
            self.assertEqual(
                {entry.federateHandle for entry in initial_status},
                {owner_handle, peer_handle},
            )
            self.assertTrue(
                all(
                    entry.saveStatus is SaveStatus.NO_SAVE_IN_PROGRESS
                    for entry in initial_status
                )
            )

            save_label = "jni-two-member-save"
            owner.requestFederationSave(save_label)
            for _ in range(20):
                drain(1)
                if owner_callbacks.save_initiations == [
                    save_label
                ] and peer_callbacks.save_initiations == [save_label]:
                    break
            self.assertEqual(owner_callbacks.save_initiations, [save_label])
            self.assertEqual(peer_callbacks.save_initiations, [save_label])

            owner.queryFederationSaveStatus()
            drain()
            instructed_status = owner_callbacks.save_status_reports[-1]
            self.assertEqual(
                {entry.federateHandle for entry in instructed_status},
                {owner_handle, peer_handle},
            )
            self.assertTrue(
                all(
                    entry.saveStatus is not SaveStatus.NO_SAVE_IN_PROGRESS
                    for entry in instructed_status
                )
            )

            owner.federateSaveBegun()
            peer.federateSaveBegun()
            owner.federateSaveComplete()
            drain()
            self.assertEqual(owner_callbacks.saved_count, 0)
            self.assertEqual(peer_callbacks.saved_count, 0)
            peer.federateSaveComplete()
            for _ in range(20):
                drain(1)
                if owner_callbacks.saved_count == 1 and peer_callbacks.saved_count == 1:
                    break
            self.assertEqual(owner_callbacks.saved_count, 1)
            self.assertEqual(peer_callbacks.saved_count, 1)

            owner.requestFederationRestore(save_label)
            for _ in range(20):
                drain(1)
                if owner_callbacks.restore_acceptances == [save_label]:
                    break
            self.assertEqual(owner_callbacks.restore_acceptances, [save_label])
            # The acceptance/rejection callback belongs to the federate that
            # requested the restore. Other members receive restore-begin and
            # per-federate initiation callbacks, not a duplicate acceptance.
            self.assertEqual(peer_callbacks.restore_acceptances, [])
            drain()
            self.assertEqual(owner_callbacks.restore_begun, 1)
            self.assertEqual(peer_callbacks.restore_begun, 1)
            self.assertEqual(len(owner_callbacks.restore_initiations), 1)
            self.assertEqual(len(peer_callbacks.restore_initiations), 1)
            self.assertEqual(
                owner_callbacks.restore_initiations[0][:2],
                (save_label, "jni-two-member-owner"),
            )
            self.assertEqual(
                peer_callbacks.restore_initiations[0][:2],
                (save_label, "jni-two-member-peer"),
            )
            self.assertIsInstance(
                owner_callbacks.restore_initiations[0][2], FederateHandle
            )
            self.assertIsInstance(
                peer_callbacks.restore_initiations[0][2], FederateHandle
            )
            self.assertGreater(
                owner_callbacks.restore_initiations[0][2].encodedLength(), 0
            )
            self.assertGreater(
                peer_callbacks.restore_initiations[0][2].encodedLength(), 0
            )

            owner.federateRestoreComplete()
            drain()
            self.assertEqual(owner_callbacks.restore_completions, 0)
            self.assertEqual(peer_callbacks.restore_completions, 0)
            peer.federateRestoreComplete()
            for _ in range(20):
                drain(1)
                if (
                    owner_callbacks.restore_completions == 1
                    and peer_callbacks.restore_completions == 1
                ):
                    break
            self.assertEqual(owner_callbacks.restore_completions, 1)
            self.assertEqual(peer_callbacks.restore_completions, 1)

            failure_label = "jni-two-member-save-failure"
            owner.requestFederationSave(failure_label)
            for _ in range(20):
                drain(1)
                if (
                    failure_label in owner_callbacks.save_initiations
                    and failure_label in peer_callbacks.save_initiations
                ):
                    break
            owner.federateSaveBegun()
            peer.federateSaveBegun()
            owner_failure_count = len(owner_callbacks.save_failures)
            peer_failure_count = len(peer_callbacks.save_failures)
            owner.federateSaveNotComplete()
            for _ in range(20):
                drain(1)
                if (
                    len(owner_callbacks.save_failures) > owner_failure_count
                    and len(peer_callbacks.save_failures) > peer_failure_count
                ):
                    break
            self.assertEqual(
                owner_callbacks.save_failures[-1],
                SaveFailureReason.FEDERATE_REPORTED_FAILURE_DURING_SAVE,
            )
            self.assertEqual(
                peer_callbacks.save_failures[-1],
                SaveFailureReason.FEDERATE_REPORTED_FAILURE_DURING_SAVE,
            )

            abort_label = "jni-two-member-save-abort"
            owner.requestFederationSave(abort_label)
            for _ in range(20):
                drain(1)
                if (
                    abort_label in owner_callbacks.save_initiations
                    and abort_label in peer_callbacks.save_initiations
                ):
                    break
            owner_abort_count = len(owner_callbacks.save_failures)
            peer_abort_count = len(peer_callbacks.save_failures)
            owner.abortFederationSave()
            for _ in range(20):
                drain(1)
                if (
                    len(owner_callbacks.save_failures) > owner_abort_count
                    and len(peer_callbacks.save_failures) > peer_abort_count
                ):
                    break
            self.assertEqual(
                owner_callbacks.save_failures[-1], SaveFailureReason.SAVE_ABORTED
            )
            self.assertEqual(
                peer_callbacks.save_failures[-1], SaveFailureReason.SAVE_ABORTED
            )

            owner_restore_failure_count = len(owner_callbacks.restore_failures)
            peer_restore_failure_count = len(peer_callbacks.restore_failures)
            owner_restore_begin_count = owner_callbacks.restore_begun
            owner.requestFederationRestore(save_label)
            for _ in range(20):
                drain(1)
                if owner_callbacks.restore_begun > owner_restore_begin_count:
                    break
            owner.federateRestoreNotComplete()
            for _ in range(20):
                drain(1)
                if (
                    len(owner_callbacks.restore_failures) > owner_restore_failure_count
                    and len(peer_callbacks.restore_failures)
                    > peer_restore_failure_count
                ):
                    break
            self.assertEqual(
                owner_callbacks.restore_failures[-1],
                RestoreFailureReason.FEDERATE_REPORTED_FAILURE_DURING_RESTORE,
            )
            self.assertEqual(
                peer_callbacks.restore_failures[-1],
                RestoreFailureReason.FEDERATE_REPORTED_FAILURE_DURING_RESTORE,
            )

            restore_abort_begin_count = owner_callbacks.restore_begun
            owner_restore_abort_count = len(owner_callbacks.restore_failures)
            peer_restore_abort_count = len(peer_callbacks.restore_failures)
            owner.requestFederationRestore(save_label)
            for _ in range(20):
                drain(1)
                if owner_callbacks.restore_begun > restore_abort_begin_count:
                    break
            owner.abortFederationRestore()
            for _ in range(20):
                drain(1)
                if (
                    len(owner_callbacks.restore_failures) > owner_restore_abort_count
                    and len(peer_callbacks.restore_failures) > peer_restore_abort_count
                ):
                    break
            self.assertEqual(
                owner_callbacks.restore_failures[-1],
                RestoreFailureReason.RESTORE_ABORTED,
            )
            self.assertEqual(
                peer_callbacks.restore_failures[-1],
                RestoreFailureReason.RESTORE_ABORTED,
            )
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if peer_connected:
                try:
                    if peer_joined:
                        peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            owner._implementation.close()
            peer._implementation.close()

    def test_cpp_jni_java_jpype_mixed_callback_model_save_restore_sequence(
        self,
    ) -> None:
        """Preserve save/restore ordering across immediate and evoked members."""

        class SequencedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[tuple[str, object | None]] = []

            def initiateFederateSave(
                self, label: str, time: object | None = None
            ) -> None:
                self.events.append(("save-initiate", label))
                super().initiateFederateSave(label, time)

            def federationSaved(self) -> None:
                self.events.append(("save-complete", None))
                super().federationSaved()

            def requestFederationRestoreSucceeded(self, label: str) -> None:
                self.events.append(("restore-accepted", label))
                super().requestFederationRestoreSucceeded(label)

            def federationRestoreBegun(self) -> None:
                self.events.append(("restore-begun", None))
                super().federationRestoreBegun()

            def initiateFederateRestore(
                self,
                label: str,
                federateName: str,
                postRestoreFederateHandle: FederateHandle,
            ) -> None:
                self.events.append(("restore-initiate", label))
                super().initiateFederateRestore(
                    label, federateName, postRestoreFederateHandle
                )

            def federationRestored(self) -> None:
                self.events.append(("restore-complete", None))
                super().federationRestored()

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-mixed-callback-save-restore-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = SequencedCallbacks()
        peer_callbacks = SequencedCallbacks()
        owner_connected = peer_connected = False
        owner_joined = peer_joined = False
        created = False

        def evoke_peer(rounds: int = 20) -> None:
            for _ in range(rounds):
                peer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_IMMEDIATE)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution("jni-mixed-callback-owner", federation_name)
            owner_joined = True
            peer.joinFederationExecution("jni-mixed-callback-peer", federation_name)
            peer_joined = True

            save_label = "jni-mixed-callback-save"
            owner.requestFederationSave(save_label)

            # The immediate member observes its C++-originated initiation
            # before the request returns; the evoked member remains quiet until
            # the standard Java evoke service is called.
            self.assertIn(("save-initiate", save_label), owner_callbacks.events)
            self.assertNotIn(("save-initiate", save_label), peer_callbacks.events)
            evoke_peer()
            self.assertIn(("save-initiate", save_label), peer_callbacks.events)

            owner.federateSaveBegun()
            peer.federateSaveBegun()
            owner.federateSaveComplete()
            self.assertNotIn(("save-complete", None), owner_callbacks.events)
            self.assertNotIn(("save-complete", None), peer_callbacks.events)
            peer.federateSaveComplete()
            self.assertIn(("save-complete", None), owner_callbacks.events)
            self.assertNotIn(("save-complete", None), peer_callbacks.events)
            evoke_peer()
            self.assertIn(("save-complete", None), peer_callbacks.events)

            owner.requestFederationRestore(save_label)
            self.assertEqual(
                owner_callbacks.events[-3:],
                [
                    ("restore-accepted", save_label),
                    ("restore-begun", None),
                    ("restore-initiate", save_label),
                ],
            )
            self.assertNotIn(("restore-begun", None), peer_callbacks.events)
            evoke_peer()
            self.assertEqual(
                peer_callbacks.events[-2:],
                [("restore-begun", None), ("restore-initiate", save_label)],
            )

            owner.federateRestoreComplete()
            self.assertNotIn(("restore-complete", None), owner_callbacks.events)
            peer.federateRestoreComplete()
            self.assertIn(("restore-complete", None), owner_callbacks.events)
            self.assertNotIn(("restore-complete", None), peer_callbacks.events)
            evoke_peer()
            self.assertIn(("restore-complete", None), peer_callbacks.events)
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if peer_connected:
                try:
                    if peer_joined:
                        peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            owner._implementation.close()
            peer._implementation.close()

    def test_cpp_jni_java_jpype_two_member_save_restore_interlocks(self) -> None:
        """Preserve multi-member save/restore service interlocks through JNI."""

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-two-member-interlocks-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        owner_connected = peer_connected = False
        owner_joined = peer_joined = False
        created = False
        region = None

        def drain(rounds: int = 30) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        def drain_until(predicate, rounds: int = 80) -> None:
            for _ in range(rounds):
                drain(1)
                if predicate():
                    return
            self.assertTrue(predicate())

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-two-member-interlock-owner", federation_name
            )
            owner_joined = True
            peer.joinFederationExecution(
                "jni-two-member-interlock-peer", federation_name
            )
            peer_joined = True

            object_class = owner.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            object_attribute = owner.getAttributeHandle(
                object_class, HLA_FIXTURES.EFFICIENCY
            )
            interaction_class = owner.getInteractionClassHandle(HLA_FOM.TAKE_ORDER)
            dimension = owner.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            attributes = AttributeHandleSet([object_attribute])
            owner.publishObjectClassAttributes(object_class, attributes)
            owner.publishInteractionClass(interaction_class)
            peer.subscribeObjectClassAttributes(object_class, attributes)
            peer.subscribeInteractionClass(interaction_class)
            region = owner.createRegion(DimensionHandleSet([dimension]))
            owner.setRangeBounds(region, dimension, RangeBounds(0, 10))
            owner.commitRegionModifications(RegionHandleSet([region]))
            time_factory = owner.getTimeFactory()

            save_label = "jni-two-member-interlock-save"
            owner.requestFederationSave(save_label)
            drain_until(
                lambda: (
                    owner_callbacks.save_initiations == [save_label]
                    and peer_callbacks.save_initiations == [save_label]
                )
            )
            save_operations = (
                (
                    "Publish Object Class Attributes",
                    lambda: owner.publishObjectClassAttributes(
                        object_class, attributes
                    ),
                ),
                (
                    "Subscribe Object Class Attributes",
                    lambda: peer.subscribeObjectClassAttributes(
                        object_class, attributes
                    ),
                ),
                (
                    "Publish Interaction Class",
                    lambda: owner.publishInteractionClass(interaction_class),
                ),
                (
                    "Subscribe Interaction Class",
                    lambda: peer.subscribeInteractionClass(interaction_class),
                ),
                (
                    "Register Object Instance",
                    lambda: owner.registerObjectInstance(object_class),
                ),
                (
                    "Create Region",
                    lambda: owner.createRegion(DimensionHandleSet([dimension])),
                ),
                ("Query Logical Time", owner.queryLogicalTime),
                ("Query Federation Restore Status", owner.queryFederationRestoreStatus),
                (
                    "Register Federation Synchronization Point",
                    lambda: owner.registerFederationSynchronizationPoint(
                        "jni-save-interlock-sync", b"save-interlock"
                    ),
                ),
                (
                    "Send Interaction",
                    lambda: owner.sendInteraction(
                        interaction_class, ParameterHandleValueMap(), b"save-interlock"
                    ),
                ),
                (
                    "Change Interaction Order Type",
                    lambda: owner.changeInteractionOrderType(
                        interaction_class, OrderType.RECEIVE
                    ),
                ),
            )
            for service_name, operation in save_operations:
                with self.subTest(phase="save", service=service_name):
                    with self.assertRaises(SaveInProgress):
                        operation()

            owner.federateSaveBegun()
            peer.federateSaveBegun()
            owner.federateSaveComplete()
            drain()
            self.assertEqual(owner_callbacks.saved_count, 0)
            self.assertEqual(peer_callbacks.saved_count, 0)
            peer.federateSaveComplete()
            drain_until(
                lambda: (
                    owner_callbacks.saved_count == 1 and peer_callbacks.saved_count == 1
                )
            )

            owner.requestFederationRestore(save_label)
            drain_until(
                lambda: (
                    owner_callbacks.restore_begun == 1
                    and peer_callbacks.restore_begun == 1
                )
            )
            restore_operations = (
                (
                    "Publish Object Class Attributes",
                    lambda: owner.publishObjectClassAttributes(
                        object_class, attributes
                    ),
                ),
                (
                    "Subscribe Object Class Attributes",
                    lambda: peer.subscribeObjectClassAttributes(
                        object_class, attributes
                    ),
                ),
                (
                    "Publish Interaction Class",
                    lambda: owner.publishInteractionClass(interaction_class),
                ),
                (
                    "Subscribe Interaction Class",
                    lambda: peer.subscribeInteractionClass(interaction_class),
                ),
                (
                    "Register Object Instance",
                    lambda: owner.registerObjectInstance(object_class),
                ),
                (
                    "Create Region",
                    lambda: owner.createRegion(DimensionHandleSet([dimension])),
                ),
                ("Query Logical Time", owner.queryLogicalTime),
                ("Query Federation Save Status", owner.queryFederationSaveStatus),
                (
                    "Register Federation Synchronization Point",
                    lambda: owner.registerFederationSynchronizationPoint(
                        "jni-restore-interlock-sync", b"restore-interlock"
                    ),
                ),
                (
                    "Send Interaction",
                    lambda: owner.sendInteraction(
                        interaction_class,
                        ParameterHandleValueMap(),
                        b"restore-interlock",
                    ),
                ),
                (
                    "Change Interaction Order Type",
                    lambda: owner.changeInteractionOrderType(
                        interaction_class, OrderType.RECEIVE
                    ),
                ),
            )
            for service_name, operation in restore_operations:
                with self.subTest(phase="restore", service=service_name):
                    with self.assertRaises(RestoreInProgress):
                        operation()

            owner.federateRestoreComplete()
            drain()
            self.assertEqual(owner_callbacks.restore_completions, 0)
            self.assertEqual(peer_callbacks.restore_completions, 0)
            peer.federateRestoreComplete()
            drain_until(
                lambda: (
                    owner_callbacks.restore_completions == 1
                    and peer_callbacks.restore_completions == 1
                )
            )
            # The control barriers are released only after both members finish;
            # a normal service remains callable through the same Java surface.
            owner.queryLogicalTime()
        finally:
            if region is not None:
                try:
                    owner.deleteRegion(region)
                except Exception:
                    pass
            if peer_connected and peer_joined:
                try:
                    peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_connected and owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            peer._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_restore_rewinds_attribute_ownership(
        self,
    ) -> None:
        """Restore the C++-saved attribute owner through the standard Java API."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-restore-ownership-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        acquirer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        acquirer_callbacks = _JniCallbacks()
        owner_connected = acquirer_connected = False
        owner_joined = acquirer_joined = created = False
        object_instance: ObjectInstanceHandle | None = None

        def drain(rounds: int = 30) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                acquirer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            acquirer.connect(acquirer_callbacks, CallbackModel.HLA_EVOKED)
            acquirer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-restore-ownership-owner",
                federation_name,
                federateName="jni-restore-ownership-owner",
            )
            owner_joined = True
            acquirer.joinFederationExecution(
                "jni-restore-ownership-acquirer",
                federation_name,
                federateName="jni-restore-ownership-acquirer",
            )
            acquirer_joined = True

            owner_class = owner.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            acquirer_class = acquirer.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            owner_attribute = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.EFFICIENCY
            )
            acquirer_attribute = acquirer.getAttributeHandle(
                acquirer_class, HLA_FIXTURES.EFFICIENCY
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            acquirer_attributes = AttributeHandleSet([acquirer_attribute])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            acquirer.publishObjectClassAttributes(acquirer_class, acquirer_attributes)
            acquirer.subscribeObjectClassAttributes(
                acquirer_class, acquirer_attributes, active=True
            )
            object_instance = owner.registerObjectInstance(owner_class)
            drain()
            self.assertEqual(
                acquirer_callbacks.discovered_objects[-1][0], object_instance
            )
            self.assertTrue(
                owner.isAttributeOwnedByFederate(object_instance, owner_attribute)
            )
            self.assertFalse(
                acquirer.isAttributeOwnedByFederate(object_instance, acquirer_attribute)
            )

            save_label = f"jni-restore-ownership-save-{uuid4()}"
            owner.requestFederationSave(save_label)
            for _ in range(30):
                drain(1)
                if (
                    save_label in owner_callbacks.save_initiations
                    and save_label in acquirer_callbacks.save_initiations
                ):
                    break
            self.assertIn(save_label, owner_callbacks.save_initiations)
            self.assertIn(save_label, acquirer_callbacks.save_initiations)
            owner.federateSaveBegun()
            acquirer.federateSaveBegun()
            owner.federateSaveComplete()
            acquirer.federateSaveComplete()
            for _ in range(30):
                drain(1)
                if (
                    owner_callbacks.saved_count == 1
                    and acquirer_callbacks.saved_count == 1
                ):
                    break
            self.assertEqual(owner_callbacks.saved_count, 1)
            self.assertEqual(acquirer_callbacks.saved_count, 1)

            # Mutate ownership after the save image is complete. Restore must
            # reinstate the saved owner rather than retaining this later state.
            owner.unconditionalAttributeOwnershipDivestiture(
                object_instance, owner_attributes, b"post-save-divest"
            )
            for _ in range(30):
                acquirer.evokeCallback(0.0)
                if acquirer_callbacks.ownership_assumptions:
                    break
            self.assertEqual(
                acquirer_callbacks.ownership_assumptions[-1],
                (object_instance, acquirer_attributes, b"post-save-divest"),
            )
            acquirer.attributeOwnershipAcquisitionIfAvailable(
                object_instance, acquirer_attributes, b"post-save-acquire"
            )
            for _ in range(30):
                acquirer.evokeCallback(0.0)
                if acquirer_callbacks.ownership_acquisitions:
                    break
            self.assertEqual(
                acquirer_callbacks.ownership_acquisitions[-1],
                (object_instance, acquirer_attributes, b"post-save-acquire"),
            )
            self.assertFalse(
                owner.isAttributeOwnedByFederate(object_instance, owner_attribute)
            )
            self.assertTrue(
                acquirer.isAttributeOwnedByFederate(object_instance, acquirer_attribute)
            )

            owner.requestFederationRestore(save_label)
            for _ in range(30):
                drain(1)
                if (
                    owner_callbacks.restore_initiations
                    and acquirer_callbacks.restore_initiations
                ):
                    break
            self.assertEqual(owner_callbacks.restore_acceptances, [save_label])
            self.assertEqual(owner_callbacks.restore_begun, 1)
            self.assertEqual(acquirer_callbacks.restore_begun, 1)
            owner.federateRestoreComplete()
            acquirer.federateRestoreComplete()
            for _ in range(30):
                drain(1)
                if (
                    owner_callbacks.restore_completions == 1
                    and acquirer_callbacks.restore_completions == 1
                ):
                    break
            self.assertEqual(owner_callbacks.restore_completions, 1)
            self.assertEqual(acquirer_callbacks.restore_completions, 1)

            self.assertTrue(
                owner.isAttributeOwnedByFederate(object_instance, owner_attribute)
            )
            self.assertFalse(
                acquirer.isAttributeOwnedByFederate(object_instance, acquirer_attribute)
            )
        finally:
            if owner_joined and object_instance is not None:
                try:
                    owner.deleteObjectInstance(object_instance)
                except Exception:
                    pass
            if acquirer_joined:
                try:
                    acquirer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if acquirer_connected:
                try:
                    acquirer.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            acquirer._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_restore_rolls_back_object_management_snapshot(
        self,
    ) -> None:
        """Restore removes post-save declarations and objects through Java."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-restore-object-management-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        owner_connected = peer_connected = False
        owner_joined = peer_joined = created = False
        object_instance: ObjectInstanceHandle | None = None

        def drain(rounds: int = 30) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-restore-object-owner",
                federation_name,
                federateName="jni-restore-object-owner",
            )
            owner_joined = True
            peer.joinFederationExecution(
                "jni-restore-object-peer",
                federation_name,
                federateName="jni-restore-object-peer",
            )
            peer_joined = True

            save_label = f"jni-restore-object-baseline-{uuid4()}"
            owner.requestFederationSave(save_label)
            for _ in range(30):
                drain(1)
                if owner_callbacks.save_initiations == [
                    save_label
                ] and peer_callbacks.save_initiations == [save_label]:
                    break
            self.assertEqual(owner_callbacks.save_initiations, [save_label])
            self.assertEqual(peer_callbacks.save_initiations, [save_label])
            owner.federateSaveBegun()
            peer.federateSaveBegun()
            owner.federateSaveComplete()
            peer.federateSaveComplete()
            for _ in range(30):
                drain(1)
                if owner_callbacks.saved_count == 1 and peer_callbacks.saved_count == 1:
                    break
            self.assertEqual(owner_callbacks.saved_count, 1)
            self.assertEqual(peer_callbacks.saved_count, 1)

            # These declarations and the object are intentionally created after
            # the baseline image. Restore must remove all of them.
            owner_class = owner.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            peer_class = peer.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            owner_attribute = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.EFFICIENCY
            )
            peer_attribute = peer.getAttributeHandle(
                peer_class, HLA_FIXTURES.EFFICIENCY
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            peer_attributes = AttributeHandleSet([peer_attribute])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            peer.subscribeObjectClassAttributes(
                peer_class, peer_attributes, active=True
            )
            object_instance = owner.registerObjectInstance(owner_class)
            for _ in range(30):
                drain(1)
                if peer_callbacks.discovered_objects:
                    break
            self.assertEqual(peer_callbacks.discovered_objects[-1][0], object_instance)

            owner.requestFederationRestore(save_label)
            for _ in range(30):
                drain(1)
                if (
                    owner_callbacks.restore_initiations
                    and peer_callbacks.restore_initiations
                ):
                    break
            self.assertEqual(owner_callbacks.restore_acceptances, [save_label])
            self.assertEqual(owner_callbacks.restore_begun, 1)
            self.assertEqual(peer_callbacks.restore_begun, 1)
            self.assertEqual(
                owner_callbacks.restore_initiations[0][:2],
                (save_label, "jni-restore-object-owner"),
            )
            self.assertEqual(
                peer_callbacks.restore_initiations[0][:2],
                (save_label, "jni-restore-object-peer"),
            )

            owner.federateRestoreComplete()
            peer.federateRestoreComplete()
            for _ in range(30):
                drain(1)
                if (
                    owner_callbacks.restore_completions == 1
                    and peer_callbacks.restore_completions == 1
                ):
                    break
            self.assertEqual(owner_callbacks.restore_completions, 1)
            self.assertEqual(peer_callbacks.restore_completions, 1)

            # The ambassador remains joined, but the saved C++ image no longer
            # contains the post-save object or its declarations.
            with self.assertRaises(ObjectInstanceNotKnown):
                owner.getKnownObjectClassHandle(object_instance)
        finally:
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if peer_joined:
                try:
                    peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            peer._implementation.close()
            owner._implementation.close()

