    def test_cpp_jni_java_jpype_immediate_restore_reschedules_pending_flush_queue(
        self,
    ) -> None:
        """Restore a C++-saved pending flush request through HLA_IMMEDIATE."""

        class ImmediatePendingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.ambassador: RTIambassador | None = None
                self.events: list[tuple[str, object]] = []

            def initiateFederateSave(
                self, label: str, time: object | None = None
            ) -> None:
                self.events.append(("save-initiate", label))
                super().initiateFederateSave(label, time)
                assert self.ambassador is not None
                self.ambassador.federateSaveBegun()
                self.ambassador.federateSaveComplete()

            def federationSaved(self) -> None:
                self.events.append(("save-complete", None))
                super().federationSaved()

            def federationRestored(self) -> None:
                self.events.append(("restore-complete", None))
                super().federationRestored()

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                self.events.append(("flush-grant", time.getTime()))
                super().flushQueueGrant(time, optimisticTime)

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-nrg-enabled-fom.xml"
        )
        federation_name = f"python-jni-immediate-flush-restore-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = ImmediatePendingCallbacks()
        callbacks.ambassador = ambassador
        connected = created = joined = False
        try:
            ambassador.connect(callbacks, CallbackModel.HLA_IMMEDIATE)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-immediate-flush-restore-member", federation_name
            )
            joined = True
            time_factory = ambassador.getTimeFactory()
            ambassador.enableTimeConstrained()
            ambassador.enableTimeRegulation(time_factory.makeLogicalTimeInterval(1))

            save_label = "jni-immediate-flush-restore-baseline"
            ambassador.requestFederationSave(
                save_label, time_factory.makeLogicalTime(5)
            )
            ambassador.flushQueueRequest(time_factory.makeLogicalTime(6))
            self.assertEqual(callbacks.saved_count, 1)
            self.assertEqual(callbacks.flush_queue_grants[-1][0].getTime(), 6)
            self.assertEqual(
                [name for name, _ in callbacks.events[:3]],
                ["save-initiate", "save-complete", "flush-grant"],
            )

            callbacks.events.clear()
            ambassador.timeAdvanceRequest(time_factory.makeLogicalTime(9))
            self.assertEqual(ambassador.queryLogicalTime().getTime(), 9)

            ambassador.requestFederationRestore(save_label)
            ambassador.federateRestoreComplete()
            self.assertEqual(callbacks.restore_completions, 1)
            self.assertEqual(callbacks.flush_queue_grants[-1][0].getTime(), 6)
            self.assertEqual(ambassador.queryLogicalTime().getTime(), 6)
            event_names = [name for name, _ in callbacks.events]
            self.assertLess(
                event_names.index("restore-complete"), event_names.index("flush-grant")
            )

            # The restored direct grant clears the saved time-advancing state;
            # a new flush request is immediately legal and gets its own grant.
            ambassador.flushQueueRequest(time_factory.makeLogicalTime(7))
            self.assertEqual(callbacks.flush_queue_grants[-1][0].getTime(), 7)
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_restore_reschedules_all_advance_variants(
        self,
    ) -> None:
        """Restore pending TARA, NMR, and NMRA requests in both callback modes."""

        class AdvanceVariantCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.ambassador: RTIambassador | None = None
                self.events: list[tuple[str, object]] = []

            def initiateFederateSave(
                self, label: str, time: object | None = None
            ) -> None:
                self.events.append(("save-initiate", label))
                super().initiateFederateSave(label, time)
                assert self.ambassador is not None
                self.ambassador.federateSaveBegun()
                self.ambassador.federateSaveComplete()

            def federationSaved(self) -> None:
                self.events.append(("save-complete", None))
                super().federationSaved()

            def federationRestored(self) -> None:
                self.events.append(("restore-complete", None))
                super().federationRestored()

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                self.events.append(("grant", time.getTime()))
                super().timeAdvanceGrant(time)

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-nrg-enabled-fom.xml"
        )
        variants = (
            ("tara", "timeAdvanceRequestAvailable"),
            ("nmr", "nextMessageRequest"),
            ("nmra", "nextMessageRequestAvailable"),
        )

        def run_scenario(
            variant_name: str,
            service_name: str,
            callback_model: CallbackModel,
        ) -> None:
            federation_name = (
                f"python-jni-{variant_name}-restore-"
                f"{'immediate' if callback_model is CallbackModel.HLA_IMMEDIATE else 'evoked'}-"
                f"{uuid4()}"
            )
            ambassador = self.factory.getRtiAmbassador()
            callbacks = AdvanceVariantCallbacks()
            callbacks.ambassador = ambassador
            connected = created = joined = False

            def submit(value: int) -> None:
                getattr(ambassador, service_name)(
                    ambassador.getTimeFactory().makeLogicalTime(value)
                )

            def evoke_until(predicate, rounds: int = 40) -> None:
                for _ in range(rounds):
                    ambassador.evokeCallback(0.0)
                    if predicate():
                        return

            try:
                ambassador.connect(callbacks, callback_model)
                connected = True
                ambassador.createFederationExecution(
                    federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
                )
                created = True
                ambassador.joinFederationExecution(
                    f"jni-{variant_name}-restore-member", federation_name
                )
                joined = True
                time_factory = ambassador.getTimeFactory()
                ambassador.enableTimeConstrained()
                if callback_model is CallbackModel.HLA_EVOKED:
                    evoke_until(lambda: bool(callbacks.time_constrained_enabled))
                self.assertEqual(len(callbacks.time_constrained_enabled), 1)

                save_label = f"jni-{variant_name}-restore-baseline"
                ambassador.requestFederationSave(save_label)
                submit(5)
                if callback_model is CallbackModel.HLA_EVOKED:
                    evoke_until(lambda: bool(callbacks.save_initiations))
                self.assertEqual(callbacks.save_initiations, [save_label])
                self.assertEqual(callbacks.time_advance_grants[-1].getTime(), 5)
                if callback_model is CallbackModel.HLA_EVOKED:
                    evoke_until(lambda: callbacks.saved_count == 1)
                self.assertEqual(callbacks.saved_count, 1)

                callbacks.events.clear()
                submit(9)
                if callback_model is CallbackModel.HLA_EVOKED:
                    evoke_until(
                        lambda: callbacks.time_advance_grants[-1].getTime() == 9
                    )
                self.assertEqual(ambassador.queryLogicalTime().getTime(), 9)

                callbacks.events.clear()
                restore_count = len(callbacks.restore_initiations)
                ambassador.requestFederationRestore(save_label)
                if callback_model is CallbackModel.HLA_EVOKED:
                    evoke_until(
                        lambda: len(callbacks.restore_initiations) > restore_count
                    )
                ambassador.federateRestoreComplete()

                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertEqual(ambassador.queryLogicalTime().getTime(), 0)
                    with self.assertRaises(InTimeAdvancingState):
                        ambassador.timeAdvanceRequest(time_factory.makeLogicalTime(6))
                    evoke_until(lambda: callbacks.restore_completions == 1)
                    grants_before_restored = len(callbacks.time_advance_grants)
                    evoke_until(
                        lambda: (
                            len(callbacks.time_advance_grants)
                            == grants_before_restored + 1
                        )
                    )
                else:
                    self.assertEqual(callbacks.restore_completions, 1)

                self.assertEqual(callbacks.time_advance_grants[-1].getTime(), 5)
                self.assertEqual(ambassador.queryLogicalTime().getTime(), 5)
                event_names = [name for name, _ in callbacks.events]
                self.assertLess(
                    event_names.index("restore-complete"), event_names.index("grant")
                )

                # The reconstructed variant releases the state and the same
                # standard Java service remains usable at a new target.
                submit(6)
                if callback_model is CallbackModel.HLA_EVOKED:
                    evoke_until(
                        lambda: callbacks.time_advance_grants[-1].getTime() == 6
                    )
                self.assertEqual(callbacks.time_advance_grants[-1].getTime(), 6)
            finally:
                if joined:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
                if created:
                    try:
                        ambassador.destroyFederationExecution(federation_name)
                    except Exception:
                        pass
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

        for callback_model in (CallbackModel.HLA_EVOKED, CallbackModel.HLA_IMMEDIATE):
            for variant_name, service_name in variants:
                with self.subTest(callback_model=callback_model, variant=variant_name):
                    run_scenario(variant_name, service_name, callback_model)

    def test_cpp_jni_java_jpype_save_restore_precondition_exceptions(self) -> None:
        """Preserve the standard save/restore state-machine errors across JNI."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-save-restore-preconditions-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = joined = created = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                ambassador.evokeCallback(0.0)

        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-save-restore-preconditions",
                federation_name,
                federateName="jni-save-restore-preconditions",
            )
            joined = True

            # These callbacks report only after a request has been accepted;
            # each direct completion/abort entry point must reject an
            # uninitiated operation with its exact IEEE exception type.
            with self.assertRaises(SaveNotInitiated):
                ambassador.federateSaveBegun()
            with self.assertRaises(FederateHasNotBegunSave):
                ambassador.federateSaveComplete()
            with self.assertRaises(FederateHasNotBegunSave):
                ambassador.federateSaveNotComplete()
            with self.assertRaises(SaveNotInProgress):
                ambassador.abortFederationSave()
            with self.assertRaises(RestoreNotRequested):
                ambassador.federateRestoreComplete()
            with self.assertRaises(RestoreNotRequested):
                ambassador.federateRestoreNotComplete()
            with self.assertRaises(RestoreNotInProgress):
                ambassador.abortFederationRestore()

            pending_label = "jni-save-restore-pending"
            ambassador.requestFederationSave(pending_label)
            with self.assertRaises(SaveInProgress):
                ambassador.requestFederationSave("jni-save-restore-duplicate")
            with self.assertRaises(SaveInProgress):
                ambassador.requestFederationRestore(pending_label)
            ambassador.abortFederationSave()
            drain()
            self.assertIn(SaveFailureReason.SAVE_ABORTED, callbacks.save_failures)

            saved_label = "jni-save-restore-precondition-snapshot"
            ambassador.requestFederationSave(saved_label)
            drain()
            ambassador.federateSaveBegun()
            ambassador.federateSaveComplete()
            drain()
            self.assertEqual(callbacks.saved_count, 1)

            ambassador.requestFederationRestore(saved_label)
            drain()
            self.assertEqual(callbacks.restore_acceptances, [saved_label])
            with self.assertRaises(RestoreInProgress):
                ambassador.requestFederationRestore(saved_label)
            with self.assertRaises(RestoreInProgress):
                ambassador.requestFederationSave("jni-save-during-restore")
            ambassador.federateRestoreComplete()
            drain()
            self.assertEqual(callbacks.restore_completions, 1)
        finally:
            if connected:
                try:
                    if joined:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_two_member_synchronization_barrier(self) -> None:
        """Exercise current-member synchronization through the external API."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-two-member-sync-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        owner_connected = peer_connected = False
        owner_joined = peer_joined = False
        created = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner_handle = owner.joinFederationExecution(
                "jni-two-member-sync-owner",
                federation_name,
                federateName="jni-two-member-sync-owner",
            )
            owner_joined = True
            peer_handle = peer.joinFederationExecution(
                "jni-two-member-sync-peer",
                federation_name,
                federateName="jni-two-member-sync-peer",
            )
            peer_joined = True

            synchronization_label = "jni-two-member-synchronization"
            synchronization_tag = b"jni-two-member-sync-tag"
            owner.registerFederationSynchronizationPoint(
                synchronization_label, synchronization_tag
            )
            for _ in range(20):
                drain(1)
                if (
                    owner_callbacks.synchronization_registrations
                    == [synchronization_label]
                    and len(owner_callbacks.synchronization_announcements) == 1
                    and len(peer_callbacks.synchronization_announcements) == 1
                ):
                    break
            self.assertEqual(
                owner_callbacks.synchronization_registrations,
                [synchronization_label],
            )
            self.assertEqual(peer_callbacks.synchronization_registrations, [])
            self.assertEqual(
                owner_callbacks.synchronization_announcements,
                [(synchronization_label, synchronization_tag)],
            )
            self.assertEqual(
                peer_callbacks.synchronization_announcements,
                [(synchronization_label, synchronization_tag)],
            )

            owner.synchronizationPointAchieved(synchronization_label)
            drain()
            self.assertEqual(owner_callbacks.synchronization_results, [])
            self.assertEqual(peer_callbacks.synchronization_results, [])
            peer.synchronizationPointAchieved(synchronization_label)
            for _ in range(20):
                drain(1)
                if (
                    len(owner_callbacks.synchronization_results) == 1
                    and len(peer_callbacks.synchronization_results) == 1
                ):
                    break
            self.assertEqual(
                owner_callbacks.synchronization_results,
                [(synchronization_label, FederateHandleSet())],
            )
            self.assertEqual(
                peer_callbacks.synchronization_results,
                [(synchronization_label, FederateHandleSet())],
            )

            # Keep the explicit-set failure reason typed when the encoded
            # handle is structurally valid but is not a current member.  Use
            # a high-order identity octet so this remains non-member even
            # after a long process has allocated adjacent low-byte IDs.
            unknown_handle_bytes = bytearray(owner_handle.encodedValue)
            unknown_handle_bytes[4] ^= 0xFF
            unknown_handle = FederateHandle(bytes(unknown_handle_bytes))
            self.assertNotIn(
                unknown_handle, FederateHandleSet([owner_handle, peer_handle])
            )
            missing_member_label = "jni-two-member-missing-set-member"
            owner.registerFederationSynchronizationPoint(
                missing_member_label,
                b"jni-two-member-missing-tag",
                synchronizationSet=FederateHandleSet([unknown_handle]),
            )
            for _ in range(20):
                drain(1)
                if owner_callbacks.synchronization_registration_failures:
                    break
            self.assertIn(
                (
                    missing_member_label,
                    SynchronizationPointFailureReason.SYNCHRONIZATION_SET_MEMBER_NOT_JOINED,
                ),
                owner_callbacks.synchronization_registration_failures,
            )

            explicit_label = "jni-two-member-explicit-synchronization"
            explicit_tag = b"jni-two-member-explicit-tag"
            explicit_set = FederateHandleSet([owner_handle, peer_handle])
            owner.registerFederationSynchronizationPoint(
                explicit_label,
                explicit_tag,
                synchronizationSet=explicit_set,
            )
            for _ in range(20):
                drain(1)
                if (
                    explicit_label in owner_callbacks.synchronization_registrations
                    and (explicit_label, explicit_tag)
                    in owner_callbacks.synchronization_announcements
                    and (explicit_label, explicit_tag)
                    in peer_callbacks.synchronization_announcements
                ):
                    break
            self.assertIn(explicit_label, owner_callbacks.synchronization_registrations)
            self.assertIn(
                (explicit_label, explicit_tag),
                owner_callbacks.synchronization_announcements,
            )
            self.assertIn(
                (explicit_label, explicit_tag),
                peer_callbacks.synchronization_announcements,
            )
            owner.synchronizationPointAchieved(explicit_label)
            peer.synchronizationPointAchieved(explicit_label)
            for _ in range(20):
                drain(1)
                if (
                    explicit_label,
                    FederateHandleSet(),
                ) in owner_callbacks.synchronization_results and (
                    explicit_label,
                    FederateHandleSet(),
                ) in peer_callbacks.synchronization_results:
                    break
            self.assertIn(
                (explicit_label, FederateHandleSet()),
                owner_callbacks.synchronization_results,
            )
            self.assertIn(
                (explicit_label, FederateHandleSet()),
                peer_callbacks.synchronization_results,
            )

            # The standard achievement overload carries a per-federate
            # success bit. Keep this failure path on the real C++ route so
            # the failed-member handle set is reconstructed by JNI/Java,
            # rather than only exercising the all-success barrier above.
            failed_label = "jni-two-member-failed-synchronization"
            failed_tag = b"jni-two-member-failed-tag"
            owner.registerFederationSynchronizationPoint(failed_label, failed_tag)
            for _ in range(20):
                drain(1)
                if (
                    failed_label in owner_callbacks.synchronization_registrations
                    and (failed_label, failed_tag)
                    in owner_callbacks.synchronization_announcements
                    and (failed_label, failed_tag)
                    in peer_callbacks.synchronization_announcements
                ):
                    break
            self.assertIn(failed_label, owner_callbacks.synchronization_registrations)
            self.assertIn(
                (failed_label, failed_tag),
                owner_callbacks.synchronization_announcements,
            )
            self.assertIn(
                (failed_label, failed_tag),
                peer_callbacks.synchronization_announcements,
            )
            owner.synchronizationPointAchieved(failed_label, successfully=True)
            peer.synchronizationPointAchieved(failed_label, successfully=False)
            expected_failure = (failed_label, FederateHandleSet([peer_handle]))
            for _ in range(20):
                drain(1)
                if (
                    expected_failure in owner_callbacks.synchronization_results
                    and expected_failure in peer_callbacks.synchronization_results
                ):
                    break
            self.assertIn(expected_failure, owner_callbacks.synchronization_results)
            self.assertIn(expected_failure, peer_callbacks.synchronization_results)

            # A resigned member's encoded handle remains structurally valid,
            # but it is no longer a joined member of this execution.  Reusing
            # that standard handle in a later explicit set must therefore
            # retain the asynchronous membership failure rather than silently
            # announcing a point to the current owner only.
            peer.resignFederationExecution(ResignAction.NO_ACTION)
            peer_joined = False
            departed_label = "jni-two-member-departed-set-member"
            owner.registerFederationSynchronizationPoint(
                departed_label,
                b"jni-two-member-departed-tag",
                synchronizationSet=FederateHandleSet([owner_handle, peer_handle]),
            )
            departed_failure = (
                departed_label,
                SynchronizationPointFailureReason.SYNCHRONIZATION_SET_MEMBER_NOT_JOINED,
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
                if (
                    departed_failure
                    in owner_callbacks.synchronization_registration_failures
                ):
                    break
            self.assertIn(
                departed_failure, owner_callbacks.synchronization_registration_failures
            )
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if peer_connected:
                try:
                    if peer_joined:
                        peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            owner._implementation.close()
            peer._implementation.close()

    def test_cpp_jni_java_jpype_synchronization_preconditions_and_idempotence(
        self,
    ) -> None:
        """Preserve synchronization preconditions and repeated-achievement semantics."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-sync-edges-{uuid4()}"
        unconnected = self.factory.getRtiAmbassador()
        unjoined = self.factory.getRtiAmbassador()
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        unjoined_connected = owner_connected = peer_connected = False
        owner_joined = peer_joined = created = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        try:
            with self.assertRaises(NotConnected):
                unconnected.registerFederationSynchronizationPoint(
                    "jni-sync-disconnected", b"tag"
                )
            with self.assertRaises(NotConnected):
                unconnected.synchronizationPointAchieved("jni-sync-disconnected")

            unjoined.connect(_JniCallbacks(), CallbackModel.HLA_EVOKED)
            unjoined_connected = True
            with self.assertRaises(FederateNotExecutionMember):
                unjoined.registerFederationSynchronizationPoint(
                    "jni-sync-unjoined", b"tag"
                )
            with self.assertRaises(FederateNotExecutionMember):
                unjoined.synchronizationPointAchieved("jni-sync-unjoined")

            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-sync-edge-owner",
                federation_name,
                federateName="jni-sync-edge-owner",
            )
            owner_joined = True
            peer.joinFederationExecution(
                "jni-sync-edge-peer",
                federation_name,
                federateName="jni-sync-edge-peer",
            )
            peer_joined = True

            report_class = peer.getInteractionClassHandle(HLA_MOM.REPORT_EXCEPTION)
            report_parameters = {
                name: peer.getParameterHandle(report_class, name)
                for name in (HLA_MOM.SERVICE, HLA_MOM.EXCEPTION)
            }
            peer.subscribeInteractionClass(report_class)
            owner.setExceptionReportingSwitch(True)
            encoder = self.factory.getEncoderFactory()

            def report_at(index: int, service_name: str, exception_name: str) -> None:
                for _ in range(20):
                    peer.evokeCallback(0.0)
                    if len(peer_callbacks.received_interactions) > index:
                        break
                self.assertEqual(len(peer_callbacks.received_interactions), index + 1)
                report = peer_callbacks.received_interactions[index]
                self.assertEqual(report[0], report_class)
                values = dict(report[1])
                service = (
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue()
                )
                exception = (
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue()
                )
                self.assertEqual(service, service_name)
                self.assertTrue(exception.startswith(exception_name))

            with self.assertRaises(SynchronizationPointLabelNotAnnounced):
                owner.synchronizationPointAchieved("jni-sync-unknown")
            report_at(
                0,
                "Synchronization Point Achieved",
                "SynchronizationPointLabelNotAnnounced",
            )

            label = "jni-sync-edge-idempotent"
            tag = b"jni-sync-edge-tag"
            owner.registerFederationSynchronizationPoint(label, tag)
            for _ in range(20):
                drain(1)
                if (
                    label in owner_callbacks.synchronization_registrations
                    and (label, tag) in owner_callbacks.synchronization_announcements
                    and (label, tag) in peer_callbacks.synchronization_announcements
                ):
                    break
            self.assertIn(label, owner_callbacks.synchronization_registrations)

            # Registration contention is asynchronous and must preserve the
            # standard failure-reason enum rather than throwing synchronously.
            owner.registerFederationSynchronizationPoint(label, b"duplicate-tag")
            for _ in range(20):
                drain(1)
                if (
                    label,
                    SynchronizationPointFailureReason.SYNCHRONIZATION_POINT_LABEL_NOT_UNIQUE,
                ) in owner_callbacks.synchronization_registration_failures:
                    break
            self.assertIn(
                (
                    label,
                    SynchronizationPointFailureReason.SYNCHRONIZATION_POINT_LABEL_NOT_UNIQUE,
                ),
                owner_callbacks.synchronization_registration_failures,
            )

            owner.synchronizationPointAchieved(label)
            # The C++ registry treats a repeated achievement as idempotent;
            # completion must wait for the other member and remain one-shot.
            owner.synchronizationPointAchieved(label)
            drain()
            self.assertEqual(owner_callbacks.synchronization_results, [])
            self.assertEqual(peer_callbacks.synchronization_results, [])
            peer.synchronizationPointAchieved(label)
            for _ in range(20):
                drain(1)
                if len(owner_callbacks.synchronization_results) == 1:
                    break
            self.assertEqual(len(owner_callbacks.synchronization_results), 1)
            self.assertEqual(len(peer_callbacks.synchronization_results), 1)
            self.assertEqual(
                owner_callbacks.synchronization_results,
                [(label, FederateHandleSet())],
            )
            self.assertEqual(
                peer_callbacks.synchronization_results,
                [(label, FederateHandleSet())],
            )

            with self.assertRaises(SynchronizationPointLabelNotAnnounced):
                owner.synchronizationPointAchieved(label)
            report_at(
                1,
                "Synchronization Point Achieved",
                "SynchronizationPointLabelNotAnnounced",
            )

            # A member-owned object makes NO_ACTION resignation fail at the
            # C++ federation-lifecycle boundary.  Keep the typed ownership
            # precondition and its separate MOM exception report on the exact
            # Java API path before selecting the standard corrective action.
            object_class = owner.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            attribute = owner.getAttributeHandle(object_class, HLA_FIXTURES.EFFICIENCY)
            owner.publishObjectClassAttributes(
                object_class, AttributeHandleSet([attribute])
            )
            owner.registerObjectInstance(object_class)
            with self.assertRaises(FederateOwnsAttributes):
                owner.resignFederationExecution(ResignAction.NO_ACTION)
            report_at(2, "Resign Federation Execution", "FederateOwnsAttributes")
            owner.resignFederationExecution(ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST)
            owner_joined = False
        finally:
            if unjoined_connected:
                try:
                    unjoined.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if peer_connected:
                try:
                    if peer_joined:
                        peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            unconnected._implementation.close()
            unjoined._implementation.close()
            owner._implementation.close()
            peer._implementation.close()

    def test_jni_api_declares_supported_cpp_standard_exception_types(self) -> None:
        """Keep every shared C++/Java exception name loadable at runtime.

        The compact fixture intentionally exposes the complete C++ exception
        inventory.  An independently supplied IEEE Java API is authoritative
        for its own vocabulary and omits a few legacy advisory exception
        names, so the external lane checks the exact intersection instead of
        skipping the boundary altogether.
        """
        import jpype

        exception_header = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.1-2025"
            / "include"
            / "RTI"
            / "Exception.h"
        )
        exception_names = sorted(
            set(
                re.findall(
                    r"RTI_EXCEPTION\(([A-Za-z_][A-Za-z0-9_]*)\)",
                    exception_header.read_text(encoding="utf-8"),
                )
            )
            - {"A"}
        )
        api_jar = os.environ.get("UMBRA_JNI_JAVA_API_JAR")
        if api_jar:
            with zipfile.ZipFile(api_jar) as archive:
                java_exception_names = {
                    Path(entry).stem
                    for entry in archive.namelist()
                    if entry.startswith("hla/rti1516_2025/exceptions/")
                    and entry.endswith(".class")
                }
            exception_names = [
                name for name in exception_names if name in java_exception_names
            ]
            self.assertTrue(
                exception_names,
                "the external Java API did not expose any shared RTI exception classes",
            )
        ambassador = self.factory.getRtiAmbassador()
        try:
            for exception_name in exception_names:
                exception_class = jpype.JClass(
                    f"hla.rti1516_2025.exceptions.{exception_name}"
                )
                self.assertEqual(
                    str(exception_class.class_.getSimpleName()), exception_name
                )
        finally:
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_callback_failure_maps_to_federate_internal_error(
        self,
    ) -> None:
        """A Python callback failure must return as a typed RTI exception."""

        class _FailingCallbacks(FederateAmbassador):
            def __init__(self) -> None:
                self.reports: list[FederationExecutionInformationSet] = []

            def reportFederationExecutions(
                self, report: FederationExecutionInformationSet
            ) -> None:
                self.reports.append(report)
                raise RuntimeError("intentional Python callback failure")

        ambassador = self.factory.getRtiAmbassador()
        callbacks = _FailingCallbacks()
        connected = False
        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.listFederationExecutions()
            with self.assertRaises(FederateInternalError):
                ambassador.evokeCallback(0.0)
            self.assertEqual(len(callbacks.reports), 1)
        finally:
            if connected:
                ambassador.disconnect()

    def test_jni_invocation_handler_routes_all_fixture_signature_arities(self) -> None:
        """Prevent a new standard overload from falling through as unbound."""
        fixture = (
            Path(__file__).parents[1]
            / "test-fixtures"
            / "mock-java-rti"
            / "src"
            / "main"
            / "java"
            / "hla"
            / "rti1516_2025"
            / "RTIambassador.java"
        ).read_text(encoding="utf-8")
        handler = (
            Path(__file__).parents[2]
            / "umbra-rti-jni"
            / "src"
            / "main"
            / "java"
            / "org"
            / "umbra"
            / "jni"
            / "rti1516_2025"
            / "NativeRTIambassador.java"
        ).read_text(encoding="utf-8")
        signatures: set[tuple[str, int]] = set()
        for match in re.finditer(
            r"(?ms)^\s*[A-Za-z_$][\w$<>, ?\[\].]*\s+"
            r"([A-Za-z_$][\w$]*)\s*\((.*?)\)\s*(?:throws[^;{}]*)?;",
            fixture,
        ):
            parameters = match.group(2).strip()
            arity = 0 if not parameters else parameters.count(",") + 1
            signatures.add((match.group(1), arity))

        # These two names deliberately select a private overload resolver
        # because Java overloads of the same arity differ by URL/string shape.
        helper_routed_names = {"connect", "joinFederationExecution"}
        for name, arity in signatures:
            marker = f'"{name}".equals(name)'
            sections = [
                handler[position : position + 600]
                for position in (
                    match.start() for match in re.finditer(re.escape(marker), handler)
                )
            ]
            self.assertTrue(sections, f"{name}/{arity} has no JNI dispatch branch")
            generic_route = re.search(
                rf'if\s*\(\s*"{re.escape(name)}"\.equals\(name\)\s*\)',
                handler,
            )
            arity_route = any(
                re.search(rf"values\.length\s*==\s*{arity}(?!\d)", section)
                for section in sections
            )
            self.assertTrue(
                name in helper_routed_names or generic_route is not None or arity_route,
                f"{name}/{arity} can fall through to the unbound-service error",
            )

    def test_jni_invocation_handler_routes_external_standard_signatures(self) -> None:
        """Audit the loaded IEEE Java interface, not only the local fixture."""
        import jpype

        # JavaRtiFactory starts the configured JVM lazily when its first
        # ambassador is requested; reflection must inspect that exact class
        # loader rather than importing JPype before startup.
        self.factory.getRtiAmbassador()
        standard_interface = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
        standard_signatures = {
            (method.getName(), method.getParameterCount())
            for method in standard_interface.getMethods()
        }
        handler = (
            Path(__file__).parents[2]
            / "umbra-rti-jni"
            / "src"
            / "main"
            / "java"
            / "org"
            / "umbra"
            / "jni"
            / "rti1516_2025"
            / "NativeRTIambassador.java"
        ).read_text(encoding="utf-8")
        helper_routed_names = {"connect", "joinFederationExecution"}
        # Normalize line wrapping and collect every explicit values.length
        # alternative from each branch. A bounded negative look-ahead keeps a
        # generic helper branch (connect/join) from consuming the following
        # dispatch branch while still handling multiline region conditions.
        normalized_handler = re.sub(r"\s+", " ", handler)
        explicit_dispatch: set[tuple[str, int]] = set()
        for match in re.finditer(
            r'if \("([A-Za-z][A-Za-z0-9_]*)"\.equals\(name\)'
            r"(?P<condition>(?:(?!if \().){0,220})\)\s*\{",
            normalized_handler,
        ):
            explicit_dispatch.update(
                (str(match.group(1)), int(arity))
                for arity in re.findall(
                    r"values\.length\s*==\s*(\d+)", match.group("condition")
                )
            )
        missing_routes = sorted(
            f"{name}/{arity}"
            for name, arity in standard_signatures
            if name not in helper_routed_names
            and (str(name), int(arity)) not in explicit_dispatch
        )
        self.assertEqual(missing_routes, [], "; ".join(sorted(missing_routes)))

    def test_jni_encoder_factory_routes_external_standard_signatures(self) -> None:
        """Audit every external 2025 EncoderFactory creator overload."""
        import jpype

        # Start the exact configured JVM before asking JPype for the external
        # class.  This also makes the focused test runnable by itself rather
        # than relying on another integration vector to initialize JPype.
        ambassador = self.factory.getRtiAmbassador()
        try:
            standard_interface = jpype.JClass(
                "hla.rti1516_2025.encoding.EncoderFactory"
            ).class_
            standard_signatures = {
                (str(method.getName()), int(method.getParameterCount()))
                for method in standard_interface.getMethods()
                if str(method.getName()).startswith("createHLA")
            }
            handler = (
                Path(__file__).parents[2]
                / "umbra-rti-jni"
                / "src"
                / "main"
                / "java"
                / "org"
                / "umbra"
                / "jni"
                / "rti1516_2025"
                / "NativeEncoderFactory.java"
            ).read_text(encoding="utf-8")
            handle_names = {
                name
                for name in re.findall(
                    r'name\.equals\("(createHLA[A-Za-z0-9_]*)"\)', handler
                )
            }
            missing_routes: list[str] = []
            for name, arity in sorted(standard_signatures):
                if name in handle_names:
                    routed = arity in {1, 2}
                else:
                    marker = f'"{name}".equals(method.getName())'
                    sections = [
                        handler[position : position + 520]
                        for position in (
                            match.start()
                            for match in re.finditer(re.escape(marker), handler)
                        )
                    ]
                    routed = any(
                        re.search(rf"values\.length\s*==\s*{arity}(?!\d)", section)
                        for section in sections
                    )
                if not routed:
                    missing_routes.append(f"{name}/{arity}")
            self.assertEqual(
                missing_routes,
                [],
                "The JNI EncoderFactory handler lacks routes for: "
                + ", ".join(missing_routes),
            )
        finally:
            ambassador._implementation.close()

    def test_jni_callback_surface_is_marshaled_and_callback_classes_are_released(
        self,
    ) -> None:
        """Keep every Java callback slot live through C++ and the Python proxy."""
        fixture = (
            Path(__file__).parents[1]
            / "test-fixtures"
            / "mock-java-rti"
            / "src"
            / "main"
            / "java"
            / "hla"
            / "rti1516_2025"
            / "FederateAmbassador.java"
        ).read_text(encoding="utf-8")
        cpp_header = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.1-2025"
            / "include"
            / "RTI"
            / "FederateAmbassador.h"
        ).read_text(encoding="utf-8")
        cpp = (
            Path(__file__).parents[2]
            / "umbra-rti-jni"
            / "src"
            / "native"
            / "umbra_rti_jni.cpp"
        ).read_text(encoding="utf-8")
        runtime = (
            Path(__file__).parents[1]
            / "src"
            / "umbra"
            / "_java"
            / "rti1516_2025"
            / "_runtime.py"
        ).read_text(encoding="utf-8")

        callback_start = cpp.index("class JavaFederateAmbassador final")
        callback_end = cpp.index("rti::CallbackModel callbackModel", callback_start)
        callback = cpp[callback_start:callback_end]
        set_target = callback[
            callback.index("void setTarget") : callback.index("void clearTarget")
        ]
        clear_target = callback[
            callback.index("void clearTarget") : callback.index("void dispose")
        ]

        def java_arity(parameters: str) -> int:
            parameters = parameters.strip()
            return 0 if not parameters else parameters.count(",") + 1

        def jni_arity(descriptor: str) -> int:
            """Count JVM descriptor parameters without depending on a JVM parser."""
            parameters = descriptor[1 : descriptor.index(")")]
            index = 0
            count = 0
            while index < len(parameters):
                while parameters[index] == "[":
                    index += 1
                if parameters[index] == "L":
                    index = parameters.index(";", index) + 1
                else:
                    self.assertIn(parameters[index], "BCDFIJSZ")
                    index += 1
                count += 1
            return count

        fixture_signatures = sorted(
            (match.group(1), java_arity(match.group(2)))
            for match in re.finditer(
                r"(?ms)^\s*void\s+([A-Za-z_$][\w$]*)\s*\((.*?)\)\s*;",
                fixture,
            )
        )
        # The compact fixture is only a harness.  When the independently
        # obtained IEEE JAR is active, compare its actual callback interface
        # before relying on the fixture text for the remaining native/JPype
        # marshalling checks.
        if os.environ.get("UMBRA_JNI_JAVA_API_JAR"):
            import jpype

            probe = self.factory.getRtiAmbassador()
            try:
                external_interface = jpype.JClass(
                    "hla.rti1516_2025.FederateAmbassador"
                ).class_
                external_signatures = sorted(
                    (method.getName(), method.getParameterCount())
                    for method in external_interface.getMethods()
                )
                self.assertEqual(
                    external_signatures,
                    fixture_signatures,
                    "the external IEEE callback interface differs from the fixture harness",
                )
            finally:
                probe._implementation.close()
        cpp_callback_signatures = sorted(
            (match.group(1), java_arity(match.group(2)))
            for match in re.finditer(
                r"virtual\s+void\s+([A-Za-z_$][\w$]*)\s*\((.*?)\)\s*=\s*0\s*;",
                cpp_header,
                re.DOTALL,
            )
        )
        self.assertEqual(
            cpp_callback_signatures,
            fixture_signatures,
            "The Java callback declaration must preserve every C++ callback name and overload arity",
        )
        native_callbacks = re.findall(
            r"auto const (\w+) = requiredMethod\(\s*environment,\s*targetClass,\s*"
            r'"([^"]+)",\s*"([^"]+)"\);',
            set_target,
        )
        self.assertEqual(
            fixture_signatures,
            sorted(
                (name, jni_arity(descriptor))
                for _, name, descriptor in native_callbacks
            ),
        )

        callback_proxy = runtime[
            runtime.index("class _FederateAmbassadorCallback") : runtime.index(
                "class JPypeJavaRuntime"
            )
        ]
        proxy_methods = set(
            re.findall(r"^    def (\w+)\(", callback_proxy, re.MULTILINE)
        )
        self.assertTrue(
            {name for name, _ in fixture_signatures}.issubset(proxy_methods),
            "every native Java callback must have a JPype-to-Python marshaller",
        )

        for slot, name, _ in native_callbacks:
            stored_slot = f"{slot}_"
            self.assertRegex(
                set_target,
                rf"\b{stored_slot}\s*=\s*{slot};",
            )
            self.assertRegex(
                clear_target,
                rf"\b{stored_slot}\s*=\s*nullptr;",
            )
            self.assertRegex(
                callback,
                rf"\b(?:invoke\w+|retainedTarget)\([^)]*\b{stored_slot}\b",
                f"{name} is resolved but never used for a C++ callback upcall",
            )

        constructor = callback[
            callback.index("JavaFederateAmbassador(") : callback.index(
                "~JavaFederateAmbassador"
            )
        ]
        global_classes = set(re.findall(r"(\w+Class_)\(globalClass\(", constructor))
        dispose = callback[
            callback.index("void dispose") : callback.index("void connectionLost")
        ]
        disposal_list = dispose[
            dispose.index("for (jclass klass : {") : dispose.index("}) {")
        ]
        disposed_classes = set(re.findall(r"\b(\w+Class_)\b", disposal_list))
        cleared_classes = set(
            re.findall(r"^\s*(\w+Class_)\s*=\s*nullptr;", dispose, re.MULTILINE)
        )
        self.assertSetEqual(global_classes, disposed_classes)
        self.assertSetEqual(global_classes, cleared_classes)

    def test_jni_bridge_registers_every_declared_native_endpoint(self) -> None:
        """Keep Java dispatch, JNI declarations, and C++ registrations aligned."""
        jni_root = Path(__file__).parents[2] / "umbra-rti-jni" / "src"
        bridge = (
            jni_root
            / "main"
            / "java"
            / "org"
            / "umbra"
            / "jni"
            / "rti1516_2025"
            / "NativeBridge.java"
        ).read_text(encoding="utf-8")
        handler = (
            jni_root
            / "main"
            / "java"
            / "org"
            / "umbra"
            / "jni"
            / "rti1516_2025"
            / "NativeRTIambassador.java"
        ).read_text(encoding="utf-8")
        native_source = (jni_root / "native" / "umbra_rti_jni.cpp").read_text(
            encoding="utf-8"
        )
        declared = set(
            re.findall(r"\bstatic\s+native\s+[\w<>\[\].? ]+\s+(native\w+)\s*\(", bridge)
        )
        self.assertGreaterEqual(len(declared), 400)
        registration_source = native_source.split(
            "JNINativeMethod const nativeMethods[] = {", 1
        )[1]
        registered = set(
            re.findall(r'const_cast<char\*>\("(native\w+)"\)', registration_source)
        )
        self.assertSetEqual(
            declared,
            registered,
            "Every NativeBridge endpoint must be registered against its C++ function",
        )
        dispatched = set(re.findall(r"NativeBridge\.(native\w+)\s*\(", handler))
        self.assertTrue(dispatched)
        self.assertTrue(
            dispatched <= declared,
            "The Java RTI handler may call only declared JNI endpoints",
        )

    def test_jni_integration_vectors_reference_every_public_rti_service(self) -> None:
        """Keep each shared RTI service covered by a real JNI test vector."""
        core = ast.parse(
            (
                Path(__file__).parents[2]
                / "umbra-rti-api"
                / "src"
                / "hla"
                / "rti1516_2025"
                / "abstract.py"
            ).read_text(encoding="utf-8")
        )
        contract = next(
            node
            for node in core.body
            if isinstance(node, ast.ClassDef) and node.name == "RTIambassador"
        )
        public_services = {
            node.name
            for node in contract.body
            if isinstance(node, ast.FunctionDef)
            and any(
                isinstance(decorator, ast.Name) and decorator.id == "abstractmethod"
                for decorator in node.decorator_list
            )
        }
        integration_source = ast.parse(Path(__file__).read_text(encoding="utf-8"))
        referenced_services = {
            node.attr
            for node in ast.walk(integration_source)
            if isinstance(node, ast.Attribute)
        }
        self.assertSetEqual(
            public_services - referenced_services,
            set(),
            "Every public RTIambassador service needs an explicit JNI integration vector",
        )

        # The end-to-end vectors are necessary but do not, by themselves,
        # prove that the Java invocation handler has a branch for every
        # service.  Compare the exact shared contract against the handler's
        # Java-name dispatch table as a second, independent guard.  ``close``
        # is an AutoCloseable extension on the dynamic proxy, not an IEEE
        # RTIambassador service.
        handler = (
            Path(__file__).parents[2]
            / "umbra-rti-jni"
            / "src"
            / "main"
            / "java"
            / "org"
            / "umbra"
            / "jni"
            / "rti1516_2025"
            / "NativeRTIambassador.java"
        ).read_text(encoding="utf-8")
        dispatched_service_names = set(
            re.findall(r'"([A-Za-z][A-Za-z0-9_]*)"\.equals\(name\)', handler)
        )
        dispatched_service_names.discard("close")
        # Python keeps a distinct name for this timestamped overload, while
        # the IEEE Java interface uses the same ``sendDirectedInteraction``
        # name with a fifth argument.  Require the arity-specific Java branch
        # and its matching JNI endpoint before treating the Python alias as
        # dispatched.
        directed_time_branch = re.compile(
            r'"sendDirectedInteraction"\.equals\(name\).*?values\.length\s*==\s*5.*?'
            r"NativeBridge\.nativeSendDirectedInteractionWithTime",
            re.DOTALL,
        )
        self.assertRegex(handler, directed_time_branch)
        dispatched_service_names.add("sendDirectedInteractionWithTime")
        self.assertSetEqual(
            public_services,
            dispatched_service_names,
            "The JNI Java handler must dispatch every shared RTIambassador service",
        )

        # Name coverage alone can hide a newly added IEEE overload: the
        # dynamic proxy would enter the handler, fail to match its argument
        # count, and only then raise the generic unavailable-service error.
        # Read the exact standard Java interface through reflection and check
        # every declared parameter count against the handler's arity guards.
        # ``connect`` and ``joinFederationExecution`` intentionally delegate
        # their overload matrix to helpers, so their helper entry points are
        # checked separately below.
        import jpype

        # This audit is intentionally runnable on its own.  Most integration
        # vectors start JPype while constructing an ambassador, but a source
        # coverage test must not depend on unittest method ordering.
        self.factory.rtiName()
        java_rti_type = jpype.JClass("hla.rti1516_2025.RTIambassador").class_
        java_overloads: dict[str, set[int]] = {}
        for method in java_rti_type.getDeclaredMethods():
            java_overloads.setdefault(str(method.getName()), set()).add(
                int(method.getParameterTypes().length)
            )

        handler_arities: dict[str, set[int]] = {}
        dispatch_matches = list(
            re.finditer(r'"([A-Za-z][A-Za-z0-9_]*)"\.equals\(name\)', handler)
        )
        for index, match in enumerate(dispatch_matches):
            end = (
                dispatch_matches[index + 1].start()
                if index + 1 < len(dispatch_matches)
                else len(handler)
            )
            segment = handler[match.start() : end]
            handler_arities.setdefault(match.group(1), set()).update(
                int(value)
                for value in re.findall(r"values\.length\s*==\s*(\d+)", segment)
            )

        self.assertEqual(
            java_overloads.get("connect"),
            {2, 3, 4},
            "The IEEE Java RTIambassador connect overload matrix changed",
        )
        self.assertEqual(
            java_overloads.get("joinFederationExecution"),
            {2, 3, 4},
            "The IEEE Java RTIambassador join overload matrix changed",
        )
        for helper_name in ("connect", "joinFederationExecution"):
            self.assertIn(
                f'"{helper_name}".equals(name)',
                handler,
                f"The JNI Java handler must enter its {helper_name} overload helper",
            )

        missing_java_overloads = {
            name: sorted(arities - handler_arities.get(name, set()))
            for name, arities in java_overloads.items()
            if name not in {"connect", "joinFederationExecution"}
            and arities - handler_arities.get(name, set())
        }
        self.assertEqual(
            missing_java_overloads,
            {},
            "The JNI Java handler is missing an IEEE RTIambassador overload arity",
        )

    @unittest.skipUnless(
        os.environ.get("UMBRA_JNI_REQUIRE_RUNTIME_SERVICE_COVERAGE") == "1",
        "set UMBRA_JNI_REQUIRE_RUNTIME_SERVICE_COVERAGE=1 for runtime service accounting",
    )
    def test_zz_jni_runtime_service_call_coverage(self) -> None:
        """Require the full external suite to execute every shared service."""
        missing = sorted(
            set(RTIambassador.__abstractmethods__) - self._runtime_service_calls
        )
        self.assertEqual(
            missing,
            [],
            "The external JNI suite did not execute these public services",
        )

    def test_cpp_jni_java_jpype_timestamped_federation_save(self) -> None:
        """Exercise the timestamped save overload through every bridge layer."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-timestamped-save-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False
        try:
            reports_directory = self._temporary_directory / "timestamped-save-reports"
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            connection = ambassador.connect(
                callbacks,
                CallbackModel.HLA_EVOKED,
                configuration,
                HLAnoCredentials(),
            )
            connected = True
            self.assertTrue(connection.configurationUsed)
            self.assertTrue(reports_directory.is_dir())
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-timestamped-save-owner", federation_name
            )
            joined = True

            time_factory = ambassador.getTimeFactory()
            ambassador.enableTimeRegulation(time_factory.makeLogicalTimeInterval(1))
            for _ in range(20):
                ambassador.evokeCallback(0.0)
                if callbacks.time_regulation_enabled:
                    break
            self.assertEqual(callbacks.time_regulation_enabled[-1].getTime(), 0)

            # Exercise the integer implementation's decoder boundary through
            # the same external Java API.  The adapter must reject truncated,
            # trailing, and negative encodings as ``CouldNotDecode`` rather
            # than exposing a Java/JNI implementation exception.
            malformed_time_values = (
                b"",
                b"\0" * 7,
                b"\0" * 9,
                struct.pack(">q", -1),
            )
            for encoded in malformed_time_values:
                with self.assertRaises(CouldNotDecode):
                    time_factory.decodeLogicalTime(encoded)
                with self.assertRaises(CouldNotDecode):
                    time_factory.decodeLogicalTimeInterval(encoded)

            # Keep integer carriers exact above the IEEE-754 double precision
            # boundary. This proves JNI/Java retains the declared long value
            # instead of routing it through a Java/Python double field.
            integer_base = time_factory.makeLogicalTime(1 << 53)
            integer_epsilon = time_factory.makeLogicalTimeInterval(1)
            integer_advanced = time_factory.add(integer_base, integer_epsilon)
            self.assertEqual(integer_advanced.getTime(), (1 << 53) + 1)
            self.assertEqual(
                time_factory.subtract(integer_advanced, integer_epsilon).getTime(),
                1 << 53,
            )
            self.assertEqual(
                time_factory.difference(integer_advanced, integer_base).getInterval(),
                1,
            )
            integer_java_factory = ambassador.unwrap_java_object().getTimeFactory()
            integer_java_time = integer_java_factory.makeTime(1 << 53)
            integer_java_interval = integer_java_factory.makeInterval(1)
            self.assertEqual(integer_java_time.getValue(), 1 << 53)
            self.assertEqual(integer_java_interval.getValue(), 1)
            import jpype

            def encode_java_time(value):
                encoded = jpype.JArray(jpype.JByte)([0] * int(value.encodedLength()))
                value.encode(encoded, 0)
                return encoded

            self.assertEqual(
                integer_java_factory.decodeTime(
                    encode_java_time(integer_java_time), 0
                ).getValue(),
                1 << 53,
            )
            self.assertEqual(
                integer_java_factory.decodeInterval(
                    encode_java_time(integer_java_interval), 0
                ).getValue(),
                1,
            )
            integer_java_zero = integer_java_factory.makeZero()
            integer_java_epsilon = integer_java_factory.makeEpsilon()
            integer_java_sum = integer_java_zero.add(integer_java_epsilon)
            self.assertEqual(integer_java_sum.getValue(), 1)
            self.assertEqual(
                integer_java_sum.subtract(integer_java_epsilon).getValue(), 0
            )
            with self.assertRaises(IllegalTimeArithmetic):
                time_factory.add(time_factory.makeFinal(), integer_epsilon)
            with self.assertRaises(IllegalTimeArithmetic):
                time_factory.subtract(time_factory.makeInitial(), integer_epsilon)
            with self.assertRaises(IllegalTimeArithmetic):
                time_factory.difference(time_factory.makeInitial(), integer_base)

            ambassador.requestFederationSave(
                "jni-timestamped-save", time_factory.makeLogicalTime(1)
            )
            for _ in range(20):
                ambassador.evokeCallback(0.0)
                if callbacks.timestamped_save_initiations:
                    break
            self.assertEqual(
                callbacks.timestamped_save_initiations[0][0],
                "jni-timestamped-save",
            )
            self.assertEqual(callbacks.timestamped_save_initiations[0][1].getTime(), 1)

            ambassador.federateSaveBegun()
            ambassador.federateSaveComplete()
            for _ in range(20):
                ambassador.evokeCallback(0.0)
                if callbacks.saved_count:
                    break
            self.assertEqual(callbacks.saved_count, 1)
        finally:
            if joined:
                ambassador.resignFederationExecution(ResignAction.NO_ACTION)
            if created:
                ambassador.destroyFederationExecution(federation_name)
            if connected:
                ambassador.disconnect()
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_float64_time_decode_boundaries(self) -> None:
        """Preserve C++ float64 decode errors through raw Java and Python."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-float64-decode-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False
        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.FLOAT64_TIME
            )
            created = True
            ambassador.joinFederationExecution("jni-float64-decode", federation_name)
            joined = True

            python_factory = ambassador.getTimeFactory()
            self.assertIsInstance(python_factory, HLAfloat64TimeFactory)
            raw_factory = ambassador.unwrap_java_object().getTimeFactory()
            raw_could_not_decode = jpype.JClass(
                "hla.rti1516_2025.exceptions.CouldNotDecode"
            )
            raw_illegal_argument = jpype.JClass("java.lang.IllegalArgumentException")

            def java_bytes(payload: bytes):
                return jpype.JArray(jpype.JByte)(
                    [value if value < 128 else value - 256 for value in payload]
                )

            valid = struct.pack(">d", 3.25)
            raw_time = raw_factory.decodeTime(java_bytes(valid), 0)
            raw_interval = raw_factory.decodeInterval(java_bytes(valid), 0)
            self.assertEqual(raw_time.getTime(), 3.25)
            self.assertEqual(raw_interval.getInterval(), 3.25)
            self.assertEqual(python_factory.decodeLogicalTime(valid).getTime(), 3.25)
            self.assertEqual(
                python_factory.decodeLogicalTimeInterval(valid).getInterval(), 3.25
            )

            # The standard Java offset overload consumes the first eight
            # octets and leaves any later data to its caller. The normalized
            # Python factory intentionally remains strict about exact bytes.
            trailing = valid + b"\x66"
            self.assertEqual(
                raw_factory.decodeTime(java_bytes(trailing), 0).getTime(), 3.25
            )
            self.assertEqual(
                raw_factory.decodeInterval(java_bytes(trailing), 0).getInterval(),
                3.25,
            )
            with self.assertRaises(CouldNotDecode):
                python_factory.decodeLogicalTime(trailing)
            with self.assertRaises(CouldNotDecode):
                python_factory.decodeLogicalTimeInterval(trailing)

            # Java validates the requested eight-octet window before C++ is
            # called, preserving the standard IllegalArgumentException for a
            # short offset payload.
            short = b"\0" * 7
            with self.assertRaises(raw_illegal_argument):
                raw_factory.decodeTime(java_bytes(short), 0)
            with self.assertRaises(raw_illegal_argument):
                raw_factory.decodeInterval(java_bytes(short), 0)

            # These exact-width payloads reach C++ and retain its typed
            # CouldNotDecode mapping for negative and non-finite values.
            malformed = (
                struct.pack(">d", -1.0),
                struct.pack(">d", math.inf),
                struct.pack(">d", math.nan),
            )
            for encoded in malformed:
                with self.subTest(encoded=encoded.hex()):
                    with self.assertRaises(raw_could_not_decode):
                        raw_factory.decodeTime(java_bytes(encoded), 0)
                    with self.assertRaises(raw_could_not_decode):
                        raw_factory.decodeInterval(java_bytes(encoded), 0)
                    with self.assertRaises(CouldNotDecode):
                        python_factory.decodeLogicalTime(encoded)
                    with self.assertRaises(CouldNotDecode):
                        python_factory.decodeLogicalTimeInterval(encoded)
        finally:
            if joined:
                ambassador.resignFederationExecution(ResignAction.NO_ACTION)
            if created:
                ambassador.destroyFederationExecution(federation_name)
            if connected:
                ambassador.disconnect()
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_integer64_time_decode_boundaries(self) -> None:
        """Preserve signed HLAinteger64Time decoding through raw Java and Python."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-integer64-decode-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False
        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution("jni-integer64-decode", federation_name)
            joined = True

            python_factory = ambassador.getTimeFactory()
            self.assertIsInstance(python_factory, HLAinteger64TimeFactory)
            raw_factory = ambassador.unwrap_java_object().getTimeFactory()
            raw_could_not_decode = jpype.JClass(
                "hla.rti1516_2025.exceptions.CouldNotDecode"
            )
            raw_illegal_argument = jpype.JClass("java.lang.IllegalArgumentException")

            def java_bytes(payload: bytes):
                return jpype.JArray(jpype.JByte)(
                    [value if value < 128 else value - 256 for value in payload]
                )

            valid = struct.pack(">q", 258)
            self.assertEqual(raw_factory.getName(), HLA_TYPES.INTEGER64_TIME)
            raw_time = raw_factory.decodeTime(java_bytes(valid), 0)
            raw_interval = raw_factory.decodeInterval(java_bytes(valid), 0)
            self.assertEqual(raw_time.getValue(), 258)
            self.assertEqual(raw_interval.getValue(), 258)
            self.assertEqual(python_factory.decodeLogicalTime(valid).getTime(), 258)
            self.assertEqual(
                python_factory.decodeLogicalTimeInterval(valid).getInterval(), 258
            )

            # The standard Java offset overload decodes one eight-octet window,
            # while the normalized Python factory deliberately requires an
            # exact eight-octet payload.
            prefixed = b"\x55" + valid + b"\x66"
            self.assertEqual(
                raw_factory.decodeTime(java_bytes(prefixed), 1).getValue(), 258
            )
            self.assertEqual(
                raw_factory.decodeInterval(java_bytes(prefixed), 1).getValue(), 258
            )
            trailing = valid + b"\x66"
            self.assertEqual(
                raw_factory.decodeTime(java_bytes(trailing), 0).getValue(), 258
            )
            self.assertEqual(
                raw_factory.decodeInterval(java_bytes(trailing), 0).getValue(), 258
            )
            with self.assertRaises(CouldNotDecode):
                python_factory.decodeLogicalTime(trailing)
            with self.assertRaises(CouldNotDecode):
                python_factory.decodeLogicalTimeInterval(trailing)

            # Java validates the requested eight-octet window before JNI is
            # entered; exact-width negative values reach C++ and preserve its
            # typed CouldNotDecode result.
            short = b"\0" * 7
            for offset in (0, 1):
                with self.subTest(offset=offset):
                    with self.assertRaises(raw_illegal_argument):
                        raw_factory.decodeTime(java_bytes(short), offset)
                    with self.assertRaises(raw_illegal_argument):
                        raw_factory.decodeInterval(java_bytes(short), offset)

            negative = struct.pack(">q", -1)
            with self.assertRaises(raw_could_not_decode):
                raw_factory.decodeTime(java_bytes(negative), 0)
            with self.assertRaises(raw_could_not_decode):
                raw_factory.decodeInterval(java_bytes(negative), 0)
            with self.assertRaises(CouldNotDecode):
                python_factory.decodeLogicalTime(negative)
            with self.assertRaises(CouldNotDecode):
                python_factory.decodeLogicalTimeInterval(negative)
        finally:
            if joined:
                ambassador.resignFederationExecution(ResignAction.NO_ACTION)
            if created:
                ambassador.destroyFederationExecution(federation_name)
            if connected:
                ambassador.disconnect()
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_timed_save_replaces_pending_request_and_orders_tso(
        self,
    ) -> None:
        """Mirror C++ timed-save replacement and pre-grant TSO ordering."""

        class ReplacementCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[tuple[str, object]] = []

            def initiateFederateSave(
                self, label: str, time: object | None = None
            ) -> None:
                self.events.append(("save-initiate", label))
                super().initiateFederateSave(label, time)

            def receiveInteraction(self, *args: object, **kwargs: object) -> None:
                self.events.append(("interaction", None))
                super().receiveInteraction(*args, **kwargs)

            def timeAdvanceGrant(self, time: object) -> None:
                self.events.append(("grant", time.getTime()))
                super().timeAdvanceGrant(time)

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )
        federation_name = f"python-jni-timed-save-replacement-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        owner_callbacks = ReplacementCallbacks()
        receiver_callbacks = ReplacementCallbacks()
        created = owner_joined = receiver_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-timed-save-replacement-owner", federation_name
            )
            owner_joined = True
            receiver.joinFederationExecution(
                "jni-timed-save-replacement-receiver", federation_name
            )
            receiver_joined = True

            interaction = owner.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            parameter = owner.getParameterHandle(interaction, HLA_FIXTURES.IDENTIFIER)
            owner.publishInteractionClass(interaction)
            owner.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            receiver.subscribeInteractionClass(interaction)

            owner_time_factory = owner.getTimeFactory()
            receiver_time_factory = receiver.getTimeFactory()
            receiver.enableTimeConstrained()
            owner.enableTimeRegulation(owner_time_factory.makeLogicalTimeInterval(1))
            drain()
            self.assertTrue(owner_callbacks.time_regulation_enabled)
            self.assertTrue(receiver_callbacks.time_constrained_enabled)
            owner_callbacks.events.clear()
            receiver_callbacks.events.clear()

            with self.assertRaises(InvalidLogicalTime):
                owner.requestFederationSave(
                    "jni-timed-save-too-early",
                    owner_time_factory.makeLogicalTime(0),
                )
            with self.assertRaises(LogicalTimeAlreadyPassed):
                receiver.requestFederationSave(
                    "jni-timed-save-at-galt",
                    receiver_time_factory.makeLogicalTime(1),
                )

            owner.requestFederationSave(
                "jni-timed-save-replaced", owner_time_factory.makeLogicalTime(5)
            )
            owner.requestFederationSave(
                "jni-timed-save-final", owner_time_factory.makeLogicalTime(7)
            )
            self.assertEqual(owner_callbacks.timestamped_save_initiations, [])
            self.assertEqual(receiver_callbacks.timestamped_save_initiations, [])

            values = ParameterHandleValueMap({parameter: b"A5%"})
            tag = b"TSO"
            retraction = owner.sendInteractionWithTime(
                interaction,
                values,
                owner_time_factory.makeLogicalTime(7),
                tag,
            )
            self.assertTrue(retraction.isValid())
            receiver.timeAdvanceRequest(receiver_time_factory.makeLogicalTime(7))
            owner.timeAdvanceRequest(owner_time_factory.makeLogicalTime(7))

            # Drain in the same member order as the C++ reference vector, then
            # assert that the constrained recipient observes TSO delivery
            # before save initiation and its qualifying grant.
            for _ in range(40):
                owner.evokeCallback(0.0)
                receiver.evokeCallback(0.0)
                if (
                    receiver_callbacks.timestamped_interactions
                    and receiver_callbacks.timestamped_save_initiations
                    and receiver_callbacks.time_advance_grants
                ):
                    break
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 1)
            self.assertEqual(
                receiver_callbacks.timestamped_save_initiations[0][0],
                "jni-timed-save-final",
            )
            self.assertEqual(
                receiver_callbacks.timestamped_save_initiations[0][1].getTime(), 7
            )
            self.assertEqual(receiver_callbacks.time_advance_grants[-1].getTime(), 7)
            receiver_interaction = receiver_callbacks.timestamped_interactions[0]
            self.assertEqual(receiver_interaction[0], interaction)
            self.assertEqual(receiver_interaction[2], tag)
            self.assertEqual(receiver_interaction[6].getTime(), 7)
            self.assertEqual(receiver_interaction[7], OrderType.TIMESTAMP)
            self.assertEqual(receiver_interaction[8], OrderType.TIMESTAMP)
            self.assertEqual(
                [event[0] for event in receiver_callbacks.events[:3]],
                ["interaction", "save-initiate", "grant"],
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
                if owner_callbacks.timestamped_save_initiations:
                    break
            self.assertEqual(
                [event[0] for event in owner_callbacks.events[:2]],
                ["grant", "save-initiate"],
            )

            owner.federateSaveBegun()
            receiver.federateSaveBegun()
            owner.federateSaveComplete()
            receiver.federateSaveComplete()
            drain()
            self.assertEqual(owner_callbacks.saved_count, 1)
            self.assertEqual(receiver_callbacks.saved_count, 1)
        finally:
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            try:
                receiver.disconnect()
            except Exception:
                pass
            try:
                owner.disconnect()
            except Exception:
                pass
            receiver._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_save_waits_for_constrained_boundary(
        self,
    ) -> None:
        """Preserve timed-save admission ordering across two external-JAR members."""

        class TimedSaveCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[tuple[str, object]] = []

            def initiateFederateSave(
                self, label: str, time: object | None = None
            ) -> None:
                self.events.append(("initiate", label))
                super().initiateFederateSave(label, time)

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                self.events.append(("grant", time.getTime()))
                super().timeAdvanceGrant(time)

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-timed-save-boundary-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = TimedSaveCallbacks()
        peer_callbacks = TimedSaveCallbacks()
        created = owner_joined = peer_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution("jni-timed-save-owner", federation_name)
            owner_joined = True
            peer.joinFederationExecution("jni-timed-save-peer", federation_name)
            peer_joined = True

            owner_time_factory = owner.getTimeFactory()
            peer_time_factory = peer.getTimeFactory()
            save_time = owner_time_factory.makeLogicalTime(5)
            owner.enableTimeRegulation(owner_time_factory.makeLogicalTimeInterval(1))
            peer.enableTimeConstrained()
            drain()
            self.assertTrue(owner_callbacks.time_regulation_enabled)
            self.assertTrue(peer_callbacks.time_constrained_enabled)

            save_label = "jni-timed-save-boundary"
            owner.requestFederationSave(save_label, save_time)
            self.assertNotIn(("initiate", save_label), owner_callbacks.events)
            self.assertNotIn(("initiate", save_label), peer_callbacks.events)

            # Reaching the boundary at the regulating member is not enough;
            # the constrained member must also obtain its qualifying grant.
            owner.timeAdvanceRequest(save_time)
            drain()
            self.assertNotIn(("initiate", save_label), owner_callbacks.events)
            self.assertNotIn(("initiate", save_label), peer_callbacks.events)

            peer.timeAdvanceRequest(peer_time_factory.makeLogicalTime(5))
            drain()
            self.assertIn(("initiate", save_label), owner_callbacks.events)
            self.assertIn(("initiate", save_label), peer_callbacks.events)
            peer_initiate_index = peer_callbacks.events.index(("initiate", save_label))
            peer_grant_index = peer_callbacks.events.index(("grant", 5))
            self.assertLess(peer_initiate_index, peer_grant_index)

            owner.federateSaveBegun()
            peer.federateSaveBegun()
            owner.federateSaveComplete()
            peer.federateSaveComplete()
            drain()
            self.assertEqual(owner_callbacks.saved_count, 1)
            self.assertEqual(peer_callbacks.saved_count, 1)
        finally:
            if peer_joined:
                try:
                    peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            peer.disconnect()
            owner.disconnect()
            peer._implementation.close()
            owner._implementation.close()

