            peer.enableTimeConstrained()
            drain()

            save_label = "jni-float64-save-restore"
            owner.requestFederationSave(save_label, save_time)
            owner.timeAdvanceRequest(save_time)
            drain()
            peer.timeAdvanceRequest(peer_time_factory.makeLogicalTime(5.0))
            drain()
            self.assertEqual(
                owner_callbacks.timestamped_save_initiations[0][0], save_label
            )
