    def test_cpp_jni_java_jpype_immediate_timed_save_mixes_flush_queue_and_tar_boundaries(
        self,
    ) -> None:
        """Preserve mixed FQR/TAR GALT clamping under HLA_IMMEDIATE."""

        class ImmediateMixedBoundaryCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[tuple[str, object]] = []

            def initiateFederateSave(
                self, label: str, time: object | None = None
            ) -> None:
                self.events.append(("initiate", label))
                super().initiateFederateSave(label, time)

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                self.events.append(("grant", time.getTime()))
