    def test_cpp_jni_java_jpype_float64_timestamped_interaction_callback(
        self,
    ) -> None:
        """Carry float64 timestamp/order/retraction metadata through a callback."""
        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )
        federation_name = f"python-jni-float64-timestamped-interaction-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = _JniCallbacks()
        publisher_connected = receiver_connected = created = False
        publisher_joined = receiver_joined = False
        receiver_interaction: InteractionClassHandle | None = None

        def pump(rounds: int = 40) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            receiver_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.FLOAT64_TIME
            )
            created = True
            publisher_federate = publisher.joinFederationExecution(
                "publisher",
                federation_name,
                federateName="jni-float64-timestamped-publisher",
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-float64-timestamped-receiver", federation_name
            )
            receiver_joined = True

            publisher_interaction = publisher.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            receiver_interaction = receiver.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            publisher_parameter = publisher.getParameterHandle(
                publisher_interaction, HLA_FIXTURES.IDENTIFIER
            )
            receiver_parameter = receiver.getParameterHandle(
                receiver_interaction, HLA_FIXTURES.IDENTIFIER
            )
            publisher.publishInteractionClass(publisher_interaction)
            publisher.changeInteractionOrderType(
                publisher_interaction, OrderType.TIMESTAMP
            )
            receiver.subscribeInteractionClass(receiver_interaction)
            receiver.enableTimeConstrained()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(1.0)
            )
            pump()
            self.assertTrue(receiver_callbacks.time_constrained_enabled)
            self.assertTrue(publisher_callbacks.time_regulation_enabled)
            self.assertIsInstance(publisher.getTimeFactory(), HLAfloat64TimeFactory)

            values = ParameterHandleValueMap({publisher_parameter: b"F64"})
            tag = b"float64-interaction"
            retraction = publisher.sendInteractionWithTime(
                publisher_interaction,
                values,
                publisher.getTimeFactory().makeLogicalTime(2.5),
                tag,
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])
            receiver.flushQueueRequest(receiver.getTimeFactory().makeLogicalTime(3.0))
            pump()
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 1)
            report = receiver_callbacks.timestamped_interactions[0]
            self.assertEqual(report[0], receiver_interaction)
            self.assertEqual(dict(report[1]), {receiver_parameter: b"F64"})
            self.assertEqual(report[2], tag)
            self.assertEqual(report[4], publisher_federate)
            self.assertIsInstance(report[6], HLAfloat64Time)
            self.assertEqual(report[6].getTime(), 2.5)
            self.assertEqual(report[7], OrderType.TIMESTAMP)
            self.assertEqual(report[8], OrderType.TIMESTAMP)
            self.assertEqual(report[9], retraction)

            publisher.retract(retraction)
            pump()
            self.assertEqual(receiver_callbacks.retraction_requests, [retraction])
        finally:
            if receiver_joined and receiver_interaction is not None:
                try:
                    receiver.unsubscribeInteractionClass(receiver_interaction)
                except Exception:
                    pass
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if receiver_connected:
                try:
                    receiver.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            receiver._implementation.close()
            publisher._implementation.close()

