    def test_cpp_jni_java_jpype_restore_preserves_terminal_regional_attribute_retraction(
        self,
    ) -> None:
        """Restore terminal and post-save regional retraction classifications."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-terminal-regional-attribute-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = _JniCallbacks()
        publisher_connected = receiver_connected = created = False
        publisher_joined = receiver_joined = False
        publisher_region: RegionHandle | None = None
        receiver_region: RegionHandle | None = None
        object_instance: ObjectInstanceHandle | None = None
        publisher_pairs: AttributeSetRegionSetPairList | None = None
        receiver_pairs: AttributeSetRegionSetPairList | None = None

        def pump(rounds: int = 30) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            receiver_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-terminal-regional-attribute-publisher", federation_name
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-terminal-regional-attribute-receiver", federation_name
            )
            receiver_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            receiver_class = receiver.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            receiver_attribute = receiver.getAttributeHandle(
                receiver_class, HLA_FIXTURES.FLAVOR
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            receiver_dimension = receiver.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            publisher_attributes = AttributeHandleSet([publisher_attribute])
            receiver_attributes = AttributeHandleSet([receiver_attribute])
            publisher.publishObjectClassAttributes(
                publisher_class, publisher_attributes
            )
            publisher.changeDefaultAttributeOrderType(
                publisher_class, publisher_attributes, OrderType.TIMESTAMP
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            receiver_region = receiver.createRegion(
                DimensionHandleSet([receiver_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 2)
            )
            receiver.setRangeBounds(
                receiver_region, receiver_dimension, RangeBounds(1, 3)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            receiver.commitRegionModifications(RegionHandleSet([receiver_region]))
            publisher_pairs = AttributeSetRegionSetPairList(
                [
                    AttributeSetRegionSetPair(
                        publisher_attributes, RegionHandleSet([publisher_region])
                    )
                ]
            )
            receiver_pairs = AttributeSetRegionSetPairList(
                [
                    AttributeSetRegionSetPair(
                        receiver_attributes, RegionHandleSet([receiver_region])
                    )
                ]
            )
            receiver.subscribeObjectClassAttributesWithRegions(
                receiver_class, receiver_pairs, active=True
            )
            receiver.setConveyRegionDesignatorSetsSwitch(True)
            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            pump()
            self.assertEqual(len(receiver_callbacks.discovered_objects), 1)

            receiver.enableTimeConstrained()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(receiver_callbacks.time_constrained_enabled)
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            values = AttributeHandleValueMap({publisher_attribute: b"TR-A"})
            tag = b"RA-T"
            timestamp = publisher.getTimeFactory().makeLogicalTime(7)
            terminal = publisher.updateAttributeValuesWithTime(
                object_instance, values, timestamp, tag
            )
            self.assertTrue(terminal.isValid())
            publisher.retract(terminal)
            pump()
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(terminal)

            # Save a separate live passel, consume it before the snapshot, and
            # create one more post-save handle. Restore must keep the terminal
            # tombstone while rejecting the post-save handle as foreign.
            admission = publisher.updateAttributeValuesWithTime(
                object_instance, values, timestamp, tag
            )
            self.assertTrue(admission.isValid())
            receiver.timeAdvanceRequest(receiver.getTimeFactory().makeLogicalTime(1))
            save_label = f"jni-terminal-regional-attribute-save-{uuid4().hex[:10]}"
            publisher.requestFederationSave(save_label)
            pump()
            publisher.federateSaveBegun()
            receiver.federateSaveBegun()
            publisher.federateSaveComplete()
            receiver.federateSaveComplete()
            pump()
            self.assertEqual(publisher_callbacks.saved_count, 1)
            self.assertEqual(receiver_callbacks.saved_count, 1)

            publisher.retract(admission)
            pump()
            post_save = publisher.updateAttributeValuesWithTime(
                object_instance, values, timestamp, tag
            )
            self.assertTrue(post_save.isValid())
            self.assertNotEqual(terminal.encodedValue, post_save.encodedValue)

            publisher.requestFederationRestore(save_label)
            pump()
            publisher.federateRestoreComplete()
            receiver.federateRestoreComplete()
            pump()
            self.assertEqual(publisher_callbacks.restore_completions, 1)
            self.assertEqual(receiver_callbacks.restore_completions, 1)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(terminal)
            with self.assertRaises(InvalidMessageRetractionHandle):
                publisher.retract(post_save)
        finally:
            if (
                receiver_joined
                and receiver_region is not None
                and receiver_pairs is not None
            ):
                try:
                    receiver.unsubscribeObjectClassAttributesWithRegions(
                        receiver_class, receiver_pairs
                    )
                except Exception:
                    pass
            if (
                object_instance is not None
                and publisher_joined
                and publisher_pairs is not None
            ):
                try:
                    publisher.unassociateRegionsForUpdates(
                        object_instance, publisher_pairs
                    )
                except Exception:
                    pass
            if receiver_region is not None:
                try:
                    receiver.deleteRegion(receiver_region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if receiver_connected:
                try:
                    receiver.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            receiver._implementation.close()
            publisher._implementation.close()

