            for _ in range(30):
                subscriber.evokeCallback(0.0)
                if subscriber_callbacks.removed_objects:
                    break
            self.assertTrue(subscriber_callbacks.report_present_at_callback)
            self.assertEqual(
                subscriber_callbacks.removed_objects,
                [(object_instance, b"rep", publisher_handle)],
            )
            report_after_removal = subscriber_report.read_text(encoding="utf-8")
            self.assertIn('"HLAservice":"RemoveObjectInstance"', report_after_removal)
            self.assertIn('"HLAargumentValue":"cmVw"', report_after_removal)
            removal_suffix = report_after_removal[len(before_removal) :]
