    def test_cpp_jni_java_jpype_timestamped_removal_report_precedes_callbacks(
        self,
    ) -> None:
        """Preserve timestamped removal reporting before receive and TSO callbacks."""

        class ReportingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.events: list[str] = []
                self.report_file: Path | None = None
                self.report_before_callback: str | None = None
                self.report_present_at_callback = False

            def removeObjectInstance(self, *args: object, **kwargs: object) -> None:
                self.events.append("remove")
                if (
                    self.report_file is not None
                    and self.report_before_callback is not None
                ):
                    report = self.report_file.read_text(encoding="utf-8")
                    self.report_present_at_callback = (
                        len(report) > len(self.report_before_callback)
                        and '"HLAservice":"RemoveObjectInstance"' in report
                    )
                super().removeObjectInstance(*args, **kwargs)

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                self.events.append("grant")
                super().timeAdvanceGrant(time)

        repository_root = Path(__file__).parents[3]
        restaurant_fom = (
            repository_root
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        switch_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-timestamped-removal-report-{uuid4().hex[:12]}"
        reports_directory = (
            self._temporary_directory
            / f"timestamped-removal-reports-{uuid4().hex[:12]}"
        )
        publisher = self.factory.getRtiAmbassador()
        immediate = self.factory.getRtiAmbassador()
        constrained = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        immediate_callbacks = ReportingCallbacks()
        constrained_callbacks = ReportingCallbacks()
        publisher_connected = immediate_connected = constrained_connected = False
        publisher_joined = immediate_joined = constrained_joined = created = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            publisher.connect(
                publisher_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            publisher_connected = True
            immediate.connect(
                immediate_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            immediate_connected = True
            constrained.connect(
                constrained_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            constrained_connected = True
            publisher.createFederationExecution(
                federation_name,
                [str(restaurant_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            publisher_handle = publisher.joinFederationExecution(
                "jni-timestamped-removal-publisher",
                federation_name,
                federateName="jni-timestamped-removal-publisher",
            )
            publisher_joined = True
            immediate.joinFederationExecution(
                "jni-timestamped-removal-immediate",
                federation_name,
                federateName="jni-timestamped-removal-immediate",
            )
            immediate_joined = True
            constrained.joinFederationExecution(
                "jni-timestamped-removal-constrained",
                federation_name,
                federateName="jni-timestamped-removal-constrained",
            )
            constrained_joined = True

            def report_for(federate_name: str) -> Path:
                marker = f'"HLAfederateName":"{federate_name}"'
                for path in sorted(reports_directory.glob("*")):
                    if marker in path.read_text(encoding="utf-8"):
                        return path
                self.fail(f"service report file not found for {federate_name}")
                raise AssertionError(
                    f"service report file not found for {federate_name}"
                )

            immediate_report = report_for("jni-timestamped-removal-immediate")
            constrained_report = report_for("jni-timestamped-removal-constrained")
            immediate_callbacks.report_file = immediate_report
            constrained_callbacks.report_file = constrained_report

            # Keep setup services out of the two recipient files. The support
            # FOM starts reporting enabled; this is the same C++ test boundary.
            for ambassador in (immediate, constrained):
                ambassador.setServiceReportingSwitch(False)
                ambassador.setSendServiceReportsToFileSwitch(False)

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            immediate_class = immediate.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            constrained_class = constrained.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            publisher_name = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.NAME
            )
            immediate_name = immediate.getAttributeHandle(
                immediate_class, HLA_FIXTURES.NAME
            )
            constrained_name = constrained.getAttributeHandle(
                constrained_class, HLA_FIXTURES.NAME
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_name])
            )
            immediate.subscribeObjectClassAttributes(
                immediate_class, AttributeHandleSet([immediate_name]), active=True
            )
            constrained.subscribeObjectClassAttributes(
                constrained_class, AttributeHandleSet([constrained_name]), active=True
            )
            object_instance = publisher.registerObjectInstance(publisher_class)
            for _ in range(30):
                immediate.evokeCallback(0.0)
                constrained.evokeCallback(0.0)
                if (
                    immediate_callbacks.discovered_objects
                    and constrained_callbacks.discovered_objects
                ):
                    break
            self.assertEqual(
                immediate_callbacks.discovered_objects[0][0], object_instance
            )
            self.assertEqual(
                constrained_callbacks.discovered_objects[0][0], object_instance
            )

            constrained.enableTimeConstrained()
            self.assertFalse(constrained.evokeCallback(0.0))
            self.assertEqual(len(constrained_callbacks.time_constrained_enabled), 1)
            time_factory = publisher.getTimeFactory()
            publisher.enableTimeRegulation(time_factory.makeLogicalTimeInterval(5))
            for _ in range(30):
                publisher.evokeCallback(0.0)
                if publisher_callbacks.time_regulation_enabled:
                    break
            self.assertEqual(len(publisher_callbacks.time_regulation_enabled), 1)

            for ambassador in (immediate, constrained):
                ambassador.setServiceReportingSwitch(True)
                ambassador.setSendServiceReportsToFileSwitch(True)
            immediate_before = immediate_report.read_text(encoding="utf-8")
            constrained_before = constrained_report.read_text(encoding="utf-8")
            tag = b"rep"
            retraction = publisher.deleteObjectInstanceWithTime(
                object_instance, time_factory.makeLogicalTime(6), tag
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(immediate_callbacks.timestamped_removals, [])
            self.assertEqual(constrained_callbacks.timestamped_removals, [])
            self.assertEqual(
                immediate_report.read_text(encoding="utf-8"), immediate_before
            )
            self.assertEqual(
                constrained_report.read_text(encoding="utf-8"), constrained_before
            )

            def decode_timestamped_removal_report(
                report_file: Path, before: str, expected_received_order: str
            ) -> dict[str, object]:
                suffix = report_file.read_text(encoding="utf-8")[len(before) :]
                record, consumed = json.JSONDecoder().raw_decode(suffix)
                self.assertEqual(consumed, len(suffix))
                self.assertEqual(record[HLA_MOM.SERVICE], "RemoveObjectInstance")
                self.assertIsInstance(record[HLA_MOM.SERIAL_NUMBER], int)
                self.assertEqual(record[HLA_MOM.RETURNED_ARGUMENT], [None])
                self.assertTrue(record[HLA_MOM.SUCCESS_INDICATOR])
                self.assertIsNone(record[HLA_MOM.EXCEPTION])
                self.assertEqual(len(record[HLA_MOM.SUPPLIED_ARGUMENTS]), 7)
                (
                    object_argument,
                    tag_argument,
                    sent_order_argument,
                    producer_argument,
                    timestamp_argument,
                    received_order_argument,
                    retraction_argument,
                ) = record[HLA_MOM.SUPPLIED_ARGUMENTS]
                self.assertEqual(object_argument[HLA_MOM.ARGUMENT_TYPE], 37)
                self.assertEqual(
                    object_argument[HLA_MOM.ARGUMENT_NAME], "Object instance designator"
                )
                self.assertRegex(
                    object_argument[HLA_MOM.ARGUMENT_VALUE],
                    r"^ObjectInstanceHandle\(\d+\)$",
                )
                self.assertEqual(
                    tag_argument,
                    {
                        HLA_MOM.ARGUMENT_TYPE: 63,
                        HLA_MOM.ARGUMENT_NAME: "User-supplied tag",
                        HLA_MOM.ARGUMENT_VALUE: "cmVw",
                    },
                )
                self.assertEqual(
                    sent_order_argument,
                    {
                        HLA_MOM.ARGUMENT_TYPE: 38,
                        HLA_MOM.ARGUMENT_NAME: "Sent message order type",
                        HLA_MOM.ARGUMENT_VALUE: "TIMESTAMP",
                    },
                )
                self.assertEqual(producer_argument[HLA_MOM.ARGUMENT_TYPE], 15)
                self.assertEqual(
                    producer_argument[HLA_MOM.ARGUMENT_NAME],
                    "Producing joined federate designator",
                )
                self.assertRegex(
                    producer_argument[HLA_MOM.ARGUMENT_VALUE],
                    r"^FederateHandle\(\d+\)$",
                )
                self.assertEqual(
                    timestamp_argument,
                    {
                        HLA_MOM.ARGUMENT_TYPE: 31,
                        HLA_MOM.ARGUMENT_NAME: "Optional timestamp",
                        HLA_MOM.ARGUMENT_VALUE: "6",
                    },
                )
                self.assertEqual(received_order_argument[HLA_MOM.ARGUMENT_TYPE], 38)
                self.assertEqual(
                    received_order_argument[HLA_MOM.ARGUMENT_NAME],
                    "Optional receive message order type",
                )
                self.assertEqual(
                    received_order_argument[HLA_MOM.ARGUMENT_VALUE],
                    expected_received_order,
                )
                self.assertEqual(retraction_argument[HLA_MOM.ARGUMENT_TYPE], 33)
                self.assertEqual(
                    retraction_argument[HLA_MOM.ARGUMENT_NAME],
                    "Optional message retraction designator",
                )
                self.assertRegex(
                    retraction_argument[HLA_MOM.ARGUMENT_VALUE],
                    r"^MessageRetractionHandle<\d+>$",
                )
                return record

            immediate_callbacks.report_before_callback = immediate_before
            immediate.evokeCallback(0.0)
            self.assertTrue(immediate_callbacks.report_present_at_callback)
            self.assertEqual(immediate_callbacks.events, ["remove"])
            self.assertEqual(len(immediate_callbacks.timestamped_removals), 1)
            immediate_removal = immediate_callbacks.timestamped_removals[0]
            self.assertEqual(immediate_removal[0], object_instance)
            self.assertEqual(immediate_removal[1], tag)
            self.assertEqual(immediate_removal[2], publisher_handle)
            self.assertEqual(immediate_removal[3].getTime(), 6)
            self.assertEqual(immediate_removal[4], OrderType.TIMESTAMP)
            self.assertEqual(immediate_removal[5], OrderType.RECEIVE)
            self.assertTrue(immediate_removal[6].isValid())
            self.assertEqual(immediate_removal[6].encodedValue, retraction.encodedValue)
            decode_timestamped_removal_report(
                immediate_report, immediate_before, "RECEIVE"
            )

            constrained.timeAdvanceRequest(
                constrained.getTimeFactory().makeLogicalTime(6)
            )
            constrained_after_request = constrained_report.read_text(encoding="utf-8")
            self.assertIn(
                '"HLAservice":"TimeAdvanceRequest"', constrained_after_request
            )
            constrained_callbacks.report_before_callback = constrained_after_request
            publisher.timeAdvanceRequest(time_factory.makeLogicalTime(2))
            self.assertFalse(publisher.evokeCallback(0.0))
            constrained.evokeCallback(0.0)
            self.assertTrue(constrained_callbacks.report_present_at_callback)
            self.assertEqual(constrained_callbacks.events, ["remove", "grant"])
            self.assertEqual(len(constrained_callbacks.timestamped_removals), 1)
            constrained_removal = constrained_callbacks.timestamped_removals[0]
            self.assertEqual(constrained_removal[0], object_instance)
            self.assertEqual(constrained_removal[1], tag)
            self.assertEqual(constrained_removal[2], publisher_handle)
            self.assertEqual(constrained_removal[3].getTime(), 6)
            self.assertEqual(constrained_removal[4], OrderType.TIMESTAMP)
            self.assertEqual(constrained_removal[5], OrderType.TIMESTAMP)
            self.assertTrue(constrained_removal[6].isValid())
            self.assertEqual(
                constrained_removal[6].encodedValue, retraction.encodedValue
            )
            decode_timestamped_removal_report(
                constrained_report, constrained_after_request, "TIMESTAMP"
            )
        finally:
            if constrained_joined:
                try:
                    constrained.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if immediate_joined:
                try:
                    immediate.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, connected in (
                (constrained, constrained_connected),
                (immediate, immediate_connected),
                (publisher, publisher_connected),
            ):
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

    def test_cpp_jni_java_jpype_service_report_precedes_time_advance_grant(
        self,
    ) -> None:
        """Keep accepted time-advance reporting ordered before the Java grant callback."""

        class ReportingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.report_file: Path | None = None
                self.report_before_callback: str | None = None
                self.report_present_at_callback = False

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                if (
                    self.report_file is not None
                    and self.report_before_callback is not None
                ):
                    report = self.report_file.read_text(encoding="utf-8")
                    self.report_present_at_callback = (
                        len(report) > len(self.report_before_callback)
                        and '"HLAservice":"TimeAdvanceRequest"' in report
                    )
                super().timeAdvanceGrant(time)

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-time-advance-report-order-{uuid4().hex[:12]}"
        reports_directory = (
            self._temporary_directory / f"time-advance-reports-{uuid4().hex[:12]}"
        )
        ambassador = self.factory.getRtiAmbassador()
        callbacks = ReportingCallbacks()
        connected = created = joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED, configuration)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-time-advance-report-subject",
                federation_name,
                federateName="jni-time-advance-report-subject",
            )
            joined = True
            report_files = sorted(reports_directory.glob("*"))
            self.assertEqual(len(report_files), 1)
            report_file = report_files[0]
            callbacks.report_file = report_file
            before_request = report_file.read_text(encoding="utf-8")
            callbacks.report_before_callback = before_request
            ambassador.timeAdvanceRequest(
                ambassador.getTimeFactory().makeLogicalTime(7)
            )
            after_request = report_file.read_text(encoding="utf-8")
            self.assertIn('"HLAservice":"TimeAdvanceRequest"', after_request)
            self.assertGreater(len(after_request), len(before_request))
            request_suffix = after_request[len(before_request) :]
            request_record, request_consumed = json.JSONDecoder().raw_decode(
                request_suffix
            )
            self.assertEqual(request_consumed, len(request_suffix))
            self.assertEqual(request_record[HLA_MOM.SERVICE], "TimeAdvanceRequest")
            self.assertIsInstance(request_record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(request_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(request_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(request_record[HLA_MOM.EXCEPTION])
            self.assertEqual(len(request_record[HLA_MOM.SUPPLIED_ARGUMENTS]), 1)
            request_argument = request_record[HLA_MOM.SUPPLIED_ARGUMENTS][0]
            self.assertEqual(request_argument[HLA_MOM.ARGUMENT_TYPE], 31)
            self.assertEqual(request_argument[HLA_MOM.ARGUMENT_NAME], "Logical time")
            self.assertEqual(request_argument[HLA_MOM.ARGUMENT_VALUE], "7")
            self.assertEqual(callbacks.time_advance_grants, [])
            self.assertEqual(ambassador.queryLogicalTime().getTime(), 0)
            ambassador.evokeCallback(0.0)
            self.assertTrue(callbacks.report_present_at_callback)
            self.assertEqual(callbacks.time_advance_grants[-1].getTime(), 7)
            self.assertEqual(ambassador.queryLogicalTime().getTime(), 7)
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

