    def test_cpp_jni_java_jpype_service_report_precedes_next_message_grant(
        self,
    ) -> None:
        """Preserve the supplied Next Message Request report before its grant."""

        class ReportingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.report_file: Path | None = None
                self.report_before_callback: str | None = None
                self.report_present_at_callback = False

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                if (
                    self.report_file is not None
                    and self.report_before_callback is not None
                ):
                    report = self.report_file.read_text(encoding="utf-8")
                    self.report_present_at_callback = (
                        len(report) > len(self.report_before_callback)
                        and '"HLAservice":"NextMessageRequest"' in report
                    )
                super().timeAdvanceGrant(time)

        repository_root = Path(__file__).parents[3]
        interaction_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )
        switch_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-next-message-report-order-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"next-message-reports-{uuid4().hex[:12]}"
        )
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = ReportingCallbacks()
        publisher_connected = receiver_connected = created = False
        publisher_joined = receiver_joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            publisher.connect(
                publisher_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            publisher_connected = True
            receiver.connect(
                receiver_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            receiver_connected = True
            publisher.createFederationExecution(
                federation_name,
                [str(interaction_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            publisher.joinFederationExecution(
                "jni-next-message-report-publisher",
                federation_name,
                federateName="jni-next-message-report-publisher",
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-next-message-report-receiver",
                federation_name,
                federateName="jni-next-message-report-receiver",
            )
            receiver_joined = True

            report_files = sorted(reports_directory.glob("*"))
            receiver_report = next(
                (
                    path
                    for path in report_files
                    if '"HLAfederateName":"jni-next-message-report-receiver"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(receiver_report)
            assert receiver_report is not None
            receiver_callbacks.report_file = receiver_report

            interaction = publisher.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            parameter = publisher.getParameterHandle(
                interaction, HLA_FIXTURES.IDENTIFIER
            )
            publisher.publishInteractionClass(interaction)
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            receiver.subscribeInteractionClass(interaction)
            receiver.enableTimeConstrained()
            receiver.evokeCallback(0.0)
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            publisher.evokeCallback(0.0)
            publisher.sendInteractionWithTime(
                interaction,
                ParameterHandleValueMap({parameter: b"nmr-report-payload"}),
                publisher.getTimeFactory().makeLogicalTime(7),
                b"NMR",
            )

            before_request = receiver_report.read_text(encoding="utf-8")
            receiver_callbacks.report_before_callback = before_request
            receiver.nextMessageRequest(receiver.getTimeFactory().makeLogicalTime(10))
            after_request = receiver_report.read_text(encoding="utf-8")
            self.assertIn('"HLAservice":"NextMessageRequest"', after_request)
            self.assertGreater(len(after_request), len(before_request))
            request_suffix = after_request[len(before_request) :]
            request_record, request_consumed = json.JSONDecoder().raw_decode(
                request_suffix
            )
            self.assertEqual(request_consumed, len(request_suffix))
            self.assertEqual(request_record[HLA_MOM.SERVICE], "NextMessageRequest")
            self.assertIsInstance(request_record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(request_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(request_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(request_record[HLA_MOM.EXCEPTION])
            self.assertEqual(len(request_record[HLA_MOM.SUPPLIED_ARGUMENTS]), 1)
            request_argument = request_record[HLA_MOM.SUPPLIED_ARGUMENTS][0]
            self.assertEqual(request_argument[HLA_MOM.ARGUMENT_TYPE], 31)
            self.assertEqual(request_argument[HLA_MOM.ARGUMENT_NAME], "Logical time")
            self.assertEqual(request_argument[HLA_MOM.ARGUMENT_VALUE], "10")
            self.assertEqual(receiver_callbacks.time_advance_grants, [])
            self.assertEqual(receiver.queryLogicalTime().getTime(), 0)

            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            publisher.evokeCallback(0.0)
            receiver.evokeCallback(0.0)
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 1)
            self.assertTrue(receiver_callbacks.report_present_at_callback)
            self.assertEqual(len(receiver_callbacks.time_advance_grants), 1)
            self.assertEqual(receiver_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(receiver.queryLogicalTime().getTime(), 7)
        finally:
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if receiver_connected:
                try:
                    receiver.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            receiver._implementation.close()
            publisher._implementation.close()

