                    self.report_present_at_callback = (
                        len(report) > len(self.report_before_callback)
                        and '"HLAservice":"RegisterFederationSynchronizationPoint"'
                        in report
                        and '"HLAservice":"ConfirmSynchronizationPointRegistration"'
                        in report
                    )
