            self.assertEqual(reflection[4], publisher_handle)
            self.assertEqual(reflection[6].getTime(), 7)
            self.assertEqual(reflection[7], OrderType.TIMESTAMP)
            self.assertEqual(reflection[8], OrderType.RECEIVE)
