    def test_cpp_jni_java_jpype_request_attribute_update_report_precedes_callback(
        self,
    ) -> None:
        """Route object/class attribute-value requests through standard MOM reporting."""

        class ReportingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.report_class: InteractionClassHandle | None = None
                self.report_seen_at_callback = False

            def provideAttributeValueUpdate(self, *arguments: object) -> None:
                if self.report_class is not None:
                    self.report_seen_at_callback = any(
                        callback[0] == self.report_class
                        for callback in self.received_interactions
                    )
                super().provideAttributeValueUpdate(*arguments)

        repository_root = Path(__file__).parents[3]
        restaurant_fom = (
            repository_root
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-attribute-request-report-{uuid4().hex[:12]}"
        provider = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        provider_callbacks = ReportingCallbacks()
        requester_callbacks = _JniCallbacks()
        provider_connected = requester_connected = created = False
        provider_joined = requester_joined = False
        requester_report_file: Path | None = None
        try:
            provider.connect(provider_callbacks, CallbackModel.HLA_IMMEDIATE)
            provider_connected = True
            reports_directory = self._temporary_directory / (
                f"attribute-request-file-reports-{uuid4().hex[:12]}"
            )
            reports_directory.mkdir(parents=True, exist_ok=True)
            requester_configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            requester.connect(
                requester_callbacks,
                CallbackModel.HLA_EVOKED,
                requester_configuration,
            )
            requester_connected = True
            provider.createFederationExecution(
                federation_name, [str(restaurant_fom)], HLA_TYPES.INTEGER64_TIME
            )
            created = True
            provider_handle = provider.joinFederationExecution(
                "jni-attribute-request-provider", federation_name
            )
            provider_joined = True
            requester.joinFederationExecution(
                "jni-attribute-request-requester",
                federation_name,
                federateName="jni-attribute-request-requester",
            )
            requester_joined = True
            requester_report_file = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-attribute-request-requester"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(requester_report_file)
            assert requester_report_file is not None

            provider_class = provider.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            requester_class = requester.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            provider_name = provider.getAttributeHandle(
                provider_class, HLA_FIXTURES.NAME
            )
            requester_name = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.NAME
            )
            provider.publishObjectClassAttributes(
                provider_class, AttributeHandleSet([provider_name])
            )
            requester.subscribeObjectClassAttributes(
                requester_class, AttributeHandleSet([requester_name])
            )
            object_instance = provider.registerObjectInstance(provider_class)
            for _ in range(30):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[0][0], object_instance
            )

            report_class = provider.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
            report_parameter_names = (
                HLA_MOM.SERVICE,
                HLA_MOM.SERVICE_TYPE,
                HLA_MOM.SUCCESS_INDICATOR,
                HLA_MOM.SUPPLIED_ARGUMENTS,
                HLA_MOM.RETURNED_ARGUMENT,
                HLA_MOM.EXCEPTION,
                HLA_MOM.SERIAL_NUMBER,
            )
            report_parameters = {
                name: provider.getParameterHandle(report_class, name)
                for name in report_parameter_names
            }
            provider.setServiceReportingSwitch(False)
            provider.subscribeInteractionClass(report_class)
            provider_callbacks.report_class = report_class
            requester.setServiceReportingSwitch(True)

            def decode_file_report(
                before: str,
                expected_first_type: int,
                tag: bytes,
                expected_serial: int,
            ) -> None:
                suffix = requester_report_file.read_text(encoding="utf-8")[
                    len(before) :
                ]
                record, consumed = json.JSONDecoder().raw_decode(suffix)
                self.assertEqual(consumed, len(suffix))
                self.assertEqual(record[HLA_MOM.SERVICE], "RequestAttributeValueUpdate")
                self.assertEqual(record[HLA_MOM.SERIAL_NUMBER], expected_serial)
                self.assertEqual(record[HLA_MOM.RETURNED_ARGUMENT], [None])
                self.assertTrue(record[HLA_MOM.SUCCESS_INDICATOR])
                self.assertIsNone(record[HLA_MOM.EXCEPTION])
                supplied = record[HLA_MOM.SUPPLIED_ARGUMENTS]
                self.assertEqual(len(supplied), 3)
                self.assertEqual(
                    supplied[0][HLA_MOM.ARGUMENT_TYPE], expected_first_type
                )
                self.assertRegex(
                    supplied[0][HLA_MOM.ARGUMENT_VALUE],
                    r"^Object(?:Instance|Class)Handle\(\d+\)$",
                )
                self.assertEqual(supplied[1][HLA_MOM.ARGUMENT_TYPE], 1)
                self.assertEqual(
                    supplied[1][HLA_MOM.ARGUMENT_NAME], "Set of attribute designators"
                )
                self.assertEqual(len(supplied[1][HLA_MOM.ARGUMENT_VALUE]), 1)
                self.assertRegex(
                    supplied[1][HLA_MOM.ARGUMENT_VALUE][0],
                    r"^AttributeHandle\(\d+\)$",
                )
                self.assertEqual(
                    supplied[2],
                    {
                        HLA_MOM.ARGUMENT_TYPE: 63,
                        HLA_MOM.ARGUMENT_NAME: "User-supplied tag",
                        HLA_MOM.ARGUMENT_VALUE: base64.b64encode(tag).decode("ascii"),
                    },
                )

            def decode_report(
                callback: tuple[object, ...],
                expected_first_type: int,
                tag: bytes,
                expected_serial: int,
            ):
                self.assertEqual(callback[0], report_class)
                values = dict(callback[1])
                encoder = self.factory.getEncoderFactory()
                self.assertEqual(
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue(),
                    "RequestAttributeValueUpdate",
                )
                self.assertEqual(
                    encoder.createHLAinteger16BE()
                    .decode(values[report_parameters[HLA_MOM.SERVICE_TYPE]])
                    .getValue(),
                    2,
                )
                self.assertTrue(
                    encoder.createHLAboolean()
                    .decode(values[report_parameters[HLA_MOM.SUCCESS_INDICATOR]])
                    .getValue()
                )
                self.assertEqual(
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue(),
                    "",
                )
                self.assertEqual(
                    encoder.createHLAinteger32BE()
                    .decode(values[report_parameters[HLA_MOM.SERIAL_NUMBER]])
                    .getValue(),
                    expected_serial,
                )

                class _MomArgumentFactory(DataElementFactory):
                    def createElement(self, index: int):
                        record = encoder.createHLAfixedRecord()
                        record.appendElement(encoder.createHLAinteger32BE())
                        record.appendElement(encoder.createHLAunicodeString())
                        record.appendElement(encoder.createHLAunicodeString())
                        return record

                supplied = encoder.createHLAvariableArray(_MomArgumentFactory())
                supplied.decode(values[report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]])
                self.assertEqual(supplied.size(), 3)
                self.assertEqual(supplied.get(0).get(0).getValue(), expected_first_type)
                self.assertIn(
                    "designator",
                    supplied.get(0).get(1).getValue().lower(),
                )
                self.assertRegex(
                    supplied.get(0).get(2).getValue(),
                    r'^"(?:ObjectInstanceHandle|ObjectClassHandle)\(\d+\)"$',
                )
                self.assertEqual(supplied.get(1).get(0).getValue(), 1)
                self.assertEqual(
                    supplied.get(1).get(1).getValue(), "Set of attribute designators"
                )
                self.assertRegex(
                    supplied.get(1).get(2).getValue(),
                    r'^\["AttributeHandle\(\d+\)"\]$',
                )
                self.assertEqual(supplied.get(2).get(0).getValue(), 63)
                self.assertEqual(supplied.get(2).get(1).getValue(), "User-supplied tag")
                self.assertIn(
                    base64.b64encode(tag).decode("ascii"),
                    supplied.get(2).get(2).getValue(),
                )
                returned = encoder.createHLAfixedRecord()
                returned.appendElement(encoder.createHLAinteger32BE())
                returned.appendElement(encoder.createHLAunicodeString())
                returned.appendElement(encoder.createHLAunicodeString())
                returned.decode(values[report_parameters[HLA_MOM.RETURNED_ARGUMENT]])
                self.assertEqual(returned.get(0).getValue(), 34)
                self.assertEqual(returned.get(2).getValue(), "null")

            object_tag = b"request-object-tag"
            initial_provider_request_count = len(
                provider_callbacks.attribute_value_update_requests
            )
            requester.requestAttributeValueUpdate(
                object_instance,
                AttributeHandleSet([requester_name]),
                object_tag,
            )
            self.assertTrue(provider_callbacks.report_seen_at_callback)
            self.assertEqual(len(provider_callbacks.received_interactions), 1)
            decode_report(
                provider_callbacks.received_interactions[0], 37, object_tag, 0
            )
            self.assertGreater(
                len(provider_callbacks.attribute_value_update_requests),
                initial_provider_request_count,
            )
            self.assertEqual(
                provider_callbacks.attribute_value_update_requests[0][0],
                object_instance,
            )

            class_tag = b"request-class-tag"
            requester.requestAttributeValueUpdate(
                requester_class,
                AttributeHandleSet([requester_name]),
                class_tag,
            )
            self.assertEqual(len(provider_callbacks.received_interactions), 2)
            decode_report(provider_callbacks.received_interactions[1], 36, class_tag, 1)
            self.assertGreater(
                len(provider_callbacks.attribute_value_update_requests),
                initial_provider_request_count + 1,
            )

            # The private file sink is an alternative routing disposition to
            # public MOM interaction delivery. Exercise both accepted request
            # overloads again after selecting that sink and decode their exact
            # JSON records independently of the public observer assertions.
            requester.setSendServiceReportsToFileSwitch(True)
            private_object_tag = b"private-request-object-tag"
            before_private_object = requester_report_file.read_text(encoding="utf-8")
            requester.requestAttributeValueUpdate(
                object_instance,
                AttributeHandleSet([requester_name]),
                private_object_tag,
            )
            decode_file_report(before_private_object, 37, private_object_tag, 2)
            private_class_tag = b"private-request-class-tag"
            before_private_class = requester_report_file.read_text(encoding="utf-8")
            requester.requestAttributeValueUpdate(
                requester_class,
                AttributeHandleSet([requester_name]),
                private_class_tag,
            )
            decode_file_report(before_private_class, 36, private_class_tag, 3)
            self.assertIsInstance(provider_handle, FederateHandle)
        finally:
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if provider_joined:
                try:
                    provider.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    provider.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if provider_connected:
                try:
                    provider.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            provider._implementation.close()

