        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = created = False
        owner_joined = requester_joined = False
        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_IMMEDIATE)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name, [str(restaurant_fom)], HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner_handle = owner.joinFederationExecution(
                "jni-query-ownership-mom-owner", federation_name
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-query-ownership-mom-requester", federation_name
            )
            requester_joined = True

            owner_class = owner.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            requester_class = requester.getObjectClassHandle(HLA_FOM.EMPLOYEE)
            owner_attribute = owner.getAttributeHandle(owner_class, HLA_FIXTURES.NAME)
            requester_attribute = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.NAME
            )
            owner.publishObjectClassAttributes(
                owner_class, AttributeHandleSet([owner_attribute])
            )
            requester.subscribeObjectClassAttributes(
                requester_class, AttributeHandleSet([requester_attribute])
            )
            object_instance = owner.registerObjectInstance(owner_class)
            for _ in range(30):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[0][0], object_instance
            )

            report_class = owner.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
            report_parameter_names = (
                HLA_MOM.SERVICE,
                HLA_MOM.SERVICE_TYPE,
                HLA_MOM.SUCCESS_INDICATOR,
                HLA_MOM.SUPPLIED_ARGUMENTS,
                HLA_MOM.RETURNED_ARGUMENT,
                HLA_MOM.EXCEPTION,
                HLA_MOM.SERIAL_NUMBER,
            )
            report_parameters = {
                name: owner.getParameterHandle(report_class, name)
                for name in report_parameter_names
            }
            owner.setServiceReportingSwitch(False)
            owner.subscribeInteractionClass(report_class)
            requester.setServiceReportingSwitch(True)

            requester.queryAttributeOwnership(
                object_instance, AttributeHandleSet([requester_attribute])
            )
            self.assertEqual(len(owner_callbacks.received_interactions), 1)
            report = owner_callbacks.received_interactions[0]
            self.assertEqual(report[0], report_class)
            values = dict(report[1])
            encoder = self.factory.getEncoderFactory()
            self.assertEqual(
                encoder.createHLAunicodeString()
                .decode(values[report_parameters[HLA_MOM.SERVICE]])
                .getValue(),
                "QueryAttributeOwnership",
            )
            self.assertEqual(
                encoder.createHLAinteger16BE()
                .decode(values[report_parameters[HLA_MOM.SERVICE_TYPE]])
                .getValue(),
                3,
            )
            self.assertTrue(
                encoder.createHLAboolean()
                .decode(values[report_parameters[HLA_MOM.SUCCESS_INDICATOR]])
                .getValue()
            )
            self.assertEqual(
                encoder.createHLAunicodeString()
                .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                .getValue(),
                "",
            )
            self.assertEqual(
                encoder.createHLAinteger32BE()
                .decode(values[report_parameters[HLA_MOM.SERIAL_NUMBER]])
                .getValue(),
                0,
            )

            class _MomArgumentFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(encoder.createHLAinteger32BE())
                    record.appendElement(encoder.createHLAunicodeString())
                    record.appendElement(encoder.createHLAunicodeString())
                    return record

            supplied = encoder.createHLAvariableArray(_MomArgumentFactory())
            supplied.decode(values[report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]])
            self.assertEqual(supplied.size(), 2)
            self.assertEqual(supplied.get(0).get(0).getValue(), 37)
            self.assertRegex(
                supplied.get(0).get(2).getValue(),
                r'^"ObjectInstanceHandle\(\d+\)"$',
            )
            self.assertEqual(supplied.get(1).get(0).getValue(), 1)
            self.assertEqual(
                supplied.get(1).get(1).getValue(), "Set of attribute designators"
            )
            self.assertRegex(
                supplied.get(1).get(2).getValue(),
                r'^\["AttributeHandle\(\d+\)"\]$',
            )
            returned = encoder.createHLAfixedRecord()
            returned.appendElement(encoder.createHLAinteger32BE())
            returned.appendElement(encoder.createHLAunicodeString())
            returned.appendElement(encoder.createHLAunicodeString())
            returned.decode(values[report_parameters[HLA_MOM.RETURNED_ARGUMENT]])
            self.assertEqual(returned.get(0).getValue(), 34)
            self.assertEqual(returned.get(2).getValue(), "null")

            for _ in range(30):
                requester.evokeCallback(0.0)
                if requester_callbacks.ownership_reports:
                    break
            self.assertEqual(len(requester_callbacks.ownership_reports), 1)
            ownership_report = requester_callbacks.ownership_reports[0]
            self.assertEqual(ownership_report[0], object_instance)
            self.assertEqual(
                ownership_report[1], AttributeHandleSet([requester_attribute])
            )
            self.assertEqual(ownership_report[2], owner_handle)
        finally:
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

