    def test_cpp_jni_java_jpype_time_regulation_file_report_preserves_lookahead(
        self,
    ) -> None:
        """Preserve the private EnableTimeRegulation payload through JNI."""

        repository_root = Path(__file__).parents[3]
        restaurant_fom = (
            repository_root
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        switch_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-time-regulation-file-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"time-regulation-file-reports-{uuid4().hex[:12]}"
        )
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED, configuration)
            connected = True
            ambassador.createFederationExecution(
                federation_name,
                [str(restaurant_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-time-regulation-file",
                federation_name,
                federateName="jni-time-regulation-file",
            )
            joined = True
            report_files = sorted(reports_directory.glob("*"))
            report_file = next(
                (
                    path
                    for path in report_files
                    if '"HLAfederateName":"jni-time-regulation-file"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(report_file)
            assert report_file is not None

            ambassador.setServiceReportingSwitch(True)
            ambassador.setSendServiceReportsToFileSwitch(True)
            before = report_file.read_text(encoding="utf-8")
            ambassador.enableTimeRegulation(
                ambassador.getTimeFactory().makeLogicalTimeInterval(1)
            )
            after = report_file.read_text(encoding="utf-8")
            suffix = after[len(before) :]
            record, consumed = json.JSONDecoder().raw_decode(suffix)
            self.assertEqual(consumed, len(suffix))
            self.assertEqual(record[HLA_MOM.SERVICE], "EnableTimeRegulation")
            self.assertIsInstance(record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(record[HLA_MOM.EXCEPTION])
            self.assertEqual(
                record[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 32,
                        HLA_MOM.ARGUMENT_NAME: "Lookahead",
                        HLA_MOM.ARGUMENT_VALUE: "1",
                    }
                ],
            )
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.time_regulation_enabled:
                    break
            self.assertEqual(len(callbacks.time_regulation_enabled), 1)
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

