    def test_cpp_jni_java_jpype_time_role_callback_gating_both_models(self) -> None:
        """Mirror C++ time-role callback gating through both Java callback models."""
        restaurant_fom = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )

        def run_scenario(callback_model: CallbackModel) -> None:
            federation_name = f"python-jni-time-role-gating-{uuid4().hex[:12]}"
            ambassador = self.factory.getRtiAmbassador()
            callbacks = _JniCallbacks()
            connected = created = joined = False
            try:
                ambassador.connect(callbacks, callback_model)
                connected = True
                ambassador.createFederationExecution(
                    federation_name, str(restaurant_fom), HLA_TYPES.INTEGER64_TIME
                )
                created = True
                ambassador.joinFederationExecution(
                    "jni-time-role-gating", federation_name
                )
                joined = True
                with self.assertRaises(TimeRegulationIsNotEnabled):
                    ambassador.queryLookahead()

                time_factory = ambassador.getTimeFactory()
                ambassador.enableTimeRegulation(time_factory.makeLogicalTimeInterval(2))
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertEqual(callbacks.time_regulation_enabled, [])
                    with self.assertRaises(RequestForTimeRegulationPending):
                        ambassador.enableTimeRegulation(
                            time_factory.makeLogicalTimeInterval(3)
                        )
                    for _ in range(20):
                        ambassador.evokeCallback(0.0)
                        if callbacks.time_regulation_enabled:
                            break
                else:
                    self.assertEqual(len(callbacks.time_regulation_enabled), 1)
                    with self.assertRaises(TimeRegulationAlreadyEnabled):
                        ambassador.enableTimeRegulation(
                            time_factory.makeLogicalTimeInterval(3)
                        )
                self.assertEqual(len(callbacks.time_regulation_enabled), 1)
                self.assertEqual(callbacks.time_regulation_enabled[-1].getTime(), 0)
                self.assertEqual(ambassador.queryLookahead().getInterval(), 2)

                ambassador.disableTimeRegulation()
                with self.assertRaises(TimeRegulationIsNotEnabled):
                    ambassador.queryLookahead()

                ambassador.enableTimeConstrained()
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertEqual(callbacks.time_constrained_enabled, [])
                    with self.assertRaises(RequestForTimeConstrainedPending):
                        ambassador.enableTimeConstrained()
                    for _ in range(20):
                        ambassador.evokeCallback(0.0)
                        if callbacks.time_constrained_enabled:
                            break
                else:
                    self.assertEqual(len(callbacks.time_constrained_enabled), 1)
                    with self.assertRaises(TimeConstrainedAlreadyEnabled):
                        ambassador.enableTimeConstrained()
                self.assertEqual(len(callbacks.time_constrained_enabled), 1)
                self.assertEqual(callbacks.time_constrained_enabled[-1].getTime(), 0)
                ambassador.disableTimeConstrained()
                with self.assertRaises(TimeConstrainedIsNotEnabled):
                    ambassador.disableTimeConstrained()
            finally:
                if joined:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
                if created:
                    try:
                        ambassador.destroyFederationExecution(federation_name)
                    except Exception:
                        pass
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

        for callback_model in (CallbackModel.HLA_EVOKED, CallbackModel.HLA_IMMEDIATE):
            with self.subTest(callback_model=callback_model):
                run_scenario(callback_model)

    def test_cpp_jni_java_jpype_synchronization_reports_reach_observer(self) -> None:
        """Decode synchronization registration and achievement through public MOM."""

        repository_root = Path(__file__).parents[3]
        restaurant_fom = (
            repository_root
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        switch_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-sync-mom-{uuid4().hex[:12]}"
        subject = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        subject_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        subject_connected = observer_connected = created = False
        subject_joined = observer_joined = False
        try:
            subject.connect(subject_callbacks, CallbackModel.HLA_EVOKED)
            subject_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_IMMEDIATE)
            observer_connected = True
            subject.createFederationExecution(
                federation_name,
                [str(restaurant_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            subject.joinFederationExecution("jni-sync-mom-subject", federation_name)
            subject_joined = True
            observer.joinFederationExecution("jni-sync-mom-observer", federation_name)
            observer_joined = True

            report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
            report_parameters = {
                name: observer.getParameterHandle(report_class, name)
                for name in (
                    HLA_MOM.SERVICE,
                    HLA_MOM.SERVICE_TYPE,
                    HLA_MOM.SUCCESS_INDICATOR,
                    HLA_MOM.SUPPLIED_ARGUMENTS,
                    HLA_MOM.RETURNED_ARGUMENT,
                    HLA_MOM.EXCEPTION,
                    HLA_MOM.SERIAL_NUMBER,
                )
            }
            observer.setServiceReportingSwitch(False)
            observer.subscribeInteractionClass(report_class)
            subject.setServiceReportingSwitch(True)
            subject.setSendServiceReportsToFileSwitch(False)
            encoder = self.factory.getEncoderFactory()

            class _MomArgumentFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(encoder.createHLAinteger32BE())
                    record.appendElement(encoder.createHLAunicodeString())
                    record.appendElement(encoder.createHLAunicodeString())
                    return record

            def assert_report(
                expected_service: str,
                expected_serial: int,
                expected_arguments: tuple[tuple[int, str, str], ...],
                expected_count: int | None = None,
            ) -> None:
                self.assertEqual(
                    len(observer_callbacks.received_interactions),
                    expected_count
                    if expected_count is not None
                    else expected_serial + 1,
                )
                callback = observer_callbacks.received_interactions[expected_serial]
                self.assertEqual(callback[0], report_class)
                values = dict(callback[1])
                self.assertEqual(
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue(),
                    expected_service,
                )
                self.assertEqual(
                    encoder.createHLAinteger16BE()
                    .decode(values[report_parameters[HLA_MOM.SERVICE_TYPE]])
                    .getValue(),
                    0,
                )
                self.assertTrue(
                    encoder.createHLAboolean()
                    .decode(values[report_parameters[HLA_MOM.SUCCESS_INDICATOR]])
                    .getValue()
                )
                self.assertEqual(
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue(),
                    "",
                )
                self.assertEqual(
                    encoder.createHLAinteger32BE()
                    .decode(values[report_parameters[HLA_MOM.SERIAL_NUMBER]])
                    .getValue(),
                    expected_serial,
                )
                supplied = encoder.createHLAvariableArray(_MomArgumentFactory())
                supplied.decode(values[report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]])
                self.assertEqual(supplied.size(), len(expected_arguments))
                for index, (expected_type, expected_name, expected_value) in enumerate(
                    expected_arguments
                ):
                    record = supplied.get(index)
                    self.assertEqual(record.get(0).getValue(), expected_type)
                    self.assertEqual(record.get(1).getValue(), expected_name)
                    self.assertEqual(record.get(2).getValue(), expected_value)
                returned = encoder.createHLAfixedRecord()
                returned.appendElement(encoder.createHLAinteger32BE())
                returned.appendElement(encoder.createHLAunicodeString())
                returned.appendElement(encoder.createHLAunicodeString())
                returned.decode(values[report_parameters[HLA_MOM.RETURNED_ARGUMENT]])
                self.assertEqual(returned.get(0).getValue(), 34)
                self.assertEqual(returned.get(2).getValue(), "null")

            label = "jni-sync-public-mom"
            tag = b"SYN"
            subject.registerFederationSynchronizationPoint(label, tag)
            assert_report(
                "RegisterFederationSynchronizationPoint",
                0,
                (
                    (53, "Synchronization point label", f'"{label}"'),
                    (63, "User-supplied tag", '"U1lO"'),
                    (34, "Optional set of joined federate designators", "null"),
                ),
                expected_count=2,
            )
            assert_report(
                "ConfirmSynchronizationPointRegistration",
                1,
                (
                    (53, "Synchronization point label", f'"{label}"'),
                    (6, "Registration-success indicator", "true"),
                    (34, "Optional failure reason", "null"),
                ),
                expected_count=2,
            )
            for _ in range(30):
                subject.evokeCallback(0.0)
                if (
                    label in subject_callbacks.synchronization_registrations
                    and (label, tag) in subject_callbacks.synchronization_announcements
                    and (label, tag) in observer_callbacks.synchronization_announcements
                ):
                    break
            self.assertIn(label, subject_callbacks.synchronization_registrations)
            self.assertIn((label, tag), subject_callbacks.synchronization_announcements)
            self.assertIn(
                (label, tag), observer_callbacks.synchronization_announcements
            )

            subject.synchronizationPointAchieved(label)
            assert_report(
                "SynchronizationPointAchieved",
                2,
                (
                    (53, "Synchronization point label", f'"{label}"'),
                    (6, "Optional synchronization-success indicator", "true"),
                ),
            )
            observer.synchronizationPointAchieved(label)
            for _ in range(30):
                subject.evokeCallback(0.0)
                if subject_callbacks.synchronization_results:
                    break
            self.assertEqual(
                subject_callbacks.synchronization_results,
                [(label, FederateHandleSet())],
            )

            save_label = "jni-save-public-mom"
            subject.requestFederationSave(save_label)
            assert_report(
                "RequestFederationSave",
                3,
                (
                    (53, "Federation save label", f'"{save_label}"'),
                    (34, "Optional timestamp", "null"),
                ),
                expected_count=5,
            )
            assert_report(
                "InitiateFederateSave",
                4,
                (
                    (53, "Federation save label", f'"{save_label}"'),
                    (34, "Optional timestamp", "null"),
                ),
            )
            subject.abortFederationSave()
        finally:
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if subject_joined:
                try:
                    subject.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    subject.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if subject_connected:
                try:
                    subject.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            subject._implementation.close()

