    def test_cpp_jni_java_jpype_save_completion_file_reports_preserve_callback_order(
        self,
    ) -> None:
        """Preserve the accepted save-completion report sequence privately."""

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-save-completion-file-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"save-completion-file-reports-{uuid4().hex[:12]}"
        )
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False

        def decode_records(suffix: str) -> list[dict[str, object]]:
            decoder = json.JSONDecoder()
            records: list[dict[str, object]] = []
            cursor = 0
            while cursor < len(suffix):
                while cursor < len(suffix) and suffix[cursor].isspace():
                    cursor += 1
                if cursor >= len(suffix):
                    break
                if suffix[cursor] != "{":
                    self.fail(
                        f"unexpected report stream byte at {cursor}: "
                        f"{suffix[cursor : cursor + 32]!r}"
                    )
                record, consumed = decoder.raw_decode(suffix, cursor)
                self.assertIsInstance(record, dict)
                records.append(record)
                cursor = consumed
            return records

        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED, configuration)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-save-completion-file",
                federation_name,
                federateName="jni-save-completion-file",
            )
            joined = True
            report_file = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-save-completion-file"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(report_file)
            assert report_file is not None
            ambassador.setServiceReportingSwitch(True)
            ambassador.setSendServiceReportsToFileSwitch(True)
            label = "jni-save-completion-private"
            ambassador.requestFederationSave(label)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.save_initiations:
                    break
            self.assertEqual(callbacks.save_initiations, [label])

            before_begun = report_file.read_text(encoding="utf-8")
            ambassador.federateSaveBegun()
            begun_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_begun) :]
            )
            begun = next(
                record
                for record in begun_records
                if record.get(HLA_MOM.SERVICE) == "FederateSaveBegun"
            )
            self.assertEqual(begun[HLA_MOM.SUPPLIED_ARGUMENTS], [])
            self.assertEqual(begun[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(begun[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(begun[HLA_MOM.EXCEPTION])

            before_complete = report_file.read_text(encoding="utf-8")
            ambassador.federateSaveComplete()
            completion_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_complete) :]
            )
            complete = next(
                record
                for record in completion_records
                if record.get(HLA_MOM.SERVICE) == "FederateSaveComplete"
            )
            saved = next(
                record
                for record in completion_records
                if record.get(HLA_MOM.SERVICE) == "FederationSaved"
            )
            self.assertEqual(
                complete[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Federate save-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: True,
                    }
                ],
            )
            self.assertEqual(complete[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(complete[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(complete[HLA_MOM.EXCEPTION])
            self.assertEqual(
                saved[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Federation save-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: True,
                    },
                    {
                        HLA_MOM.ARGUMENT_TYPE: 34,
                        HLA_MOM.ARGUMENT_NAME: "Optional failure reason",
                        HLA_MOM.ARGUMENT_VALUE: None,
                    },
                ],
            )
            self.assertEqual(saved[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(saved[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(saved[HLA_MOM.EXCEPTION])
            self.assertEqual(callbacks.saved_count, 0)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.saved_count:
                    break
            self.assertEqual(callbacks.saved_count, 1)

            # Repeat the lifecycle through the negative completion selector so
            # the private route proves the false success indicator and failure
            # reason before federationNotSaved is evoked.
            failure_label = "jni-save-completion-private-failure"
            ambassador.requestFederationSave(failure_label)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if len(callbacks.save_initiations) >= 2:
                    break
            self.assertEqual(callbacks.save_initiations, [label, failure_label])
            ambassador.federateSaveBegun()
            before_failure = report_file.read_text(encoding="utf-8")
            ambassador.federateSaveNotComplete()
            failure_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_failure) :]
            )
            self.assertEqual(
                [record[HLA_MOM.SERVICE] for record in failure_records],
                ["FederateSaveComplete", "FederationSaved"],
            )
            failed_complete, failed_saved = failure_records
            self.assertEqual(
                failed_complete[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Federate save-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: False,
                    }
                ],
            )
            self.assertEqual(failed_complete[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(failed_complete[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(failed_complete[HLA_MOM.EXCEPTION])
            self.assertEqual(
                failed_saved[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Federation save-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: False,
                    },
                    {
                        HLA_MOM.ARGUMENT_TYPE: 48,
                        HLA_MOM.ARGUMENT_NAME: "Optional failure reason",
                        HLA_MOM.ARGUMENT_VALUE: "FEDERATE_REPORTED_FAILURE_DURING_SAVE",
                    },
                ],
            )
            self.assertEqual(failed_saved[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(failed_saved[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(failed_saved[HLA_MOM.EXCEPTION])
            self.assertEqual(callbacks.save_failures, [])
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.save_failures:
                    break
            self.assertEqual(
                callbacks.save_failures,
                [SaveFailureReason.FEDERATE_REPORTED_FAILURE_DURING_SAVE],
            )
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_restore_completion_and_status_file_reports(
        self,
    ) -> None:
        """Preserve private restore reports and callback ordering through JNI."""

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-restore-file-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"restore-file-reports-{uuid4().hex[:12]}"
        )
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False

        def decode_records(suffix: str) -> list[dict[str, object]]:
            decoder = json.JSONDecoder()
            records: list[dict[str, object]] = []
            cursor = 0
            while cursor < len(suffix):
                while cursor < len(suffix) and suffix[cursor].isspace():
                    cursor += 1
                if cursor >= len(suffix):
                    break
                if suffix[cursor] != "{":
                    self.fail(
                        f"unexpected report stream byte at {cursor}: "
                        f"{suffix[cursor : cursor + 32]!r}"
                    )
                record, consumed = decoder.raw_decode(suffix, cursor)
                self.assertIsInstance(record, dict)
                records.append(record)
                cursor = consumed
            return records

        def assert_common(record: dict[str, object], service: str) -> None:
            self.assertEqual(record[HLA_MOM.SERVICE], service)
            self.assertIsInstance(record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(record[HLA_MOM.EXCEPTION])

        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED, configuration)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-restore-file",
                federation_name,
                federateName="jni-restore-file",
            )
            joined = True
            report_file = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-restore-file"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(report_file)
            assert report_file is not None
            ambassador.setServiceReportingSwitch(True)
            ambassador.setSendServiceReportsToFileSwitch(True)

            label = "jni-restore-file-snapshot"
            ambassador.requestFederationSave(label)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.save_initiations:
                    break
            self.assertEqual(callbacks.save_initiations, [label])
            ambassador.federateSaveBegun()
            ambassador.federateSaveComplete()
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.saved_count:
                    break
            self.assertEqual(callbacks.saved_count, 1)

            before_restore = report_file.read_text(encoding="utf-8")
            ambassador.requestFederationRestore(label)
            restore_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_restore) :]
            )
            self.assertEqual(
                [record[HLA_MOM.SERVICE] for record in restore_records],
                [
                    "RequestFederationRestore",
                    "ConfirmFederationRestorationRequest",
                    "FederationRestoreBegun",
                    "InitiateFederateRestore",
                ],
            )
            request_record, confirmation, begun, initiation = restore_records
            assert_common(request_record, "RequestFederationRestore")
            self.assertEqual(
                request_record[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 53,
                        HLA_MOM.ARGUMENT_NAME: "Federation save label",
                        HLA_MOM.ARGUMENT_VALUE: label,
                    }
                ],
            )
            assert_common(confirmation, "ConfirmFederationRestorationRequest")
            self.assertEqual(
                confirmation[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 53,
                        HLA_MOM.ARGUMENT_NAME: "Federation save label",
                        HLA_MOM.ARGUMENT_VALUE: label,
                    },
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Request-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: True,
                    },
                ],
            )
            assert_common(begun, "FederationRestoreBegun")
            self.assertEqual(begun[HLA_MOM.SUPPLIED_ARGUMENTS], [])
            assert_common(initiation, "InitiateFederateRestore")
            initiation_arguments = initiation[HLA_MOM.SUPPLIED_ARGUMENTS]
            self.assertEqual(len(initiation_arguments), 3)
            self.assertEqual(
                initiation_arguments[0],
                {
                    HLA_MOM.ARGUMENT_TYPE: 53,
                    HLA_MOM.ARGUMENT_NAME: "Federation save label",
                    HLA_MOM.ARGUMENT_VALUE: label,
                },
            )
            self.assertEqual(initiation_arguments[1][HLA_MOM.ARGUMENT_TYPE], 15)
            self.assertEqual(
                initiation_arguments[1][HLA_MOM.ARGUMENT_NAME],
                "Joined federate designator",
            )
            self.assertRegex(
                initiation_arguments[1][HLA_MOM.ARGUMENT_VALUE],
                r"^FederateHandle\(\d+\)$",
            )
            self.assertEqual(
                initiation_arguments[2],
                {
                    HLA_MOM.ARGUMENT_TYPE: 53,
                    HLA_MOM.ARGUMENT_NAME: "Federate name",
                    HLA_MOM.ARGUMENT_VALUE: "jni-restore-file",
                },
            )
            self.assertEqual(callbacks.restore_acceptances, [])
            self.assertEqual(callbacks.restore_begun, 0)
            self.assertEqual(callbacks.restore_initiations, [])
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.restore_initiations:
                    break
            self.assertEqual(callbacks.restore_acceptances, [label])
            self.assertEqual(callbacks.restore_begun, 1)
            self.assertEqual(len(callbacks.restore_initiations), 1)

            before_complete = report_file.read_text(encoding="utf-8")
            ambassador.federateRestoreComplete()
            completion_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_complete) :]
            )
            self.assertEqual(len(completion_records), 1)
            completion = completion_records[0]
            assert_common(completion, "FederateRestoreComplete")
            self.assertEqual(
                completion[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Federate restore-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: True,
                    }
                ],
            )
            self.assertEqual(callbacks.restore_completions, 0)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.restore_completions:
                    break
            self.assertEqual(callbacks.restore_completions, 1)

            before_status = report_file.read_text(encoding="utf-8")
            ambassador.queryFederationRestoreStatus()
            status_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_status) :]
            )
            self.assertEqual(
                [record[HLA_MOM.SERVICE] for record in status_records],
                ["QueryFederationRestoreStatus", "FederationRestoreStatusResponse"],
            )
            status_query, status_response = status_records
            assert_common(status_query, "QueryFederationRestoreStatus")
            self.assertEqual(status_query[HLA_MOM.SUPPLIED_ARGUMENTS], [])
            assert_common(status_response, "FederationRestoreStatusResponse")
            self.assertEqual(len(status_response[HLA_MOM.SUPPLIED_ARGUMENTS]), 1)
            status_argument = status_response[HLA_MOM.SUPPLIED_ARGUMENTS][0]
            self.assertEqual(status_argument[HLA_MOM.ARGUMENT_TYPE], 20)
            self.assertEqual(
                status_argument[HLA_MOM.ARGUMENT_NAME],
                "List of joined federates and restore status for each",
            )
            self.assertEqual(len(status_argument[HLA_MOM.ARGUMENT_VALUE]), 1)
            status_entry = status_argument[HLA_MOM.ARGUMENT_VALUE][0]
            self.assertRegex(
                status_entry["preRestoreHandle"], r"^FederateHandle\(\d+\)$"
            )
            self.assertEqual(
                status_entry["postRestoreHandle"], "FederateHandle(invalid)"
            )
            self.assertEqual(status_entry["status"], "NO_RESTORE_IN_PROGRESS")
            self.assertEqual(callbacks.restore_status_reports, [])
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.restore_status_reports:
                    break
            self.assertEqual(len(callbacks.restore_status_reports), 1)

            # A second restore exercises the negative completion selector on
            # the same external Java ambassador and proves serial progression
            # continues across the restored snapshot.
            before_second_restore = report_file.read_text(encoding="utf-8")
            ambassador.requestFederationRestore(label)
            second_restore_records = decode_records(
                report_file.read_text(encoding="utf-8")[len(before_second_restore) :]
            )
            self.assertEqual(
                [record[HLA_MOM.SERVICE] for record in second_restore_records],
                [
                    "RequestFederationRestore",
                    "ConfirmFederationRestorationRequest",
                    "FederationRestoreBegun",
                    "InitiateFederateRestore",
                ],
            )
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if len(callbacks.restore_initiations) >= 2:
                    break
            self.assertEqual(len(callbacks.restore_initiations), 2)
            before_failure = report_file.read_text(encoding="utf-8")
            ambassador.federateRestoreNotComplete()
            failure_suffix = report_file.read_text(encoding="utf-8")[
                len(before_failure) :
            ]
            failure_record, failure_consumed = json.JSONDecoder().raw_decode(
                failure_suffix
            )
            self.assertEqual(failure_consumed, len(failure_suffix))
            assert_common(failure_record, "FederateRestoreComplete")
            self.assertGreater(
                failure_record[HLA_MOM.SERIAL_NUMBER], completion[HLA_MOM.SERIAL_NUMBER]
            )
            self.assertEqual(
                failure_record[HLA_MOM.SUPPLIED_ARGUMENTS],
                [
                    {
                        HLA_MOM.ARGUMENT_TYPE: 6,
                        HLA_MOM.ARGUMENT_NAME: "Federate restore-success indicator",
                        HLA_MOM.ARGUMENT_VALUE: False,
                    }
                ],
            )
            self.assertEqual(callbacks.restore_failures, [])
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if len(callbacks.restore_failures) >= 1:
                    break
            self.assertEqual(
                callbacks.restore_failures,
                [RestoreFailureReason.FEDERATE_REPORTED_FAILURE_DURING_RESTORE],
            )
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_abort_restore_file_report_precedes_callback(
        self,
    ) -> None:
        """Preserve AbortFederationRestore reporting before RESTORE_ABORTED."""

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-abort-restore-file-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"abort-restore-file-reports-{uuid4().hex[:12]}"
        )
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False

        def decode_one(suffix: str) -> dict[str, object]:
            decoder = json.JSONDecoder()
            cursor = 0
            while cursor < len(suffix) and suffix[cursor].isspace():
                cursor += 1
            record, consumed = decoder.raw_decode(suffix, cursor)
            self.assertIsInstance(record, dict)
            self.assertEqual(suffix[consumed:].strip(), "")
            return record

        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED, configuration)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-abort-restore-file",
                federation_name,
                federateName="jni-abort-restore-file",
            )
            joined = True
            report_file = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-abort-restore-file"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(report_file)
            assert report_file is not None
            ambassador.setServiceReportingSwitch(True)
            ambassador.setSendServiceReportsToFileSwitch(True)

            label = "jni-abort-restore-file-snapshot"
            ambassador.requestFederationSave(label)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.save_initiations:
                    break
            self.assertEqual(callbacks.save_initiations, [label])
            ambassador.federateSaveBegun()
            ambassador.federateSaveComplete()
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.saved_count:
                    break
            self.assertEqual(callbacks.saved_count, 1)

            ambassador.requestFederationRestore(label)
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.restore_initiations:
                    break
            self.assertEqual(callbacks.restore_acceptances, [label])
            self.assertEqual(callbacks.restore_begun, 1)
            self.assertEqual(len(callbacks.restore_initiations), 1)

            before_abort = report_file.read_text(encoding="utf-8")
            ambassador.abortFederationRestore()
            abort_record = decode_one(
                report_file.read_text(encoding="utf-8")[len(before_abort) :]
            )
            self.assertEqual(abort_record[HLA_MOM.SERVICE], "AbortFederationRestore")
            self.assertIsInstance(abort_record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(abort_record[HLA_MOM.SUPPLIED_ARGUMENTS], [])
            self.assertEqual(abort_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(abort_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(abort_record[HLA_MOM.EXCEPTION])
            self.assertEqual(callbacks.restore_failures, [])
            for _ in range(30):
                ambassador.evokeCallback(0.0)
                if callbacks.restore_failures:
                    break
            self.assertEqual(
                callbacks.restore_failures,
                [RestoreFailureReason.RESTORE_ABORTED],
            )
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

