        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = ReportingCallbacks()
        publisher_connected = receiver_connected = created = False
        publisher_joined = receiver_joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            publisher.connect(
                publisher_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            publisher_connected = True
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            receiver_connected = True
            publisher.createFederationExecution(
                federation_name, [str(restaurant_fom)], HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher_handle = publisher.joinFederationExecution(
                "jni-directed-report-publisher",
                federation_name,
                federateName="jni-directed-report-publisher",
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-directed-report-receiver",
                federation_name,
                federateName="jni-directed-report-receiver",
            )
            receiver_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            receiver_class = receiver.getObjectClassHandle(HLA_FOM.EMPLOYEE_SERVER)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.EFFICIENCY
            )
            receiver_attribute = receiver.getAttributeHandle(
                receiver_class, HLA_FIXTURES.EFFICIENCY
            )
            publisher_interaction = publisher.getInteractionClassHandle(
                HLA_FOM.TAKE_ORDER
            )
            receiver_interaction = receiver.getInteractionClassHandle(
                HLA_FOM.TAKE_ORDER
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )
            receiver.subscribeObjectClassAttributes(
                receiver_class, AttributeHandleSet([receiver_attribute])
            )
            publisher.publishObjectClassDirectedInteractions(
                publisher_class, InteractionClassHandleSet([publisher_interaction])
            )
            receiver.subscribeObjectClassDirectedInteractionsUniversally(
                receiver_class, InteractionClassHandleSet([receiver_interaction])
            )
            target = publisher.registerObjectInstance(publisher_class)
            for _ in range(30):
                receiver.evokeCallback(0.0)
                if receiver_callbacks.discovered_objects:
                    break
            self.assertEqual(receiver_callbacks.discovered_objects[0][0], target)

            publisher_report = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-directed-report-publisher"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(publisher_report)
            assert publisher_report is not None
            receiver_callbacks.report_file = publisher_report
            publisher.setServiceReportingSwitch(True)
            publisher.setSendServiceReportsToFileSwitch(True)

            before_send = publisher_report.read_text(encoding="utf-8")
            receiver_callbacks.report_before_callback = before_send
            publisher.sendDirectedInteraction(
                publisher_interaction,
                target,
                ParameterHandleValueMap(),
                b"directed-report-tag",
            )
            after_send = publisher_report.read_text(encoding="utf-8")
            self.assertIn('"HLAservice":"SendDirectedInteraction"', after_send)
            self.assertGreater(len(after_send), len(before_send))
            directed_suffix = after_send[len(before_send) :]
            directed_record, directed_consumed = json.JSONDecoder().raw_decode(
                directed_suffix
            )
            self.assertEqual(directed_consumed, len(directed_suffix))
            self.assertEqual(
                directed_record[HLA_MOM.SERVICE], "SendDirectedInteraction"
            )
            self.assertIsInstance(directed_record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(directed_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(directed_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(directed_record[HLA_MOM.EXCEPTION])
            self.assertEqual(len(directed_record[HLA_MOM.SUPPLIED_ARGUMENTS]), 5)
            (
                interaction_argument,
                object_argument,
                values_argument,
                tag_argument,
                time_argument,
            ) = directed_record[HLA_MOM.SUPPLIED_ARGUMENTS]
            self.assertEqual(interaction_argument[HLA_MOM.ARGUMENT_TYPE], 27)
            self.assertEqual(
                interaction_argument[HLA_MOM.ARGUMENT_NAME],
                "Interaction class designator",
            )
            self.assertRegex(
                interaction_argument[HLA_MOM.ARGUMENT_VALUE],
                r"^InteractionClassHandle\(\d+\)$",
            )
            self.assertEqual(object_argument[HLA_MOM.ARGUMENT_TYPE], 37)
            self.assertEqual(
                object_argument[HLA_MOM.ARGUMENT_NAME], "Object instance designator"
            )
            self.assertRegex(
                object_argument[HLA_MOM.ARGUMENT_VALUE],
                r"^ObjectInstanceHandle\(\d+\)$",
            )
            self.assertEqual(values_argument[HLA_MOM.ARGUMENT_TYPE], 40)
            self.assertEqual(
                values_argument[HLA_MOM.ARGUMENT_NAME],
                "Constrained set of interaction parameter designator and value pairs",
            )
            self.assertEqual(values_argument[HLA_MOM.ARGUMENT_VALUE], {})
            self.assertEqual(
                tag_argument,
                {
                    HLA_MOM.ARGUMENT_TYPE: 63,
                    HLA_MOM.ARGUMENT_NAME: "User-supplied tag",
                    HLA_MOM.ARGUMENT_VALUE: base64.b64encode(
                        b"directed-report-tag"
                    ).decode("ascii"),
                },
            )
            self.assertEqual(
                time_argument,
                {
                    HLA_MOM.ARGUMENT_TYPE: 34,
                    HLA_MOM.ARGUMENT_NAME: "Optional timestamp",
                    HLA_MOM.ARGUMENT_VALUE: None,
                },
            )
            self.assertEqual(receiver_callbacks.directed_interactions, [])
            for _ in range(30):
                receiver.evokeCallback(0.0)
                if receiver_callbacks.directed_interactions:
                    break
            self.assertTrue(receiver_callbacks.report_present_at_callback)
            self.assertEqual(len(receiver_callbacks.directed_interactions), 1)
            callback = receiver_callbacks.directed_interactions[0]
            self.assertEqual(callback[0], receiver_interaction)
            self.assertEqual(callback[1], target)
            self.assertEqual(callback[2], ParameterHandleValueMap())
            self.assertEqual(callback[3], b"directed-report-tag")
            self.assertEqual(
                callback[4], publisher.getTransportationTypeHandle(HLA_MOM.RELIABLE)
            )
            self.assertEqual(callback[5], publisher_handle)
        finally:
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if receiver_connected:
                try:
                    receiver.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            receiver._implementation.close()
            publisher._implementation.close()

