            decoder = json.JSONDecoder()
            records = []
            cursor = 0
            suffix = after_request[len(before_request) :]
            while cursor < len(suffix):
                record, cursor = decoder.raw_decode(suffix, cursor)
                records.append(record)
            request_record = next(
                record
                for record in records
                if record[HLA_MOM.SERVICE] == "RequestAttributeTransportationTypeChange"
            )
            self.assertTrue(request_record[HLA_MOM.SUCCESS_INDICATOR])
