        owner_connected = requester_connected = created = False
        owner_joined = requester_joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(
                requester_callbacks, CallbackModel.HLA_EVOKED, configuration
            )
            requester_connected = True
            owner.createFederationExecution(
                federation_name,
                [str(ownership_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            owner.joinFederationExecution(
                "jni-acquisition-cancel-owner",
                federation_name,
                federateName="jni-acquisition-cancel-owner",
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-acquisition-cancel-requester",
                federation_name,
                federateName="jni-acquisition-cancel-requester",
            )
            requester_joined = True
            requester.setServiceReportingSwitch(False)
            requester.setSendServiceReportsToFileSwitch(False)

            report_files = sorted(reports_directory.glob("*"))
            requester_report = next(
                (
                    path
                    for path in report_files
                    if '"HLAfederateName":"jni-acquisition-cancel-requester"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(requester_report)
            assert requester_report is not None
            requester_callbacks.report_file = requester_report

            owner_class = owner.getObjectClassHandle(HLA_FOM.ATTRIBUTE_FIXTURE_CHILD)
            requester_class = requester.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            owner_attribute = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            requester_attribute = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            requester_attributes = AttributeHandleSet([requester_attribute])
            requester.subscribeObjectClassAttributes(
                requester_class, requester_attributes, active=True
            )
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            object_instance = owner.registerObjectInstance(owner_class)
            for _ in range(30):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(len(requester_callbacks.discovered_objects), 1)
            requester.publishObjectClassAttributes(
                requester_class, requester_attributes
            )
            requester.attributeOwnershipAcquisition(
                object_instance, requester_attributes, b"ACQUIRE"
            )

            requester.setServiceReportingSwitch(True)
            requester.setSendServiceReportsToFileSwitch(True)
            before_cancellation = requester_report.read_text(encoding="utf-8")
            requester_callbacks.report_before_callback = before_cancellation
            requester.cancelAttributeOwnershipAcquisition(
                object_instance, requester_attributes
            )
            after_cancellation = requester_report.read_text(encoding="utf-8")
            self.assertIn(
                '"HLAservice":"CancelAttributeOwnershipAcquisition"',
                after_cancellation,
            )
            self.assertGreater(len(after_cancellation), len(before_cancellation))
            cancellation_record, cancellation_consumed = json.JSONDecoder().raw_decode(
                after_cancellation[len(before_cancellation) :]
            )
            self.assertEqual(
                cancellation_consumed,
                len(after_cancellation) - len(before_cancellation),
            )
            self.assertEqual(
                cancellation_record[HLA_MOM.SERVICE],
                "CancelAttributeOwnershipAcquisition",
            )
            self.assertTrue(cancellation_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(cancellation_record[HLA_MOM.EXCEPTION])
            self.assertEqual(cancellation_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            cancellation_arguments = cancellation_record[HLA_MOM.SUPPLIED_ARGUMENTS]
            self.assertEqual(cancellation_arguments[0][HLA_MOM.ARGUMENT_TYPE], 37)
            self.assertEqual(
                cancellation_arguments[0][HLA_MOM.ARGUMENT_NAME],
                "Object instance designator",
            )
            self.assertRegex(
                cancellation_arguments[0][HLA_MOM.ARGUMENT_VALUE],
                r"^ObjectInstanceHandle\(\d+\)$",
            )
            self.assertEqual(cancellation_arguments[1][HLA_MOM.ARGUMENT_TYPE], 1)
            self.assertEqual(
                cancellation_arguments[1][HLA_MOM.ARGUMENT_NAME],
                "Set of attribute designators",
            )
            self.assertEqual(len(cancellation_arguments[1][HLA_MOM.ARGUMENT_VALUE]), 1)
            self.assertRegex(
                cancellation_arguments[1][HLA_MOM.ARGUMENT_VALUE][0],
                r"^AttributeHandle\(\d+\)$",
            )
            self.assertEqual(
                requester_callbacks.ownership_acquisition_cancellations, []
            )
            for _ in range(30):
                requester.evokeCallback(0.0)
                if requester_callbacks.ownership_acquisition_cancellations:
                    break
            self.assertTrue(requester_callbacks.report_present_at_callback)
            self.assertEqual(
                requester_callbacks.ownership_acquisition_cancellations,
                [(object_instance, requester_attributes)],
            )
        finally:
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

