    def test_cpp_jni_java_jpype_service_report_precedes_negotiated_divestiture_callback(
        self,
    ) -> None:
        """Keep negotiated divestiture reporting ordered before owner confirmation callbacks."""

        class ReportingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.report_file: Path | None = None
                self.report_before_callback: str | None = None
                self.report_present_at_callback = False

            def requestDivestitureConfirmation(
                self,
                objectInstance: ObjectInstanceHandle,
                releasedAttributes: AttributeHandleSet,
                userSuppliedTag: bytes,
            ) -> None:
                if (
                    self.report_file is not None
                    and self.report_before_callback is not None
                ):
                    report = self.report_file.read_text(encoding="utf-8")
                    self.report_present_at_callback = (
                        len(report) > len(self.report_before_callback)
                        and '"HLAservice":"NegotiatedAttributeOwnershipDivestiture"'
                        in report
                    )
                super().requestDivestitureConfirmation(
                    objectInstance, releasedAttributes, userSuppliedTag
                )

        repository_root = Path(__file__).parents[3]
        ownership_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        switch_fom = (
            repository_root
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-negotiated-divestiture-report-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / (
            f"negotiated-divestiture-reports-{uuid4().hex[:12]}"
        )
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = ReportingCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = created = False
        owner_joined = requester_joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED, configuration)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name,
                [str(ownership_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            owner.joinFederationExecution(
                "jni-negotiated-divestiture-owner",
                federation_name,
                federateName="jni-negotiated-divestiture-owner",
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-negotiated-divestiture-requester",
                federation_name,
                federateName="jni-negotiated-divestiture-requester",
            )
            requester_joined = True
            owner.setServiceReportingSwitch(False)
            owner.setSendServiceReportsToFileSwitch(False)

            report_files = sorted(reports_directory.glob("*"))
            owner_report = next(
                (
                    path
                    for path in report_files
                    if '"HLAfederateName":"jni-negotiated-divestiture-owner"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(owner_report)
            assert owner_report is not None
            owner_callbacks.report_file = owner_report

            owner_class = owner.getObjectClassHandle(HLA_FOM.ATTRIBUTE_FIXTURE_CHILD)
            requester_class = requester.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            owner_attribute = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            requester_attribute = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            requester_attributes = AttributeHandleSet([requester_attribute])
            requester.subscribeObjectClassAttributes(
                requester_class, requester_attributes, active=True
            )
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            object_instance = owner.registerObjectInstance(owner_class)
            for _ in range(30):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(len(requester_callbacks.discovered_objects), 1)
            requester.publishObjectClassAttributes(
                requester_class, requester_attributes
            )
            requester.attributeOwnershipAcquisition(
                object_instance, requester_attributes, b"ACQUIRE"
            )
            for _ in range(30):
                owner.evokeCallback(0.0)
                if owner_callbacks.ownership_release_requests:
                    break
            self.assertEqual(len(owner_callbacks.ownership_release_requests), 1)

            owner.setServiceReportingSwitch(True)
            owner.setSendServiceReportsToFileSwitch(True)
            before_divestiture = owner_report.read_text(encoding="utf-8")
            owner_callbacks.report_before_callback = before_divestiture
            owner.negotiatedAttributeOwnershipDivestiture(
                object_instance, owner_attributes, b"DIVEST"
            )
            after_divestiture = owner_report.read_text(encoding="utf-8")
            self.assertIn(
                '"HLAservice":"NegotiatedAttributeOwnershipDivestiture"',
                after_divestiture,
            )
            self.assertGreater(len(after_divestiture), len(before_divestiture))
            negotiated_record, negotiated_consumed = json.JSONDecoder().raw_decode(
                after_divestiture[len(before_divestiture) :]
            )
            self.assertEqual(
                negotiated_consumed, len(after_divestiture) - len(before_divestiture)
            )
            self.assertEqual(
                negotiated_record[HLA_MOM.SERVICE],
                "NegotiatedAttributeOwnershipDivestiture",
            )
            self.assertTrue(negotiated_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(negotiated_record[HLA_MOM.EXCEPTION])
            self.assertEqual(negotiated_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            negotiated_arguments = negotiated_record[HLA_MOM.SUPPLIED_ARGUMENTS]
            self.assertEqual(negotiated_arguments[0][HLA_MOM.ARGUMENT_TYPE], 37)
            self.assertEqual(
                negotiated_arguments[0][HLA_MOM.ARGUMENT_NAME],
                "Object instance designator",
            )
            self.assertRegex(
                negotiated_arguments[0][HLA_MOM.ARGUMENT_VALUE],
                r"^ObjectInstanceHandle\(\d+\)$",
            )
            self.assertEqual(negotiated_arguments[1][HLA_MOM.ARGUMENT_TYPE], 1)
            self.assertEqual(
                negotiated_arguments[1][HLA_MOM.ARGUMENT_NAME],
                "Set of attribute designators",
            )
            self.assertEqual(len(negotiated_arguments[1][HLA_MOM.ARGUMENT_VALUE]), 1)
            self.assertRegex(
                negotiated_arguments[1][HLA_MOM.ARGUMENT_VALUE][0],
                r"^AttributeHandle\(\d+\)$",
            )
            self.assertEqual(
                negotiated_arguments[2],
                {
                    HLA_MOM.ARGUMENT_TYPE: 63,
                    HLA_MOM.ARGUMENT_NAME: "User-supplied tag",
                    HLA_MOM.ARGUMENT_VALUE: base64.b64encode(b"DIVEST").decode("ascii"),
                },
            )
            self.assertEqual(owner_callbacks.ownership_divestiture_requests, [])
            for _ in range(30):
                owner.evokeCallback(0.0)
                if owner_callbacks.ownership_divestiture_requests:
                    break
            self.assertTrue(owner_callbacks.report_present_at_callback)
            self.assertEqual(
                owner_callbacks.ownership_divestiture_requests,
                [(object_instance, owner_attributes, b"ACQUIRE")],
            )
        finally:
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

