    def test_cpp_jni_java_jpype_async_delivery_gates_temporal_receive_callbacks(
        self,
    ) -> None:
        """Mirror C++ asynchronous-delivery gating for both callback models."""
        interaction_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )

        def run_scenario(callback_model: CallbackModel) -> None:
            federation_name = f"python-jni-async-gating-{uuid4().hex[:12]}"
            publisher = self.factory.getRtiAmbassador()
            receiver = self.factory.getRtiAmbassador()
            publisher_callbacks = _JniCallbacks()
            receiver_callbacks = _JniCallbacks()
            publisher_connected = receiver_connected = created = False
            publisher_joined = receiver_joined = False
            try:
                with self.assertRaises(NotConnected):
                    receiver.enableAsynchronousDelivery()
                with self.assertRaises(NotConnected):
                    receiver.disableAsynchronousDelivery()

                publisher.connect(publisher_callbacks, callback_model)
                publisher_connected = True
                receiver.connect(receiver_callbacks, callback_model)
                receiver_connected = True
                with self.assertRaises(FederateNotExecutionMember):
                    receiver.enableAsynchronousDelivery()
                with self.assertRaises(FederateNotExecutionMember):
                    receiver.disableAsynchronousDelivery()

                publisher.createFederationExecution(
                    federation_name, str(interaction_fom), HLA_TYPES.INTEGER64_TIME
                )
                created = True
                publisher.joinFederationExecution(
                    "jni-async-gating-publisher", federation_name
                )
                publisher_joined = True
                receiver.joinFederationExecution(
                    "jni-async-gating-receiver", federation_name
                )
                receiver_joined = True

                interaction_name = HLA_FOM.PARAMETER_FIXTURE_CHILD
                interaction = publisher.getInteractionClassHandle(interaction_name)
                receiver_interaction = receiver.getInteractionClassHandle(
                    interaction_name
                )
                publisher.publishInteractionClass(interaction)
                receiver.subscribeInteractionClass(receiver_interaction)

                receiver.enableTimeConstrained()
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertEqual(receiver_callbacks.time_constrained_enabled, [])
                    self.assertFalse(receiver.evokeCallback(0.0))
                self.assertEqual(len(receiver_callbacks.time_constrained_enabled), 1)

                # With asynchronous delivery disabled, a receive-order message
                # is retained for a constrained federate rather than dropped.
                publisher.sendInteraction(interaction, ParameterHandleValueMap(), b"")
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertFalse(receiver.evokeCallback(0.0))
                self.assertEqual(receiver_callbacks.received_interactions, [])

                receiver.enableAsynchronousDelivery()
                with self.assertRaises(AsynchronousDeliveryAlreadyEnabled):
                    receiver.enableAsynchronousDelivery()
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertFalse(receiver.evokeCallback(0.0))
                self.assertEqual(len(receiver_callbacks.received_interactions), 1)
                first = receiver_callbacks.received_interactions[0]
                self.assertEqual(first[0], receiver_interaction)
                self.assertEqual(dict(first[1]), {})
                self.assertEqual(first[2], b"")

                receiver.disableAsynchronousDelivery()
                with self.assertRaises(AsynchronousDeliveryAlreadyDisabled):
                    receiver.disableAsynchronousDelivery()

                # A second receive-order message is held again while the
                # receiver remains time constrained and callbacks are gated.
                publisher.sendInteraction(interaction, ParameterHandleValueMap(), b"")
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertFalse(receiver.evokeCallback(0.0))
                self.assertEqual(len(receiver_callbacks.received_interactions), 1)

                # Entering time advancement establishes the eligibility
                # boundary. The retained callback is released at that service
                # boundary for HLA_IMMEDIATE and on the following evoke for
                # HLA_EVOKED; no grant callback is manufactured here.
                receiver.timeAdvanceRequest(
                    receiver.getTimeFactory().makeLogicalTime(1)
                )
                if callback_model is CallbackModel.HLA_EVOKED:
                    self.assertFalse(receiver.evokeCallback(0.0))
                self.assertEqual(len(receiver_callbacks.received_interactions), 2)
                second = receiver_callbacks.received_interactions[1]
                self.assertEqual(second[0], receiver_interaction)
                self.assertEqual(dict(second[1]), {})
                self.assertEqual(second[2], b"")
                self.assertEqual(receiver_callbacks.time_advance_grants, [])
            finally:
                if receiver_joined:
                    try:
                        receiver.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
                if publisher_joined:
                    try:
                        publisher.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
                if created:
                    try:
                        publisher.destroyFederationExecution(federation_name)
                    except Exception:
                        pass
                if receiver_connected:
                    try:
                        receiver.disconnect()
                    except Exception:
                        pass
                if publisher_connected:
                    try:
                        publisher.disconnect()
                    except Exception:
                        pass
                receiver._implementation.close()
                publisher._implementation.close()

        for callback_model in (CallbackModel.HLA_EVOKED, CallbackModel.HLA_IMMEDIATE):
            with self.subTest(callback_model=callback_model):
                run_scenario(callback_model)

