    def test_cpp_jni_java_jpype_timestamped_send_interaction_emits_mom_report(
        self,
    ) -> None:
        """Report a C++-admitted TSO send with its retraction return value."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-tso-mom-report-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        publisher_connected = observer_connected = False
        publisher_joined = observer_joined = False
        created = False

        def drain(rounds: int = 25) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                observer.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_EVOKED)
            observer_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution("jni-tso-mom-publisher", federation_name)
            publisher_joined = True
            observer.joinFederationExecution("jni-tso-mom-observer", federation_name)
            observer_joined = True

            interaction_name = HLA_FOM.MAIN_COURSE_SERVED
            publisher_interaction = publisher.getInteractionClassHandle(
                interaction_name
            )
            observer_interaction = observer.getInteractionClassHandle(interaction_name)
            publisher_parameter = publisher.getParameterHandle(
                publisher_interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            observer_parameter = observer.getParameterHandle(
                observer_interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            publisher.publishInteractionClass(publisher_interaction)
            publisher.changeInteractionOrderType(
                publisher_interaction, OrderType.TIMESTAMP
            )
            observer.subscribeInteractionClass(observer_interaction)

            report_class_name = HLA_MOM.REPORT_SERVICE_INVOCATION
            observer_report_class = observer.getInteractionClassHandle(
                report_class_name
            )
            report_parameter_names = (
                HLA_MOM.SERVICE,
                HLA_MOM.SERVICE_TYPE,
                HLA_MOM.SUCCESS_INDICATOR,
                HLA_MOM.SUPPLIED_ARGUMENTS,
                HLA_MOM.RETURNED_ARGUMENT,
                HLA_MOM.EXCEPTION,
                HLA_MOM.SERIAL_NUMBER,
            )
            observer_report_parameters = {
                name: observer.getParameterHandle(observer_report_class, name)
                for name in report_parameter_names
            }
            observer.subscribeInteractionClass(observer_report_class)

            time_factory = publisher.getTimeFactory()
            publisher.enableTimeRegulation(time_factory.makeLogicalTimeInterval(1))
            drain()
            publisher.setServiceReportingSwitch(True)
            timestamp = time_factory.makeLogicalTime(5)
            retraction = publisher.sendInteractionWithTime(
                publisher_interaction,
                ParameterHandleValueMap({publisher_parameter: b"tso-report-payload"}),
                timestamp,
                b"tso-report-tag",
            )
            self.assertTrue(retraction.isValid())
            drain()

            self.assertEqual(len(observer_callbacks.received_interactions), 1)
            report = observer_callbacks.received_interactions[0]
            self.assertEqual(report[0], observer_report_class)
            self.assertTrue(report[4].encodedValue)
            self.assertFalse(any(report[4].encodedValue[4:]))
            self.assertEqual(len(observer_callbacks.timestamped_interactions), 1)
            normal = observer_callbacks.timestamped_interactions[0]
            self.assertEqual(normal[0], observer_interaction)
            self.assertEqual(
                dict(normal[1]), {observer_parameter: b"tso-report-payload"}
            )
            self.assertEqual(normal[2], b"tso-report-tag")
            self.assertEqual(normal[6].getTime(), 5)
            self.assertEqual(normal[7], OrderType.TIMESTAMP)
            self.assertEqual(normal[8], OrderType.RECEIVE)
            self.assertEqual(normal[9], retraction)

            report_values = dict(report[1])
            encoder = self.factory.getEncoderFactory()
            self.assertEqual(
                encoder.createHLAunicodeString()
                .decode(report_values[observer_report_parameters[HLA_MOM.SERVICE]])
                .getValue(),
                "SendInteraction",
            )
            self.assertEqual(
                encoder.createHLAinteger16BE()
                .decode(report_values[observer_report_parameters[HLA_MOM.SERVICE_TYPE]])
                .getValue(),
                2,
            )
            self.assertTrue(
                encoder.createHLAboolean()
                .decode(
                    report_values[observer_report_parameters[HLA_MOM.SUCCESS_INDICATOR]]
                )
                .getValue()
            )

            class _MomArgumentFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(encoder.createHLAinteger32BE())
                    record.appendElement(encoder.createHLAunicodeString())
                    record.appendElement(encoder.createHLAunicodeString())
                    return record

            supplied_arguments = encoder.createHLAvariableArray(_MomArgumentFactory())
            supplied_arguments.decode(
                report_values[observer_report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]]
            )
            self.assertEqual(supplied_arguments.size(), 4)
            timestamp_argument = supplied_arguments.get(3)
            self.assertEqual(timestamp_argument.get(0).getValue(), 31)
            self.assertEqual(timestamp_argument.get(1).getValue(), "Optional timestamp")
            # Table 5 encodes logical-time arguments as a JSON-like string
            # containing the implementation's ``LogicalTime.toString()``.
            self.assertEqual(timestamp_argument.get(2).getValue(), '"5"')

            returned_argument = encoder.createHLAfixedRecord()
            returned_argument.appendElement(encoder.createHLAinteger32BE())
            returned_argument.appendElement(encoder.createHLAunicodeString())
            returned_argument.appendElement(encoder.createHLAunicodeString())
            returned_argument.decode(
                report_values[observer_report_parameters[HLA_MOM.RETURNED_ARGUMENT]]
            )
            self.assertEqual(returned_argument.get(0).getValue(), 33)
            self.assertEqual(
                returned_argument.get(1).getValue(),
                "Message retraction designator",
            )
            self.assertRegex(
                returned_argument.get(2).getValue(),
                r'^"MessageRetractionHandle<\d+>"$',
            )
            self.assertEqual(
                encoder.createHLAunicodeString()
                .decode(report_values[observer_report_parameters[HLA_MOM.EXCEPTION]])
                .getValue(),
                "",
            )
            self.assertEqual(
                encoder.createHLAinteger32BE()
                .decode(
                    report_values[observer_report_parameters[HLA_MOM.SERIAL_NUMBER]]
                )
                .getValue(),
                0,
            )
        finally:
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            publisher._implementation.close()

