            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-regional-send-mom-receiver", federation_name
            )
            receiver_joined = True
            observer.joinFederationExecution(
                "jni-regional-send-mom-observer", federation_name
            )
            observer_joined = True

            report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
