        publisher_connected = receiver_connected = observer_connected = False
        publisher_joined = receiver_joined = observer_joined = created = False
        publisher_region: RegionHandle | None = None
        receiver_region: RegionHandle | None = None
        report_class: InteractionClassHandle | None = None

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            receiver_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_IMMEDIATE)
            observer_connected = True
            publisher.createFederationExecution(
                federation_name,
                [str(fom_module), str(switch_module)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            publisher.joinFederationExecution(
                "jni-regional-update-failure-mom-publisher", federation_name
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-regional-update-failure-mom-receiver", federation_name
            )
            receiver_joined = True
            observer.joinFederationExecution(
                "jni-regional-update-failure-mom-observer", federation_name
            )
            observer_joined = True

            report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SERVICE_INVOCATION
            )
            report_parameters = {
                name: observer.getParameterHandle(report_class, name)
                for name in (
                    HLA_MOM.SERVICE,
                    HLA_MOM.SERVICE_TYPE,
                    HLA_MOM.SUCCESS_INDICATOR,
                    HLA_MOM.SUPPLIED_ARGUMENTS,
                    HLA_MOM.RETURNED_ARGUMENT,
                    HLA_MOM.EXCEPTION,
                    HLA_MOM.SERIAL_NUMBER,
                )
            }
            observer.setServiceReportingSwitch(False)
            observer.subscribeInteractionClass(report_class)
            receiver.setServiceReportingSwitch(False)
            receiver.setSendServiceReportsToFileSwitch(False)
            publisher.setServiceReportingSwitch(False)
            publisher.setSendServiceReportsToFileSwitch(False)

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            receiver_class = receiver.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            receiver_attribute = receiver.getAttributeHandle(
                receiver_class, HLA_FIXTURES.FLAVOR
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            receiver_dimension = receiver.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            receiver_region = receiver.createRegion(
                DimensionHandleSet([receiver_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 2)
            )
            receiver.setRangeBounds(
                receiver_region, receiver_dimension, RangeBounds(1, 3)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            receiver.commitRegionModifications(RegionHandleSet([receiver_region]))
            publisher_pairs = (
                publisher.getAttributeSetRegionSetPairListFactory().create(1)
            )
            publisher_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([publisher_attribute]),
                    RegionHandleSet([publisher_region]),
                )
            )
            receiver_pairs = receiver.getAttributeSetRegionSetPairListFactory().create(
                1
            )
            receiver_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([receiver_attribute]),
                    RegionHandleSet([receiver_region]),
                )
            )
            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            receiver.subscribeObjectClassAttributesWithRegions(
                receiver_class, receiver_pairs
            )
            receiver.evokeCallback(0.0)
            self.assertEqual(
                receiver_callbacks.discovered_objects[0][0], object_instance
            )

            publisher.setServiceReportingSwitch(True)
            values = AttributeHandleValueMap({publisher_attribute: b"\x01\x02"})
            unknown_object_bytes = bytearray(object_instance.encodedValue)
            unknown_object_bytes[-1] ^= 1
            unknown_object = ObjectInstanceHandle(bytes(unknown_object_bytes))
            unknown_attribute_bytes = bytearray(publisher_attribute.encodedValue)
            unknown_attribute_bytes[-1] ^= 1
            invalid_values = AttributeHandleValueMap(
                {AttributeHandle(bytes(unknown_attribute_bytes)): b"\x01\x02"}
            )
            tag = b"reg"

            class _MomArgumentFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(encoder.createHLAinteger32BE())
                    record.appendElement(encoder.createHLAunicodeString())
                    record.appendElement(encoder.createHLAunicodeString())
                    return record

            encoder = self.factory.getEncoderFactory()

            def verify_report(
                index: int,
                expected_map_fragment: str,
                expected_exception: type[Exception],
            ) -> None:
                report = observer_callbacks.received_interactions[index]
                self.assertEqual(report[0], report_class)
                report_values = dict(report[1])
                self.assertEqual(
                    encoder.createHLAunicodeString()
                    .decode(report_values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue(),
                    "UpdateAttributeValues",
                )
                self.assertEqual(
                    encoder.createHLAinteger16BE()
                    .decode(report_values[report_parameters[HLA_MOM.SERVICE_TYPE]])
                    .getValue(),
                    2,
                )
                self.assertFalse(
                    encoder.createHLAboolean()
                    .decode(report_values[report_parameters[HLA_MOM.SUCCESS_INDICATOR]])
                    .getValue()
                )
                supplied = encoder.createHLAvariableArray(_MomArgumentFactory())
                supplied.decode(
                    report_values[report_parameters[HLA_MOM.SUPPLIED_ARGUMENTS]]
                )
                self.assertEqual(supplied.size(), 4)
                self.assertEqual(supplied.get(0).get(0).getValue(), 37)
                self.assertEqual(
                    supplied.get(0).get(1).getValue(), "Object instance designator"
                )
                self.assertIn("ObjectInstanceHandle", supplied.get(0).get(2).getValue())
                self.assertEqual(supplied.get(1).get(0).getValue(), 2)
                self.assertIn(
                    "attribute designator",
                    supplied.get(1).get(1).getValue(),
                )
                self.assertIn(expected_map_fragment, supplied.get(1).get(2).getValue())
                self.assertEqual(supplied.get(2).get(0).getValue(), 63)
                self.assertEqual(supplied.get(2).get(1).getValue(), "User-supplied tag")
                self.assertIn("cmVn", supplied.get(2).get(2).getValue())
                self.assertEqual(supplied.get(3).get(0).getValue(), 34)
                self.assertEqual(
                    supplied.get(3).get(1).getValue(), "Optional timestamp"
                )
                self.assertEqual(supplied.get(3).get(2).getValue(), "null")

                returned = encoder.createHLAfixedRecord()
                returned.appendElement(encoder.createHLAinteger32BE())
                returned.appendElement(encoder.createHLAunicodeString())
                returned.appendElement(encoder.createHLAunicodeString())
                returned.decode(
                    report_values[report_parameters[HLA_MOM.RETURNED_ARGUMENT]]
                )
                self.assertEqual(returned.get(0).getValue(), 34)
                self.assertEqual(returned.get(1).getValue(), "")
                self.assertEqual(returned.get(2).getValue(), "null")
                exception_text = (
                    encoder.createHLAunicodeString()
                    .decode(report_values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue()
                )
                self.assertTrue(
                    exception_text.startswith(expected_exception.__name__ + ":")
                )
                self.assertEqual(
                    encoder.createHLAinteger32BE()
                    .decode(report_values[report_parameters[HLA_MOM.SERIAL_NUMBER]])
                    .getValue(),
                    index,
                )

            with self.assertRaises(ObjectInstanceNotKnown):
                publisher.updateAttributeValues(unknown_object, values, tag)
            # A standards-shaped but unknown attribute handle reaches C++ as
            # a valid handle-domain value; the ownership precondition is
            # therefore the observable failure before the attribute catalog
            # check.  Empty handles are rejected by the Java decoder before
            # they could exercise the C++ report boundary.
            with self.assertRaises(AttributeNotOwned):
                publisher.updateAttributeValues(object_instance, invalid_values, tag)
            self.assertEqual(len(observer_callbacks.received_interactions), 2)
            verify_report(0, "AQI=", ObjectInstanceNotKnown)
            verify_report(1, "AQI=", AttributeNotOwned)
            self.assertEqual(receiver_callbacks.reflected_attributes, [])
            self.assertEqual(receiver_callbacks.regional_reflections, [])
        finally:
            if receiver_region is not None:
                try:
                    receiver.deleteRegion(receiver_region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            if observer_joined and report_class is not None:
                try:
                    observer.unsubscribeInteractionClass(report_class)
                except Exception:
                    pass
            for ambassador, joined in (
                (receiver, receiver_joined),
                (observer, observer_joined),
                (publisher, publisher_joined),
            ):
                if joined:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, connected in (
                (observer, observer_connected),
                (receiver, receiver_connected),
                (publisher, publisher_connected),
            ):
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
            observer._implementation.close()
            receiver._implementation.close()
            publisher._implementation.close()

