    def test_cpp_jni_java_jpype_delayed_regional_interaction_rechecks_callback_range(
        self,
    ) -> None:
        """Re-evaluate a delayed regional interaction at the callback boundary."""
        restaurant_fom = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        switch_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        federation_name = f"python-jni-delayed-regional-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        created = publisher_joined = subscriber_joined = False
        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name,
                [str(restaurant_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            publisher.joinFederationExecution("jni-delayed-publisher", federation_name)
            publisher_joined = True
            subscriber.joinFederationExecution(
                "jni-delayed-subscriber", federation_name
            )
            subscriber_joined = True
            self.assertTrue(subscriber.getDelaySubscriptionEvaluationSwitch())

            interaction_name = HLA_FOM.MAIN_COURSE_SERVED
            publisher_interaction = publisher.getInteractionClassHandle(
                interaction_name
            )
            subscriber_interaction = subscriber.getInteractionClassHandle(
                interaction_name
            )
            publisher_parameter = publisher.getParameterHandle(
                publisher_interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            subscriber_parameter = subscriber.getParameterHandle(
                subscriber_interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            publisher.publishInteractionClass(publisher_interaction)
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            subscriber_dimension = subscriber.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            subscriber_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 2)
            )
            subscriber.setRangeBounds(
                subscriber_region, subscriber_dimension, RangeBounds(3, 4)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            subscriber.commitRegionModifications(RegionHandleSet([subscriber_region]))
            subscriber.subscribeInteractionClassWithRegions(
                subscriber_interaction, RegionHandleSet([subscriber_region])
            )
            publisher.sendInteractionWithRegions(
                publisher_interaction,
                ParameterHandleValueMap({publisher_parameter: b"delayed-regional"}),
                RegionHandleSet([publisher_region]),
                b"delayed-regional-tag",
            )
            self.assertEqual(subscriber_callbacks.received_interactions, [])
            self.assertEqual(subscriber_callbacks.regional_interactions, [])

            # The delayed route keeps the queued message but must consult the
            # committed range when the subscriber finally evokes callbacks.
            subscriber.setRangeBounds(
                subscriber_region, subscriber_dimension, RangeBounds(1, 3)
            )
            subscriber.commitRegionModifications(RegionHandleSet([subscriber_region]))
            subscriber.evokeCallback(0.0)
            self.assertEqual(
                len(subscriber_callbacks.received_interactions)
                + len(subscriber_callbacks.regional_interactions),
                1,
            )
            received = (
                subscriber_callbacks.received_interactions[-1]
                if subscriber_callbacks.received_interactions
                else subscriber_callbacks.regional_interactions[-1]
            )
            self.assertEqual(received[0], subscriber_interaction)
            self.assertEqual(received[1][subscriber_parameter], b"delayed-regional")
            self.assertEqual(received[2], b"delayed-regional-tag")
        finally:
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            subscriber.disconnect()
            publisher.disconnect()
            subscriber._implementation.close()
            publisher._implementation.close()

