    def test_cpp_jni_java_jpype_mixed_default_region_timestamped_update_delivers_before_time_grants(
        self,
    ) -> None:
        """Fan out one C++ default-region TSO update through all Java time requests."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-mixed-default-region-tso-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        fqr = self.factory.getRtiAmbassador()
        tara = self.factory.getRtiAmbassador()
        nmra = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        fqr_callbacks = _JniCallbacks()
        tara_callbacks = _JniCallbacks()
        nmra_callbacks = _JniCallbacks()
        receivers = (
            (fqr, fqr_callbacks, "jni-mixed-default-region-fqr"),
            (tara, tara_callbacks, "jni-mixed-default-region-tara"),
            (nmra, nmra_callbacks, "jni-mixed-default-region-nmra"),
        )
        created = publisher_joined = False
        receiver_joined = {name: False for _, _, name in receivers}

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                for ambassador, _, _ in receivers:
                    ambassador.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            region: RegionHandle,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([attribute]), RegionHandleSet([region])
                )
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            for ambassador, callbacks, _ in receivers:
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-mixed-default-region-publisher", federation_name
            )
            publisher_joined = True
            for ambassador, _, name in receivers:
                ambassador.joinFederationExecution(name, federation_name)
                receiver_joined[name] = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            publisher_attributes = AttributeHandleSet([publisher_attribute])
            publisher.publishObjectClassAttributes(
                publisher_class, publisher_attributes
            )
            publisher.changeDefaultAttributeOrderType(
                publisher_class, publisher_attributes, OrderType.TIMESTAMP
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            receiver_pairs: list[
                tuple[RTIambassador, _JniCallbacks, AttributeSetRegionSetPairList]
            ] = []
            for ambassador, callbacks, _ in receivers:
                receiver_class = ambassador.getObjectClassHandle(
                    HLA_FOM.FOOD_DRINK_SODA
                )
                receiver_attribute = ambassador.getAttributeHandle(
                    receiver_class, HLA_FIXTURES.FLAVOR
                )
                receiver_dimension = ambassador.getDimensionHandle(
                    HLA_FIXTURES.SODA_FLAVOR
                )
                receiver_region = ambassador.createRegion(
                    DimensionHandleSet([receiver_dimension])
                )
                ambassador.setRangeBounds(
                    receiver_region, receiver_dimension, RangeBounds(2, 3)
                )
                ambassador.commitRegionModifications(RegionHandleSet([receiver_region]))
                pairs = pair_list(ambassador, receiver_attribute, receiver_region)
                ambassador.subscribeObjectClassAttributesWithRegions(
                    receiver_class, pairs, active=True
                )
                self.assertFalse(ambassador.getConveyRegionDesignatorSetsSwitch())
                ambassador.setConveyRegionDesignatorSetsSwitch(True)
                ambassador.enableTimeConstrained()
                receiver_pairs.append((ambassador, callbacks, pairs))
            pump()

            object_instance = publisher.registerObjectInstance(publisher_class)
            pump()
            for _, callbacks, _ in receiver_pairs:
                self.assertEqual(len(callbacks.discovered_objects), 1)
                self.assertEqual(callbacks.discovered_objects[0][0], object_instance)

            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = b"jni-mixed-default-region-tso"
            values = AttributeHandleValueMap(
                {publisher_attribute: b"default-region-tso"}
            )
            retraction = publisher.updateAttributeValuesWithTime(
                object_instance,
                values,
                publisher.getTimeFactory().makeLogicalTime(7),
                tag,
            )
            self.assertTrue(retraction.isValid())
            for _, callbacks, _ in receiver_pairs:
                self.assertEqual(callbacks.timestamped_reflections, [])

            fqr.flushQueueRequest(fqr.getTimeFactory().makeLogicalTime(10))
            tara.timeAdvanceRequestAvailable(tara.getTimeFactory().makeLogicalTime(7))
            nmra.nextMessageRequestAvailable(nmra.getTimeFactory().makeLogicalTime(10))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(len(publisher_callbacks.time_advance_grants), 1)
            self.assertEqual(publisher_callbacks.time_advance_grants[0].getTime(), 2)

            for ambassador, callbacks, _ in receiver_pairs:
                self.assertEqual(len(callbacks.timestamped_reflections), 1)
                reflection = callbacks.timestamped_reflections[0]
                self.assertEqual(reflection[0], object_instance)
                self.assertEqual(
                    list(dict(reflection[1]).values()), [b"default-region-tso"]
                )
                self.assertEqual(reflection[2], tag)
                self.assertEqual(reflection[5], RegionHandleSet())
                self.assertEqual(reflection[6].getTime(), 7)
                self.assertEqual(reflection[7], OrderType.TIMESTAMP)
                self.assertEqual(reflection[8], OrderType.TIMESTAMP)
                self.assertEqual(reflection[9], retraction)
            self.assertEqual(len(fqr_callbacks.flush_queue_grants), 1)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][0].getTime(), 7)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][1].getTime(), 7)
            self.assertEqual(len(tara_callbacks.time_advance_grants), 1)
            self.assertEqual(tara_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(len(nmra_callbacks.time_advance_grants), 1)
            self.assertEqual(nmra_callbacks.time_advance_grants[0].getTime(), 7)
        finally:
            for ambassador, _, name in reversed(receivers):
                if receiver_joined[name]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, _, _ in receivers:
                ambassador.disconnect()
            publisher.disconnect()
            for ambassador, _, _ in receivers:
                ambassador._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_mixed_default_and_regional_timestamped_update_available_advances(
        self,
    ) -> None:
        """Fan out explicit and default-region TSO updates before each available grant."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def reflectAttributeValues(
                self, *arguments: object, **keywords: object
            ) -> None:
                super().reflectAttributeValues(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("reflection")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                super().flushQueueGrant(time, optimisticTime)
                self.order.append("flush-grant")

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-mixed-source-tso-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        fqr = self.factory.getRtiAmbassador()
        tara = self.factory.getRtiAmbassador()
        nmra = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        fqr_callbacks = OrderedCallbacks()
        tara_callbacks = OrderedCallbacks()
        nmra_callbacks = OrderedCallbacks()
        receivers = (
            (fqr, fqr_callbacks, "jni-mixed-source-tso-fqr"),
            (tara, tara_callbacks, "jni-mixed-source-tso-tara"),
            (nmra, nmra_callbacks, "jni-mixed-source-tso-nmra"),
        )
        created = publisher_joined = False
        receiver_joined = {name: False for _, _, name in receivers}
        publisher_region: RegionHandle | None = None
        publisher_pairs: AttributeSetRegionSetPairList | None = None
        receiver_regions: list[
            tuple[RTIambassador, RegionHandle, AttributeSetRegionSetPairList]
        ] = []
        explicit_object: ObjectInstanceHandle | None = None
        default_object: ObjectInstanceHandle | None = None

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                for ambassador, _, _ in receivers:
                    ambassador.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            region: RegionHandle,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([attribute]), RegionHandleSet([region])
                )
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            for ambassador, callbacks, _ in receivers:
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "publisher",
                federation_name,
                federateName="jni-mixed-source-tso-publisher",
            )
            publisher_joined = True
            for ambassador, _, name in receivers:
                ambassador.joinFederationExecution(name, federation_name)
                receiver_joined[name] = True
            publisher_federate = publisher.getFederateHandle(
                "jni-mixed-source-tso-publisher"
            )

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            publisher_attributes = AttributeHandleSet([publisher_attribute])
            publisher.publishObjectClassAttributes(
                publisher_class, publisher_attributes
            )
            publisher.changeDefaultAttributeOrderType(
                publisher_class, publisher_attributes, OrderType.TIMESTAMP
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 2)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            publisher_pairs = pair_list(
                publisher, publisher_attribute, publisher_region
            )

            for ambassador, _, _ in receivers:
                receiver_class = ambassador.getObjectClassHandle(
                    HLA_FOM.FOOD_DRINK_SODA
                )
                receiver_attribute = ambassador.getAttributeHandle(
                    receiver_class, HLA_FIXTURES.FLAVOR
                )
                receiver_dimension = ambassador.getDimensionHandle(
                    HLA_FIXTURES.SODA_FLAVOR
                )
                receiver_region = ambassador.createRegion(
                    DimensionHandleSet([receiver_dimension])
                )
                ambassador.setRangeBounds(
                    receiver_region, receiver_dimension, RangeBounds(1, 3)
                )
                ambassador.commitRegionModifications(RegionHandleSet([receiver_region]))
                receiver_pairs = pair_list(
                    ambassador, receiver_attribute, receiver_region
                )
                ambassador.subscribeObjectClassAttributesWithRegions(
                    receiver_class, receiver_pairs, active=True
                )
                ambassador.setConveyRegionDesignatorSetsSwitch(True)
                ambassador.enableTimeConstrained()
                receiver_regions.append((ambassador, receiver_region, receiver_pairs))
            pump()

            explicit_object = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            default_object = publisher.registerObjectInstance(publisher_class)
            pump()
            for _, callbacks, _ in receivers:
                self.assertEqual(
                    {entry[0] for entry in callbacks.discovered_objects},
                    {explicit_object, default_object},
                )

            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            explicit_retraction = publisher.updateAttributeValuesWithTime(
                explicit_object,
                AttributeHandleValueMap({publisher_attribute: b"explicit-tso"}),
                publisher.getTimeFactory().makeLogicalTime(7),
                b"explicit-tso-tag",
            )
            default_retraction = publisher.updateAttributeValuesWithTime(
                default_object,
                AttributeHandleValueMap({publisher_attribute: b"default-tso"}),
                publisher.getTimeFactory().makeLogicalTime(7),
                b"default-tso-tag",
            )
            self.assertTrue(explicit_retraction.isValid())
            self.assertTrue(default_retraction.isValid())
            for _, callbacks, _ in receivers:
                self.assertEqual(callbacks.timestamped_reflections, [])

            fqr.flushQueueRequest(fqr.getTimeFactory().makeLogicalTime(10))
            tara.timeAdvanceRequestAvailable(tara.getTimeFactory().makeLogicalTime(7))
            nmra.nextMessageRequestAvailable(nmra.getTimeFactory().makeLogicalTime(10))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(publisher_callbacks.time_advance_grants[0].getTime(), 2)

            for ambassador, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.timestamped_reflections), 2)
                self.assertEqual(callbacks.order[:2], ["reflection", "reflection"])
                self.assertEqual(
                    callbacks.order[-1], "flush-grant" if ambassador is fqr else "grant"
                )
                by_object = {
                    reflection[0]: reflection
                    for reflection in callbacks.timestamped_reflections
                }
                explicit_reflection = by_object[explicit_object]
                default_reflection = by_object[default_object]
                self.assertEqual(
                    explicit_reflection[1],
                    AttributeHandleValueMap(
                        {
                            ambassador.getAttributeHandle(
                                ambassador.getObjectClassHandle(
                                    HLA_FOM.FOOD_DRINK_SODA
                                ),
                                HLA_FIXTURES.FLAVOR,
                            ): b"explicit-tso"
                        }
                    ),
                )
                self.assertEqual(explicit_reflection[2], b"explicit-tso-tag")
                self.assertEqual(explicit_reflection[4], publisher_federate)
                self.assertEqual(
                    explicit_reflection[5], RegionHandleSet([publisher_region])
                )
                self.assertEqual(explicit_reflection[6].getTime(), 7)
                self.assertEqual(explicit_reflection[7], OrderType.TIMESTAMP)
                self.assertEqual(explicit_reflection[8], OrderType.TIMESTAMP)
                self.assertEqual(explicit_reflection[9], explicit_retraction)
                self.assertEqual(default_reflection[2], b"default-tso-tag")
                self.assertEqual(default_reflection[4], publisher_federate)
                self.assertEqual(default_reflection[5], RegionHandleSet())
                self.assertEqual(default_reflection[6].getTime(), 7)
                self.assertEqual(default_reflection[7], OrderType.TIMESTAMP)
                self.assertEqual(default_reflection[8], OrderType.TIMESTAMP)
                self.assertEqual(default_reflection[9], default_retraction)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][0].getTime(), 7)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][1].getTime(), 7)
            self.assertEqual(tara_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(nmra_callbacks.time_advance_grants[0].getTime(), 7)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(explicit_retraction)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(default_retraction)
        finally:
            if explicit_object is not None and publisher_pairs is not None:
                try:
                    publisher.unassociateRegionsForUpdates(
                        explicit_object, publisher_pairs
                    )
                except Exception:
                    pass
            for ambassador, _, pairs in receiver_regions:
                try:
                    ambassador.unsubscribeObjectClassAttributesWithRegions(
                        ambassador.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA),
                        pairs,
                    )
                except Exception:
                    pass
            for ambassador, region, _ in receiver_regions:
                try:
                    ambassador.deleteRegion(region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            for ambassador, _, name in reversed(receivers):
                if receiver_joined[name]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, _, _ in receivers:
                ambassador.disconnect()
            publisher.disconnect()
            for ambassador, _, _ in receivers:
                ambassador._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_flush_queue_admits_future_timestamped_inputs_before_grant(
        self,
    ) -> None:
        """FQR admitted before send still drains future TSO input before FQG."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def receiveInteraction(
                self, *arguments: object, **keywords: object
            ) -> None:
                super().receiveInteraction(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("interaction")

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                super().flushQueueGrant(time, optimisticTime)
                self.order.append("flush-grant")

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )
        federation_name = f"python-jni-future-input-fqr-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = OrderedCallbacks()
        created = publisher_joined = receiver_joined = False

        def pump() -> None:
            for _ in range(12):
                publisher.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-future-input-fqr-publisher", federation_name
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-future-input-fqr-receiver", federation_name
            )
            receiver_joined = True

            interaction_class = publisher.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            identifier = publisher.getParameterHandle(
                interaction_class, HLA_FIXTURES.IDENTIFIER
            )
            parameter_values = ParameterHandleValueMap({identifier: b"F4"})
            publisher.publishInteractionClass(interaction_class)
            publisher.changeInteractionOrderType(interaction_class, OrderType.TIMESTAMP)
            receiver.subscribeInteractionClass(interaction_class)
            receiver.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()

            # Accept FQR before the producer queues either payload. Both
            # timestamped inputs arrive before the evoked callback frontier.
            receiver.flushQueueRequest(receiver.getTimeFactory().makeLogicalTime(10))
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])
            first = publisher.sendInteractionWithTime(
                interaction_class,
                parameter_values,
                publisher.getTimeFactory().makeLogicalTime(9),
                b"FUT",
            )
            second = publisher.sendInteractionWithTime(
                interaction_class,
                parameter_values,
                publisher.getTimeFactory().makeLogicalTime(12),
                b"FUT",
            )
            self.assertTrue(first.isValid())
            self.assertTrue(second.isValid())
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])

            receiver.evokeCallback(0.0)
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 2)
            self.assertEqual(len(receiver_callbacks.flush_queue_grants), 1)
            self.assertEqual(
                receiver_callbacks.order, ["interaction", "interaction", "flush-grant"]
            )
            self.assertEqual(
                [
                    entry[6].getTime()
                    for entry in receiver_callbacks.timestamped_interactions
                ],
                [9, 12],
            )
            self.assertEqual(receiver_callbacks.flush_queue_grants[0][0].getTime(), 5)
            self.assertEqual(receiver_callbacks.flush_queue_grants[0][1].getTime(), 9)
            for index, (entry, retraction) in enumerate(
                zip(receiver_callbacks.timestamped_interactions, (first, second))
            ):
                self.assertEqual(entry[0], interaction_class)
                self.assertEqual(dict(entry[1]), dict(parameter_values))
                self.assertEqual(entry[2], b"FUT")
                self.assertEqual(entry[6].getTime(), (9, 12)[index])
                self.assertEqual(entry[7], OrderType.TIMESTAMP)
                self.assertEqual(entry[8], OrderType.TIMESTAMP)
                self.assertEqual(entry[9], retraction)
        finally:
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            receiver.disconnect()
            publisher.disconnect()
            receiver._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_default_region_timestamped_interaction_retraction_sequence(
        self,
    ) -> None:
        """Retract an immediate default-region callback while TSO remains queued."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def receiveInteraction(
                self, *arguments: object, **keywords: object
            ) -> None:
                super().receiveInteraction(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("interaction")

            def requestRetraction(self, retraction: MessageRetractionHandle) -> None:
                super().requestRetraction(retraction)
                self.order.append("request-retraction")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-default-region-retraction-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        constrained = self.factory.getRtiAmbassador()
        immediate = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        constrained_callbacks = OrderedCallbacks()
        immediate_callbacks = OrderedCallbacks()
        created = publisher_joined = constrained_joined = immediate_joined = False
        constrained_region: RegionHandle | None = None
        immediate_region: RegionHandle | None = None

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                constrained.evokeCallback(0.0)
                immediate.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            constrained.connect(constrained_callbacks, CallbackModel.HLA_EVOKED)
            immediate.connect(immediate_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-default-region-retraction-publisher", federation_name
            )
            publisher_joined = True
            constrained.joinFederationExecution(
                "jni-default-region-retraction-constrained", federation_name
            )
            constrained_joined = True
            immediate.joinFederationExecution(
                "jni-default-region-retraction-immediate", federation_name
            )
            immediate_joined = True

            interaction = publisher.getInteractionClassHandle(
                HLA_FOM.MAIN_COURSE_SERVED
            )
            constrained_interaction = constrained.getInteractionClassHandle(
                HLA_FOM.MAIN_COURSE_SERVED
            )
            immediate_interaction = immediate.getInteractionClassHandle(
                HLA_FOM.MAIN_COURSE_SERVED
            )
            parameter = publisher.getParameterHandle(
                interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            immediate_parameter = immediate.getParameterHandle(
                immediate_interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            parameter_values = ParameterHandleValueMap({parameter: b"DEFI"})
            dimension = publisher.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            constrained_dimension = constrained.getDimensionHandle(
                HLA_FIXTURES.SERVER_ID
            )
            immediate_dimension = immediate.getDimensionHandle(HLA_FIXTURES.SERVER_ID)

            publisher.publishInteractionClass(interaction)
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            constrained_region = constrained.createRegion(
                DimensionHandleSet([constrained_dimension])
            )
            immediate_region = immediate.createRegion(
                DimensionHandleSet([immediate_dimension])
            )
            constrained.setRangeBounds(
                constrained_region, constrained_dimension, RangeBounds(8, 9)
            )
            immediate.setRangeBounds(
                immediate_region, immediate_dimension, RangeBounds(8, 9)
            )
            constrained.commitRegionModifications(RegionHandleSet([constrained_region]))
            immediate.commitRegionModifications(RegionHandleSet([immediate_region]))
            constrained.subscribeInteractionClassWithRegions(
                constrained_interaction,
                RegionHandleSet([constrained_region]),
                active=True,
            )
            immediate.subscribeInteractionClassWithRegions(
                immediate_interaction, RegionHandleSet([immediate_region]), active=True
            )
            constrained.setConveyRegionDesignatorSetsSwitch(True)
            immediate.setConveyRegionDesignatorSetsSwitch(True)
            constrained.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()

            tag = b"DEF-TSO"
            retraction = publisher.sendInteractionWithTime(
                interaction,
                parameter_values,
                publisher.getTimeFactory().makeLogicalTime(6),
                tag,
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(constrained_callbacks.timestamped_interactions, [])
            immediate.evokeCallback(0.0)
            self.assertEqual(len(immediate_callbacks.timestamped_interactions), 1)
            immediate_report = immediate_callbacks.timestamped_interactions[0]
            self.assertEqual(immediate_report[0], immediate_interaction)
            self.assertEqual(
                dict(immediate_report[1]),
                ParameterHandleValueMap({immediate_parameter: b"DEFI"}),
            )
            self.assertEqual(immediate_report[2], tag)
            self.assertEqual(immediate_report[5], RegionHandleSet())
            self.assertEqual(immediate_report[6].getTime(), 6)
            self.assertEqual(immediate_report[7], OrderType.TIMESTAMP)
            self.assertEqual(immediate_report[8], OrderType.RECEIVE)
            self.assertEqual(immediate_report[9], retraction)

            constrained.timeAdvanceRequest(
                constrained.getTimeFactory().makeLogicalTime(6)
            )
            publisher.retract(retraction)
            immediate.evokeCallback(0.0)
            self.assertEqual(immediate_callbacks.retraction_requests, [retraction])
            self.assertEqual(
                immediate_callbacks.order, ["interaction", "request-retraction"]
            )

            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(constrained_callbacks.time_advance_grants[-1].getTime(), 6)
            self.assertEqual(constrained_callbacks.timestamped_interactions, [])
            self.assertEqual(constrained_callbacks.retraction_requests, [])
            self.assertEqual(constrained_callbacks.order, ["grant"])
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
        finally:
            if constrained_region is not None and constrained_joined:
                try:
                    constrained.unsubscribeInteractionClassWithRegions(
                        constrained.getInteractionClassHandle(
                            HLA_FOM.MAIN_COURSE_SERVED
                        ),
                        RegionHandleSet([constrained_region]),
                    )
                except Exception:
                    pass
            if immediate_region is not None and immediate_joined:
                try:
                    immediate.unsubscribeInteractionClassWithRegions(
                        immediate.getInteractionClassHandle(HLA_FOM.MAIN_COURSE_SERVED),
                        RegionHandleSet([immediate_region]),
                    )
                except Exception:
                    pass
            if constrained_region is not None:
                try:
                    constrained.deleteRegion(constrained_region)
                except Exception:
                    pass
            if immediate_region is not None:
                try:
                    immediate.deleteRegion(immediate_region)
                except Exception:
                    pass
            if immediate_joined:
                try:
                    immediate.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if constrained_joined:
                try:
                    constrained.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            immediate.disconnect()
            constrained.disconnect()
            publisher.disconnect()
            immediate._implementation.close()
            constrained._implementation.close()
            publisher._implementation.close()

