    def test_cpp_jni_java_jpype_timestamped_interaction_retraction_and_resignation(
        self,
    ) -> None:
        """Retract delivered interaction fanout and suppress a queued recipient."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def receiveInteraction(
                self, *arguments: object, **keywords: object
            ) -> None:
                super().receiveInteraction(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("interaction")

            def requestRetraction(self, retraction: MessageRetractionHandle) -> None:
                super().requestRetraction(retraction)
                self.order.append("request-retraction")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "parameter-handle-provider-fom.xml"
        )
        federation_name = f"python-jni-interaction-retraction-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        immediate = self.factory.getRtiAmbassador()
        constrained = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        immediate_callbacks = OrderedCallbacks()
        constrained_callbacks = OrderedCallbacks()
        created = publisher_joined = immediate_joined = constrained_joined = False

        def pump(rounds: int = 16) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                immediate.evokeCallback(0.0)
                constrained.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            immediate.connect(immediate_callbacks, CallbackModel.HLA_EVOKED)
            constrained.connect(constrained_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-interaction-retraction-publisher", federation_name
            )
            publisher_joined = True
            immediate.joinFederationExecution(
                "jni-interaction-retraction-immediate", federation_name
            )
            immediate_joined = True
            constrained.joinFederationExecution(
                "jni-interaction-retraction-constrained", federation_name
            )
            constrained_joined = True

            interaction = publisher.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            immediate_interaction = immediate.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            constrained_interaction = constrained.getInteractionClassHandle(
                HLA_FOM.PARAMETER_FIXTURE_CHILD
            )
            publisher.publishInteractionClass(interaction)
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            immediate.subscribeInteractionClass(immediate_interaction)
            constrained.subscribeInteractionClass(constrained_interaction)
            constrained.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(1)
            )
            pump()

            tag = b"RTI"
            retraction = publisher.sendInteractionWithTime(
                interaction,
                ParameterHandleValueMap(),
                publisher.getTimeFactory().makeLogicalTime(2),
                tag,
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(immediate_callbacks.timestamped_interactions, [])
            self.assertEqual(constrained_callbacks.timestamped_interactions, [])

            pump()
            self.assertEqual(len(immediate_callbacks.timestamped_interactions), 1)
            immediate_report = immediate_callbacks.timestamped_interactions[0]
            self.assertEqual(immediate_report[0], immediate_interaction)
            self.assertEqual(immediate_report[1], ParameterHandleValueMap())
            self.assertEqual(immediate_report[2], tag)
            self.assertEqual(immediate_report[6].getTime(), 2)
            self.assertEqual(immediate_report[7], OrderType.TIMESTAMP)
            self.assertEqual(immediate_report[8], OrderType.RECEIVE)
            self.assertEqual(immediate_report[9], retraction)
            self.assertEqual(immediate_callbacks.order, ["interaction"])

            publisher.retract(retraction)
            pump()
            self.assertEqual(immediate_callbacks.retraction_requests, [retraction])
            self.assertEqual(
                immediate_callbacks.order, ["interaction", "request-retraction"]
            )
            self.assertEqual(constrained_callbacks.timestamped_interactions, [])
            self.assertEqual(constrained_callbacks.retraction_requests, [])

            constrained.timeAdvanceRequest(
                constrained.getTimeFactory().makeLogicalTime(2)
            )
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(constrained_callbacks.time_advance_grants[-1].getTime(), 2)
            self.assertEqual(constrained_callbacks.timestamped_interactions, [])
            self.assertEqual(constrained_callbacks.retraction_requests, [])
            self.assertEqual(constrained_callbacks.order, ["grant"])

            # Once the constrained member resigns, a later timestamped send
            # has no queued fanout but remains retractable for the immediate
            # recipient through the same C++ ledger.
            constrained.resignFederationExecution(ResignAction.NO_ACTION)
            constrained_joined = False
            immediate_only = publisher.sendInteractionWithTime(
                interaction,
                ParameterHandleValueMap(),
                publisher.getTimeFactory().makeLogicalTime(4),
                tag,
            )
            self.assertTrue(immediate_only.isValid())
            pump()
            self.assertEqual(len(immediate_callbacks.timestamped_interactions), 2)
            second_report = immediate_callbacks.timestamped_interactions[-1]
            self.assertEqual(second_report[6].getTime(), 4)
            self.assertEqual(second_report[8], OrderType.RECEIVE)
            self.assertEqual(second_report[9], immediate_only)

            publisher.retract(immediate_only)
            pump()
            self.assertEqual(
                immediate_callbacks.retraction_requests,
                [retraction, immediate_only],
            )
            self.assertEqual(
                immediate_callbacks.order,
                [
                    "interaction",
                    "request-retraction",
                    "interaction",
                    "request-retraction",
                ],
            )
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(immediate_only)
        finally:
            if constrained_joined:
                try:
                    constrained.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if immediate_joined:
                try:
                    immediate.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            constrained.disconnect()
            immediate.disconnect()
            publisher.disconnect()
            constrained._implementation.close()
            immediate._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_mixed_default_region_timestamped_interaction_delivers_before_time_grants(
        self,
    ) -> None:
        """Fan out one C++ default-region interaction through all Java time requests."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def receiveInteraction(
                self, *arguments: object, **keywords: object
            ) -> None:
                super().receiveInteraction(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("interaction")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                super().flushQueueGrant(time, optimisticTime)
                self.order.append("flush-grant")

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-mixed-default-region-interaction-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        fqr = self.factory.getRtiAmbassador()
        tara = self.factory.getRtiAmbassador()
        nmra = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        fqr_callbacks = OrderedCallbacks()
        tara_callbacks = OrderedCallbacks()
        nmra_callbacks = OrderedCallbacks()
        receivers = (
            (fqr, fqr_callbacks, "jni-mixed-default-region-interaction-fqr"),
            (tara, tara_callbacks, "jni-mixed-default-region-interaction-tara"),
            (nmra, nmra_callbacks, "jni-mixed-default-region-interaction-nmra"),
        )
        created = publisher_joined = False
        receiver_joined = {name: False for _, _, name in receivers}

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                for ambassador, _, _ in receivers:
                    ambassador.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            for ambassador, callbacks, _ in receivers:
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-mixed-default-region-interaction-publisher", federation_name
            )
            publisher_joined = True
            for ambassador, _, name in receivers:
                ambassador.joinFederationExecution(name, federation_name)
                receiver_joined[name] = True

            interaction = publisher.getInteractionClassHandle(
                HLA_FOM.MAIN_COURSE_SERVED
            )
            publisher_parameter = publisher.getParameterHandle(
                interaction, HLA_FIXTURES.TEMPERATURE_OK
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            publisher.publishInteractionClass(interaction)
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)
            parameters = ParameterHandleValueMap(
                {publisher_parameter: b"interaction-default"}
            )

            for ambassador, _, _ in receivers:
                receiver_interaction = ambassador.getInteractionClassHandle(
                    HLA_FOM.MAIN_COURSE_SERVED
                )
                receiver_dimension = ambassador.getDimensionHandle(
                    HLA_FIXTURES.SERVER_ID
                )
                receiver_region = ambassador.createRegion(
                    DimensionHandleSet([receiver_dimension])
                )
                ambassador.setRangeBounds(
                    receiver_region, receiver_dimension, RangeBounds(8, 9)
                )
                ambassador.commitRegionModifications(RegionHandleSet([receiver_region]))
                ambassador.subscribeInteractionClassWithRegions(
                    receiver_interaction,
                    RegionHandleSet([receiver_region]),
                    active=True,
                )
                self.assertFalse(ambassador.getConveyRegionDesignatorSetsSwitch())
                ambassador.setConveyRegionDesignatorSetsSwitch(True)
                ambassador.enableTimeConstrained()
            pump()

            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)
            tag = b"jni-mixed-default-region-interaction"
            retraction = publisher.sendInteractionWithTime(
                interaction,
                parameters,
                publisher.getTimeFactory().makeLogicalTime(7),
                tag,
            )
            self.assertTrue(retraction.isValid())
            for _, callbacks, _ in receivers:
                self.assertEqual(callbacks.timestamped_interactions, [])

            fqr.flushQueueRequest(fqr.getTimeFactory().makeLogicalTime(10))
            tara.timeAdvanceRequestAvailable(tara.getTimeFactory().makeLogicalTime(7))
            nmra.nextMessageRequestAvailable(nmra.getTimeFactory().makeLogicalTime(10))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(len(publisher_callbacks.time_advance_grants), 1)
            self.assertEqual(publisher_callbacks.time_advance_grants[0].getTime(), 2)

            for _, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.timestamped_interactions), 1)
                report = callbacks.timestamped_interactions[0]
                self.assertEqual(report[0], interaction)
                self.assertEqual(
                    list(dict(report[1]).values()), [b"interaction-default"]
                )
                self.assertEqual(report[2], tag)
                self.assertEqual(report[5], RegionHandleSet())
                self.assertEqual(report[6].getTime(), 7)
                self.assertEqual(report[7], OrderType.TIMESTAMP)
                self.assertEqual(report[8], OrderType.TIMESTAMP)
                self.assertEqual(report[9], retraction)
            self.assertEqual(fqr_callbacks.order, ["interaction", "flush-grant"])
            self.assertEqual(tara_callbacks.order, ["interaction", "grant"])
            self.assertEqual(nmra_callbacks.order, ["interaction", "grant"])
            self.assertEqual(len(fqr_callbacks.flush_queue_grants), 1)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][0].getTime(), 7)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][1].getTime(), 7)
            self.assertEqual(len(tara_callbacks.time_advance_grants), 1)
            self.assertEqual(tara_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(len(nmra_callbacks.time_advance_grants), 1)
            self.assertEqual(nmra_callbacks.time_advance_grants[0].getTime(), 7)
        finally:
            for ambassador, _, name in reversed(receivers):
                if receiver_joined[name]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, _, _ in receivers:
                ambassador.disconnect()
            publisher.disconnect()
            for ambassador, _, _ in receivers:
                ambassador._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_object_deletion_survives_time_constrained_reenable(
        self,
    ) -> None:
        """Preserve a queued C++ deletion across constrained-role re-enable."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def removeObjectInstance(
                self,
                objectInstance: ObjectInstanceHandle,
                userSuppliedTag: bytes,
                producingFederate: FederateHandle,
                time: HLAinteger64Time | None = None,
                sentOrderType: OrderType | None = None,
                receivedOrderType: OrderType | None = None,
                retraction: MessageRetractionHandle | None = None,
            ) -> None:
                super().removeObjectInstance(
                    objectInstance,
                    userSuppliedTag,
                    producingFederate,
                    time,
                    sentOrderType,
                    receivedOrderType,
                    retraction,
                )
                if time is not None:
                    self.order.append("remove")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        federation_name = f"python-jni-timestamped-delete-reenable-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = OrderedCallbacks()
        publisher_connected = receiver_connected = False
        publisher_joined = receiver_joined = created = False
        receiver_class: ObjectClassHandle | None = None
        receiver_attributes: AttributeHandleSet | None = None

        def pump(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            receiver_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher_handle = publisher.joinFederationExecution(
                "jni-timestamped-delete-reenable-publisher", federation_name
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "jni-timestamped-delete-reenable-receiver", federation_name
            )
            receiver_joined = True

            object_class = publisher.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            receiver_class = receiver.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            reliable = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            best_effort = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            receiver_reliable = receiver.getAttributeHandle(
                receiver_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            receiver_best_effort = receiver.getAttributeHandle(
                receiver_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            attributes = AttributeHandleSet([reliable, best_effort])
            receiver_attributes = AttributeHandleSet(
                [receiver_reliable, receiver_best_effort]
            )
            publisher.publishObjectClassAttributes(object_class, attributes)
            receiver.subscribeObjectClassAttributes(receiver_class, receiver_attributes)

            object_instance = publisher.registerObjectInstance(object_class)
            pump()
            self.assertEqual(len(receiver_callbacks.discovered_objects), 1)
            self.assertEqual(
                receiver_callbacks.discovered_objects[0][0], object_instance
            )
            object_name = publisher.getObjectInstanceName(object_instance)
            self.assertEqual(
                receiver.getObjectInstanceHandle(object_name), object_instance
            )

            receiver.enableTimeConstrained()
            pump()
            self.assertEqual(len(receiver_callbacks.time_constrained_enabled), 1)
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = bytes((0x52, 0x45, 0x45, 0x4E, 0x2D, 0x44))
            retraction = publisher.deleteObjectInstanceWithTime(
                object_instance,
                publisher.getTimeFactory().makeLogicalTime(6),
                tag,
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(receiver_callbacks.timestamped_removals, [])
            self.assertEqual(
                receiver.getObjectInstanceHandle(object_name), object_instance
            )

            receiver.disableTimeConstrained()
            pump()
            self.assertEqual(receiver_callbacks.timestamped_removals, [])
            receiver.enableTimeConstrained()
            pump()
            self.assertEqual(len(receiver_callbacks.time_constrained_enabled), 2)

            receiver.timeAdvanceRequest(receiver.getTimeFactory().makeLogicalTime(6))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(len(receiver_callbacks.timestamped_removals), 1)
            self.assertEqual(receiver_callbacks.order, ["remove", "grant"])
            removal = receiver_callbacks.timestamped_removals[0]
            self.assertEqual(removal[0], object_instance)
            self.assertEqual(removal[1], tag)
            self.assertEqual(removal[2], publisher_handle)
            self.assertEqual(removal[3].getTime(), 6)
            self.assertEqual(removal[4], OrderType.TIMESTAMP)
            self.assertEqual(removal[5], OrderType.TIMESTAMP)
            self.assertEqual(removal[6], retraction)
            with self.assertRaises(ObjectInstanceNotKnown):
                receiver.getObjectInstanceHandle(object_name)
            with self.assertRaises(ObjectInstanceNotKnown):
                publisher.getObjectInstanceName(object_instance)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
        finally:
            if receiver_joined:
                if receiver_class is not None and receiver_attributes is not None:
                    try:
                        receiver.unsubscribeObjectClassAttributes(
                            receiver_class, receiver_attributes
                        )
                    except Exception:
                        pass
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if receiver_connected:
                receiver.disconnect()
            if publisher_connected:
                publisher.disconnect()
            receiver._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_object_deletion_retraction_reconstitutes_delivered_object(
        self,
    ) -> None:
        """Reconstitute a delivered C++ deletion and suppress queued fanout."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def removeObjectInstance(
                self,
                objectInstance: ObjectInstanceHandle,
                userSuppliedTag: bytes,
                producingFederate: FederateHandle,
                time: HLAinteger64Time | None = None,
                sentOrderType: OrderType | None = None,
                receivedOrderType: OrderType | None = None,
                retraction: MessageRetractionHandle | None = None,
            ) -> None:
                super().removeObjectInstance(
                    objectInstance,
                    userSuppliedTag,
                    producingFederate,
                    time,
                    sentOrderType,
                    receivedOrderType,
                    retraction,
                )
                if time is not None:
                    self.order.append("remove")

            def requestRetraction(self, retraction: MessageRetractionHandle) -> None:
                super().requestRetraction(retraction)
                self.order.append("request-retraction")

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        federation_name = f"python-jni-timestamped-delete-retraction-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        immediate = self.factory.getRtiAmbassador()
        constrained = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        immediate_callbacks = OrderedCallbacks()
        constrained_callbacks = OrderedCallbacks()
        publisher_connected = immediate_connected = constrained_connected = False
        publisher_joined = immediate_joined = constrained_joined = created = False
        immediate_class: ObjectClassHandle | None = None
        immediate_attributes: AttributeHandleSet | None = None
        constrained_class: ObjectClassHandle | None = None
        constrained_attributes: AttributeHandleSet | None = None

        def pump(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                immediate.evokeCallback(0.0)
                constrained.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            immediate.connect(immediate_callbacks, CallbackModel.HLA_EVOKED)
            immediate_connected = True
            constrained.connect(constrained_callbacks, CallbackModel.HLA_EVOKED)
            constrained_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher_handle = publisher.joinFederationExecution(
                "jni-timestamped-delete-retraction-publisher", federation_name
            )
            publisher_joined = True
            immediate.joinFederationExecution(
                "jni-timestamped-delete-retraction-immediate", federation_name
            )
            immediate_joined = True
            constrained.joinFederationExecution(
                "jni-timestamped-delete-retraction-constrained", federation_name
            )
            constrained_joined = True

            class_name = HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            object_class = publisher.getObjectClassHandle(class_name)
            immediate_class = immediate.getObjectClassHandle(class_name)
            constrained_class = constrained.getObjectClassHandle(class_name)
            reliable = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            best_effort = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            immediate_reliable = immediate.getAttributeHandle(
                immediate_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            immediate_best_effort = immediate.getAttributeHandle(
                immediate_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            constrained_reliable = constrained.getAttributeHandle(
                constrained_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            constrained_best_effort = constrained.getAttributeHandle(
                constrained_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            attributes = AttributeHandleSet([reliable, best_effort])
            immediate_attributes = AttributeHandleSet(
                [immediate_reliable, immediate_best_effort]
            )
            constrained_attributes = AttributeHandleSet(
                [constrained_reliable, constrained_best_effort]
            )
            publisher.publishObjectClassAttributes(object_class, attributes)
            immediate.subscribeObjectClassAttributes(
                immediate_class, immediate_attributes
            )
            constrained.subscribeObjectClassAttributes(
                constrained_class, constrained_attributes
            )

            object_instance = publisher.registerObjectInstance(object_class)
            pump()
            self.assertEqual(len(immediate_callbacks.discovered_objects), 1)
            self.assertEqual(len(constrained_callbacks.discovered_objects), 1)
            object_name = publisher.getObjectInstanceName(object_instance)
            self.assertEqual(
                immediate.getObjectInstanceHandle(object_name), object_instance
            )

            # Move one attribute to the immediate recipient so reconstitution
            # proves that the deletion snapshot restores split ownership.
            immediate_owned = AttributeHandleSet([immediate_best_effort])
            immediate.publishObjectClassAttributes(immediate_class, immediate_owned)
            immediate.attributeOwnershipAcquisitionIfAvailable(
                object_instance, immediate_owned, b"retraction-ownership"
            )
            divested = publisher.attributeOwnershipDivestitureIfWanted(
                object_instance, immediate_owned, b"retraction-ownership"
            )
            self.assertEqual(divested, immediate_owned)
            pump()
            self.assertFalse(
                publisher.isAttributeOwnedByFederate(object_instance, best_effort)
            )
            self.assertTrue(
                immediate.isAttributeOwnedByFederate(
                    object_instance, immediate_best_effort
                )
            )

            constrained.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()

            tag = bytes((0xD5, 0x37, 0x2B))
            retraction = publisher.deleteObjectInstanceWithTime(
                object_instance,
                publisher.getTimeFactory().makeLogicalTime(6),
                tag,
            )
            self.assertTrue(retraction.isValid())
            immediate.evokeCallback(0.0)
            self.assertEqual(len(immediate_callbacks.timestamped_removals), 1)
            self.assertEqual(constrained_callbacks.timestamped_removals, [])
            removal = immediate_callbacks.timestamped_removals[0]
            self.assertEqual(removal[0], object_instance)
            self.assertEqual(removal[1], tag)
            self.assertEqual(removal[2], publisher_handle)
            self.assertEqual(removal[3].getTime(), 6)
            self.assertEqual(removal[4], OrderType.TIMESTAMP)
            self.assertEqual(removal[5], OrderType.RECEIVE)
            self.assertEqual(removal[6], retraction)
            self.assertEqual(immediate_callbacks.order, ["remove"])
            with self.assertRaises(ObjectInstanceNotKnown):
                publisher.getObjectInstanceName(object_instance)
            with self.assertRaises(ObjectInstanceNotKnown):
                immediate.getObjectInstanceHandle(object_name)

            constrained.timeAdvanceRequest(
                constrained.getTimeFactory().makeLogicalTime(6)
            )
            publisher.retract(retraction)
            immediate.evokeCallback(0.0)
            self.assertEqual(immediate_callbacks.retraction_requests, [retraction])
            self.assertEqual(
                immediate_callbacks.order, ["remove", "request-retraction"]
            )
            self.assertEqual(immediate_callbacks.retraction_requests[0], retraction)
            self.assertEqual(
                publisher.getObjectInstanceName(object_instance), object_name
            )
            self.assertEqual(
                immediate.getObjectInstanceHandle(object_name), object_instance
            )
            self.assertEqual(
                constrained.getObjectInstanceHandle(object_name), object_instance
            )
            self.assertTrue(
                publisher.isAttributeOwnedByFederate(object_instance, reliable)
            )
            self.assertFalse(
                publisher.isAttributeOwnedByFederate(object_instance, best_effort)
            )
            self.assertTrue(
                immediate.isAttributeOwnedByFederate(
                    object_instance, immediate_best_effort
                )
            )

            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(len(constrained_callbacks.time_advance_grants), 1)
            self.assertEqual(constrained_callbacks.time_advance_grants[0].getTime(), 6)
            self.assertEqual(constrained_callbacks.timestamped_removals, [])
            self.assertEqual(constrained_callbacks.retraction_requests, [])
        finally:
            if constrained_joined:
                try:
                    constrained.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if immediate_joined:
                try:
                    immediate.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if constrained_connected:
                try:
                    constrained.disconnect()
                except Exception:
                    pass
            if immediate_connected:
                try:
                    immediate.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            constrained._implementation.close()
            immediate._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_object_deletion_without_recipient_reconstitutes_on_retract(
        self,
    ) -> None:
        """Reconstitute a no-fanout deletion while preserving the C++ ledger."""
        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        federation_name = f"python-jni-timestamped-delete-no-fanout-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = joined = created = False
        try:
            publisher.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-timestamped-delete-no-fanout", federation_name
            )
            joined = True

            object_class = publisher.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            reliable = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            attributes = AttributeHandleSet([reliable])
            publisher.publishObjectClassAttributes(object_class, attributes)
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            publisher.evokeCallback(0.0)

            boundary_object = publisher.registerObjectInstance(object_class)
            boundary_retraction = publisher.deleteObjectInstanceWithTime(
                boundary_object,
                publisher.getTimeFactory().makeLogicalTime(5),
                b"D6-boundary",
            )
            self.assertTrue(boundary_retraction.isValid())
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(boundary_retraction)

            object_instance = publisher.registerObjectInstance(object_class)
            object_name = publisher.getObjectInstanceName(object_instance)
            retraction = publisher.deleteObjectInstanceWithTime(
                object_instance,
                publisher.getTimeFactory().makeLogicalTime(6),
                b"D6-reconstitute",
            )
            self.assertTrue(retraction.isValid())
            with self.assertRaises(ObjectInstanceNotKnown):
                publisher.getObjectInstanceHandle(object_name)
            publisher.retract(retraction)
            self.assertEqual(
                publisher.getObjectInstanceHandle(object_name), object_instance
            )
            self.assertTrue(
                publisher.isAttributeOwnedByFederate(object_instance, reliable)
            )
            self.assertEqual(callbacks.removed_objects, [])
            self.assertEqual(callbacks.timestamped_removals, [])
            self.assertEqual(callbacks.retraction_requests, [])
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
        finally:
            if joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_object_deletion_reconstitutes_only_joined_owners(
        self,
    ) -> None:
        """Restore deletion state only for ownership held by joined members."""
        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        federation_name = f"python-jni-timestamped-delete-joined-owner-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        former_owner = self.factory.getRtiAmbassador()
        constrained = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        former_callbacks = _JniCallbacks()
        constrained_callbacks = _JniCallbacks()
        publisher_connected = former_connected = constrained_connected = False
        publisher_joined = former_joined = constrained_joined = created = False

        def pump(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                former_owner.evokeCallback(0.0)
                constrained.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            former_owner.connect(former_callbacks, CallbackModel.HLA_EVOKED)
            former_connected = True
            constrained.connect(constrained_callbacks, CallbackModel.HLA_EVOKED)
            constrained_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-timestamped-delete-joined-owner-publisher", federation_name
            )
            publisher_joined = True
            former_owner.joinFederationExecution(
                "jni-timestamped-delete-joined-owner-former", federation_name
            )
            former_joined = True
            constrained.joinFederationExecution(
                "jni-timestamped-delete-joined-owner-constrained", federation_name
            )
            constrained_joined = True

            class_name = HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            publisher_class = publisher.getObjectClassHandle(class_name)
            former_class = former_owner.getObjectClassHandle(class_name)
            constrained_class = constrained.getObjectClassHandle(class_name)
            reliable = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            best_effort = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            former_reliable = former_owner.getAttributeHandle(
                former_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            former_best_effort = former_owner.getAttributeHandle(
                former_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            constrained_reliable = constrained.getAttributeHandle(
                constrained_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            constrained_best_effort = constrained.getAttributeHandle(
                constrained_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            publisher_attributes = AttributeHandleSet([reliable, best_effort])
            former_attributes = AttributeHandleSet(
                [former_reliable, former_best_effort]
            )
            constrained_attributes = AttributeHandleSet(
                [constrained_reliable, constrained_best_effort]
            )
            publisher.publishObjectClassAttributes(
                publisher_class, publisher_attributes
            )
            former_owner.subscribeObjectClassAttributes(former_class, former_attributes)
            constrained.subscribeObjectClassAttributes(
                constrained_class, constrained_attributes
            )

            object_instance = publisher.registerObjectInstance(publisher_class)
            pump()
            object_name = publisher.getObjectInstanceName(object_instance)
            self.assertEqual(
                former_owner.getObjectInstanceHandle(object_name), object_instance
            )
            self.assertEqual(
                constrained.getObjectInstanceHandle(object_name), object_instance
            )

            # Transfer BestEffortBase to the member that will later resign.
            former_owned = AttributeHandleSet([former_best_effort])
            former_owner.publishObjectClassAttributes(former_class, former_owned)
            former_owner.attributeOwnershipAcquisitionIfAvailable(
                object_instance, former_owned, b"joined-owner-transfer"
            )
            divested = publisher.attributeOwnershipDivestitureIfWanted(
                object_instance,
                AttributeHandleSet([best_effort]),
                b"joined-owner-transfer",
            )
            self.assertEqual(divested, AttributeHandleSet([best_effort]))
            pump()
            self.assertTrue(
                former_owner.isAttributeOwnedByFederate(
                    object_instance, former_best_effort
                )
            )

            constrained.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()

            retraction = publisher.deleteObjectInstanceWithTime(
                object_instance,
                publisher.getTimeFactory().makeLogicalTime(6),
                b"D7-joined-owner",
            )
            self.assertTrue(retraction.isValid())
            former_owner.evokeCallback(0.0)
            self.assertEqual(len(former_callbacks.timestamped_removals), 1)
            former_owner.resignFederationExecution(
                ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
            )
            former_joined = False

            constrained.timeAdvanceRequest(
                constrained.getTimeFactory().makeLogicalTime(6)
            )
            publisher.retract(retraction)
            self.assertEqual(former_callbacks.retraction_requests, [])
            self.assertEqual(
                publisher.getObjectInstanceName(object_instance), object_name
            )
            self.assertEqual(
                constrained.getObjectInstanceHandle(object_name), object_instance
            )
            self.assertTrue(
                publisher.isAttributeOwnedByFederate(object_instance, reliable)
            )
            self.assertFalse(
                publisher.isAttributeOwnedByFederate(object_instance, best_effort)
            )

            publisher.queryAttributeOwnership(
                object_instance, AttributeHandleSet([best_effort])
            )
            for _ in range(20):
                publisher.evokeCallback(0.0)
                if publisher_callbacks.ownership_not_owned:
                    break
            self.assertIn(
                (object_instance, AttributeHandleSet([best_effort])),
                publisher_callbacks.ownership_not_owned,
            )

            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(constrained_callbacks.timestamped_removals, [])
            self.assertEqual(constrained_callbacks.retraction_requests, [])
        finally:
            if constrained_joined:
                try:
                    constrained.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if former_joined:
                try:
                    former_owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, connected in (
                (constrained, constrained_connected),
                (former_owner, former_connected),
                (publisher, publisher_connected),
            ):
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
            constrained._implementation.close()
            former_owner._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_object_deletion_delivers_before_time_grants(
        self,
    ) -> None:
        """Fan out one C++ timestamped removal through all Java time requests."""

        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def removeObjectInstance(
                self,
                objectInstance: ObjectInstanceHandle,
                userSuppliedTag: bytes,
                producingFederate: FederateHandle,
                time: HLAinteger64Time | None = None,
                sentOrderType: OrderType | None = None,
                receivedOrderType: OrderType | None = None,
                retraction: MessageRetractionHandle | None = None,
            ) -> None:
                super().removeObjectInstance(
                    objectInstance,
                    userSuppliedTag,
                    producingFederate,
                    time,
                    sentOrderType,
                    receivedOrderType,
                    retraction,
                )
                if time is not None:
                    self.order.append("remove")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                super().flushQueueGrant(time, optimisticTime)
                self.order.append("flush-grant")

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        federation_name = f"python-jni-timestamped-object-deletion-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        fqr = self.factory.getRtiAmbassador()
        tara = self.factory.getRtiAmbassador()
        nmra = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        fqr_callbacks = OrderedCallbacks()
        tara_callbacks = OrderedCallbacks()
        nmra_callbacks = OrderedCallbacks()
        receivers = (
            (fqr, fqr_callbacks, "jni-timestamped-delete-fqr"),
            (tara, tara_callbacks, "jni-timestamped-delete-tara"),
            (nmra, nmra_callbacks, "jni-timestamped-delete-nmra"),
        )
        created = publisher_joined = False
        receiver_joined = {name: False for _, _, name in receivers}

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                for ambassador, _, _ in receivers:
                    ambassador.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            for ambassador, callbacks, _ in receivers:
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-timestamped-delete-publisher", federation_name
            )
            publisher_joined = True
            for ambassador, _, name in receivers:
                ambassador.joinFederationExecution(name, federation_name)
                receiver_joined[name] = True

            object_class = publisher.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            reliable = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            best_effort = publisher.getAttributeHandle(
                object_class, HLA_FIXTURES.BEST_EFFORT_BASE
            )
            attributes = AttributeHandleSet([reliable, best_effort])
            publisher.publishObjectClassAttributes(object_class, attributes)
            publisher.changeDefaultAttributeOrderType(
                object_class, attributes, OrderType.TIMESTAMP
            )
            for ambassador, _, _ in receivers:
                receiver_class = ambassador.getObjectClassHandle(
                    HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
                )
                receiver_reliable = ambassador.getAttributeHandle(
                    receiver_class, HLA_FIXTURES.RELIABLE_BASE_A
                )
                receiver_best_effort = ambassador.getAttributeHandle(
                    receiver_class, HLA_FIXTURES.BEST_EFFORT_BASE
                )
                ambassador.subscribeObjectClassAttributes(
                    receiver_class,
                    AttributeHandleSet([receiver_reliable, receiver_best_effort]),
                )

            object_instance = publisher.registerObjectInstance(object_class)
            pump()
            for _, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.discovered_objects), 1)
                self.assertEqual(callbacks.discovered_objects[0][0], object_instance)

            for ambassador, _, _ in receivers:
                ambassador.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = bytes((0xD8, 0x61, 0x4E))
            retraction = publisher.deleteObjectInstanceWithTime(
                object_instance,
                publisher.getTimeFactory().makeLogicalTime(7),
                tag,
            )
            self.assertTrue(retraction.isValid())
            for _, callbacks, _ in receivers:
                self.assertEqual(callbacks.timestamped_removals, [])

            fqr.flushQueueRequest(fqr.getTimeFactory().makeLogicalTime(10))
            tara.timeAdvanceRequestAvailable(tara.getTimeFactory().makeLogicalTime(7))
            nmra.nextMessageRequestAvailable(nmra.getTimeFactory().makeLogicalTime(10))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(len(publisher_callbacks.time_advance_grants), 1)
            self.assertEqual(publisher_callbacks.time_advance_grants[0].getTime(), 2)

            for _, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.timestamped_removals), 1)
                removal = callbacks.timestamped_removals[0]
                self.assertEqual(removal[0], object_instance)
                self.assertEqual(removal[1], tag)
                self.assertEqual(removal[3].getTime(), 7)
                self.assertEqual(removal[4], OrderType.TIMESTAMP)
                self.assertEqual(removal[5], OrderType.TIMESTAMP)
                self.assertEqual(removal[6], retraction)
            self.assertEqual(fqr_callbacks.order, ["remove", "flush-grant"])
            self.assertEqual(tara_callbacks.order, ["remove", "grant"])
            self.assertEqual(nmra_callbacks.order, ["remove", "grant"])
            self.assertEqual(len(fqr_callbacks.flush_queue_grants), 1)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][0].getTime(), 7)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][1].getTime(), 7)
            self.assertEqual(len(tara_callbacks.time_advance_grants), 1)
            self.assertEqual(tara_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(len(nmra_callbacks.time_advance_grants), 1)
            self.assertEqual(nmra_callbacks.time_advance_grants[0].getTime(), 7)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
        finally:
            for ambassador, _, name in reversed(receivers):
                if receiver_joined[name]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, _, _ in receivers:
                ambassador.disconnect()
            publisher.disconnect()
            for ambassador, _, _ in receivers:
                ambassador._implementation.close()
            publisher._implementation.close()

