    def test_cpp_jni_java_jpype_timestamped_directed_resignation_drops_stale_recipient(
        self,
    ) -> None:
        """Drop a queued directed TSO for a recipient that resigns before grant."""
        object_consumer_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "directed-interaction-object-consumer-fom.xml"
        )
        interaction_provider_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "directed-interaction-interaction-provider-fom.xml"
        )
        federation_name = f"python-jni-timestamped-directed-resign-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        departing = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        departing_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        created = publisher_joined = False
        joined = {"departing": False, "survivor": False}

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                departing.evokeCallback(0.0)
                survivor.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            departing.connect(departing_callbacks, CallbackModel.HLA_EVOKED)
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name,
                [str(object_consumer_fom), str(interaction_provider_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            publisher.joinFederationExecution(
                "publisher",
                federation_name,
                federateName="jni-directed-resign-publisher",
            )
            publisher_joined = True
            departing.joinFederationExecution(
                "subscriber",
                federation_name,
                federateName="jni-directed-resign-departing",
            )
            joined["departing"] = True
            survivor.joinFederationExecution(
                "subscriber",
                federation_name,
                federateName="jni-directed-resign-survivor",
            )
            joined["survivor"] = True

            publisher_class = publisher.getObjectClassHandle(
                HLA_FOM.DIRECTED_FIXTURE_OBJECT
            )
            publisher_marker = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.DIRECTED_TARGET_MARKER
            )
            interaction = publisher.getInteractionClassHandle(
                HLA_FOM.DIRECTED_FIXTURE_INTERACTION
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_marker])
            )
            publisher.publishObjectClassDirectedInteractions(
                publisher_class, InteractionClassHandleSet([interaction])
            )
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)

            for ambassador in (departing, survivor):
                receiver_class = ambassador.getObjectClassHandle(
                    HLA_FOM.DIRECTED_FIXTURE_OBJECT
                )
                receiver_marker = ambassador.getAttributeHandle(
                    receiver_class, HLA_FIXTURES.DIRECTED_TARGET_MARKER
                )
                receiver_interaction = ambassador.getInteractionClassHandle(
                    HLA_FOM.DIRECTED_FIXTURE_INTERACTION
                )
                ambassador.subscribeObjectClassAttributes(
                    receiver_class, AttributeHandleSet([receiver_marker])
                )
                ambassador.subscribeObjectClassDirectedInteractionsUniversally(
                    receiver_class, InteractionClassHandleSet([receiver_interaction])
                )

            target = publisher.registerObjectInstance(publisher_class)
            pump()
            self.assertEqual(len(departing_callbacks.discovered_objects), 1)
            self.assertEqual(len(survivor_callbacks.discovered_objects), 1)

            departing.enableTimeConstrained()
            survivor.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = b"jni-directed-resignation-tso"
            retraction = publisher.sendDirectedInteractionWithTime(
                interaction,
                target,
                ParameterHandleValueMap(),
                publisher.getTimeFactory().makeLogicalTime(7),
                tag,
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(departing_callbacks.timestamped_directed_interactions, [])
            self.assertEqual(survivor_callbacks.timestamped_directed_interactions, [])

            # Resignation invalidates the departing member's queued delivery;
            # it must not be reconstructed by the Java callback layer later.
            departing.resignFederationExecution(ResignAction.NO_ACTION)
            joined["departing"] = False
            survivor.timeAdvanceRequest(survivor.getTimeFactory().makeLogicalTime(7))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump(24)

            self.assertEqual(departing_callbacks.timestamped_directed_interactions, [])
            self.assertEqual(
                len(survivor_callbacks.timestamped_directed_interactions), 1
            )
            delivered = survivor_callbacks.timestamped_directed_interactions[0]
            self.assertEqual(delivered[1], target)
            self.assertEqual(delivered[2], ParameterHandleValueMap())
            self.assertEqual(delivered[3], tag)
            self.assertEqual(delivered[6].getTime(), 7)
            self.assertEqual(delivered[7], OrderType.TIMESTAMP)
            self.assertEqual(delivered[8], OrderType.TIMESTAMP)
            self.assertEqual(delivered[9], retraction)

            # The surviving delivery consumed the retraction window at the
            # producer's requested-time-plus-lookahead boundary.  The
            # standard Java surface must therefore reject a later retract;
            # the handle remains observable on the callback, while the stale
            # departed-recipient queue stays silent.
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
            self.assertEqual(departing_callbacks.retraction_requests, [])
            self.assertEqual(survivor_callbacks.retraction_requests, [])
        finally:
            if joined["survivor"]:
                try:
                    survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if joined["departing"]:
                try:
                    departing.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            departing.disconnect()
            survivor.disconnect()
            publisher.disconnect()
            departing._implementation.close()
            survivor._implementation.close()
            publisher._implementation.close()

