        subject = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        subject_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        subject_connected = observer_connected = False
        subject_joined = observer_joined = created = False
        try:
            subject.connect(subject_callbacks, CallbackModel.HLA_EVOKED)
            subject_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_EVOKED)
            observer_connected = True
            subject.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            subject.joinFederationExecution(
                "mom-all-malformed-subject",
                federation_name,
                federateName="mom-all-malformed-subject",
            )
            subject_joined = True
            observer.joinFederationExecution(
                "mom-all-malformed-observer",
                federation_name,
                federateName="mom-all-malformed-observer",
            )
            observer_joined = True

            report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_MOM_EXCEPTION
            )
            report_parameters = {
                name: observer.getParameterHandle(report_class, name)
                for name in (
                    HLA_MOM.SERVICE,
                    HLA_MOM.EXCEPTION,
                    HLA_MOM.PARAMETER_ERROR,
                )
            }
            observer.subscribeInteractionClass(report_class)
            set_switches_class = subject.getInteractionClassHandle(
                HLA_MOM.SET_SWITCHES_FEDERATE
            )
            invalid_parameter = subject.getParameterHandle(
                set_switches_class, HLA_MOM.SERVICE_REPORTING
            )
            subject.setExceptionReportingSwitch(True)
            encoder = self.factory.getEncoderFactory()

            request_paths = [
                HLA_MOM.REQUEST_OBJECT_INSTANCES_UPDATED,
                HLA_MOM.REQUEST_OBJECT_INSTANCES_THAT_CAN_BE_DELETED,
                HLA_MOM.REQUEST_OBJECT_INSTANCES_REFLECTED,
                HLA_MOM.REQUEST_UPDATES_SENT,
                HLA_MOM.REQUEST_INTERACTIONS_SENT,
                HLA_MOM.REQUEST_DIRECTED_INTERACTIONS_SENT,
                HLA_MOM.REQUEST_INTERACTIONS_RECEIVED,
                HLA_MOM.REQUEST_DIRECTED_INTERACTIONS_RECEIVED,
                HLA_MOM.REQUEST_REFLECTIONS_RECEIVED,
                HLA_MOM.REQUEST_OBJECT_INSTANCE_INFORMATION,
                HLA_MOM.REQUEST_PUBLICATIONS,
                HLA_MOM.REQUEST_FOM_MODULE_DATA_FEDERATE,
                HLA_MOM.REQUEST_FOM_MODULE_DATA_FEDERATION,
                HLA_MOM.REQUEST_MIM_DATA,
                HLA_MOM.REQUEST_SYNCHRONIZATION_POINTS,
                HLA_MOM.REQUEST_SYNCHRONIZATION_POINT_STATUS,
                HLA_MOM.REQUEST_SUBSCRIPTIONS,
            ]
            invalid_payload = ParameterHandleValueMap(
                {invalid_parameter: encoder.createHLAboolean(True).toByteArray()}
            )
            for request_path in request_paths:
                with self.subTest(request_path=request_path):
                    request_class = subject.getInteractionClassHandle(request_path)
                    observer_callbacks.received_interactions.clear()
                    with self.assertRaises(InteractionParameterNotDefined):
                        subject.sendInteraction(request_class, invalid_payload, b"")
                    for _ in range(20):
                        observer.evokeCallback(0.0)
                        if observer_callbacks.received_interactions:
                            break
                    self.assertEqual(len(observer_callbacks.received_interactions), 1)
                    report = observer_callbacks.received_interactions[0]
                    self.assertEqual(report[0], report_class)
                    self.assertEqual(report[2], b"")
                    self.assertEqual(
                        report[3],
                        observer.getTransportationTypeHandle(HLA_MOM.RELIABLE),
                    )
                    self.assertFalse(any(report[4].encodedValue[4:]))
                    values = dict(report[1])
                    self.assertEqual(set(values), set(report_parameters.values()))
                    service = encoder.createHLAunicodeString()
                    service.decode(values[report_parameters[HLA_MOM.SERVICE]])
                    exception = encoder.createHLAunicodeString()
                    exception.decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                    parameter_error = encoder.createHLAboolean()
                    parameter_error.decode(
                        values[report_parameters[HLA_MOM.PARAMETER_ERROR]]
                    )
                    self.assertEqual(service.getValue(), request_path)
                    self.assertIn(
                        "InteractionParameterNotDefined", exception.getValue()
                    )
                    self.assertTrue(parameter_error.getValue())
        finally:
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if subject_joined:
                try:
                    subject.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    subject.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if subject_connected:
                try:
                    subject.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            subject._implementation.close()

