    def test_cpp_jni_java_jpype_mom_federation_content_request_reports(self) -> None:
        """Carry federation-scoped FOM and MIM reports through Java."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-mom-federation-content-{uuid4()}"
        subject = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        subject_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        subject_connected = observer_connected = False
        subject_joined = observer_joined = created = False
        try:
            subject.connect(subject_callbacks, CallbackModel.HLA_EVOKED)
            subject_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_EVOKED)
            observer_connected = True
            subject.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            subject.joinFederationExecution(
                "mom-federation-content-subject",
                federation_name,
                federateName="mom-federation-content-subject",
            )
            subject_joined = True
            observer.joinFederationExecution(
                "mom-federation-content-observer",
                federation_name,
                federateName="mom-federation-content-observer",
            )
            observer_joined = True

            fom_request_class = observer.getInteractionClassHandle(
                HLA_MOM.REQUEST_FOM_MODULE_DATA_FEDERATION
            )
            fom_request_indicator = observer.getParameterHandle(
                fom_request_class, HLA_MOM.FOM_MODULE_INDICATOR
            )
            fom_report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_FOM_MODULE_DATA_FEDERATION
            )
            fom_report_indicator = observer.getParameterHandle(
                fom_report_class, HLA_MOM.FOM_MODULE_INDICATOR
            )
            fom_report_data = observer.getParameterHandle(
                fom_report_class, HLA_MOM.FOM_MODULE_DATA
            )
            mim_request_class = observer.getInteractionClassHandle(
                HLA_MOM.REQUEST_MIM_DATA
            )
            mim_report_class = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_MIM_DATA
            )
            mim_report_data = observer.getParameterHandle(
                mim_report_class, HLA_MOM.MIM_DATA
            )
            observer.subscribeInteractionClass(fom_report_class)
            observer.subscribeInteractionClass(mim_report_class)
            for _ in range(20):
                observer.evokeCallback(0.0)

            encoder = self.factory.getEncoderFactory()

            def request_and_get(expected_class):
                observer_callbacks.received_interactions.clear()
                if expected_class == fom_report_class:
                    subject.sendInteraction(
                        fom_request_class,
                        ParameterHandleValueMap(
                            {fom_request_indicator: b"\x00\x00\x00\x00"}
                        ),
                        b"",
                    )
                else:
                    subject.sendInteraction(
                        mim_request_class, ParameterHandleValueMap(), b""
                    )
                for _ in range(20):
                    observer.evokeCallback(0.0)
                self.assertEqual(len(observer_callbacks.received_interactions), 1)
                report = observer_callbacks.received_interactions[0]
                self.assertEqual(report[0], expected_class)
                self.assertEqual(report[2], b"")
                self.assertEqual(
                    report[3], observer.getTransportationTypeHandle(HLA_MOM.RELIABLE)
                )
                self.assertFalse(any(report[4].encodedValue[4:]))
                return dict(report[1])

            fom_values = request_and_get(fom_report_class)
            self.assertEqual(set(fom_values), {fom_report_indicator, fom_report_data})
            indicator = encoder.createHLAinteger32BE()
            indicator.decode(fom_values[fom_report_indicator])
            self.assertEqual(indicator.getValue(), 0)
            fom_data = encoder.createHLAunicodeString()
            fom_data.decode(fom_values[fom_report_data])
            self.assertIn("<objectModel", fom_data.getValue())
            self.assertIn("Restaurant FOM Module", fom_data.getValue())

            mim_values = request_and_get(mim_report_class)
            self.assertEqual(set(mim_values), {mim_report_data})
            mim_data = encoder.createHLAunicodeString()
            mim_data.decode(mim_values[mim_report_data])
            # The standard MIM XML stores the interaction's leaf name in its
            # declarations, not the fully qualified runtime path used for
            # handle lookup.  Keep the assertion edition/provider neutral.
            self.assertIn(HLA_MOM.REQUEST_MIM_DATA_NAME, mim_data.getValue())
            self.assertIn("Standard MOM", mim_data.getValue())
        finally:
            if subject_joined:
                try:
                    subject.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    observer.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if subject_connected:
                try:
                    subject.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            subject._implementation.close()

    def test_cpp_jni_java_jpype_mom_synchronization_request_reports(self) -> None:
        """Carry synchronization-point list and status reports through Java."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-mom-synchronization-{uuid4()}"
        subject = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        subject_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        subject_connected = observer_connected = False
        subject_joined = observer_joined = created = False
        try:
            subject.connect(subject_callbacks, CallbackModel.HLA_EVOKED)
            subject_connected = True
            observer.connect(observer_callbacks, CallbackModel.HLA_EVOKED)
            observer_connected = True
            subject.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            subject_federate = subject.joinFederationExecution(
                "mom-sync-subject", federation_name, federateName="mom-sync-subject"
            )
            subject_joined = True
            observer_federate = observer.joinFederationExecution(
                "mom-sync-observer", federation_name, federateName="mom-sync-observer"
            )
            observer_joined = True
            label = "mom-sync-report"
            subject.registerFederationSynchronizationPoint(label, b"")
            for _ in range(20):
                subject.evokeCallback(0.0)
                observer.evokeCallback(0.0)

            points_request = subject.getInteractionClassHandle(
                HLA_MOM.REQUEST_SYNCHRONIZATION_POINTS
            )
            points_report = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SYNCHRONIZATION_POINTS
            )
            points_parameter = observer.getParameterHandle(
                points_report, HLA_MOM.SYNC_POINTS
            )
            status_request = subject.getInteractionClassHandle(
                HLA_MOM.REQUEST_SYNCHRONIZATION_POINT_STATUS
            )
            status_request_parameter = subject.getParameterHandle(
                status_request, HLA_MOM.SYNC_POINT_NAME
            )
            status_report = observer.getInteractionClassHandle(
                HLA_MOM.REPORT_SYNCHRONIZATION_POINT_STATUS
            )
            status_name_parameter = observer.getParameterHandle(
                status_report, HLA_MOM.SYNC_POINT_NAME
            )
            status_federates_parameter = observer.getParameterHandle(
                status_report, HLA_MOM.SYNC_POINT_FEDERATES
            )
            observer.subscribeInteractionClass(points_report)
            observer.subscribeInteractionClass(status_report)
            for _ in range(20):
                observer.evokeCallback(0.0)

            encoder = self.factory.getEncoderFactory()

            class _UnicodeStringFactory(DataElementFactory):
                def createElement(self, index: int):
                    return encoder.createHLAunicodeString()

            class _StatusRecordFactory(DataElementFactory):
                def createElement(self, index: int):
                    record = encoder.createHLAfixedRecord()
                    record.appendElement(
                        encoder.createHLAvariableArray(_OctetElementFactory(encoder))
                    )
                    record.appendElement(encoder.createHLAinteger32BE())
                    return record

            def decode_points(payload: bytes) -> list[str]:
                values = encoder.createHLAvariableArray(_UnicodeStringFactory())
                values.decode(payload)
                return [values.get(index).getValue() for index in range(values.size())]

            def decode_statuses(payload: bytes) -> dict[bytes, int]:
                values = encoder.createHLAvariableArray(_StatusRecordFactory())
                values.decode(payload)
                decoded: dict[bytes, int] = {}
                for index in range(values.size()):
                    record = values.get(index)
                    decoded[bytes(record.get(0).toByteArray())] = record.get(
                        1
                    ).getValue()
                return decoded

            def request_points() -> list[str]:
                observer_callbacks.received_interactions.clear()
                subject.sendInteraction(points_request, ParameterHandleValueMap(), b"")
                for _ in range(20):
                    observer.evokeCallback(0.0)
                self.assertEqual(len(observer_callbacks.received_interactions), 1)
                report = observer_callbacks.received_interactions[0]
                self.assertEqual(report[0], points_report)
                self.assertEqual(report[2], b"")
                self.assertEqual(
                    report[3], observer.getTransportationTypeHandle(HLA_MOM.RELIABLE)
                )
                self.assertFalse(any(report[4].encodedValue[4:]))
                return decode_points(dict(report[1])[points_parameter])

            def request_status(name: str) -> dict[bytes, int]:
                observer_callbacks.received_interactions.clear()
                subject.sendInteraction(
                    status_request,
                    ParameterHandleValueMap(
                        {
                            status_request_parameter: encoder.createHLAunicodeString(
                                name
                            ).toByteArray()
                        }
                    ),
                    b"",
                )
                for _ in range(20):
                    observer.evokeCallback(0.0)
                self.assertEqual(len(observer_callbacks.received_interactions), 1)
                report = observer_callbacks.received_interactions[0]
                self.assertEqual(report[0], status_report)
                values = dict(report[1])
                name_value = encoder.createHLAunicodeString()
                name_value.decode(values[status_name_parameter])
                self.assertEqual(name_value.getValue(), name)
                return decode_statuses(values[status_federates_parameter])

            self.assertEqual(request_points(), [label])
            before = request_status(label)
            self.assertEqual(
                before,
                {
                    bytes(subject_federate.encodedValue): 2,
                    bytes(observer_federate.encodedValue): 2,
                },
            )
            subject.synchronizationPointAchieved(label)
            for _ in range(20):
                subject.evokeCallback(0.0)
                observer.evokeCallback(0.0)
            after = request_status(label)
            self.assertEqual(after[bytes(subject_federate.encodedValue)], 3)
            self.assertEqual(after[bytes(observer_federate.encodedValue)], 2)
            self.assertEqual(request_status("missing-sync-report"), {})
            observer.synchronizationPointAchieved(label)
            for _ in range(20):
                subject.evokeCallback(0.0)
                observer.evokeCallback(0.0)
            self.assertEqual(request_points(), [])
        finally:
            if subject_joined:
                try:
                    subject.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    observer.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if observer_connected:
                try:
                    observer.disconnect()
                except Exception:
                    pass
            if subject_connected:
                try:
                    subject.disconnect()
                except Exception:
                    pass
            observer._implementation.close()
            subject._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_exception_matrix(self) -> None:
        """Preserve typed regional-object registration and association errors."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-object-errors-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        owner_connected = peer_connected = False
        owner_joined = peer_joined = created = False
        object_instance: ObjectInstanceHandle | None = None
        owner_region: RegionHandle | None = None
        peer_region: RegionHandle | None = None
        owner_uncommitted: RegionHandle | None = None
        owner_wrong_context: RegionHandle | None = None
        peer_uncommitted: RegionHandle | None = None
        peer_wrong_context: RegionHandle | None = None
        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-regional-object-errors-owner", federation_name
            )
            owner_joined = True
            peer.joinFederationExecution(
                "jni-regional-object-errors-peer", federation_name
            )
            peer_joined = True

            report_class = peer.getInteractionClassHandle(HLA_MOM.REPORT_EXCEPTION)
            report_parameters = {
                name: peer.getParameterHandle(report_class, name)
                for name in (HLA_MOM.SERVICE, HLA_MOM.EXCEPTION)
            }
            peer.subscribeInteractionClass(report_class)
            owner.setExceptionReportingSwitch(True)
            peer.setExceptionReportingSwitch(True)
            encoder = self.factory.getEncoderFactory()

            def report_at(index: int, service_name: str, exception_name: str) -> None:
                for _ in range(20):
                    peer.evokeCallback(0.0)
                    if len(peer_callbacks.received_interactions) > index:
                        break
                self.assertEqual(len(peer_callbacks.received_interactions), index + 1)
                report = peer_callbacks.received_interactions[index]
                self.assertEqual(report[0], report_class)
                values = dict(report[1])
                service = (
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue()
                )
                exception = (
                    encoder.createHLAunicodeString()
                    .decode(values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue()
                )
                self.assertEqual(service, service_name)
                self.assertTrue(exception.startswith(exception_name), exception)

            owner_class = owner.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            peer_class = peer.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            owner_attribute = owner.getAttributeHandle(owner_class, HLA_FIXTURES.FLAVOR)
            peer_attribute = peer.getAttributeHandle(peer_class, HLA_FIXTURES.FLAVOR)
            owner_dimension = owner.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            peer_dimension = peer.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            # ServerId belongs to an unrelated object-class branch, unlike
            # BarQuantity which is inherited by the Soda class through Drink.
            owner_bar_dimension = owner.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            peer_bar_dimension = peer.getDimensionHandle(HLA_FIXTURES.SERVER_ID)
            owner.publishObjectClassAttributes(
                owner_class, AttributeHandleSet([owner_attribute])
            )

            owner_region = owner.createRegion(DimensionHandleSet([owner_dimension]))
            peer_region = peer.createRegion(DimensionHandleSet([peer_dimension]))
            owner.setRangeBounds(owner_region, owner_dimension, RangeBounds(0, 1))
            peer.setRangeBounds(peer_region, peer_dimension, RangeBounds(0, 1))
            owner.commitRegionModifications(RegionHandleSet([owner_region]))
            peer.commitRegionModifications(RegionHandleSet([peer_region]))

            owner_uncommitted = owner.createRegion(
                DimensionHandleSet([owner_dimension])
            )
            owner_wrong_context = owner.createRegion(
                DimensionHandleSet([owner_bar_dimension])
            )
            owner.setRangeBounds(
                owner_wrong_context, owner_bar_dimension, RangeBounds(0, 10)
            )
            owner.commitRegionModifications(RegionHandleSet([owner_wrong_context]))
            peer_uncommitted = peer.createRegion(DimensionHandleSet([peer_dimension]))
            peer_wrong_context = peer.createRegion(
                DimensionHandleSet([peer_bar_dimension])
            )
            peer.setRangeBounds(
                peer_wrong_context, peer_bar_dimension, RangeBounds(0, 10)
            )
            peer.commitRegionModifications(RegionHandleSet([peer_wrong_context]))

            def pair_list(
                ambassador: RTIambassador,
                attribute: AttributeHandle,
                region: RegionHandle,
            ) -> AttributeSetRegionSetPairList:
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([attribute]), RegionHandleSet([region])
                    )
                )
                return pairs

            owner_foreign_pairs = pair_list(owner, owner_attribute, peer_region)
            owner_uncommitted_pairs = pair_list(
                owner, owner_attribute, owner_uncommitted
            )
            owner_wrong_context_pairs = pair_list(
                owner, owner_attribute, owner_wrong_context
            )
            owner_valid_pairs = pair_list(owner, owner_attribute, owner_region)

            with self.assertRaises(RegionNotCreatedByThisFederate):
                owner.registerObjectInstanceWithRegions(
                    owner_class, owner_foreign_pairs
                )
            report_at(
                0,
                "Register Object Instance With Regions",
                "RegionNotCreatedByThisFederate",
            )
            with self.assertRaises(InvalidRegion):
                owner.registerObjectInstanceWithRegions(
                    owner_class, owner_uncommitted_pairs
                )
            report_at(1, "Register Object Instance With Regions", "InvalidRegion")
            with self.assertRaises(InvalidRegionContext):
                owner.registerObjectInstanceWithRegions(
                    owner_class, owner_wrong_context_pairs
                )
            report_at(
                2,
                "Register Object Instance With Regions",
                "InvalidRegionContext",
            )

            # The official pair-list carrier is accepted for a valid
            # registration, after which the association service must retain
            # the same C++ validation vocabulary.
            object_instance = owner.registerObjectInstanceWithRegions(
                owner_class, owner_valid_pairs
            )
            unknown_object_encoding = bytearray(object_instance.encodedValue)
            unknown_object_encoding[-1] = 0x7F
            unknown_object_instance = owner.getObjectInstanceHandleFactory().decode(
                bytes(unknown_object_encoding)
            )
            with self.assertRaises(RegionNotCreatedByThisFederate):
                owner.associateRegionsForUpdates(object_instance, owner_foreign_pairs)
            report_at(
                3,
                "Associate Regions For Updates",
                "RegionNotCreatedByThisFederate",
            )
            with self.assertRaises(InvalidRegion):
                owner.associateRegionsForUpdates(
                    object_instance, owner_uncommitted_pairs
                )
            report_at(4, "Associate Regions For Updates", "InvalidRegion")
            with self.assertRaises(InvalidRegionContext):
                owner.associateRegionsForUpdates(
                    object_instance, owner_wrong_context_pairs
                )
            report_at(5, "Associate Regions For Updates", "InvalidRegionContext")

            with self.assertRaises(RegionNotCreatedByThisFederate):
                owner.unassociateRegionsForUpdates(object_instance, owner_foreign_pairs)
            report_at(
                6,
                "Unassociate Regions For Updates",
                "RegionNotCreatedByThisFederate",
            )
            with self.assertRaises(ObjectInstanceNotKnown):
                owner.unassociateRegionsForUpdates(
                    unknown_object_instance, owner_uncommitted_pairs
                )
            report_at(7, "Unassociate Regions For Updates", "ObjectInstanceNotKnown")

            peer_foreign_pairs = pair_list(peer, peer_attribute, owner_region)
            peer_uncommitted_pairs = pair_list(peer, peer_attribute, peer_uncommitted)
            peer_wrong_context_pairs = pair_list(
                peer, peer_attribute, peer_wrong_context
            )
            with self.assertRaises(RegionNotCreatedByThisFederate):
                peer.subscribeObjectClassAttributesWithRegions(
                    peer_class, peer_foreign_pairs
                )
            report_at(
                8,
                "Subscribe Object Class Attributes With Regions",
                "RegionNotCreatedByThisFederate",
            )
            with self.assertRaises(InvalidRegion):
                peer.subscribeObjectClassAttributesWithRegions(
                    peer_class, peer_uncommitted_pairs
                )
            report_at(
                9,
                "Subscribe Object Class Attributes With Regions",
                "InvalidRegion",
            )
            with self.assertRaises(InvalidRegionContext):
                peer.subscribeObjectClassAttributesWithRegions(
                    peer_class, peer_wrong_context_pairs
                )
            report_at(
                10,
                "Subscribe Object Class Attributes With Regions",
                "InvalidRegionContext",
            )

            with self.assertRaises(RegionNotCreatedByThisFederate):
                peer.unsubscribeObjectClassAttributesWithRegions(
                    peer_class, peer_foreign_pairs
                )
            report_at(
                11,
                "Unsubscribe Object Class Attributes With Regions",
                "RegionNotCreatedByThisFederate",
            )
            unknown_region_encoding = bytearray(peer_region.encodedValue)
            unknown_region_encoding[-1] = 0x7F
            unknown_region = peer.getRegionHandleFactory().decode(
                bytes(unknown_region_encoding)
            )
            unknown_region_pairs = pair_list(peer, peer_attribute, unknown_region)
            with self.assertRaises(InvalidRegion):
                peer.unsubscribeObjectClassAttributesWithRegions(
                    peer_class, unknown_region_pairs
                )
            report_at(
                12,
                "Unsubscribe Object Class Attributes With Regions",
                "InvalidRegion",
            )
        finally:
            if object_instance is not None and owner_joined:
                try:
                    owner.deleteObjectInstance(object_instance)
                except Exception:
                    pass
            for ambassador, region in (
                (owner, owner_wrong_context),
                (owner, owner_uncommitted),
                (owner, owner_region),
                (peer, peer_wrong_context),
                (peer, peer_uncommitted),
                (peer, peer_region),
            ):
                if region is not None:
                    try:
                        ambassador.deleteRegion(region)
                    except Exception:
                        pass
            if peer_joined:
                try:
                    peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            peer._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_auto_provide_after_discovery(self) -> None:
        """Route C++ automatic provision through the standard Java callback."""
        object_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        switch_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-nrg-enabled-fom.xml"
        )
        federation_name = f"python-jni-auto-provide-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = False
        owner_joined = requester_joined = created = False
        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            # This is the standard Java String[] FOM-module overload.  The
            # provider builds the carrier; C++ remains the catalog owner.
            owner.createFederationExecution(
                federation_name,
                [str(object_fom), str(switch_fom)],
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            owner.joinFederationExecution("jni-auto-provide-owner", federation_name)
            owner_joined = True
            requester.joinFederationExecution(
                "jni-auto-provide-requester", federation_name
            )
            requester_joined = True

            self.assertTrue(owner.getAutoProvideSwitch())
            self.assertTrue(requester.getAutoProvideSwitch())
            owner_class = owner.getObjectClassHandle(HLA_FOM.ATTRIBUTE_FIXTURE_CHILD)
            requester_class = requester.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            owner_base = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            owner_child = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.RELIABLE_CHILD
            )
            requester_base = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            requester_child = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.RELIABLE_CHILD
            )
            owner_attributes = AttributeHandleSet([owner_base, owner_child])
            requester_attributes = AttributeHandleSet([requester_base, requester_child])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)

            object_instance = owner.registerObjectInstance(owner_class)
            self.assertEqual(requester_callbacks.discovered_objects, [])
            requester.subscribeObjectClassAttributes(
                requester_class, requester_attributes
            )
            for _ in range(20):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(len(requester_callbacks.discovered_objects), 1)
            self.assertEqual(
                requester_callbacks.discovered_objects[0][0], object_instance
            )

            # Auto Provide is evaluated after discovery and queues a separate
            # provider callback; it must not be synthesized by Java/JPype.
            self.assertEqual(owner_callbacks.attribute_value_update_requests, [])
            for _ in range(20):
                owner.evokeCallback(0.0)
                if owner_callbacks.attribute_value_update_requests:
                    break
            self.assertEqual(len(owner_callbacks.attribute_value_update_requests), 1)
            request = owner_callbacks.attribute_value_update_requests[0]
            self.assertEqual(request[0], object_instance)
            self.assertEqual(request[1], owner_attributes)
            self.assertEqual(request[2], b"")
        finally:
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_auto_provide_mom_switch(self) -> None:
        """Drive federation-wide Auto Provide through standard HLAsetSwitches."""
        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "attribute-update-passel-fom.xml"
        )
        federation_name = f"python-jni-auto-provide-mom-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = False
        owner_joined = requester_joined = created = False
        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution("jni-auto-provide-mom-owner", federation_name)
            owner_joined = True
            requester.joinFederationExecution(
                "jni-auto-provide-mom-requester", federation_name
            )
            requester_joined = True
            self.assertFalse(owner.getAutoProvideSwitch())
            self.assertFalse(requester.getAutoProvideSwitch())

            federation_mom_class = requester.getObjectClassHandle(
                HLA_MOM.FEDERATION_OBJECT_CLASS
            )
            federation_auto_provide_attribute = requester.getAttributeHandle(
                federation_mom_class, HLA_MOM.AUTO_PROVIDE
            )
            requester.subscribeObjectClassAttributes(
                federation_mom_class,
                AttributeHandleSet([federation_auto_provide_attribute]),
                active=True,
            )
            for _ in range(20):
                requester.evokeCallback(0.0)

            def require_federation_auto_provide(expected: bool) -> None:
                encoder = self.factory.getEncoderFactory()
                for _ in range(30):
                    requester.evokeCallback(0.0)
                    for reflection in requester_callbacks.reflected_attributes:
                        values = dict(reflection[1])
                        encoded = values.get(federation_auto_provide_attribute)
                        if encoded is None:
                            continue
                        switch = encoder.createHLAinteger32BE()
                        switch.decode(encoded)
                        if bool(switch.getValue()) == expected:
                            return
                self.fail(
                    f"HLAautoProvide federation MOM value {expected} was not reflected"
                )

            set_switches = owner.getInteractionClassHandle(
                HLA_MOM.SET_SWITCHES_FEDERATION
            )
            owner_auto_provide = owner.getParameterHandle(
                set_switches, HLA_MOM.AUTO_PROVIDE
            )
            requester_set_switches = requester.getInteractionClassHandle(
                HLA_MOM.SET_SWITCHES_FEDERATION
            )
            requester_auto_provide = requester.getParameterHandle(
                requester_set_switches, HLA_MOM.AUTO_PROVIDE
            )
            owner.sendInteraction(
                set_switches,
                ParameterHandleValueMap({owner_auto_provide: b"\x00\x00\x00\x01"}),
                b"",
            )
            self.assertTrue(owner.getAutoProvideSwitch())
            self.assertTrue(requester.getAutoProvideSwitch())
            require_federation_auto_provide(True)

            owner_class = owner.getObjectClassHandle(HLA_FOM.ATTRIBUTE_FIXTURE_CHILD)
            requester_class = requester.getObjectClassHandle(
                HLA_FOM.ATTRIBUTE_FIXTURE_CHILD
            )
            owner_base = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            owner_child = owner.getAttributeHandle(
                owner_class, HLA_FIXTURES.RELIABLE_CHILD
            )
            requester_base = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.RELIABLE_BASE_A
            )
            requester_child = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.RELIABLE_CHILD
            )
            owner_attributes = AttributeHandleSet([owner_base, owner_child])
            requester_attributes = AttributeHandleSet([requester_base, requester_child])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            requester.subscribeObjectClassAttributes(
                requester_class, requester_attributes
            )

            first_object = owner.registerObjectInstance(owner_class)
            for _ in range(20):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[-1][0], first_object
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
                if owner_callbacks.attribute_value_update_requests:
                    break
            self.assertEqual(len(owner_callbacks.attribute_value_update_requests), 1)

            requester.sendInteraction(
                requester_set_switches,
                ParameterHandleValueMap({requester_auto_provide: b"\x00\x00\x00\x00"}),
                b"",
            )
            self.assertFalse(owner.getAutoProvideSwitch())
            self.assertFalse(requester.getAutoProvideSwitch())
            require_federation_auto_provide(False)
            second_object = owner.registerObjectInstance(owner_class)
            for _ in range(20):
                requester.evokeCallback(0.0)
                if len(requester_callbacks.discovered_objects) >= 2:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[-1][0], second_object
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
            self.assertEqual(len(owner_callbacks.attribute_value_update_requests), 1)

            owner.sendInteraction(
                set_switches,
                ParameterHandleValueMap({owner_auto_provide: b"\x00\x00\x00\x01"}),
                b"",
            )
            self.assertTrue(owner.getAutoProvideSwitch())
            self.assertTrue(requester.getAutoProvideSwitch())
            require_federation_auto_provide(True)
            third_object = owner.registerObjectInstance(owner_class)
            for _ in range(20):
                requester.evokeCallback(0.0)
                if len(requester_callbacks.discovered_objects) >= 3:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[-1][0], third_object
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
                if len(owner_callbacks.attribute_value_update_requests) >= 2:
                    break
            self.assertEqual(len(owner_callbacks.attribute_value_update_requests), 2)
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests[-1][1], owner_attributes
            )
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests[-1][2], b""
            )
        finally:
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_two_dimensional_request_matrix(
        self,
    ) -> None:
        """Filter regional value requests before the provider callback."""

        class RespondingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.ambassador: RTIambassador | None = None
                self.respond = False
                self.values: dict[AttributeHandle, bytes] = {}

            def provideAttributeValueUpdate(
                self,
                objectInstance: ObjectInstanceHandle,
                attributes: AttributeHandleSet,
                userSuppliedTag: bytes,
            ) -> None:
                super().provideAttributeValueUpdate(
                    objectInstance, attributes, userSuppliedTag
                )
                if not self.respond or self.ambassador is None:
                    return
                self.ambassador.updateAttributeValues(
                    objectInstance,
                    AttributeHandleValueMap(
                        {attribute: self.values[attribute] for attribute in attributes}
                    ),
                    b"response-" + userSuppliedTag,
                )

        fom_module = (
            Path(__file__).parents[3]
            / "packages"
            / "umbra-rti-native"
            / "tests"
            / "data"
            / "regional-two-dimensional-multi-attribute-fom.xml"
        )
        federation_name = f"python-jni-regional-object-2d-request-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = RespondingCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = False
        owner_joined = requester_joined = created = False
        owner_region_flavor: RegionHandle | None = None
        owner_region_organic: RegionHandle | None = None
        requester_region_flavor: RegionHandle | None = None
        requester_region_organic: RegionHandle | None = None
        object_instance: ObjectInstanceHandle | None = None
        owner_pairs: AttributeSetRegionSetPairList | None = None
        requester_pairs: AttributeSetRegionSetPairList | None = None

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                requester.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            entries: tuple[tuple[AttributeHandle, RegionHandle], ...],
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(
                len(entries)
            )
            for attribute, region in entries:
                pairs.add(
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([attribute]), RegionHandleSet([region])
                    )
                )
            return pairs

        def set_region(
            ambassador: RTIambassador,
            region: RegionHandle,
            x_dimension: DimensionHandle,
            y_dimension: DimensionHandle,
            x_bounds: tuple[int, int],
            y_bounds: tuple[int, int],
        ) -> None:
            ambassador.setRangeBounds(region, x_dimension, RangeBounds(*x_bounds))
            ambassador.setRangeBounds(region, y_dimension, RangeBounds(*y_bounds))

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution("jni-2d-request-owner", federation_name)
            owner_joined = True
            requester.joinFederationExecution("jni-2d-requester", federation_name)
            requester_joined = True

            owner_class = owner.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            requester_class = requester.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            owner_flavor = owner.getAttributeHandle(owner_class, HLA_FIXTURES.FLAVOR)
            owner_organic = owner.getAttributeHandle(owner_class, HLA_FIXTURES.ORGANIC)
            requester_flavor = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.FLAVOR
            )
            requester_organic = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.ORGANIC
            )
            owner_attributes = AttributeHandleSet([owner_flavor, owner_organic])
            requester_attributes = AttributeHandleSet(
                [requester_flavor, requester_organic]
            )
            owner.publishObjectClassAttributes(owner_class, owner_attributes)

            owner_x = owner.getDimensionHandle(HLA_FIXTURES.UMBRA_REGION_X)
            owner_y = owner.getDimensionHandle(HLA_FIXTURES.UMBRA_REGION_Y)
            requester_x = requester.getDimensionHandle(HLA_FIXTURES.UMBRA_REGION_X)
            requester_y = requester.getDimensionHandle(HLA_FIXTURES.UMBRA_REGION_Y)
            owner_dimensions = DimensionHandleSet([owner_x, owner_y])
            requester_dimensions = DimensionHandleSet([requester_x, requester_y])
            owner_region_flavor = owner.createRegion(owner_dimensions)
            owner_region_organic = owner.createRegion(owner_dimensions)
            requester_region_flavor = requester.createRegion(requester_dimensions)
            requester_region_organic = requester.createRegion(requester_dimensions)
            set_region(
                owner,
                owner_region_flavor,
                owner_x,
                owner_y,
                (0, 2),
                (0, 2),
            )
            set_region(
                owner,
                owner_region_organic,
                owner_x,
                owner_y,
                (5, 7),
                (5, 7),
            )
            set_region(
                requester,
                requester_region_flavor,
                requester_x,
                requester_y,
                (0, 2),
                (0, 2),
            )
            set_region(
                requester,
                requester_region_organic,
                requester_x,
                requester_y,
                (5, 7),
                (5, 7),
            )
            owner.commitRegionModifications(
                RegionHandleSet([owner_region_flavor, owner_region_organic])
            )
            requester.commitRegionModifications(
                RegionHandleSet([requester_region_flavor, requester_region_organic])
            )
            requester.setConveyRegionDesignatorSetsSwitch(True)
            requester_pairs = pair_list(
                requester,
                (
                    (requester_flavor, requester_region_flavor),
                    (requester_organic, requester_region_organic),
                ),
            )
            requester.subscribeObjectClassAttributesWithRegions(
                requester_class, requester_pairs, active=True
            )
            owner_pairs = pair_list(
                owner,
                (
                    (owner_flavor, owner_region_flavor),
                    (owner_organic, owner_region_organic),
                ),
            )
            object_instance = owner.registerObjectInstanceWithRegions(
                owner_class, owner_pairs
            )
            drain()
            self.assertEqual(len(requester_callbacks.discovered_objects), 1)
            self.assertEqual(
                requester_callbacks.discovered_objects[-1][0], object_instance
            )

            # Do not answer discovery-time automatic provision. The requests
            # below then provide a clean accounting of provider callbacks.
            owner_callbacks.ambassador = owner
            owner_callbacks.values = {
                owner_flavor: b"flavor-request-response",
                owner_organic: b"organic-request-response",
            }
            owner_callbacks.respond = True
            baseline_requests = len(owner_callbacks.attribute_value_update_requests)
            baseline_reflections = len(requester_callbacks.regional_reflections)

            def request_and_wait(
                tag: bytes, expected_attributes: AttributeHandleSet
            ) -> None:
                requester.requestAttributeValueUpdateWithRegions(
                    requester_class, requester_pairs, tag
                )
                for _ in range(30):
                    drain(1)
                    if (
                        len(owner_callbacks.attribute_value_update_requests)
                        > baseline_requests
                    ):
                        break
                self.assertGreater(
                    len(owner_callbacks.attribute_value_update_requests),
                    baseline_requests,
                )
                self.assertEqual(
                    owner_callbacks.attribute_value_update_requests[-1],
                    (object_instance, expected_attributes, tag),
                )

            request_and_wait(b"initial", owner_attributes)
            for _ in range(30):
                drain(1)
                if (
                    len(requester_callbacks.regional_reflections)
                    >= baseline_reflections + 2
                ):
                    break
            self.assertEqual(
                len(requester_callbacks.regional_reflections), baseline_reflections + 2
            )
            initial_reflections = requester_callbacks.regional_reflections[-2:]
            self.assertTrue(
                any(
                    reflection[1]
                    == AttributeHandleValueMap(
                        {requester_flavor: b"flavor-request-response"}
                    )
                    for reflection in initial_reflections
                )
            )
            self.assertTrue(
                any(
                    reflection[1]
                    == AttributeHandleValueMap(
                        {requester_organic: b"organic-request-response"}
                    )
                    for reflection in initial_reflections
                )
            )

            # Mirror the native callback-boundary case through the external
            # Java API: an accepted evoked request must be re-evaluated after
            # the requester moves both regions disjoint and before the
            # provider callback is delivered.  The stale provider callback
            # and any response reflection must be suppressed.
            baseline_requests = len(owner_callbacks.attribute_value_update_requests)
            baseline_reflections = len(requester_callbacks.regional_reflections)
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, b"queued-then-disjoint"
            )
            requester.setRangeBounds(
                requester_region_flavor, requester_x, RangeBounds(8, 9)
            )
            requester.setRangeBounds(
                requester_region_organic, requester_y, RangeBounds(8, 9)
            )
            requester.commitRegionModifications(
                RegionHandleSet([requester_region_flavor, requester_region_organic])
            )
            drain(30)
            self.assertEqual(
                len(owner_callbacks.attribute_value_update_requests), baseline_requests
            )
            self.assertEqual(
                len(requester_callbacks.regional_reflections), baseline_reflections
            )

            # Restore the requester regions before the per-attribute matrix;
            # the later request must re-enter through the same standard pair
            # list rather than relying on a fresh subscription declaration.
            requester.setRangeBounds(
                requester_region_flavor, requester_x, RangeBounds(0, 2)
            )
            requester.setRangeBounds(
                requester_region_organic, requester_y, RangeBounds(5, 7)
            )
            requester.commitRegionModifications(
                RegionHandleSet([requester_region_flavor, requester_region_organic])
            )

            # Move only the Flavor requester on X. The provider callback must
            # receive only Organic; filtering after a two-attribute callback is
            # too late and would violate request-region semantics.
            requester.setRangeBounds(
                requester_region_flavor, requester_x, RangeBounds(8, 9)
            )
            requester.commitRegionModifications(
                RegionHandleSet([requester_region_flavor])
            )
            baseline_requests = len(owner_callbacks.attribute_value_update_requests)
            baseline_reflections = len(requester_callbacks.regional_reflections)
            request_and_wait(b"organic-only", AttributeHandleSet([owner_organic]))
            self.assertEqual(
                len(requester_callbacks.regional_reflections), baseline_reflections + 1
            )
            self.assertEqual(
                requester_callbacks.regional_reflections[-1][1],
                AttributeHandleValueMap(
                    {requester_organic: b"organic-request-response"}
                ),
            )

            # Move Organic out on Y as well. No provider callback or reflection
            # is legal while both per-attribute requester regions are disjoint.
            requester.setRangeBounds(
                requester_region_organic, requester_y, RangeBounds(8, 9)
            )
            requester.commitRegionModifications(
                RegionHandleSet([requester_region_organic])
            )
            baseline_requests = len(owner_callbacks.attribute_value_update_requests)
            baseline_reflections = len(requester_callbacks.regional_reflections)
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, b"none"
            )
            drain(30)
            self.assertEqual(
                len(owner_callbacks.attribute_value_update_requests), baseline_requests
            )
            self.assertEqual(
                len(requester_callbacks.regional_reflections), baseline_reflections
            )

            # Restore both requester dimensions; the complete pair-list request
            # once again produces one callback and two recipient-local updates.
            requester.setRangeBounds(
                requester_region_flavor, requester_x, RangeBounds(0, 2)
            )
            requester.setRangeBounds(
                requester_region_organic, requester_y, RangeBounds(5, 7)
            )
            requester.commitRegionModifications(
                RegionHandleSet([requester_region_flavor, requester_region_organic])
            )
            baseline_requests = len(owner_callbacks.attribute_value_update_requests)
            baseline_reflections = len(requester_callbacks.regional_reflections)
            request_and_wait(b"restored", owner_attributes)
            for _ in range(30):
                drain(1)
                if (
                    len(requester_callbacks.regional_reflections)
                    >= baseline_reflections + 2
                ):
                    break
            self.assertEqual(
                len(requester_callbacks.regional_reflections),
                baseline_reflections + 2,
                requester_callbacks.regional_reflections,
            )
        finally:
            if requester_joined and requester_pairs is not None:
                try:
                    requester.unsubscribeObjectClassAttributesWithRegions(
                        requester_class, requester_pairs
                    )
                except Exception:
                    pass
            if object_instance is not None and owner_joined and owner_pairs is not None:
                try:
                    owner.unassociateRegionsForUpdates(object_instance, owner_pairs)
                except Exception:
                    pass
            for ambassador, region in (
                (requester, requester_region_flavor),
                (requester, requester_region_organic),
                (owner, owner_region_flavor),
                (owner, owner_region_organic),
            ):
                if region is not None:
                    try:
                        ambassador.deleteRegion(region)
                    except Exception:
                        pass
            for ambassador, joined in (
                (requester, requester_joined),
                (owner, owner_joined),
            ):
                if joined:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                requester.disconnect()
            if owner_connected:
                owner.disconnect()
            requester._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_request_response(self) -> None:
        """Route a regional value request and response through the standard Java callback."""

        class RespondingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.ambassador: RTIambassador | None = None
                self.respond = False
                self.report_file: Path | None = None
                self.report_before_request = ""
                self.provide_report_at_callback = False

            def provideAttributeValueUpdate(
                self,
                objectInstance: ObjectInstanceHandle,
                attributes: AttributeHandleSet,
                userSuppliedTag: bytes,
            ) -> None:
                if self.report_file is not None and self.report_before_request:
                    suffix = self.report_file.read_text(encoding="utf-8")[
                        len(self.report_before_request) :
                    ]
                    self.provide_report_at_callback = (
                        '"HLAservice":"ProvideAttributeValueUpdate"' in suffix
                    )
                super().provideAttributeValueUpdate(
                    objectInstance, attributes, userSuppliedTag
                )
                if not self.respond or self.ambassador is None:
                    return
                values = AttributeHandleValueMap(
                    {
                        attribute: b"jni-regional-response-value"
                        for attribute in attributes
                    }
                )
                self.ambassador.updateAttributeValues(
                    objectInstance, values, b"jni-regional-response-tag"
                )

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-object-response-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = RespondingCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = False
        owner_joined = requester_joined = created = False
        object_instance: ObjectInstanceHandle | None = None
        owner_region: RegionHandle | None = None
        requester_region: RegionHandle | None = None
        owner_report_file: Path | None = None
        requester_report_file: Path | None = None
        try:
            reports_directory = self._temporary_directory / (
                f"regional-object-request-reports-{uuid4().hex[:12]}"
            )
            reports_directory.mkdir(parents=True, exist_ok=True)
            owner_configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            owner.connect(
                owner_callbacks, CallbackModel.HLA_EVOKED, owner_configuration
            )
            owner_connected = True
            requester_configuration = (
                RtiConfiguration.createConfiguration().withAdditionalSettings(
                    f"serviceReportDirectory={reports_directory}"
                )
            )
            requester.connect(
                requester_callbacks,
                CallbackModel.HLA_EVOKED,
                requester_configuration,
            )
            requester_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner_handle = owner.joinFederationExecution(
                "jni-regional-object-response-owner",
                federation_name,
                federateName="jni-regional-object-response-owner",
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-regional-object-response-requester",
                federation_name,
                federateName="jni-regional-object-response-requester",
            )
            requester_joined = True
            owner_report_file = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-regional-object-response-owner"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            requester_report_file = next(
                (
                    path
                    for path in sorted(reports_directory.glob("*"))
                    if '"HLAfederateName":"jni-regional-object-response-requester"'
                    in path.read_text(encoding="utf-8")
                ),
                None,
            )
            self.assertIsNotNone(owner_report_file)
            self.assertIsNotNone(requester_report_file)
            assert owner_report_file is not None
            assert requester_report_file is not None

            owner.setServiceReportingSwitch(False)
            owner.setSendServiceReportsToFileSwitch(False)
            requester.setServiceReportingSwitch(False)
            requester.setSendServiceReportsToFileSwitch(False)

            owner_class = owner.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            requester_class = requester.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            owner_attribute = owner.getAttributeHandle(owner_class, HLA_FIXTURES.FLAVOR)
            requester_attribute = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.FLAVOR
            )
            owner_dimension = owner.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            requester_dimension = requester.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            owner_attributes = AttributeHandleSet([owner_attribute])
            requester_attributes = AttributeHandleSet([requester_attribute])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)

            owner_region = owner.createRegion(DimensionHandleSet([owner_dimension]))
            requester_region = requester.createRegion(
                DimensionHandleSet([requester_dimension])
            )
            owner.setRangeBounds(owner_region, owner_dimension, RangeBounds(0, 1))
            requester.setRangeBounds(
                requester_region, requester_dimension, RangeBounds(0, 1)
            )
            owner.commitRegionModifications(RegionHandleSet([owner_region]))
            requester.commitRegionModifications(RegionHandleSet([requester_region]))

            def pair_list(
                ambassador: RTIambassador,
                attributes: AttributeHandleSet,
                region: RegionHandle,
            ) -> AttributeSetRegionSetPairList:
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(attributes, RegionHandleSet([region]))
                )
                return pairs

            owner_pairs = pair_list(owner, owner_attributes, owner_region)
            requester_pairs = pair_list(
                requester, requester_attributes, requester_region
            )
            requester.subscribeObjectClassAttributesWithRegions(
                requester_class, requester_pairs
            )
            requester.setConveyRegionDesignatorSetsSwitch(True)
            object_instance = owner.registerObjectInstanceWithRegions(
                owner_class, owner_pairs
            )
            for _ in range(20):
                requester.evokeCallback(0.0)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[-1][0], object_instance
            )

            # RestaurantFOM may arrange automatic provision during discovery;
            # drain that setup work before enabling the explicit response.
            while owner.evokeCallback(0.0):
                pass
            owner_callbacks.ambassador = owner
            owner_callbacks.respond = True
            owner.setServiceReportingSwitch(True)
            owner.setSendServiceReportsToFileSwitch(True)
            requester.setServiceReportingSwitch(True)
            requester.setSendServiceReportsToFileSwitch(True)
            initial_request_count = len(owner_callbacks.attribute_value_update_requests)
            request_tag = b"jni-regional-request-response"
            owner_before_request = owner_report_file.read_text(encoding="utf-8")
            owner_callbacks.report_file = owner_report_file
            owner_callbacks.report_before_request = owner_before_request
            report_before_request = requester_report_file.read_text(encoding="utf-8")
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, request_tag
            )
            report_after_request = requester_report_file.read_text(encoding="utf-8")
            report_suffix = report_after_request[len(report_before_request) :]
            report_record, report_consumed = json.JSONDecoder().raw_decode(
                report_suffix
            )
            self.assertEqual(report_consumed, len(report_suffix))
            self.assertEqual(
                report_record[HLA_MOM.SERVICE], "RequestAttributeValueUpdateWithRegions"
            )
            self.assertIsInstance(report_record[HLA_MOM.SERIAL_NUMBER], int)
            self.assertEqual(report_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            self.assertTrue(report_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(report_record[HLA_MOM.EXCEPTION])
            supplied_arguments = report_record[HLA_MOM.SUPPLIED_ARGUMENTS]
            self.assertEqual(len(supplied_arguments), 3)
            self.assertEqual(supplied_arguments[0][HLA_MOM.ARGUMENT_TYPE], 36)
            self.assertEqual(
                supplied_arguments[0][HLA_MOM.ARGUMENT_NAME], "Object class designator"
            )
            self.assertRegex(
                supplied_arguments[0][HLA_MOM.ARGUMENT_VALUE],
                r"^ObjectClassHandle\(\d+\)$",
            )
            self.assertEqual(supplied_arguments[1][HLA_MOM.ARGUMENT_TYPE], 4)
            self.assertEqual(
                supplied_arguments[1][HLA_MOM.ARGUMENT_NAME],
                "Collection of attribute designator set and region designator set pairs",
            )
            self.assertEqual(len(supplied_arguments[1][HLA_MOM.ARGUMENT_VALUE]), 1)
            pair_argument = supplied_arguments[1][HLA_MOM.ARGUMENT_VALUE][0]
            self.assertEqual(len(pair_argument["attributeHandleSet"]), 1)
            self.assertRegex(
                pair_argument["attributeHandleSet"][0],
                r"^AttributeHandle\(\d+\)$",
            )
            self.assertEqual(len(pair_argument["regionHandleSet"]), 1)
            self.assertRegex(
                pair_argument["regionHandleSet"][0],
                r"^RegionHandle\(\d+\)$",
            )
            self.assertEqual(
                supplied_arguments[2],
                {
                    HLA_MOM.ARGUMENT_TYPE: 63,
                    HLA_MOM.ARGUMENT_NAME: "User-supplied tag",
                    HLA_MOM.ARGUMENT_VALUE: base64.b64encode(request_tag).decode(
                        "ascii"
                    ),
                },
            )
            # C++ commits the provider-side service report before queueing the
            # standard Java callback. Nothing is appended until the callback
            # boundary, then the callback observes the exact service record.
            self.assertEqual(
                owner_report_file.read_text(encoding="utf-8"), owner_before_request
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
                if (
                    len(owner_callbacks.attribute_value_update_requests)
                    > initial_request_count
                ):
                    break
            self.assertTrue(owner_callbacks.provide_report_at_callback)
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests[-1],
                (object_instance, owner_attributes, request_tag),
            )
            owner_report_suffix = owner_report_file.read_text(encoding="utf-8")[
                len(owner_before_request) :
            ]
            owner_report_decoder = json.JSONDecoder()
            owner_report_records: list[dict[str, object]] = []
            owner_report_offset = 0
            while owner_report_offset < len(owner_report_suffix):
                owner_report_record, owner_report_consumed = (
                    owner_report_decoder.raw_decode(
                        owner_report_suffix[owner_report_offset:]
                    )
                )
                self.assertIsInstance(owner_report_record, dict)
                owner_report_records.append(owner_report_record)
                owner_report_offset += owner_report_consumed
            self.assertEqual(owner_report_offset, len(owner_report_suffix))
            owner_report_record = next(
                record
                for record in owner_report_records
                if record[HLA_MOM.SERVICE] == "ProvideAttributeValueUpdate"
            )
            self.assertEqual(
                owner_report_record[HLA_MOM.SERVICE], "ProvideAttributeValueUpdate"
            )
            self.assertTrue(owner_report_record[HLA_MOM.SUCCESS_INDICATOR])
            self.assertIsNone(owner_report_record[HLA_MOM.EXCEPTION])
            self.assertEqual(owner_report_record[HLA_MOM.RETURNED_ARGUMENT], [None])
            owner_supplied_arguments = owner_report_record[HLA_MOM.SUPPLIED_ARGUMENTS]
            self.assertEqual(
                [
                    argument[HLA_MOM.ARGUMENT_TYPE]
                    for argument in owner_supplied_arguments
                ],
                [37, 1, 63],
            )
            self.assertRegex(
                owner_supplied_arguments[0][HLA_MOM.ARGUMENT_VALUE],
                r"^ObjectInstanceHandle\(\d+\)$",
            )
            self.assertRegex(
                owner_supplied_arguments[1][HLA_MOM.ARGUMENT_VALUE][0],
                r"^AttributeHandle\(\d+\)$",
            )
            self.assertEqual(
                owner_supplied_arguments[2][HLA_MOM.ARGUMENT_VALUE],
                base64.b64encode(request_tag).decode("ascii"),
            )
            for _ in range(20):
                requester.evokeCallback(0.0)
                if requester_callbacks.regional_reflections:
                    break
            self.assertEqual(len(requester_callbacks.regional_reflections), 1)
            reflected = requester_callbacks.regional_reflections[-1]
            self.assertEqual(reflected[0], object_instance)
            self.assertEqual(
                reflected[1],
                AttributeHandleValueMap(
                    {requester_attribute: b"jni-regional-response-value"}
                ),
            )
            self.assertEqual(reflected[2], b"jni-regional-response-tag")
            self.assertEqual(
                reflected[3], owner.getTransportationTypeHandle(HLA_MOM.RELIABLE)
            )
            self.assertEqual(reflected[4], owner_handle)
            self.assertEqual(reflected[5], RegionHandleSet([owner_region]))

            # A second provider response is queued while the requester still
            # overlaps. Move only the requester's committed region to a
            # disjoint range before its callback boundary; C++ must re-check
            # current DDM eligibility and suppress the stale reflection.
            reflection_count = len(requester_callbacks.regional_reflections)
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, b"jni-regional-recheck"
            )
            for _ in range(20):
                owner.evokeCallback(0.0)
                if (
                    len(owner_callbacks.attribute_value_update_requests)
                    > initial_request_count + 1
                ):
                    break
            requester.setRangeBounds(
                requester_region,
                requester_dimension,
                RangeBounds(2, 3),
            )
            requester.commitRegionModifications(RegionHandleSet([requester_region]))
            for _ in range(20):
                requester.evokeCallback(0.0)
            self.assertEqual(
                len(requester_callbacks.regional_reflections), reflection_count
            )
        finally:
            if requester_joined:
                try:
                    requester.unsubscribeObjectClassAttributesWithRegions(
                        requester_class, requester_pairs
                    )
                except Exception:
                    pass
            if object_instance is not None and owner_joined:
                try:
                    owner.unassociateRegionsForUpdates(object_instance, owner_pairs)
                except Exception:
                    pass
            for ambassador, region in (
                (requester, requester_region),
                (owner, owner_region),
            ):
                if region is not None:
                    try:
                        ambassador.deleteRegion(region)
                    except Exception:
                        pass
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_regional_request_default_region_fallback(
        self,
    ) -> None:
        """Preserve default-region request eligibility through the Java surface."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-request-default-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = False
        owner_joined = requester_joined = created = False
        owner_region: RegionHandle | None = None
        requester_region: RegionHandle | None = None
        regional_object: ObjectInstanceHandle | None = None
        default_object: ObjectInstanceHandle | None = None

        def drain_owner_until(target_count: int) -> None:
            for _ in range(40):
                owner.evokeCallback(0.0)
                if len(owner_callbacks.attribute_value_update_requests) >= target_count:
                    return

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution(
                "jni-regional-request-default-owner", federation_name
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-regional-request-default-requester", federation_name
            )
            requester_joined = True

            # Disable automatic provision so every callback below is caused by
            # the regional request under test, not by object discovery.
            set_switches = owner.getInteractionClassHandle(
                HLA_MOM.SET_SWITCHES_FEDERATION
            )
            auto_provide = owner.getParameterHandle(set_switches, HLA_MOM.AUTO_PROVIDE)
            owner.sendInteraction(
                set_switches,
                ParameterHandleValueMap({auto_provide: b"\x00\x00\x00\x00"}),
                b"",
            )
            self.assertFalse(owner.getAutoProvideSwitch())
            self.assertFalse(requester.getAutoProvideSwitch())

            owner_class = owner.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            requester_class = requester.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            owner_attribute = owner.getAttributeHandle(owner_class, HLA_FIXTURES.FLAVOR)
            requester_attribute = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.FLAVOR
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            requester_attributes = AttributeHandleSet([requester_attribute])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)

            owner_dimension = owner.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            requester_dimension = requester.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            owner_region = owner.createRegion(DimensionHandleSet([owner_dimension]))
            requester_region = requester.createRegion(
                DimensionHandleSet([requester_dimension])
            )
            owner.setRangeBounds(owner_region, owner_dimension, RangeBounds(0, 1))
            requester.setRangeBounds(
                requester_region, requester_dimension, RangeBounds(2, 3)
            )
            owner.commitRegionModifications(RegionHandleSet([owner_region]))
            requester.commitRegionModifications(RegionHandleSet([requester_region]))

            def pair_list(
                ambassador: RTIambassador,
                attributes: AttributeHandleSet,
                region: RegionHandle,
            ) -> AttributeSetRegionSetPairList:
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(attributes, RegionHandleSet([region]))
                )
                return pairs

            owner_pairs = pair_list(owner, owner_attributes, owner_region)
            requester_pairs = pair_list(
                requester, requester_attributes, requester_region
            )
            regional_object = owner.registerObjectInstanceWithRegions(
                owner_class, owner_pairs
            )
            default_object = owner.registerObjectInstance(owner_class)
            for _ in range(20):
                owner.evokeCallback(0.0)
            self.assertEqual(owner_callbacks.attribute_value_update_requests, [])

            request_tag = b"jni-regional-default-request"

            # An explicit [0,1] source is disjoint from the requester's [2,3]
            # region, but an ordinary/default-region source remains eligible.
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, request_tag
            )
            drain_owner_until(1)
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests,
                [(default_object, owner_attributes, request_tag)],
            )

            # Overlap makes both the explicitly associated and default-region
            # objects eligible for the same request.
            owner_callbacks.attribute_value_update_requests.clear()
            requester.setRangeBounds(
                requester_region, requester_dimension, RangeBounds(0, 1)
            )
            requester.commitRegionModifications(RegionHandleSet([requester_region]))
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, request_tag
            )
            drain_owner_until(2)
            self.assertEqual(
                {entry[0] for entry in owner_callbacks.attribute_value_update_requests},
                {regional_object, default_object},
            )
            self.assertTrue(
                all(
                    entry[1] == owner_attributes and entry[2] == request_tag
                    for entry in owner_callbacks.attribute_value_update_requests
                )
            )

            # Queue the overlapping request, then move the request region away
            # before callback delivery. C++ rechecks the queued association at
            # the callback boundary: only the default-region callback survives.
            owner_callbacks.attribute_value_update_requests.clear()
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, request_tag
            )
            requester.setRangeBounds(
                requester_region, requester_dimension, RangeBounds(2, 3)
            )
            requester.commitRegionModifications(RegionHandleSet([requester_region]))
            drain_owner_until(1)
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests,
                [(default_object, owner_attributes, request_tag)],
            )
            for _ in range(10):
                owner.evokeCallback(0.0)
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests,
                [(default_object, owner_attributes, request_tag)],
            )
        finally:
            if (
                regional_object is not None
                and owner_joined
                and owner_region is not None
            ):
                try:
                    owner.unassociateRegionsForUpdates(regional_object, owner_pairs)
                except Exception:
                    pass
            if requester_joined and requester_region is not None:
                try:
                    requester.deleteRegion(requester_region)
                except Exception:
                    pass
            if owner_joined and owner_region is not None:
                try:
                    owner.deleteRegion(owner_region)
                except Exception:
                    pass
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_timestamped_request_response(
        self,
    ) -> None:
        """Route a timestamped regional provider response through C++ and Java."""

        class TimestampedRespondingCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.ambassador: RTIambassador | None = None
                self.time_factory: object | None = None
                self.respond = False
                self.response_retraction: MessageRetractionHandle | None = None

            def provideAttributeValueUpdate(
                self,
                objectInstance: ObjectInstanceHandle,
                attributes: AttributeHandleSet,
                userSuppliedTag: bytes,
            ) -> None:
                super().provideAttributeValueUpdate(
                    objectInstance, attributes, userSuppliedTag
                )
                if (
                    not self.respond
                    or self.ambassador is None
                    or self.time_factory is None
                ):
                    return
                values = AttributeHandleValueMap(
                    {
                        attribute: b"jni-regional-timestamped-response"
                        for attribute in attributes
                    }
                )
                self.response_retraction = (
                    self.ambassador.updateAttributeValuesWithTime(
                        objectInstance,
                        values,
                        self.time_factory.makeLogicalTime(2),  # type: ignore[attr-defined]
                        b"jni-regional-timestamped-response-tag",
                    )
                )

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-timestamped-response-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = TimestampedRespondingCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = False
        owner_joined = requester_joined = created = False
        object_instance: ObjectInstanceHandle | None = None
        owner_region: RegionHandle | None = None
        requester_region: RegionHandle | None = None

        def drain(rounds: int = 30) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                requester.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner_handle = owner.joinFederationExecution(
                "jni-regional-timestamped-response-owner", federation_name
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-regional-timestamped-response-requester", federation_name
            )
            requester_joined = True

            owner_class = owner.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            requester_class = requester.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            owner_attribute = owner.getAttributeHandle(owner_class, HLA_FIXTURES.FLAVOR)
            requester_attribute = requester.getAttributeHandle(
                requester_class, HLA_FIXTURES.FLAVOR
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            requester_attributes = AttributeHandleSet([requester_attribute])
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            owner.changeDefaultAttributeOrderType(
                owner_class, owner_attributes, OrderType.TIMESTAMP
            )

            owner_dimension = owner.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            requester_dimension = requester.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            owner_region = owner.createRegion(DimensionHandleSet([owner_dimension]))
            requester_region = requester.createRegion(
                DimensionHandleSet([requester_dimension])
            )
            owner.setRangeBounds(owner_region, owner_dimension, RangeBounds(0, 1))
            requester.setRangeBounds(
                requester_region, requester_dimension, RangeBounds(0, 1)
            )
            owner.commitRegionModifications(RegionHandleSet([owner_region]))
            requester.commitRegionModifications(RegionHandleSet([requester_region]))

            def pair_list(
                ambassador: RTIambassador,
                attributes: AttributeHandleSet,
                region: RegionHandle,
            ) -> AttributeSetRegionSetPairList:
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(attributes, RegionHandleSet([region]))
                )
                return pairs

            owner_pairs = pair_list(owner, owner_attributes, owner_region)
            requester_pairs = pair_list(
                requester, requester_attributes, requester_region
            )
            requester.subscribeObjectClassAttributesWithRegions(
                requester_class, requester_pairs
            )
            requester.setConveyRegionDesignatorSetsSwitch(True)
            object_instance = owner.registerObjectInstanceWithRegions(
                owner_class, owner_pairs
            )
            for _ in range(30):
                drain(1)
                if requester_callbacks.discovered_objects:
                    break
            self.assertEqual(
                requester_callbacks.discovered_objects[-1][0], object_instance
            )

            while owner.evokeCallback(0.0):
                pass
            owner_callbacks.ambassador = owner
            owner_callbacks.time_factory = owner.getTimeFactory()
            owner_callbacks.respond = True
            requester.enableTimeConstrained()
            owner.enableTimeRegulation(
                owner_callbacks.time_factory.makeLogicalTimeInterval(1)  # type: ignore[attr-defined]
            )
            drain()
            self.assertTrue(requester_callbacks.time_constrained_enabled)
            self.assertTrue(owner_callbacks.time_regulation_enabled)

            request_tag = b"jni-regional-timestamped-request-tag"
            initial_request_count = len(owner_callbacks.attribute_value_update_requests)
            requester.requestAttributeValueUpdateWithRegions(
                requester_class, requester_pairs, request_tag
            )
            for _ in range(30):
                owner.evokeCallback(0.0)
                if (
                    len(owner_callbacks.attribute_value_update_requests)
                    > initial_request_count
                ):
                    break
            self.assertEqual(
                owner_callbacks.attribute_value_update_requests[-1],
                (object_instance, owner_attributes, request_tag),
            )
            self.assertIsNotNone(owner_callbacks.response_retraction)
            self.assertEqual(requester_callbacks.timestamped_reflections, [])

            requester.timeAdvanceRequest(requester.getTimeFactory().makeLogicalTime(2))
            owner.timeAdvanceRequest(owner_callbacks.time_factory.makeLogicalTime(2))  # type: ignore[attr-defined]
            drain()
            self.assertEqual(len(requester_callbacks.timestamped_reflections), 1)
            self.assertEqual(len(requester_callbacks.time_advance_grants), 1)
            reflection = requester_callbacks.timestamped_reflections[0]
            self.assertEqual(reflection[0], object_instance)
            self.assertEqual(
                reflection[1],
                AttributeHandleValueMap(
                    {requester_attribute: b"jni-regional-timestamped-response"}
                ),
            )
            self.assertEqual(reflection[2], b"jni-regional-timestamped-response-tag")
            self.assertEqual(
                reflection[3], owner.getTransportationTypeHandle(HLA_MOM.RELIABLE)
            )
            self.assertEqual(reflection[4], owner_handle)
            self.assertEqual(reflection[5], RegionHandleSet([owner_region]))
            self.assertEqual(reflection[6].getTime(), 2)
            self.assertEqual(reflection[7], OrderType.TIMESTAMP)
            self.assertEqual(reflection[8], OrderType.TIMESTAMP)
            self.assertEqual(reflection[9], owner_callbacks.response_retraction)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                owner.retract(owner_callbacks.response_retraction)
        finally:
            if requester_joined:
                try:
                    requester.unsubscribeObjectClassAttributesWithRegions(
                        requester_class, requester_pairs
                    )
                except Exception:
                    pass
            if object_instance is not None and owner_joined:
                try:
                    owner.unassociateRegionsForUpdates(object_instance, owner_pairs)
                except Exception:
                    pass
            for ambassador, region in (
                (requester, requester_region),
                (owner, owner_region),
            ):
                if region is not None:
                    try:
                        ambassador.deleteRegion(region)
                    except Exception:
                        pass
            if requester_joined:
                try:
                    requester.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if requester_connected:
                try:
                    requester.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            requester._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_three_dimensional_regional_object_matrix(
        self,
    ) -> None:
        """Require overlap in every inherited Light-object dimension."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-object-3d-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        created = publisher_joined = subscriber_joined = False
        object_instance: ObjectInstanceHandle | None = None
        publisher_region: RegionHandle | None = None
        subscriber_region: RegionHandle | None = None
        publisher_pairs: AttributeSetRegionSetPairList | None = None
        subscriber_pairs: AttributeSetRegionSetPairList | None = None
        publisher_class: ObjectClassHandle | None = None
        subscriber_class: ObjectClassHandle | None = None

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                subscriber.evokeCallback(0.0)

        def pairs(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            region: RegionHandle,
        ) -> AttributeSetRegionSetPairList:
            result = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            result.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([attribute]), RegionHandleSet([region])
                )
            )
            return result

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-regional-object-3d-publisher", federation_name
            )
            publisher_joined = True
            subscriber.joinFederationExecution(
                "jni-regional-object-3d-subscriber", federation_name
            )
            subscriber_joined = True

            publisher_class = publisher.getObjectClassHandle(
                HLA_FOM.FOOD_DRINK_SODA_LIGHT
            )
            subscriber_class = subscriber.getObjectClassHandle(
                HLA_FOM.FOOD_DRINK_SODA_LIGHT
            )
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            subscriber_attribute = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.FLAVOR
            )
            dimensions = [
                publisher.getDimensionHandle(name)
                for name in (
                    HLA_FIXTURES.BAR_QUANTITY,
                    HLA_FIXTURES.SODA_FLAVOR,
                    HLA_FIXTURES.SWEETENER,
                )
            ]
            subscriber_dimensions = [
                subscriber.getDimensionHandle(name)
                for name in (
                    HLA_FIXTURES.BAR_QUANTITY,
                    HLA_FIXTURES.SODA_FLAVOR,
                    HLA_FIXTURES.SWEETENER,
                )
            ]
            publisher_region = publisher.createRegion(DimensionHandleSet(dimensions))
            subscriber_region = subscriber.createRegion(
                DimensionHandleSet(subscriber_dimensions)
            )
            initial_bounds = ((0, 5), (0, 2), (0, 1))
            for dimension, bounds in zip(dimensions, initial_bounds):
                publisher.setRangeBounds(
                    publisher_region, dimension, RangeBounds(*bounds)
                )
            for dimension, bounds in zip(subscriber_dimensions, initial_bounds):
                subscriber.setRangeBounds(
                    subscriber_region, dimension, RangeBounds(*bounds)
                )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            subscriber.commitRegionModifications(RegionHandleSet([subscriber_region]))

            publisher_pairs = pairs(publisher, publisher_attribute, publisher_region)
            subscriber_pairs = pairs(
                subscriber, subscriber_attribute, subscriber_region
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )
            subscriber.setConveyRegionDesignatorSetsSwitch(True)
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, subscriber_pairs
            )
            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            for _ in range(20):
                drain(1)
                if subscriber_callbacks.discovered_objects:
                    break
            self.assertEqual(
                subscriber_callbacks.discovered_objects[-1][0], object_instance
            )

            values = AttributeHandleValueMap({publisher_attribute: b"3d-initial"})
            publisher.updateAttributeValues(object_instance, values, b"3d-initial-tag")
            for _ in range(20):
                drain(1)
                if subscriber_callbacks.regional_reflections:
                    break
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 1)
            initial = subscriber_callbacks.regional_reflections[-1]
            self.assertEqual(initial[0], object_instance)
            self.assertEqual(dict(initial[1]), {subscriber_attribute: b"3d-initial"})
            self.assertEqual(initial[2], b"3d-initial-tag")
            self.assertEqual(initial[5], RegionHandleSet([publisher_region]))

            # The C++ DDM rule is an intersection across all dimensions. Move
            # one source dimension outside the receiver at a time; each
            # update must be suppressed until that dimension is restored.
            for index, disjoint_bounds in enumerate(((6, 8), (3, 4), (2, 3))):
                publisher.setRangeBounds(
                    publisher_region,
                    dimensions[index],
                    RangeBounds(*disjoint_bounds),
                )
                publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
                publisher.updateAttributeValues(
                    object_instance,
                    AttributeHandleValueMap(
                        {publisher_attribute: f"3d-disjoint-{index}".encode()}
                    ),
                    f"3d-disjoint-{index}-tag".encode(),
                )
                drain()
                self.assertEqual(
                    len(subscriber_callbacks.regional_reflections),
                    1,
                    f"dimension {index} unexpectedly admitted a disjoint update",
                )
                publisher.setRangeBounds(
                    publisher_region,
                    dimensions[index],
                    RangeBounds(*initial_bounds[index]),
                )
                publisher.commitRegionModifications(RegionHandleSet([publisher_region]))

            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap({publisher_attribute: b"3d-restored"}),
                b"3d-restored-tag",
            )
            for _ in range(20):
                drain(1)
                if len(subscriber_callbacks.regional_reflections) > 1:
                    break
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 2)
            restored = subscriber_callbacks.regional_reflections[-1]
            self.assertEqual(dict(restored[1]), {subscriber_attribute: b"3d-restored"})
            self.assertEqual(restored[2], b"3d-restored-tag")
            self.assertEqual(restored[5], RegionHandleSet([publisher_region]))
        finally:
            if (
                object_instance is not None
                and publisher_joined
                and publisher_pairs is not None
            ):
                try:
                    publisher.unassociateRegionsForUpdates(
                        object_instance, publisher_pairs
                    )
                except Exception:
                    pass
            if (
                subscriber_joined
                and subscriber_pairs is not None
                and subscriber_class is not None
            ):
                try:
                    subscriber.unsubscribeObjectClassAttributesWithRegions(
                        subscriber_class, subscriber_pairs
                    )
                except Exception:
                    pass
            for ambassador, region in (
                (subscriber, subscriber_region),
                (publisher, publisher_region),
            ):
                if region is not None:
                    try:
                        ambassador.deleteRegion(region)
                    except Exception:
                        pass
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            publisher.disconnect()
            subscriber.disconnect()
            publisher._implementation.close()
            subscriber._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_filters_disjoint_subscriber(
        self,
    ) -> None:
        """Exercise official Java regional-object carriers against C++ DDM."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-object-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        overlap = self.factory.getRtiAmbassador()
        disjoint = self.factory.getRtiAmbassador()
        observer = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        overlap_callbacks = _JniCallbacks()
        disjoint_callbacks = _JniCallbacks()
        observer_callbacks = _JniCallbacks()
        created = publisher_joined = overlap_joined = disjoint_joined = False
        observer_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                overlap.evokeCallback(0.0)
                disjoint.evokeCallback(0.0)
                observer.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            overlap.connect(overlap_callbacks, CallbackModel.HLA_EVOKED)
            disjoint.connect(disjoint_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-regional-object-publisher", federation_name
            )
            publisher_joined = True
            overlap.joinFederationExecution(
                "jni-regional-object-overlap", federation_name
            )
            overlap_joined = True
            disjoint.joinFederationExecution(
                "jni-regional-object-disjoint", federation_name
            )
            disjoint_joined = True
            observer.connect(observer_callbacks, CallbackModel.HLA_EVOKED)
            observer.joinFederationExecution(
                "jni-regional-object-observer", federation_name
            )
            observer_joined = True

            report_class = observer.getInteractionClassHandle(HLA_MOM.REPORT_EXCEPTION)
            report_parameters = {
                name: observer.getParameterHandle(report_class, name)
                for name in (HLA_MOM.SERVICE, HLA_MOM.EXCEPTION)
            }
            observer.subscribeInteractionClass(report_class)
            publisher.setExceptionReportingSwitch(True)
            encoder = self.factory.getEncoderFactory()

            def report_at(index: int, service_name: str, exception_name: str) -> None:
                for _ in range(20):
                    observer.evokeCallback(0.0)
                    if len(observer_callbacks.received_interactions) > index:
                        break
                self.assertGreater(len(observer_callbacks.received_interactions), index)
                report = observer_callbacks.received_interactions[index]
                self.assertEqual(report[0], report_class)
                self.assertEqual(report[2], b"")
                self.assertEqual(
                    report[3], observer.getTransportationTypeHandle(HLA_MOM.RELIABLE)
                )
                report_values = dict(report[1])
                self.assertEqual(set(report_values), set(report_parameters.values()))
                service = (
                    encoder.createHLAunicodeString()
                    .decode(report_values[report_parameters[HLA_MOM.SERVICE]])
                    .getValue()
                )
                exception = (
                    encoder.createHLAunicodeString()
                    .decode(report_values[report_parameters[HLA_MOM.EXCEPTION]])
                    .getValue()
                )
                self.assertEqual(service, service_name)
                self.assertTrue(exception.startswith(exception_name))

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            overlap_class = overlap.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            disjoint_class = disjoint.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            overlap_attribute = overlap.getAttributeHandle(
                overlap_class, HLA_FIXTURES.FLAVOR
            )
            disjoint_attribute = disjoint.getAttributeHandle(
                disjoint_class, HLA_FIXTURES.FLAVOR
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            overlap_dimension = overlap.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            disjoint_dimension = disjoint.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            overlap_region = overlap.createRegion(
                DimensionHandleSet([overlap_dimension])
            )
            disjoint_region = disjoint.createRegion(
                DimensionHandleSet([disjoint_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 1)
            )
            overlap.setRangeBounds(overlap_region, overlap_dimension, RangeBounds(0, 1))
            disjoint.setRangeBounds(
                disjoint_region, disjoint_dimension, RangeBounds(2, 3)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            overlap.commitRegionModifications(RegionHandleSet([overlap_region]))
            disjoint.commitRegionModifications(RegionHandleSet([disjoint_region]))

            publisher_pairs = (
                publisher.getAttributeSetRegionSetPairListFactory().create(1)
            )
            publisher_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([publisher_attribute]),
                    RegionHandleSet([publisher_region]),
                )
            )
            overlap_pairs = overlap.getAttributeSetRegionSetPairListFactory().create(1)
            overlap_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([overlap_attribute]),
                    RegionHandleSet([overlap_region]),
                )
            )
            disjoint_pairs = disjoint.getAttributeSetRegionSetPairListFactory().create(
                1
            )
            disjoint_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([disjoint_attribute]),
                    RegionHandleSet([disjoint_region]),
                )
            )
            empty_publisher_pairs = (
                publisher.getAttributeSetRegionSetPairListFactory().create(1)
            )
            empty_publisher_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([publisher_attribute]), RegionHandleSet()
                )
            )
            empty_disjoint_pairs = (
                disjoint.getAttributeSetRegionSetPairListFactory().create(1)
            )
            empty_disjoint_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([disjoint_attribute]), RegionHandleSet()
                )
            )
            overlap.setConveyRegionDesignatorSetsSwitch(False)
            disjoint.setConveyRegionDesignatorSetsSwitch(True)
            overlap.subscribeObjectClassAttributesWithRegions(
                overlap_class, overlap_pairs, active=True
            )
            disjoint.subscribeObjectClassAttributesWithRegions(
                disjoint_class, disjoint_pairs, active=True
            )
            # The official Java pair carrier must preserve the C++ empty-region
            # no-op: adding an empty source association or subscription cannot
            # create discovery or reflection eligibility.
            disjoint.subscribeObjectClassAttributesWithRegions(
                disjoint_class, empty_disjoint_pairs, active=True
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )

            instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            publisher.associateRegionsForUpdates(instance, empty_publisher_pairs)
            # The C++ registry keeps the source region live while an object
            # registration still references it.  Preserve the standard
            # RegionInUseForUpdateOrSubscription mapping through Java/JPype.
            with self.assertRaises(RegionInUseForUpdateOrSubscription):
                publisher.deleteRegion(publisher_region)
            report_at(0, "Delete Region", "RegionInUseForUpdateOrSubscription")
            for _ in range(20):
                drain(1)
                if overlap_callbacks.discovered_objects:
                    break
            self.assertEqual(overlap_callbacks.discovered_objects[-1][0], instance)
            self.assertEqual(disjoint_callbacks.discovered_objects, [])

            values = AttributeHandleValueMap(
                {publisher_attribute: b"regional-object-jni"}
            )
            publisher.updateAttributeValues(instance, values, b"regional-object-tag")
            for _ in range(20):
                drain(1)
                if (
                    overlap_callbacks.reflected_attributes
                    or overlap_callbacks.regional_reflections
                ):
                    break
            self.assertEqual(
                len(overlap_callbacks.reflected_attributes)
                + len(overlap_callbacks.regional_reflections),
                1,
            )
            initial_regional_count = len(overlap_callbacks.regional_reflections)
            if overlap_callbacks.reflected_attributes:
                reflection = overlap_callbacks.reflected_attributes[-1]
            else:
                reflection = overlap_callbacks.regional_reflections[-1]
                self.assertEqual(reflection[5], RegionHandleSet())
            self.assertEqual(reflection[0], instance)
            self.assertEqual(
                dict(reflection[1]), {overlap_attribute: b"regional-object-jni"}
            )
            self.assertEqual(reflection[2], b"regional-object-tag")
            self.assertEqual(disjoint_callbacks.regional_reflections, [])

            # Conveying source regions is recipient-local.  Enabling the
            # switch exposes the same C++ source association on the next
            # update without changing overlap routing.
            overlap.setConveyRegionDesignatorSetsSwitch(True)
            conveyed_values = AttributeHandleValueMap(
                {publisher_attribute: b"regional-object-conveyed"}
            )
            publisher.updateAttributeValues(
                instance, conveyed_values, b"regional-object-conveyed-tag"
            )
            for _ in range(20):
                drain(1)
                if overlap_callbacks.regional_reflections:
                    break
            conveyed_count = initial_regional_count + 1
            self.assertEqual(
                len(overlap_callbacks.regional_reflections), conveyed_count
            )
            conveyed = overlap_callbacks.regional_reflections[-1]
            self.assertEqual(conveyed[0], instance)
            self.assertEqual(
                dict(conveyed[1]),
                {overlap_attribute: b"regional-object-conveyed"},
            )
            self.assertEqual(conveyed[2], b"regional-object-conveyed-tag")
            self.assertEqual(conveyed[5], RegionHandleSet([publisher_region]))

            # A committed disjoint subscriber range suppresses the next
            # no-time update, while restoring overlap admits it again.
            overlap.setRangeBounds(overlap_region, overlap_dimension, RangeBounds(2, 3))
            overlap.commitRegionModifications(RegionHandleSet([overlap_region]))
            suppressed_values = AttributeHandleValueMap(
                {publisher_attribute: b"regional-object-suppressed"}
            )
            publisher.updateAttributeValues(
                instance, suppressed_values, b"regional-object-suppressed-tag"
            )
            for _ in range(20):
                drain(1)
            self.assertEqual(
                len(overlap_callbacks.regional_reflections), conveyed_count
            )

            overlap.setRangeBounds(overlap_region, overlap_dimension, RangeBounds(0, 1))
            overlap.commitRegionModifications(RegionHandleSet([overlap_region]))
            restored_values = AttributeHandleValueMap(
                {publisher_attribute: b"regional-object-restored"}
            )
            publisher.updateAttributeValues(
                instance, restored_values, b"regional-object-restored-tag"
            )
            for _ in range(20):
                drain(1)
                if len(overlap_callbacks.regional_reflections) >= conveyed_count + 1:
                    break
            self.assertEqual(
                len(overlap_callbacks.regional_reflections),
                conveyed_count + 1,
            )
            restored = overlap_callbacks.regional_reflections[-1]
            self.assertEqual(
                dict(restored[1]),
                {overlap_attribute: b"regional-object-restored"},
            )
            self.assertEqual(restored[5], RegionHandleSet([publisher_region]))

            # Remove both source associations before the standard region
            # teardown; the object remains known while its registration is
            # still valid.
            publisher.unassociateRegionsForUpdates(instance, publisher_pairs)
            publisher.unassociateRegionsForUpdates(instance, empty_publisher_pairs)
            disjoint.unsubscribeObjectClassAttributesWithRegions(
                disjoint_class, empty_disjoint_pairs
            )
        finally:
            if disjoint_joined:
                try:
                    disjoint.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if observer_joined:
                try:
                    observer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if overlap_joined:
                try:
                    overlap.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            disjoint.disconnect()
            overlap.disconnect()
            publisher.disconnect()
            observer.disconnect()
            disjoint._implementation.close()
            overlap._implementation.close()
            publisher._implementation.close()
            observer._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_mixes_default_and_explicit_subscriptions(
        self,
    ) -> None:
        """Keep ordinary and explicit regional declarations independently effective."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-default-regional-mix-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        regional = self.factory.getRtiAmbassador()
        mixed = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        regional_callbacks = _JniCallbacks()
        mixed_callbacks = _JniCallbacks()
        created = publisher_joined = regional_joined = mixed_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                regional.evokeCallback(0.0)
                mixed.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            regions: RegionHandleSet,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(AttributeHandleSet([attribute]), regions)
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            regional.connect(regional_callbacks, CallbackModel.HLA_EVOKED)
            mixed.connect(mixed_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-default-regional-mix-publisher", federation_name
            )
            publisher_joined = True
            regional.joinFederationExecution(
                "jni-default-regional-mix-regional", federation_name
            )
            regional_joined = True
            mixed.joinFederationExecution(
                "jni-default-regional-mix-mixed", federation_name
            )
            mixed_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            regional_class = regional.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            mixed_class = mixed.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            regional_attribute = regional.getAttributeHandle(
                regional_class, HLA_FIXTURES.FLAVOR
            )
            mixed_attribute = mixed.getAttributeHandle(mixed_class, HLA_FIXTURES.FLAVOR)
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )

            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            regional_dimension = regional.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            mixed_dimension = mixed.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            regional_region = regional.createRegion(
                DimensionHandleSet([regional_dimension])
            )
            mixed_region = mixed.createRegion(DimensionHandleSet([mixed_dimension]))
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 1)
            )
            regional.setRangeBounds(
                regional_region, regional_dimension, RangeBounds(0, 1)
            )
            mixed.setRangeBounds(mixed_region, mixed_dimension, RangeBounds(2, 3))
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            regional.commitRegionModifications(RegionHandleSet([regional_region]))
            mixed.commitRegionModifications(RegionHandleSet([mixed_region]))

            publisher_pairs = pair_list(
                publisher, publisher_attribute, RegionHandleSet([publisher_region])
            )
            regional_pairs = pair_list(
                regional, regional_attribute, RegionHandleSet([regional_region])
            )
            mixed_pairs = pair_list(
                mixed, mixed_attribute, RegionHandleSet([mixed_region])
            )
            regional.setConveyRegionDesignatorSetsSwitch(True)
            mixed.setConveyRegionDesignatorSetsSwitch(True)
            regional.subscribeObjectClassAttributesWithRegions(
                regional_class, regional_pairs, active=True
            )
            mixed.subscribeObjectClassAttributes(
                mixed_class, AttributeHandleSet([mixed_attribute]), active=True
            )
            mixed.subscribeObjectClassAttributesWithRegions(
                mixed_class, mixed_pairs, active=True
            )

            # The explicit disjoint declaration suppresses the retained
            # ordinary declaration while the source has an explicit region.
            instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            drain()
            self.assertEqual(len(regional_callbacks.discovered_objects), 1)
            self.assertEqual(regional_callbacks.discovered_objects[-1][0], instance)
            self.assertEqual(mixed_callbacks.discovered_objects, [])

            # Removing only the explicit declaration restores the ordinary
            # default-region realization for the already-registered object.
            mixed.unsubscribeObjectClassAttributesWithRegions(mixed_class, mixed_pairs)
            mixed.subscribeObjectClassAttributes(
                mixed_class, AttributeHandleSet([mixed_attribute]), active=True
            )
            drain()
            self.assertEqual(len(mixed_callbacks.discovered_objects), 1)
            self.assertEqual(mixed_callbacks.discovered_objects[-1][0], instance)

            # Reintroduce the disjoint regional declaration, then remove the
            # source association. Both recipients should receive the derived
            # default-region update with an empty conveyed region set.
            mixed.subscribeObjectClassAttributesWithRegions(
                mixed_class, mixed_pairs, active=True
            )
            publisher.unassociateRegionsForUpdates(instance, publisher_pairs)
            update_count_regional = len(regional_callbacks.regional_reflections)
            update_count_mixed = len(mixed_callbacks.regional_reflections)
            values = AttributeHandleValueMap({publisher_attribute: b"default-1"})
            publisher.updateAttributeValues(instance, values, b"default-1-tag")
            drain()
            self.assertEqual(
                len(regional_callbacks.regional_reflections), update_count_regional + 1
            )
            self.assertEqual(
                len(mixed_callbacks.regional_reflections), update_count_mixed + 1
            )
            self.assertEqual(
                regional_callbacks.regional_reflections[-1][5], RegionHandleSet()
            )
            self.assertEqual(
                mixed_callbacks.regional_reflections[-1][5], RegionHandleSet()
            )

            # Reassociating the explicit source region routes only to the
            # matching regional declaration; the mixed recipient remains
            # suppressed by its disjoint explicit declaration.
            publisher.associateRegionsForUpdates(instance, publisher_pairs)
            publisher.updateAttributeValues(
                instance,
                AttributeHandleValueMap({publisher_attribute: b"explicit"}),
                b"explicit-tag",
            )
            drain()
            self.assertEqual(
                len(regional_callbacks.regional_reflections), update_count_regional + 2
            )
            self.assertEqual(
                regional_callbacks.regional_reflections[-1][5],
                RegionHandleSet([publisher_region]),
            )
            self.assertEqual(
                len(mixed_callbacks.regional_reflections), update_count_mixed + 1
            )

            # Removing the association again returns both declarations to the
            # derived default region without creating a public RegionHandle.
            publisher.unassociateRegionsForUpdates(instance, publisher_pairs)
            publisher.updateAttributeValues(
                instance,
                AttributeHandleValueMap({publisher_attribute: b"default-2"}),
                b"default-2-tag",
            )
            drain()
            self.assertEqual(
                len(regional_callbacks.regional_reflections), update_count_regional + 3
            )
            self.assertEqual(
                len(mixed_callbacks.regional_reflections), update_count_mixed + 2
            )
            self.assertEqual(
                regional_callbacks.regional_reflections[-1][5], RegionHandleSet()
            )
            self.assertEqual(
                mixed_callbacks.regional_reflections[-1][5], RegionHandleSet()
            )
        finally:
            for ambassador, joined in (
                (mixed, mixed_joined),
                (regional, regional_joined),
                (publisher, publisher_joined),
            ):
                if joined:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            mixed.disconnect()
            regional.disconnect()
            publisher.disconnect()
            mixed._implementation.close()
            regional._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_passive_object_subscriptions_require_active_replacement(
        self,
    ) -> None:
        """Keep passive ordinary and regional declarations non-delivering."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-passive-object-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        created = publisher_joined = subscriber_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                subscriber.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-passive-object-publisher", federation_name
            )
            publisher_joined = True
            subscriber.joinFederationExecution(
                "jni-passive-object-subscriber", federation_name
            )
            subscriber_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            subscriber_class = subscriber.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            subscriber_attribute = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.FLAVOR
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            subscriber_dimension = subscriber.getDimensionHandle(
                HLA_FIXTURES.SODA_FLAVOR
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            subscriber_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 1)
            )
            subscriber.setRangeBounds(
                subscriber_region, subscriber_dimension, RangeBounds(0, 1)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            subscriber.commitRegionModifications(RegionHandleSet([subscriber_region]))

            def pair_list(
                ambassador: RTIambassador,
                attribute: AttributeHandle,
                region: RegionHandle,
            ) -> AttributeSetRegionSetPairList:
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([attribute]), RegionHandleSet([region])
                    )
                )
                return pairs

            publisher_pairs = pair_list(
                publisher, publisher_attribute, publisher_region
            )
            subscriber_pairs = pair_list(
                subscriber, subscriber_attribute, subscriber_region
            )
            values = AttributeHandleValueMap({publisher_attribute: b"passive-ordinary"})

            # A passive ordinary declaration is retained but does not arrange
            # discovery. Replacing it with the active declaration reprojects
            # the already-registered object through C++.
            subscriber.subscribeObjectClassAttributes(
                subscriber_class,
                AttributeHandleSet([subscriber_attribute]),
                active=False,
            )
            first_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            drain()
            self.assertEqual(subscriber_callbacks.discovered_objects, [])
            with self.assertRaises(ObjectInstanceNotKnown):
                subscriber.getKnownObjectClassHandle(first_instance)

            subscriber.subscribeObjectClassAttributes(
                subscriber_class,
                AttributeHandleSet([subscriber_attribute]),
                active=True,
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.discovered_objects), 1)
            self.assertEqual(
                subscriber_callbacks.discovered_objects[-1][0], first_instance
            )

            # The active declaration can be made passive again; the next
            # update is suppressed until an active replacement is installed.
            subscriber.subscribeObjectClassAttributes(
                subscriber_class,
                AttributeHandleSet([subscriber_attribute]),
                active=False,
            )
            publisher.updateAttributeValues(
                first_instance, values, b"passive-ordinary-tag"
            )
            drain()
            self.assertEqual(subscriber_callbacks.reflected_attributes, [])
            subscriber.subscribeObjectClassAttributes(
                subscriber_class,
                AttributeHandleSet([subscriber_attribute]),
                active=True,
            )
            publisher.updateAttributeValues(
                first_instance,
                AttributeHandleValueMap({publisher_attribute: b"active-ordinary"}),
                b"active-ordinary-tag",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.reflected_attributes), 1)
            self.assertEqual(
                dict(subscriber_callbacks.reflected_attributes[-1][1]),
                {subscriber_attribute: b"active-ordinary"},
            )

            # Ordinary and regional declarations are independent. Remove the
            # ordinary declaration, then exercise the same passive/active
            # replacement rule through the standard pair-list carrier.
            subscriber.unsubscribeObjectClassAttributes(
                subscriber_class, AttributeHandleSet([subscriber_attribute])
            )
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, subscriber_pairs, active=False
            )
            second_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.discovered_objects), 1)
            with self.assertRaises(ObjectInstanceNotKnown):
                subscriber.getKnownObjectClassHandle(second_instance)

            ordinary_reflection_count = len(subscriber_callbacks.reflected_attributes)
            publisher.updateAttributeValues(
                second_instance,
                AttributeHandleValueMap({publisher_attribute: b"passive-regional"}),
                b"passive-regional-tag",
            )
            drain()
            self.assertEqual(
                len(subscriber_callbacks.reflected_attributes),
                ordinary_reflection_count,
            )

            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, subscriber_pairs, active=True
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.discovered_objects), 2)
            self.assertEqual(
                subscriber_callbacks.discovered_objects[-1][0], second_instance
            )
            publisher.updateAttributeValues(
                first_instance,
                AttributeHandleValueMap({publisher_attribute: b"active-regional"}),
                b"active-regional-tag",
            )
            drain()
            self.assertEqual(
                len(subscriber_callbacks.reflected_attributes),
                ordinary_reflection_count + 1,
            )
            self.assertEqual(
                dict(subscriber_callbacks.reflected_attributes[-1][1]),
                {subscriber_attribute: b"active-regional"},
            )
        finally:
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            subscriber.disconnect()
            publisher.disconnect()
            subscriber._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_preserves_update_rate_advisories(
        self,
    ) -> None:
        """Preserve named-rate scope advisories across regional source changes."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-rate-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        owner_connected = subscriber_connected = False
        owner_joined = subscriber_joined = created = False
        owner_region: RegionHandle | None = None
        disjoint_owner_region: RegionHandle | None = None
        subscriber_region: RegionHandle | None = None
        object_instance: ObjectInstanceHandle | None = None
        subscriber_class: ObjectClassHandle | None = None
        subscriber_pair: AttributeSetRegionSetPairList | None = None

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                subscriber.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            subscriber_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            owner.joinFederationExecution("jni-regional-rate-owner", federation_name)
            owner_joined = True
            subscriber.joinFederationExecution(
                "jni-regional-rate-subscriber", federation_name
            )
            subscriber_joined = True

            owner_class = owner.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            subscriber_class = subscriber.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            owner_attribute = owner.getAttributeHandle(owner_class, HLA_FIXTURES.FLAVOR)
            subscriber_attribute = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.FLAVOR
            )
            owner_dimension = owner.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            subscriber_dimension = subscriber.getDimensionHandle(
                HLA_FIXTURES.SODA_FLAVOR
            )
            owner.publishObjectClassAttributes(
                owner_class, AttributeHandleSet([owner_attribute])
            )
            self.assertTrue(owner.getAttributeRelevanceAdvisorySwitch())

            owner_region = owner.createRegion(DimensionHandleSet([owner_dimension]))
            disjoint_owner_region = owner.createRegion(
                DimensionHandleSet([owner_dimension])
            )
            subscriber_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            owner.setRangeBounds(owner_region, owner_dimension, RangeBounds(0, 1))
            owner.setRangeBounds(
                disjoint_owner_region, owner_dimension, RangeBounds(2, 3)
            )
            subscriber.setRangeBounds(
                subscriber_region, subscriber_dimension, RangeBounds(0, 1)
            )
            owner.commitRegionModifications(
                RegionHandleSet([owner_region, disjoint_owner_region])
            )
            subscriber.commitRegionModifications(RegionHandleSet([subscriber_region]))

            def pair_list(
                ambassador: RTIambassador,
                attribute: AttributeHandle,
                region: RegionHandle,
            ) -> AttributeSetRegionSetPairList:
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([attribute]), RegionHandleSet([region])
                    )
                )
                return pairs

            owner_pair = pair_list(owner, owner_attribute, owner_region)
            disjoint_owner_pair = pair_list(
                owner, owner_attribute, disjoint_owner_region
            )
            subscriber_pair = pair_list(
                subscriber, subscriber_attribute, subscriber_region
            )
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class,
                subscriber_pair,
                active=True,
                updateRateDesignator="High",
            )
            object_instance = owner.registerObjectInstanceWithRegions(
                owner_class, owner_pair
            )
            drain()
            self.assertEqual(
                subscriber_callbacks.discovered_objects[-1][0], object_instance
            )

            # Drain discovery-triggered work before isolating the scope advisory
            # transitions.  The rate-bearing callback must be generated by the
            # exact Java overload and preserved by the C++ callback queue.
            owner_callbacks.updates_on.clear()
            owner_callbacks.updates_off.clear()

            owner.unassociateRegionsForUpdates(object_instance, owner_pair)
            drain()
            self.assertEqual(owner_callbacks.updates_off, [])

            owner.associateRegionsForUpdates(object_instance, disjoint_owner_pair)
            drain()
            self.assertEqual(
                owner_callbacks.updates_off,
                [(object_instance, AttributeHandleSet([owner_attribute]))],
            )

            owner.unassociateRegionsForUpdates(object_instance, disjoint_owner_pair)
            drain()
            self.assertEqual(
                owner_callbacks.updates_on,
                [
                    (
                        object_instance,
                        AttributeHandleSet([owner_attribute]),
                        "High",
                    )
                ],
            )
        finally:
            if object_instance is not None and owner_joined:
                try:
                    owner.unassociateRegionsForUpdates(
                        object_instance, disjoint_owner_pair
                    )
                except Exception:
                    pass
            if (
                subscriber_joined
                and subscriber_class is not None
                and subscriber_pair is not None
            ):
                try:
                    subscriber.unsubscribeObjectClassAttributesWithRegions(
                        subscriber_class, subscriber_pair
                    )
                except Exception:
                    pass
            for ambassador, region in (
                (subscriber, subscriber_region),
                (owner, disjoint_owner_region),
                (owner, owner_region),
            ):
                if region is not None and owner_joined:
                    try:
                        ambassador.deleteRegion(region)
                    except Exception:
                        pass
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if owner_joined:
                try:
                    owner.resignFederationExecution(
                        ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
                    )
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if subscriber_connected:
                try:
                    subscriber.disconnect()
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            subscriber._implementation.close()
            owner._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_reprojects_multiple_overlaps(
        self,
    ) -> None:
        """Exercise multi-region discovery and selective unassociation via the IEEE Java API."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-reprojection-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        created = publisher_joined = subscriber_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                subscriber.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-regional-reprojection-publisher", federation_name
            )
            publisher_joined = True
            subscriber.joinFederationExecution(
                "jni-regional-reprojection-subscriber", federation_name
            )
            subscriber_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            subscriber_class = subscriber.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            subscriber_attribute = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.FLAVOR
            )
            publisher.publishObjectClassAttributes(
                publisher_class, AttributeHandleSet([publisher_attribute])
            )
            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            subscriber_dimension = subscriber.getDimensionHandle(
                HLA_FIXTURES.SODA_FLAVOR
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            disjoint_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            overlap_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            overlap_region_two = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 1)
            )
            subscriber.setRangeBounds(
                disjoint_region, subscriber_dimension, RangeBounds(3, 4)
            )
            subscriber.setRangeBounds(
                overlap_region, subscriber_dimension, RangeBounds(0, 2)
            )
            subscriber.setRangeBounds(
                overlap_region_two, subscriber_dimension, RangeBounds(0, 2)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            subscriber.commitRegionModifications(
                RegionHandleSet([disjoint_region, overlap_region, overlap_region_two])
            )

            def pair_list(
                ambassador: RTIambassador, attribute: AttributeHandle, regions
            ):
                pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
                pairs.add(
                    AttributeSetRegionSetPair(AttributeHandleSet([attribute]), regions)
                )
                return pairs

            disjoint_pairs = pair_list(
                subscriber, subscriber_attribute, RegionHandleSet([disjoint_region])
            )
            overlap_pairs = pair_list(
                subscriber, subscriber_attribute, RegionHandleSet([overlap_region])
            )
            overlap_two_pairs = pair_list(
                subscriber, subscriber_attribute, RegionHandleSet([overlap_region_two])
            )
            publisher_pairs = pair_list(
                publisher, publisher_attribute, RegionHandleSet([publisher_region])
            )

            subscriber.setConveyRegionDesignatorSetsSwitch(True)
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, disjoint_pairs, active=True
            )
            instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            drain()
            self.assertEqual(subscriber_callbacks.discovered_objects, [])

            # Adding the first overlapping region must reproject the existing
            # object exactly once; adding a second equivalent overlap must not
            # emit duplicate discovery.
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, overlap_pairs, active=True
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.discovered_objects), 1)
            self.assertEqual(subscriber_callbacks.discovered_objects[0][0], instance)
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, overlap_two_pairs, active=True
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.discovered_objects), 1)

            values = AttributeHandleValueMap({publisher_attribute: b"two-overlaps"})
            publisher.updateAttributeValues(instance, values, b"two-overlaps-tag")
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 1)
            self.assertEqual(
                subscriber_callbacks.regional_reflections[0][1],
                AttributeHandleValueMap({subscriber_attribute: b"two-overlaps"}),
            )

            subscriber.setAttributeScopeAdvisorySwitch(True)
            subscriber.unsubscribeObjectClassAttributesWithRegions(
                subscriber_class, overlap_pairs
            )
            drain()
            self.assertEqual(subscriber_callbacks.attributes_out_of_scope, [])
            publisher.updateAttributeValues(
                instance,
                AttributeHandleValueMap({publisher_attribute: b"one-overlap"}),
                b"one-overlap-tag",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 2)
            self.assertEqual(
                subscriber_callbacks.regional_reflections[-1][1],
                AttributeHandleValueMap({subscriber_attribute: b"one-overlap"}),
            )

            subscriber.unsubscribeObjectClassAttributesWithRegions(
                subscriber_class,
                pair_list(
                    subscriber,
                    subscriber_attribute,
                    RegionHandleSet([disjoint_region, overlap_region_two]),
                ),
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.attributes_out_of_scope), 1)
            publisher.updateAttributeValues(
                instance,
                AttributeHandleValueMap({publisher_attribute: b"out-of-scope"}),
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 2)

            # Re-subscribing one of the removed overlapping regions must
            # reproject the already-known object into scope, including the
            # standard attributesInScope callback, and restore delivery.
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class, overlap_two_pairs, active=True
            )
            drain()
            self.assertIn(
                (instance, AttributeHandleSet([subscriber_attribute])),
                subscriber_callbacks.attributes_in_scope,
            )
            publisher.updateAttributeValues(
                instance,
                AttributeHandleValueMap({publisher_attribute: b"resubscribed"}),
                b"resubscribed-tag",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 3)
            self.assertEqual(
                subscriber_callbacks.regional_reflections[-1][1],
                AttributeHandleValueMap({subscriber_attribute: b"resubscribed"}),
            )
            self.assertEqual(
                subscriber_callbacks.regional_reflections[-1][2], b"resubscribed-tag"
            )
        finally:
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            subscriber.disconnect()
            publisher.disconnect()
            subscriber._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_keeps_independent_attributes_active(
        self,
    ) -> None:
        """Preserve independent source-region associations per attribute."""
        fom_module = (
            Path(__file__).parents[3]
            / "packages"
            / "umbra-rti-native"
            / "tests"
            / "data"
            / "regional-multi-attribute-fom.xml"
        )
        federation_name = f"python-jni-independent-regional-attributes-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        created = publisher_joined = subscriber_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                subscriber.evokeCallback(0.0)

        def pair_list(ambassador: RTIambassador, *pairs: AttributeSetRegionSetPair):
            result = ambassador.getAttributeSetRegionSetPairListFactory().create(
                len(pairs)
            )
            for pair in pairs:
                result.add(pair)
            return result

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-independent-region-publisher", federation_name
            )
            publisher_joined = True
            subscriber.joinFederationExecution(
                "jni-independent-region-subscriber", federation_name
            )
            subscriber_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            subscriber_class = subscriber.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            publisher_flavor = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            publisher_organic = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.ORGANIC
            )
            subscriber_flavor = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.FLAVOR
            )
            subscriber_organic = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.ORGANIC
            )
            publisher.publishObjectClassAttributes(
                publisher_class,
                AttributeHandleSet([publisher_flavor, publisher_organic]),
            )
            publisher_dimension = publisher.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            subscriber_dimension = subscriber.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            publisher_overlap = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher_disjoint = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            subscriber_overlap = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            publisher.setRangeBounds(
                publisher_overlap, publisher_dimension, RangeBounds(0, 1)
            )
            publisher.setRangeBounds(
                publisher_disjoint, publisher_dimension, RangeBounds(3, 4)
            )
            subscriber.setRangeBounds(
                subscriber_overlap, subscriber_dimension, RangeBounds(0, 1)
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_overlap, publisher_disjoint])
            )
            subscriber.commitRegionModifications(RegionHandleSet([subscriber_overlap]))
            subscriber.setConveyRegionDesignatorSetsSwitch(True)
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class,
                pair_list(
                    subscriber,
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([subscriber_flavor, subscriber_organic]),
                        RegionHandleSet([subscriber_overlap]),
                    ),
                ),
                active=True,
            )

            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class,
                pair_list(
                    publisher,
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([publisher_flavor]),
                        RegionHandleSet([publisher_overlap, publisher_disjoint]),
                    ),
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([publisher_organic]),
                        RegionHandleSet([publisher_disjoint]),
                    ),
                ),
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.discovered_objects), 1)

            values = AttributeHandleValueMap(
                {publisher_flavor: b"flavor-1", publisher_organic: b"organic-1"}
            )
            publisher.updateAttributeValues(object_instance, values, b"initial")
            drain()
            self.assertEqual(
                set(subscriber_callbacks.regional_reflections[-1][1].keys()),
                {subscriber_flavor},
            )

            publisher.associateRegionsForUpdates(
                object_instance,
                pair_list(
                    publisher,
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([publisher_organic]),
                        RegionHandleSet([publisher_overlap]),
                    ),
                ),
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {publisher_flavor: b"flavor-2", publisher_organic: b"organic-2"}
                ),
                b"both-overlap",
            )
            drain()
            self.assertEqual(
                set(subscriber_callbacks.regional_reflections[-1][1].keys()),
                {subscriber_flavor, subscriber_organic},
            )

            publisher.unassociateRegionsForUpdates(
                object_instance,
                pair_list(
                    publisher,
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([publisher_flavor]),
                        RegionHandleSet([publisher_overlap]),
                    ),
                ),
            )
            reflection_count = len(subscriber_callbacks.regional_reflections)
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-disjoint",
                        publisher_organic: b"organic-3",
                    }
                ),
                b"organic-only",
            )
            drain()
            self.assertEqual(
                len(subscriber_callbacks.regional_reflections), reflection_count + 1
            )
            self.assertEqual(
                set(subscriber_callbacks.regional_reflections[-1][1].keys()),
                {subscriber_organic},
            )
            self.assertEqual(
                subscriber_callbacks.regional_reflections[-1][1][subscriber_organic],
                b"organic-3",
            )

            publisher.unassociateRegionsForUpdates(
                object_instance,
                pair_list(
                    publisher,
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([publisher_flavor]),
                        RegionHandleSet([publisher_disjoint]),
                    ),
                    AttributeSetRegionSetPair(
                        AttributeHandleSet([publisher_organic]),
                        RegionHandleSet([publisher_overlap, publisher_disjoint]),
                    ),
                ),
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-default",
                        publisher_organic: b"organic-default",
                    }
                ),
                b"default-region",
            )
            drain()
            self.assertEqual(
                set(subscriber_callbacks.regional_reflections[-1][1].keys()),
                {subscriber_flavor, subscriber_organic},
            )
        finally:
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            subscriber.disconnect()
            publisher.disconnect()
            subscriber._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_recipient_isolation(self) -> None:
        """Preserve per-recipient scope transitions as source regions change."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-recipient-isolation-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        matching = self.factory.getRtiAmbassador()
        disjoint = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        matching_callbacks = _JniCallbacks()
        disjoint_callbacks = _JniCallbacks()
        created = publisher_joined = matching_joined = disjoint_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                matching.evokeCallback(0.0)
                disjoint.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            regions: RegionHandleSet,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(AttributeHandleSet([attribute]), regions)
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            matching.connect(matching_callbacks, CallbackModel.HLA_EVOKED)
            disjoint.connect(disjoint_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-regional-isolation-publisher", federation_name
            )
            publisher_joined = True
            matching.joinFederationExecution(
                "jni-regional-isolation-matching", federation_name
            )
            matching_joined = True
            disjoint.joinFederationExecution(
                "jni-regional-isolation-disjoint", federation_name
            )
            disjoint_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            matching_class = matching.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            disjoint_class = disjoint.getObjectClassHandle(HLA_FOM.FOOD_DRINK_SODA)
            publisher_attribute = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            matching_attribute = matching.getAttributeHandle(
                matching_class, HLA_FIXTURES.FLAVOR
            )
            disjoint_attribute = disjoint.getAttributeHandle(
                disjoint_class, HLA_FIXTURES.FLAVOR
            )
            publisher_attributes = AttributeHandleSet([publisher_attribute])
            matching_attributes = AttributeHandleSet([matching_attribute])
            disjoint_attributes = AttributeHandleSet([disjoint_attribute])
            publisher.publishObjectClassAttributes(
                publisher_class, publisher_attributes
            )

            # Ordinary subscriptions establish object knowledge for both
            # recipients before regional filtering is applied.
            matching.subscribeObjectClassAttributes(matching_class, matching_attributes)
            disjoint.subscribeObjectClassAttributes(disjoint_class, disjoint_attributes)
            object_instance = publisher.registerObjectInstance(publisher_class)
            drain()
            self.assertEqual(
                matching_callbacks.discovered_objects[-1][0], object_instance
            )
            self.assertEqual(
                disjoint_callbacks.discovered_objects[-1][0], object_instance
            )

            publisher_dimension = publisher.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            matching_dimension = matching.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            disjoint_dimension = disjoint.getDimensionHandle(HLA_FIXTURES.SODA_FLAVOR)
            publisher_overlap = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher_disjoint = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            matching_region = matching.createRegion(
                DimensionHandleSet([matching_dimension])
            )
            disjoint_region = disjoint.createRegion(
                DimensionHandleSet([disjoint_dimension])
            )
            publisher.setRangeBounds(
                publisher_overlap, publisher_dimension, RangeBounds(0, 1)
            )
            publisher.setRangeBounds(
                publisher_disjoint, publisher_dimension, RangeBounds(3, 4)
            )
            matching.setRangeBounds(
                matching_region, matching_dimension, RangeBounds(0, 1)
            )
            disjoint.setRangeBounds(
                disjoint_region, disjoint_dimension, RangeBounds(3, 4)
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_overlap, publisher_disjoint])
            )
            matching.commitRegionModifications(RegionHandleSet([matching_region]))
            disjoint.commitRegionModifications(RegionHandleSet([disjoint_region]))

            matching_pairs = pair_list(
                matching, matching_attribute, RegionHandleSet([matching_region])
            )
            disjoint_pairs = pair_list(
                disjoint, disjoint_attribute, RegionHandleSet([disjoint_region])
            )
            publisher_overlap_pairs = pair_list(
                publisher, publisher_attribute, RegionHandleSet([publisher_overlap])
            )
            publisher_disjoint_pairs = pair_list(
                publisher, publisher_attribute, RegionHandleSet([publisher_disjoint])
            )
            matching.setAttributeScopeAdvisorySwitch(True)
            disjoint.setAttributeScopeAdvisorySwitch(True)
            matching.setConveyRegionDesignatorSetsSwitch(True)
            disjoint.setConveyRegionDesignatorSetsSwitch(True)
            matching.subscribeObjectClassAttributesWithRegions(
                matching_class, matching_pairs, active=True
            )
            disjoint.subscribeObjectClassAttributesWithRegions(
                disjoint_class, disjoint_pairs, active=True
            )

            # Establish an explicit source overlap while ordinary delivery is
            # still active. Removing the ordinary declarations below exposes
            # the known object to the regional scope state: matching remains
            # in scope and disjoint transitions out of scope.
            publisher.associateRegionsForUpdates(
                object_instance, publisher_overlap_pairs
            )
            matching.unsubscribeObjectClassAttributes(
                matching_class, matching_attributes
            )
            disjoint.unsubscribeObjectClassAttributes(
                disjoint_class, disjoint_attributes
            )
            drain()
            self.assertIn(
                (object_instance, disjoint_attributes),
                disjoint_callbacks.attributes_out_of_scope,
            )
            self.assertNotIn(
                (object_instance, matching_attributes),
                matching_callbacks.attributes_out_of_scope,
            )
            matching_callbacks.attributes_in_scope.clear()
            matching_callbacks.attributes_out_of_scope.clear()
            disjoint_callbacks.attributes_in_scope.clear()
            disjoint_callbacks.attributes_out_of_scope.clear()

            # Adding the source disjoint region brings only the previously
            # out-of-scope known recipient back into scope.
            publisher.associateRegionsForUpdates(
                object_instance, publisher_disjoint_pairs
            )
            drain()
            self.assertIn(
                (object_instance, disjoint_attributes),
                disjoint_callbacks.attributes_in_scope,
            )
            self.assertEqual(matching_callbacks.attributes_in_scope, [])
            self.assertEqual(matching_callbacks.attributes_out_of_scope, [])

            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap({publisher_attribute: b"both-regions"}),
                b"both-regions-tag",
            )
            drain()
            self.assertEqual(len(matching_callbacks.regional_reflections), 1)
            self.assertEqual(len(disjoint_callbacks.regional_reflections), 1)

            # Removing only the original overlap leaves disjoint as the sole
            # source association, so matching exits scope while disjoint stays
            # active and continues receiving updates.
            publisher.unassociateRegionsForUpdates(
                object_instance, publisher_overlap_pairs
            )
            drain()
            self.assertIn(
                (object_instance, matching_attributes),
                matching_callbacks.attributes_out_of_scope,
            )
            self.assertEqual(disjoint_callbacks.attributes_out_of_scope, [])
            matching_reflections = len(matching_callbacks.regional_reflections)
            disjoint_reflections = len(disjoint_callbacks.regional_reflections)
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap({publisher_attribute: b"disjoint-only"}),
                b"disjoint-only-tag",
            )
            drain()
            self.assertEqual(
                len(matching_callbacks.regional_reflections), matching_reflections
            )
            self.assertEqual(
                len(disjoint_callbacks.regional_reflections), disjoint_reflections + 1
            )
            self.assertEqual(
                disjoint_callbacks.regional_reflections[-1][1],
                AttributeHandleValueMap({disjoint_attribute: b"disjoint-only"}),
            )

            # Removing the final explicit association restores the default
            # source region and re-enters the matching recipient only.
            publisher.unassociateRegionsForUpdates(
                object_instance, publisher_disjoint_pairs
            )
            drain()
            self.assertIn(
                (object_instance, matching_attributes),
                matching_callbacks.attributes_in_scope,
            )
            matching_reflections = len(matching_callbacks.regional_reflections)
            disjoint_reflections = len(disjoint_callbacks.regional_reflections)
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap({publisher_attribute: b"default-region"}),
                b"default-region-tag",
            )
            drain()
            self.assertEqual(
                len(matching_callbacks.regional_reflections), matching_reflections + 1
            )
            self.assertEqual(
                len(disjoint_callbacks.regional_reflections), disjoint_reflections + 1
            )
        finally:
            if disjoint_joined:
                try:
                    disjoint.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if matching_joined:
                try:
                    matching.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            disjoint.disconnect()
            matching.disconnect()
            publisher.disconnect()
            disjoint._implementation.close()
            matching._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_multi_attribute_association_isolation(
        self,
    ) -> None:
        """Keep two independently associated attributes isolated in one update."""
        fom_module = (
            Path(__file__).parents[2]
            / "umbra-rti-native"
            / "tests"
            / "data"
            / "regional-multi-attribute-fom.xml"
        )
        federation_name = f"python-jni-regional-multi-attribute-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        subscriber_callbacks = _JniCallbacks()
        created = publisher_joined = subscriber_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                subscriber.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            entries: tuple[tuple[AttributeHandle, RegionHandleSet], ...],
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(
                len(entries)
            )
            for attribute, regions in entries:
                pairs.add(
                    AttributeSetRegionSetPair(AttributeHandleSet([attribute]), regions)
                )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            subscriber.connect(subscriber_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name,
                str(fom_module),
                HLA_TYPES.INTEGER64_TIME,
            )
            created = True
            publisher.joinFederationExecution(
                "jni-multi-attribute-publisher", federation_name
            )
            publisher_joined = True
            subscriber.joinFederationExecution(
                "jni-multi-attribute-subscriber", federation_name
            )
            subscriber_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            subscriber_class = subscriber.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            publisher_flavor = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            publisher_organic = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.ORGANIC
            )
            subscriber_flavor = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.FLAVOR
            )
            subscriber_organic = subscriber.getAttributeHandle(
                subscriber_class, HLA_FIXTURES.ORGANIC
            )
            publisher_attributes = AttributeHandleSet(
                [publisher_flavor, publisher_organic]
            )
            subscriber_attributes = AttributeHandleSet(
                [subscriber_flavor, subscriber_organic]
            )
            publisher.publishObjectClassAttributes(
                publisher_class, publisher_attributes
            )

            publisher_dimension = publisher.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            subscriber_dimension = subscriber.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            publisher_flavor_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher_organic_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            subscriber_flavor_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            subscriber_organic_region = subscriber.createRegion(
                DimensionHandleSet([subscriber_dimension])
            )
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(0, 20),
            )
            publisher.setRangeBounds(
                publisher_organic_region,
                publisher_dimension,
                RangeBounds(80, 100),
            )
            subscriber.setRangeBounds(
                subscriber_flavor_region,
                subscriber_dimension,
                RangeBounds(0, 20),
            )
            subscriber.setRangeBounds(
                subscriber_organic_region,
                subscriber_dimension,
                RangeBounds(80, 100),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region, publisher_organic_region])
            )
            subscriber.commitRegionModifications(
                RegionHandleSet([subscriber_flavor_region, subscriber_organic_region])
            )
            subscriber.setConveyRegionDesignatorSetsSwitch(True)
            subscriber.subscribeObjectClassAttributesWithRegions(
                subscriber_class,
                pair_list(
                    subscriber,
                    (
                        (
                            subscriber_flavor,
                            RegionHandleSet([subscriber_flavor_region]),
                        ),
                        (
                            subscriber_organic,
                            RegionHandleSet([subscriber_organic_region]),
                        ),
                    ),
                ),
            )
            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class,
                pair_list(
                    publisher,
                    (
                        (publisher_flavor, RegionHandleSet([publisher_flavor_region])),
                        (
                            publisher_organic,
                            RegionHandleSet([publisher_organic_region]),
                        ),
                    ),
                ),
            )
            drain()
            self.assertEqual(
                subscriber_callbacks.discovered_objects[-1][0], object_instance
            )

            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-overlap",
                        publisher_organic: b"organic-overlap",
                    }
                ),
                b"both-overlap",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 2)
            first_reflections = subscriber_callbacks.regional_reflections[-2:]
            self.assertTrue(
                any(
                    reflection[1]
                    == AttributeHandleValueMap({subscriber_flavor: b"flavor-overlap"})
                    and reflection[5] == RegionHandleSet([publisher_flavor_region])
                    for reflection in first_reflections
                )
            )
            self.assertTrue(
                any(
                    reflection[1]
                    == AttributeHandleValueMap({subscriber_organic: b"organic-overlap"})
                    and reflection[5] == RegionHandleSet([publisher_organic_region])
                    for reflection in first_reflections
                )
            )

            # Move only Flavor out of scope. The C++ attribute association
            # ledger must retain Organic in the same service call and the
            # Java callback must carry only that attribute's source region.
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(30, 40),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region])
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-disjoint",
                        publisher_organic: b"organic-only",
                    }
                ),
                b"organic-only-tag",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 3)
            reflection = subscriber_callbacks.regional_reflections[-1]
            self.assertEqual(
                reflection[1],
                AttributeHandleValueMap({subscriber_organic: b"organic-only"}),
            )
            self.assertEqual(reflection[5], RegionHandleSet([publisher_organic_region]))

            # Restore Flavor's overlap and move only Organic out of scope.
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(0, 20),
            )
            publisher.setRangeBounds(
                publisher_organic_region,
                publisher_dimension,
                RangeBounds(30, 40),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region, publisher_organic_region])
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-only",
                        publisher_organic: b"organic-disjoint",
                    }
                ),
                b"flavor-only-tag",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 4)
            reflection = subscriber_callbacks.regional_reflections[-1]
            self.assertEqual(
                reflection[1],
                AttributeHandleValueMap({subscriber_flavor: b"flavor-only"}),
            )
            self.assertEqual(reflection[5], RegionHandleSet([publisher_flavor_region]))

            # With both source regions disjoint, a map containing both
            # attributes must not produce an empty or stale callback.
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(30, 40),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region])
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"none-flavor",
                        publisher_organic: b"none-organic",
                    }
                ),
                b"none-tag",
            )
            drain()
            self.assertEqual(len(subscriber_callbacks.regional_reflections), 4)
        finally:
            if subscriber_joined:
                try:
                    subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            subscriber.disconnect()
            publisher.disconnect()
            subscriber._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_regional_object_multi_attribute_recipient_isolation(
        self,
    ) -> None:
        """Combine per-attribute filtering with independent recipients."""
        fom_module = (
            Path(__file__).parents[2]
            / "umbra-rti-native"
            / "tests"
            / "data"
            / "regional-multi-attribute-fom.xml"
        )
        federation_name = f"python-jni-regional-multi-attribute-recipients-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        flavor_subscriber = self.factory.getRtiAmbassador()
        organic_subscriber = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        flavor_callbacks = _JniCallbacks()
        organic_callbacks = _JniCallbacks()
        created = publisher_joined = flavor_joined = organic_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                flavor_subscriber.evokeCallback(0.0)
                organic_subscriber.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            regions: RegionHandleSet,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(AttributeHandleSet([attribute]), regions)
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            flavor_subscriber.connect(flavor_callbacks, CallbackModel.HLA_EVOKED)
            organic_subscriber.connect(organic_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), HLA_TYPES.INTEGER64_TIME
            )
            created = True
            publisher.joinFederationExecution(
                "jni-multi-attribute-recipient-publisher", federation_name
            )
            publisher_joined = True
            flavor_subscriber.joinFederationExecution(
                "jni-multi-attribute-flavor-subscriber", federation_name
            )
            flavor_joined = True
            organic_subscriber.joinFederationExecution(
                "jni-multi-attribute-organic-subscriber", federation_name
            )
            organic_joined = True

            publisher_class = publisher.getObjectClassHandle(HLA_FOM.REGIONAL_THING)
            flavor_class = flavor_subscriber.getObjectClassHandle(
                HLA_FOM.REGIONAL_THING
            )
            organic_class = organic_subscriber.getObjectClassHandle(
                HLA_FOM.REGIONAL_THING
            )
            publisher_flavor = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.FLAVOR
            )
            publisher_organic = publisher.getAttributeHandle(
                publisher_class, HLA_FIXTURES.ORGANIC
            )
            flavor_attribute = flavor_subscriber.getAttributeHandle(
                flavor_class, HLA_FIXTURES.FLAVOR
            )
            organic_attribute = organic_subscriber.getAttributeHandle(
                organic_class, HLA_FIXTURES.ORGANIC
            )
            publisher.publishObjectClassAttributes(
                publisher_class,
                AttributeHandleSet([publisher_flavor, publisher_organic]),
            )

            publisher_dimension = publisher.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            flavor_dimension = flavor_subscriber.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            organic_dimension = organic_subscriber.getDimensionHandle(
                HLA_FIXTURES.UMBRA_REGIONAL_DIMENSION
            )
            publisher_flavor_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher_organic_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            flavor_region = flavor_subscriber.createRegion(
                DimensionHandleSet([flavor_dimension])
            )
            organic_region = organic_subscriber.createRegion(
                DimensionHandleSet([organic_dimension])
            )
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(0, 20),
            )
            publisher.setRangeBounds(
                publisher_organic_region,
                publisher_dimension,
                RangeBounds(80, 100),
            )
            flavor_subscriber.setRangeBounds(
                flavor_region, flavor_dimension, RangeBounds(0, 20)
            )
            organic_subscriber.setRangeBounds(
                organic_region, organic_dimension, RangeBounds(80, 100)
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region, publisher_organic_region])
            )
            flavor_subscriber.commitRegionModifications(
                RegionHandleSet([flavor_region])
            )
            organic_subscriber.commitRegionModifications(
                RegionHandleSet([organic_region])
            )
            flavor_subscriber.setConveyRegionDesignatorSetsSwitch(True)
            organic_subscriber.setConveyRegionDesignatorSetsSwitch(True)
            flavor_subscriber.subscribeObjectClassAttributesWithRegions(
                flavor_class,
                pair_list(
                    flavor_subscriber,
                    flavor_attribute,
                    RegionHandleSet([flavor_region]),
                ),
                active=True,
            )
            organic_subscriber.subscribeObjectClassAttributesWithRegions(
                organic_class,
                pair_list(
                    organic_subscriber,
                    organic_attribute,
                    RegionHandleSet([organic_region]),
                ),
                active=True,
            )
            publisher_pairs = (
                publisher.getAttributeSetRegionSetPairListFactory().create(2)
            )
            publisher_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([publisher_flavor]),
                    RegionHandleSet([publisher_flavor_region]),
                )
            )
            publisher_pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([publisher_organic]),
                    RegionHandleSet([publisher_organic_region]),
                )
            )
            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            drain()
            self.assertEqual(
                flavor_callbacks.discovered_objects[-1][0], object_instance
            )
            self.assertEqual(
                organic_callbacks.discovered_objects[-1][0], object_instance
            )

            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-overlap",
                        publisher_organic: b"organic-overlap",
                    }
                ),
                b"both-overlap",
            )
            drain()
            self.assertEqual(len(flavor_callbacks.regional_reflections), 1)
            self.assertEqual(len(organic_callbacks.regional_reflections), 1)
            flavor_reflection = flavor_callbacks.regional_reflections[-1]
            organic_reflection = organic_callbacks.regional_reflections[-1]
            self.assertEqual(
                flavor_reflection[1],
                AttributeHandleValueMap({flavor_attribute: b"flavor-overlap"}),
            )
            self.assertEqual(
                organic_reflection[1],
                AttributeHandleValueMap({organic_attribute: b"organic-overlap"}),
            )
            self.assertEqual(
                flavor_reflection[5], RegionHandleSet([publisher_flavor_region])
            )
            self.assertEqual(
                organic_reflection[5], RegionHandleSet([publisher_organic_region])
            )

            # Moving only Flavor out of scope must silence that recipient
            # while Organic continues to arrive through its independent
            # source/subscription region pair.
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(30, 40),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region])
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-disjoint",
                        publisher_organic: b"organic-only",
                    }
                ),
                b"organic-only-tag",
            )
            drain()
            self.assertEqual(len(flavor_callbacks.regional_reflections), 1)
            self.assertEqual(len(organic_callbacks.regional_reflections), 2)
            self.assertEqual(
                organic_callbacks.regional_reflections[-1][1],
                AttributeHandleValueMap({organic_attribute: b"organic-only"}),
            )

            # Restore Flavor and move only Organic out of scope.  The
            # recipient-local projections must reverse without cross-talk.
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(0, 20),
            )
            publisher.setRangeBounds(
                publisher_organic_region,
                publisher_dimension,
                RangeBounds(30, 40),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region, publisher_organic_region])
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"flavor-only",
                        publisher_organic: b"organic-disjoint",
                    }
                ),
                b"flavor-only-tag",
            )
            drain()
            self.assertEqual(len(flavor_callbacks.regional_reflections), 2)
            self.assertEqual(len(organic_callbacks.regional_reflections), 2)
            self.assertEqual(
                flavor_callbacks.regional_reflections[-1][1],
                AttributeHandleValueMap({flavor_attribute: b"flavor-only"}),
            )

            # With both source regions disjoint, neither recipient may see a
            # stale or empty callback for the combined value map.
            publisher.setRangeBounds(
                publisher_flavor_region,
                publisher_dimension,
                RangeBounds(30, 40),
            )
            publisher.commitRegionModifications(
                RegionHandleSet([publisher_flavor_region])
            )
            publisher.updateAttributeValues(
                object_instance,
                AttributeHandleValueMap(
                    {
                        publisher_flavor: b"none-flavor",
                        publisher_organic: b"none-organic",
                    }
                ),
                b"none-tag",
            )
            drain()
            self.assertEqual(len(flavor_callbacks.regional_reflections), 2)
            self.assertEqual(len(organic_callbacks.regional_reflections), 2)
        finally:
            if organic_joined:
                try:
                    organic_subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if flavor_joined:
                try:
                    flavor_subscriber.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            organic_subscriber.disconnect()
            flavor_subscriber.disconnect()
            publisher.disconnect()
            organic_subscriber._implementation.close()
            flavor_subscriber._implementation.close()
            publisher._implementation.close()

